// The club host may not have the optional mbstring extension enabled. Private
// chat writes use mb_substr(), so keep normal messages working without it.
if (!function_exists('mb_substr')) {
  function mb_substr($str, $start, $length = null, $encoding = 'UTF-8') {
    $chars = preg_split('//u', (string)$str, -1, PREG_SPLIT_NO_EMPTY);
    if ($chars === false) $chars = str_split((string)$str);
    return $length === null ? implode('', array_slice($chars, $start)) : implode('', array_slice($chars, $start, (int)$length));
  }
}
