self.addEventListener('install',e=>{e.waitUntil(caches.open(C).then(c=>c.addAll([HOME,HOME+'?a=manifest',HOME+'?a=icon&s=192',HOME+'?a=icon&s=badge'].map(url=>new Request(url,{cache:'reload'}))))) });
self.addEventListener('message',e=>{if(e.data&&e.data.type==='SKIP_WAITING')self.skipWaiting()});
