self.addEventListener('fetch',e=>{
 const req=e.request,u=new URL(req.url);
 if(req.method!=='GET'||u.origin!==self.location.origin||(u.pathname!==HOME&&u.pathname!=='/'))return;
 // API/private media/state requests never enter the shell cache.
 if(req.cache==='no-store'||req.headers.has('X-AGFC'))return;
 const params=Array.from(u.searchParams.entries());
