 let copy=null;
 // Fetch the original navigation URL so reset/checkin behavior is unchanged.
 const network=fetch(req).then(r=>{
  const type=(r.headers.get('Content-Type')||'').split(';')[0].trim().toLowerCase();
  const valid=kind==='html'?type==='text/html':kind==='icon'?type==='image/png':type==='application/manifest+json'||type==='application/json';
  const privateResponse=/(?:^|,)\s*(?:private|no-store)(?:\s|,|=|$)/i.test(r.headers.get('Cache-Control')||'');
  if(r.ok&&!r.redirected&&valid&&!privateResponse){
   // A new Response also avoids retaining reset/checkin URLs as response metadata.
   const cloned=r.clone();copy=new Response(cloned.body,{status:cloned.status,statusText:cloned.statusText,headers:cloned.headers});
  }
