/* ---------------- storage ---------------- */
function lock() { global $DIR; $f = fopen("$DIR/lock", 'c'); flock($f, LOCK_EX); return $f; }
function unlock($f) { flock($f, LOCK_UN); fclose($f); }
function load_state() {
  global $DIR; $raw = @file_get_contents("$DIR/state.json");
  $st = $raw ? json_decode($raw) : (object)['rev' => 1, 'S' => json_decode(seed_json())];
  if (migrate($st->S)) { $st->rev++; save_state($st); }
  return $st;
}
/* one-off data updates from Alfie (applied once, then remembered) */
function migrate($S) {
  $S->mig = $S->mig ?? new stdClass; $done = false;
  // Permanent club player references. Internal player IDs remain unchanged so historical
  // fixtures, attendance, loyalty stamps and messages continue to resolve correctly.
  $usedRefs = []; $maxRef = 0;
  foreach (($S->players ?? []) as $pl) {
    $ref = strtoupper(trim((string)($pl->playerRef ?? '')));
    if (preg_match('/^AGFC-(\\d{6})$/', $ref, $m)) $maxRef = max($maxRef, (int)$m[1]);
  }
  foreach (($S->players ?? []) as $pl) {
    $ref = strtoupper(trim((string)($pl->playerRef ?? '')));
    if (!$ref || isset($usedRefs[$ref])) {
      do { $ref = 'AGFC-' . str_pad((string)++$maxRef, 6, '0', STR_PAD_LEFT); } while (isset($usedRefs[$ref]));
      $pl->playerRef = $ref; $done = true;
    } else {
      $pl->playerRef = $ref;
    }
    $usedRefs[$ref] = true;
  }

  if (empty($S->mig->u10g_stats_1)) {
    // U10 (U9) Greens: surnames + this season's appearances, goals and assists before the app (from Alfie's stats sheet, 21 Nov 2026)
    $data = ['Joe' => ['Jameson', 7, 1, 1], 'Patrick' => ["O'Neill", 7, 0, 0], 'Jacob' => ['Porter', 7, 4, 2], 'Rory' => ['Greenhalgh', 7, 4, 1], 'Harley' => ['McShane', 7, 4, 11],
             'Jimmy' => ['Abram', 7, 1, 2], 'Denis' => ['Ejupi', 7, 12, 1], 'Henry' => ['Jenkins-Breen', 7, 0, 1], 'Sharo' => ['Shkar Al-Jaf', 7, 0, 0]];
    foreach ($S->players as $pl) if ($pl->team === 'u10g' && isset($data[$pl->name])) { [$last, $apps, $g, $as] = $data[$pl->name]; if (empty($pl->last)) $pl->last = $last; $pl->base = (object)['apps' => $apps, 'goals' => $g, 'ast' => $as]; }
    $S->mig->u10g_stats_1 = time(); $done = true;
  }
  if (empty($S->mig->camps_only_1)) { if (!isset($S->teams->camps)) $S->teams->camps = (object)['name' => 'General · no squad', 'short' => 'General', 'fmt' => 0, 'sub' => 'Not in a squad · camps, 1-1s & events', 'campsOnly' => true];
    $S->mig->camps_only_1 = time(); $done = true; }
  if (empty($S->mig->camps_only_2) && isset($S->teams->camps)) { $S->teams->camps->name = 'General · no squad'; $S->teams->camps->short = 'General'; $S->teams->camps->sub = 'Not in a squad · camps, 1-1s & events'; $S->mig->camps_only_2 = time(); $done = true; }
  if (empty($S->mig->loyalty_1)) { $ids = []; foreach (($S->sessions ?? []) as $x) if (stripos($x->title ?? '', 'Monday Development') !== false) $ids[] = $x->id;
    if (!isset($S->loyalty)) $S->loyalty = (object)['on' => true, 'sessions' => $ids, 'need' => 11, 'reward' => '£5 off your next block'];
    if (!isset($S->stamps)) $S->stamps = new stdClass; $S->mig->loyalty_1 = time(); $done = true; }
  return $done;
}
function atomic_json_write($file, $value) {
  $tmp = $file . '.tmp.' . bin2hex(random_bytes(4));
  $json = json_encode($value, JSON_UNESCAPED_UNICODE);
  if ($json === false || @file_put_contents($tmp, $json, LOCK_EX) === false) { @unlink($tmp); throw new RuntimeException('Could not write application data'); }
  @chmod($tmp, 0600);
  if (!@rename($tmp, $file)) { @unlink($tmp); throw new RuntimeException('Could not commit application data'); }
  return true;
}
function save_state($st) { global $DIR; atomic_json_write("$DIR/state.json", $st);
  $d = date('Y-m-d'); if (!file_exists("$DIR/backup-$d.json")) { @copy("$DIR/state.json", "$DIR/backup-$d.json"); foreach (glob("$DIR/backup-*.json") as $b) if (filemtime($b) < time() - 30 * 86400) @unlink($b); } }
function load_accounts() { global $DIR; $f = "$DIR/accounts.json";
  if (!file_exists($f)) { $A = []; foreach (STARTER as $s) $A[] = ['id' => $s['id'], 'role' => $s['role'], 'name' => $s['name'], 'email' => $s['email'], 'mobile' => $s['mobile'], 'pass' => password_hash($s['pw'], PASSWORD_DEFAULT), 'status' => 'approved', 'tokens' => [], 'created' => time()]; file_put_contents($f, json_encode($A)); return $A; }
  $x = json_decode(@file_get_contents($f) ?: '[]', true); $x = is_array($x) ? $x : [];
  // Remove the retired hidden support account and its tokens from existing installations.
  $clean = array_values(array_filter($x, fn($a) => !is_array($a) || ($a['id'] ?? '') !== 'npc_support'));
  if (count($clean) !== count($x)) save_accounts($clean);
  return $clean; }
function save_accounts($A) { global $DIR; atomic_json_write("$DIR/accounts.json", $A); }


