function mail_html($title, $inner) {
  return '<div style="background:#040a06;padding:28px 12px;font-family:Arial,sans-serif"><div style="max-width:520px;margin:0 auto;background:#0b1710;border:1px solid #1d3324;border-radius:18px;padding:28px;color:#eef5ef">'
   . '<div style="font-size:12px;letter-spacing:3px;color:#c4ff4d;font-weight:bold">AG COACHING FC</div><h1 style="font-size:24px;margin:8px 0 16px;color:#ffffff">' . htmlspecialchars($title) . '</h1>'
   . '<div style="font-size:15px;line-height:1.6;color:#d8e4da">' . $inner . '</div><p style="font-size:11px;color:#8ea292;margin-top:26px">AG Coaching FC club app · designed &amp; created by North Point Creative</p></div></div>'; }
function send_mail($to, $subject, $html, $att = null, $replyTo = null) {
  $b = '=_agfc' . bin2hex(random_bytes(8));
  $reply = is_string($replyTo) && filter_var($replyTo, FILTER_VALIDATE_EMAIL) ? $replyTo : HEAD_COACH_EMAIL;
  $h = 'From: AG Coaching FC <' . MAIL_FROM . ">\r\nReply-To: " . $reply . "\r\nMIME-Version: 1.0\r\n";
  if ($att) { $h .= "Content-Type: multipart/mixed; boundary=\"$b\"\r\n";
    $body = "--$b\r\nContent-Type: text/html; charset=UTF-8\r\nContent-Transfer-Encoding: base64\r\n\r\n" . chunk_split(base64_encode($html))
      . "--$b\r\nContent-Type: application/zip; name=\"{$att[0]}\"\r\nContent-Transfer-Encoding: base64\r\nContent-Disposition: attachment; filename=\"{$att[0]}\"\r\n\r\n" . chunk_split(base64_encode($att[1])) . "--$b--\r\n"; }
  else { $h .= "Content-Type: text/html; charset=UTF-8\r\nContent-Transfer-Encoding: base64\r\n"; $body = chunk_split(base64_encode($html)); }
  return @mail($to, '=?UTF-8?B?' . base64_encode($subject) . '?=', $body, $h, '-f' . MAIL_FROM); }
function zip_store($files) { $data = ''; $cen = ''; $n = 0;
  foreach ($files as $name => $body) { $crc = crc32($body); $len = strlen($body); $off = strlen($data);
    $data .= pack('VvvvvvVVVvv', 0x04034b50, 20, 0x0800, 0, 0, 0x21, $crc, $len, $len, strlen($name), 0) . $name . $body;
    $cen .= pack('VvvvvvvVVVvvvvvVV', 0x02014b50, 20, 20, 0x0800, 0, 0, 0x21, $crc, $len, $len, strlen($name), 0, 0, 0, 0, 0, $off) . $name; $n++; }
  return $data . $cen . pack('VvvvvVVv', 0x06054b50, 0, 0, $n, $n, strlen($cen), strlen($data), 0); }
function backup_zip() { global $DIR;
  $A = json_decode(@file_get_contents("$DIR/accounts.json") ?: '[]', true) ?: []; foreach ($A as &$x) { unset($x['tokens'], $x['admin_tokens'], $x['reset_hash'], $x['reset_exp']); } unset($x);
  $f = ['state.json' => @file_get_contents("$DIR/state.json") ?: '{}', 'accounts.json' => json_encode($A, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE),
    'README.txt' => "AG Coaching FC app backup, " . date('d/m/Y H:i') . "\r\n\r\nstate.json = all club data (players, fixtures, chats, bookings).\r\naccounts.json = log-ins (passwords are scrambled, not readable).\r\n\r\nTo restore: ask North Point Creative (hello@northpointcreative.co.uk).\r\nThis file contains children's medical information and parents' contact details. Keep it safe.\r\n"];
  $qrToken = checkin_token_get(false); if ($qrToken !== '') $f['checkin-token'] = $qrToken; // preserve the permanent printed QR code in backups
  foreach ([0, 1] as $k) { $m = date('Y-m', strtotime("first day of -$k month")); if (is_file("$DIR/stats/$m.log")) $f["stats/$m.log"] = file_get_contents("$DIR/stats/$m.log"); }
  return zip_store($f); }
function weekly_backup() { global $DIR; $f = "$DIR/last_backup_mail";
  if (time() - (int)@file_get_contents($f) < 7 * 86400) return; @file_put_contents($f, (string)time());
  $st = json_decode(@file_get_contents("$DIR/state.json") ?: '{}'); $np = 0; foreach ($st->S->users ?? [] as $u) if (($u->role ?? '') === 'parent') $np++;
  send_mail(BACKUP_TO, 'AG Coaching FC · weekly app backup · ' . date('d/m/Y'), mail_html('Weekly backup', '<p>Here is this week\'s automatic backup of the club app (' . $np . ' parents &amp; guardians, ' . count($st->S->players ?? []) . ' players).</p><p>Keep this email. If anything ever happened to the website, everything can be put back from the attached file. Chat photos are kept on the server and in the full backup in the back office.</p><p style="color:#ffc93c">🔒 The file contains children\'s medical information and parents\' contact details. Don\'t forward it.</p>'),
    ['AGFC-backup-' . date('Y-m-d') . '.zip', backup_zip()]); }
function error_alert() { global $DIR; $f = "$DIR/last_alert";
  if (time() - (int)@file_get_contents($f) < 3600) return; $lines = @file("$DIR/errors.log", FILE_IGNORE_NEW_LINES) ?: []; if (!$lines) return;
  $since = (int)@file_get_contents("$DIR/last_alert_line"); $new = array_slice($lines, $since); if (!$new) return;
  @file_put_contents($f, (string)time()); @file_put_contents("$DIR/last_alert_line", (string)count($lines));
  send_mail(ALERT_TO, '⚠️ AG Coaching FC app: ' . count($new) . ' error' . (count($new) > 1 ? 's' : ''), mail_html('App error alert', '<p>The app logged ' . count($new) . ' new error' . (count($new) > 1 ? 's' : '') . ':</p><pre style="white-space:pre-wrap;font-size:12px;background:#000;padding:12px;border-radius:10px;color:#ffb3b3">' . htmlspecialchars(implode("\n", array_slice($new, -15))) . '</pre><p>Full list: ' . SITE_URL . 'index.php?a=stats</p>')); }
register_shutdown_function(function () { global $DIR;
  $e = error_get_last();
  if ($e && in_array($e['type'], [E_ERROR, E_PARSE, E_CORE_ERROR, E_COMPILE_ERROR], true)) @file_put_contents("$DIR/errors.log", date('c') . ' | PHP: ' . substr($e['message'], 0, 250) . ' @' . basename($e['file']) . ':' . $e['line'] . "\n", FILE_APPEND | LOCK_EX);
  if (function_exists('fastcgi_finish_request')) @fastcgi_finish_request();
  try { weekly_backup(); error_alert(); } catch (Throwable $t) {} });

/* ---------------- helpers ---------------- */
function gz($body) { // compress big replies when the phone accepts it (much faster on mobile data)
  if (strlen($body) > 1400 && strpos($_SERVER['HTTP_ACCEPT_ENCODING'] ?? '', 'gzip') !== false && function_exists('gzencode') && !ini_get('zlib.output_compression') && !headers_sent()) { header('Content-Encoding: gzip'); header('Vary: Accept-Encoding'); return gzencode($body, 5); }
  return $body; }
function out($x, $code = 200) { http_response_code($code); header('Content-Type: application/json'); header('Cache-Control: no-store'); $b = gz(json_encode($x, JSON_UNESCAPED_UNICODE)); header('Content-Length: ' . strlen($b)); echo $b; exit; }
function fail($msg, $code = 400) { out(['ok' => false, 'error' => $msg], $code); }
function body() { $j = json_decode(file_get_contents('php://input')); return $j ?: new stdClass; }
function rid($p) { return $p . bin2hex(random_bytes(5)); }
function first_name($n) { return explode(' ', trim($n))[0]; }
function token_cookie($t) { setcookie('agfc', $t, ['expires' => time() + 400 * 86400, 'path' => dirname($_SERVER['SCRIPT_NAME']) ?: '/', 'httponly' => true, 'samesite' => 'Lax', 'secure' => !empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off']); }
function current_account(&$A) {
  $t = $_COOKIE['agfc'] ?? ''; if (strlen($t) < 20) return null; $h = hash('sha256', $t);
  foreach ($A as $i => $acc) if (in_array($h, $acc['tokens'] ?? [], true)) return $i;
  return null;
}
function eff($acc) { if ($acc && !empty($acc['hidden']) && ($acc['view'] ?? '') === 'parent') $acc['role'] = 'parent'; return $acc; }
function public_user($acc) { return ['hidden' => !empty($acc['hidden']), 'view' => $acc['view'] ?? 'coach', 'viewas' => $acc['viewas'] ?? '', 'id' => $acc['id'], 'name' => $acc['name'], 'first' => first_name($acc['name']), 'role' => $acc['role'], 'status' => $acc['status'], 'email' => $acc['email'], 'mobile' => $acc['mobile'] ?? '', 'cal' => empty($acc['hidden']) ? cal_sig($acc['id']) : '']; }
function cal_sig($id) { return substr(hash_hmac('sha256', 'cal|' . $id, SECRET), 0, 20); }
function need_ajax() { if (($_SERVER['HTTP_X_AGFC'] ?? '') !== '1') fail('Bad request'); }

/* ---------------- what each person may see ---------------- */
function pars($p) { $o = []; if (!empty($p->parent)) $o[] = $p->parent; foreach (($p->parents ?? []) as $x) if ($x) $o[] = $x; return array_values(array_unique($o)); }
function own_info($S, $uid) {
  $own = []; $teams = [];
  foreach ($S->players as $p) if (in_array($uid, pars($p), true)) { $own[] = $p->id; $teams[] = $p->team; }
  $groups = [];
  foreach (($S->groups ?? []) as $g) {
    if (!empty($g->coaches)) continue;
    $in = !empty($g->all) || (!empty($g->teams) && array_intersect($g->teams, $teams));
    if (!$in && !empty($g->camp)) foreach (($S->campBk ?? []) as $b) if ($b->camp === $g->camp && ($b->uid ?? '') === $uid) $in = true;
    if ($in) $groups[] = $g->id;
  }
  return [$own, array_values(array_unique($teams)), $groups];
}
// who is in each group chat (for "Seen by"), first names only: [[uid, label], ...]
function group_mem($S) { $out = []; $ppl = [];
  foreach ($S->users as $u) $ppl[$u->id] = $u;
  foreach (($S->groups ?? []) as $g) { $m = [];
    foreach ($S->users as $u) if ($u->role === 'coach') $m[$u->id] = 'Coach ' . ($u->first ?? first_name($u->name));
    if (empty($g->coaches)) { $kids = [];
      if (!empty($g->all) || !empty($g->teams)) foreach ($S->players as $pl) if (!empty($g->all) || in_array($pl->team, (array)$g->teams, true)) foreach (pars($pl) as $x) $kids[$x][] = $pl->name;
      if (!empty($g->camp)) foreach (($S->campBk ?? []) as $b) if ($b->camp === $g->camp && !empty($b->uid)) $kids[$b->uid][] = $b->child ?? '';
