  $keep('bookings', function ($b) use ($uid) { return ($b->user ?? '') === $uid; });
  $keep('campBk', function ($b) use ($uid) { return ($b->uid ?? '') === $uid; });
  $keep('payments', function ($x) use ($uid) { return ($x->uid ?? '') === $uid; });
  $keep('threads', function ($t) use ($uid) { return ($t->fam ?? '') === $uid; });
  $keep('groups', function ($g) use ($groups) { return in_array($g->id, $groups, true); });
