    if (!$path) return false; $last = end($path); $par = &nav($S, array_slice($path, 0, -1), $t === 'set'); if ($par === null) return false;
    if (is_object($par)) { $k = (string)$last; if ($t === 'set') $par->$k = $op->value ?? null; else unset($par->$k); return true; }
    if (is_array($par)) {
      if (is_string($last) && $last !== '' && $last[0] === '#') { foreach ($par as $i => $v) if (is_object($v) && isset($v->id) && (string)$v->id === substr($last, 1)) { if ($t === 'set') $par[$i] = $op->value; else array_splice($par, $i, 1); return true; } return false; }
      if ($t === 'set') $par[$last] = $op->value ?? null; else { if (array_key_exists($last, $par)) array_splice($par, (int)$last, 1); } return true;
    }
    return false;
  }
