  if ($t === 'remove') { $id = (string)($op->id ?? ''); $arr = array_values(array_filter($arr, function ($x) use ($id) { return !(is_object($x) && isset($x->id) && (string)$x->id === $id); })); return true; }
  if ($t === 'append') { foreach (($op->items ?? []) as $x) $arr[] = $x; if (count($arr) > 2000) $arr = array_slice($arr, -2000); return true; }
  if ($t === 'prepend') { $arr = array_slice(array_merge($op->items ?? [], $arr), 0, max(1, min(200, (int)($op->max ?? 200)))); return true; }
  return false;
}

/* ---------------- chat extras: reactions, edits, photos ---------------- */
const REACTS = ['❤️', '😂', '👍', '😮', '😢', '🙏', '👏', '⚽'];
function photo_ok($f) { global $DIR; return is_string($f) && preg_match('/^[a-f0-9]{24}\.jpg$/', $f) && is_file("$DIR/photos/$f"); }
function audio_ok($f) { global $DIR; return is_string($f) && preg_match('/^[a-f0-9]{24}\.(webm|m4a|ogg|aac|wav)$/', $f) && is_file("$DIR/audio/$f"); }
function clean_msg($m) { if (isset($m->img) && !photo_ok($m->img)) unset($m->img); if (isset($m->audio) && !audio_ok($m->audio)) unset($m->audio, $m->dur); if (isset($m->audio)) $m->dur = max(1, min(20, (int)($m->dur ?? 1))); unset($m->re, $m->ed, $m->del); }
function react_ok($op, $m, $uid) { global $acc; $p = $op->path; $n = count($p); $t = $op->op;
  $fix = function ($v) use ($acc) { return is_object($v) && in_array($v->e ?? '', REACTS, true) ? (object)['e' => $v->e, 'n' => first_name($acc['name'] ?? 'Parent')] : null; };
  if ($n === 6 && (string)$p[5] === $uid) { if ($t === 'del') return true; if ($t === 'set' && ($v = $fix($op->value))) { $op->value = $v; return true; } return false; }
