  return false; }
function msg_edit_ok($op) { $k = (string)($op->path[4] ?? ''); $t = $op->op;
  if ($k === 't' && $t === 'set') { $op->value = mb_substr((string)$op->value, 0, 2000); return true; }
  if (in_array($k, ['ed', 'del'], true) && $t === 'set') return is_numeric($op->value);
  if (in_array($k, ['img', 'audio', 'dur', 're'], true) && $t === 'del') return true;
  return false; }
function msg_txt($m) { if (!empty($m->del)) return ''; $t = trim((string)($m->t ?? $m->text ?? '')); if (!empty($m->img)) return $t === '' ? '📷 Photo' : "📷 $t"; return !empty($m->audio) ? ($t === '' ? '🎤 Voice note' : "🎤 $t") : $t; }
function all_imgs($S) { $o = []; foreach (['groups', 'threads'] as $k) foreach (($S->$k ?? []) as $g) foreach (($g->msgs ?? []) as $m) if (!empty($m->img)) $o[] = $m->img;
  foreach (($S->messages ?? []) as $m) if (!empty($m->img)) $o[] = $m->img;
