  return array_values(array_unique($o)); }
function all_audio($S) { $o = []; foreach (['groups', 'threads'] as $k) foreach (($S->$k ?? []) as $c) foreach (($c->msgs ?? []) as $m) if (!empty($m->audio)) $o[] = $m->audio; return array_values(array_unique($o)); }

/* ---------------- what a parent is allowed to change ---------------- */
function keys_ok($v, $allowed) { if (!is_object($v)) return false; foreach (get_object_vars($v) as $k => $_) if (!in_array((string)$k, $allowed, true)) return false; return true; }
function parent_may(&$op, $S, $uid, $own, $groups) {
  $p = $op->path; $t = $op->op; $n = count($p); $s0 = $p[0] ?? ''; $id = fn($i) => substr((string)($p[$i] ?? ''), 1);
  switch ($s0) {
    case 'fixtures':
      if ($n === 4 && $p[2] === 'avail' && in_array($t, ['set', 'del'], true)) return in_array((string)$p[3], $own, true);
      if ($n === 3 && $p[2] === 'avail' && $t === 'set') return keys_ok($op->value, $own) && !get_object_vars((object)(get_at($S, $p) ?? []));
      if ($n === 3 && $p[2] === 'plan' && $t === 'set') return ($op->value ?? null) === null;
      return false;
    case 'rsvp':
      if ($n === 3 && in_array($t, ['set', 'del'], true)) return in_array((string)$p[2], $own, true);
      if ($n === 2 && $t === 'set') return keys_ok($op->value, $own);
      return false;
    case 'players':
      if ($n === 3 && $p[2] === 'dob' && in_array($id(1), $own, true) && in_array($t, ['set','del'], true)) { if ($t === 'del') return true; $v = (string)($op->value ?? ''); if ($v === '') return true; if (!preg_match('/^(\d{4})-(\d{2})-(\d{2})$/', $v, $m)) return false; return checkdate((int)$m[2], (int)$m[3], (int)$m[1]) && $v <= date('Y-m-d'); }
      if ($n >= 3 && $p[2] === 'info' && in_array($id(1), $own, true)) {
        if ($n !== 4 || !in_array((string)$p[3], ['med', 'emer', 'photo'], true) || !in_array($t, ['set', 'del'], true)) return false;
        if ($t === 'del') return true;
        if ($p[3] === 'photo') return is_bool($op->value ?? null);
        if (!is_string($op->value ?? null)) return false;
        $op->value = mb_substr(trim($op->value), 0, 1000);
        return true;
      }
      return false;
    case 'threads':
      if ($n === 1 && $t === 'upsert') {
        if (!is_object($op->value) || ($op->value->fam ?? '') !== $uid || !empty(get_at($S, ['threads', '#' . ($op->value->id ?? '')]))) return false;
        if (!keys_ok($op->value, ['id', 'fam', 'name', 'kid', 'msgs', 'cu', 'pu'])) return false;
        $op->value->name = mb_substr(trim((string)($op->value->name ?? '')), 0, 160);
        $op->value->kid = mb_substr(trim((string)($op->value->kid ?? '')), 0, 120);
        $op->value->msgs = [];
        $op->value->cu = 0; $op->value->pu = 0;
        return true;
      }
      if ($n < 3) return false;
      $th = get_at($S, ['threads', $p[1]]);
      if (!$th || ($th->fam ?? '') !== $uid) return false;
      if ($p[2] === 'msgs' && $t === 'append') {
        if (!is_array($op->items ?? null) || count($op->items) > 20) return false;
        foreach ($op->items as $m) {
          if (!is_object($m)) return false;
          if (!keys_ok($m, ['by', 't', 'ts', 'img', 'audio', 'dur'])) return false;
          // A parent can only append a parent-authored message. Never trust
          // client-supplied author, timestamp, moderation, or reaction fields.
          $m->by = 'p';
          $m->t = mb_substr((string)($m->t ?? ''), 0, 2000);
          $m->ts = (int)(microtime(true) * 1000);
          clean_msg($m);
          if ($m->t === '' && empty($m->img) && empty($m->audio)) return false;
        }
        return true;
      }
      if ($p[2] === 'msgs' && $n >= 5 && is_int($p[3])) {
        $m = get_at($S, ['threads', $p[1], 'msgs', $p[3]]); if (!is_object($m)) return false;
        if ($p[4] === 're') return react_ok($op, $m, $uid);
        return ($m->by ?? '') === 'p' && $n === 5 && msg_edit_ok($op);
      }
      if ($n === 3 && $p[2] === 'cu' && $t === 'set') {
        if (!is_numeric($op->value) || (int)$op->value < 0 || (int)$op->value > 100000) return false;
        // Keep a concurrent coach message's unread count; the parent is only
        // allowed to acknowledge or add to its own locally projected count.
