      return false;
    case 'groups':
      if ($n < 3 || !in_array($id(1), $groups, true)) return false; $g = get_at($S, ['groups', $p[1]]);
      if ($p[2] === 'msgs' && $t === 'append' && empty($g->ro)) {
        if (!is_array($op->items ?? null) || count($op->items) > 20) return false;
        global $acc;
        foreach ($op->items as $m) {
          if (!is_object($m) || !keys_ok($m, ['by', 'uid', 'name', 't', 'ts', 'img', 'audio', 'dur'])) return false;
          $m->by = 'p'; $m->uid = $uid; $m->name = first_name($acc['name'] ?? 'Parent');
          $m->t = mb_substr((string)($m->t ?? ''), 0, 2000); $m->ts = (int)(microtime(true) * 1000); clean_msg($m);
          if ($m->t === '' && empty($m->img) && empty($m->audio)) return false;
        }
        return true;
      }
      if ($p[2] === 'msgs' && $n >= 5 && is_int($p[3])) { $m = get_at($S, ['groups', $p[1], 'msgs', $p[3]]); if (!is_object($m)) return false;
        if ($p[4] === 're') return react_ok($op, $m, $uid);
        return ($m->uid ?? '') === $uid && $n === 5 && msg_edit_ok($op); }
      if ($p[2] === 'read' && $n === 4 && $t === 'set') return (string)$p[3] === $uid;
      if ($p[2] === 'read' && $n === 3 && $t === 'set') return keys_ok($op->value, [$uid]);
      return false;
    case 'notes':
      $x = get_at($S, ['notes', $p[1] ?? '']); return $n === 3 && $p[2] === 'read' && $t === 'set' && $x && ($x->to ?? '') === $uid;
    case 'messages':
      return $n === 3 && $p[2] === 'read' && $t === 'append' && $op->items == [$uid];
    case 'bookings':
      if (is_object($op->value ?? null)) { unset($op->value->att); if (isset($op->value->refBy)) $op->value->refBy = mb_substr((string)$op->value->refBy, 0, 60); }
      return $n === 1 && $t === 'upsert' && is_object($op->value) && ($op->value->user ?? '') === $uid && ($op->value->status ?? '') === 'pending' && !get_at($S, ['bookings', '#' . ($op->value->id ?? '')]);
    case 'campBk':
      return $n === 1 && $t === 'upsert' && is_object($op->value) && ($op->value->uid ?? '') === $uid && in_array($op->value->pid ?? '', $own, true) && !get_at($S, ['campBk', '#' . ($op->value->id ?? '')]);
    case 'slots':
      if ($n === 3 && $p[2] === 'booked' && $t === 'set') { $cur = get_at($S, $p); return empty($cur) && is_object($op->value) && ($op->value->uid ?? '') === $uid; }
      return false;
    case 'events':
      if ($n === 4 && $p[2] === 'rsvp' && $t === 'set') return (string)$p[3] === $uid;
      if ($n === 3 && $p[2] === 'rsvp' && $t === 'set') return keys_ok($op->value, [$uid]);
      return false;
    case 'payments':
      return $n === 1 && $t === 'upsert' && is_object($op->value) && ($op->value->uid ?? '') === $uid && !get_at($S, ['payments', '#' . ($op->value->id ?? '')]);
    case 'activity':
      return $n === 1 && $t === 'prepend' && count($op->items ?? []) <= 3;
  }
  return false;
}

/* ---------------- routes ---------------- */
/* ---------------- visitor stats (Dan only, no cookies, no personal data kept) ---------------- */
const STATS_PASS = 'stats-vWq2y-6-';
function is_bot($ua) { return $ua === '' || preg_match('/bot|crawl|spider|slurp|preview|facebookexternalhit|whatsapp|telegram|discord|curl|wget|python|headless|monitor|uptime/i', $ua); }
function ua_info($ua) {
  $dev = preg_match('/iphone|ipod/i', $ua) ? 'iPhone' : (preg_match('/ipad/i', $ua) ? 'iPad' : (preg_match('/android/i', $ua) ? 'Android' : 'Computer'));
  $br = preg_match('/FBAN|FBAV/i', $ua) ? 'Facebook app' : (preg_match('/Instagram/i', $ua) ? 'Instagram app' : (preg_match('/Edg\//', $ua) ? 'Edge' : (preg_match('/CriOS|Chrome\//', $ua) ? 'Chrome' : (preg_match('/Firefox|FxiOS/', $ua) ? 'Firefox' : (preg_match('/Safari\//', $ua) ? 'Safari' : 'Other')))));
  return [$dev, $br];
}
function track($page, $ev = 'view', $mode = '', $ref = '', $who = null) {
  global $DIR;
  if ($who === null) { $A = load_accounts(); $ai = current_account($A); if ($ai !== null && !empty($A[$ai]['hidden'])) return; $who = $ai === null ? '' : ($A[$ai]['role'] === 'coach' ? $A[$ai]['name'] : 'Parent'); } if ($who === '__hidden') return; $ua = $_SERVER['HTTP_USER_AGENT'] ?? ''; if (is_bot($ua)) return;
  if (!is_dir("$DIR/stats")) @mkdir("$DIR/stats", 0750, true);
  $ip = $_SERVER['HTTP_X_FORWARDED_FOR'] ?? $_SERVER['REMOTE_ADDR'] ?? ''; $ip = trim(explode(',', $ip)[0]);
  $vid = substr(hash('sha256', SECRET . date('Y-m-d') . $ip . $ua), 0, 12); // changes daily, can't be traced back to a person
  [$dev, $br] = ua_info($ua);
  $host = $ref ? (parse_url($ref, PHP_URL_HOST) ?: '') : ''; if ($host === ($_SERVER['HTTP_HOST'] ?? '')) $host = '';
  $line = json_encode(['t' => time(), 'p' => substr($page, 0, 12), 'e' => substr($ev, 0, 16), 'm' => substr($mode, 0, 12), 'v' => $vid, 'd' => $dev, 'b' => $br, 'r' => substr($host, 0, 60), 'u' => substr((string)$who, 0, 40)]) . "\n";
  @file_put_contents("$DIR/stats/" . date('Y-m') . '.log', $line, FILE_APPEND | LOCK_EX);
}
if ($a === 'hit') {
  header('Access-Control-Allow-Origin: *'); $p = preg_replace('/[^a-z]/', '', $_GET['p'] ?? 'app'); $e = preg_replace('/[^a-z_]/', '', $_GET['e'] ?? 'view'); $m = preg_replace('/[^a-z]/', '', $_GET['m'] ?? '');
  track($p ?: 'app', $e ?: 'view', $m, (string)($_GET['r'] ?? ''));
  header('Content-Type: image/gif'); header('Cache-Control: no-store'); echo base64_decode('R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7'); exit;
}
if ($a === 'err') { $line = date('c') . ' | ' . preg_replace('/[\r\n]/', ' ', substr((string)($_GET['m'] ?? ''), 0, 300)) . ' | view=' . substr((string)($_GET['v'] ?? ''), 0, 20) . ' | ' . substr($_SERVER['HTTP_USER_AGENT'] ?? '', 0, 120) . "\n"; @file_put_contents("$DIR/errors.log", $line, FILE_APPEND | LOCK_EX); header('Content-Type: image/gif'); echo base64_decode('R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7'); exit; }
if ($a === 'stats') {
  header('Content-Type: text/html; charset=utf-8'); header('Cache-Control: no-store'); header('X-Robots-Tag: noindex');
  $ok = hash_equals(hash('sha256', STATS_PASS), $_COOKIE['agfcstats'] ?? '');
  if (!$ok && isset($_POST['pw'])) { if (hash_equals(STATS_PASS, (string)$_POST['pw'])) { setcookie('agfcstats', hash('sha256', STATS_PASS), ['expires' => time() + 365 * 86400, 'path' => '/', 'httponly' => true, 'samesite' => 'Lax', 'secure' => !empty($_SERVER['HTTPS'])]); header('Location: ?a=stats'); exit; } sleep(2); }
  $css = '*{box-sizing:border-box;margin:0;padding:0}body{overflow-wrap:anywhere;background:#030805;color:#f3f7f1;font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;padding:20px;max-width:980px;margin:0 auto}h1{font-size:26px;font-weight:900;letter-spacing:-.01em;text-transform:uppercase;font-style:italic}h1 span{color:#3ff36a}h2{font-size:13px;letter-spacing:.18em;text-transform:uppercase;color:#3ff36a;margin:26px 0 10px}.k{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:10px}.c{background:#0c1810;border:1px solid rgba(150,255,170,.12);border-radius:16px;padding:14px}.c small{display:block;color:#8ea292;font-size:12px;font-weight:600}.c b{font-size:30px;font-weight:900;display:block;margin-top:4px}.c em{font-style:normal;color:#8ea292;font-size:12px}table{width:100%;border-collapse:collapse;font-size:14px}td,th{padding:8px 6px;border-bottom:1px solid rgba(150,255,170,.08);text-align:left}th{color:#8ea292;font-size:11px;text-transform:uppercase;letter-spacing:.1em}.bar{height:8px;background:#3ff36a;border-radius:4px}.g2{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:12px}@media(max-width:640px){.g2{grid-template-columns:minmax(0,1fr)}}form{max-width:320px;margin:80px auto;text-align:center}input,button{width:100%;font:inherit;padding:14px;border-radius:12px;margin-top:10px;border:1px solid #224;background:#0c1810;color:#fff}button{background:#3ff36a;color:#04140a;font-weight:800;border:0}.sel a{display:inline-block;padding:6px 12px;border-radius:99px;background:#0c1810;color:#8ea292;text-decoration:none;margin:12px 6px 0 0;font-size:13px;font-weight:700}.sel a.on{background:#3ff36a;color:#04140a}svg text{fill:#8ea292;font-size:10px}';
