  echo "<h2>Overview · last $days day" . ($days > 1 ? 's' : '') . "</h2><div class=k>" . $c('Visitors', $uniq($views), 'unique per day') . $c('Page views', count($views), 'all pages') . $c('Today', $uniq($today), count($today) . ' views') . $c('App opens', count($app), count($inst) . ' from home screen') . $c('Coming soon page', count($soon), $uniq($soon) . ' visitors') . $c('Installs', $ev('install'), $ev('install_screen') . ' saw install screen') . $c('Log-ins', $ev('login'), '') . $c('Sign-ups', $ev('signup'), 'new parents & coaches') . "</div>";
