  $modeName = array_map(function ($x) { $x['m'] = $x['p'] !== 'app' ? 'Website page' : ($x['m'] === 'standalone' ? 'Home screen app' : 'Browser'); return $x; }, $views);
  $pageName = array_map(function ($x) { $x['p'] = ['app' => 'App'][$x['p']] ?? $x['p']; return $x; }, $views);
  echo "<div class=g2 style='margin-top:12px'>" . $tbl('Devices', $views, 'd') . $tbl('Browsers', $views, 'b') . $tbl('How they open it', $modeName, 'm') . $tbl('Pages', $pageName, 'p') . $tbl('Came from', array_filter($views, fn($x) => $x['r'] !== ''), 'r') . "</div>";
  $co = []; foreach ($rows as $x) { $u = $x['u'] ?? ''; if ($u === '' || $u === 'Parent') continue; $co[$u] ??= ['all' => 0, 'today' => 0, 'week' => 0, 'last' => 0, 'dev' => []];
