  $par = array_filter($views, fn($x) => ($x['u'] ?? '') === 'Parent');
  $ago = function ($t) { $s = time() - $t; return $s < 120 ? 'just now' : ($s < 3600 ? floor($s / 60) . ' mins ago' : ($s < 86400 ? floor($s / 3600) . ' hrs ago' : date('D j M H:i', $t))); };
  echo "<h2>Coaches · who's been on</h2><div class=c><table><tr><th>Coach</th><th>Today</th><th>7 days</th><th>This period</th><th>Last seen</th></tr>";
  foreach ($co as $n => $v) echo "<tr><td><b style='font-size:15px;display:inline'>" . htmlspecialchars($n) . "</b><br><span style='color:#8ea292;font-size:12px'>" . htmlspecialchars(implode(', ', array_keys($v['dev']))) . "</span></td><td>{$v['today']}</td><td>{$v['week']}</td><td>{$v['all']}</td><td>" . $ago($v['last']) . "</td></tr>";
  if (!$co) echo "<tr><td colspan=5>No coach visits yet</td></tr>";
  echo "</table><em>Each time the app is opened, or brought back after 5+ minutes away, counts as a visit.</em></div>";
  echo "<div class=k style='margin-top:10px'>" . $c('Parent visits', count($par), $uniq($par) . ' different parents') . $c('Not logged in', count(array_filter($views, fn($x) => ($x['u'] ?? '') === '')), 'visitors') . "</div>";
  echo "<h2>Latest</h2><div class=c><table><tr><th>When</th><th>Who</th><th>What</th><th>Device</th><th>How</th></tr>";
  $names = ['view' => 'Visit', 'login' => 'Log-in', 'signup' => 'Sign-up', 'install' => 'Installed app', 'install_screen' => 'Saw install screen'];
  foreach (array_slice(array_reverse($rows), 0, 40) as $x) echo "<tr><td>" . date('D j M H:i', $x['t']) . "</td><td>" . htmlspecialchars(($x['u'] ?? '') ?: 'Visitor') . "</td><td>" . ($names[$x['e']] ?? $x['e']) . ($x['p'] === 'soon' ? ' · coming soon' : '') . "</td><td>{$x['d']} · {$x['b']}</td><td>" . ($x['m'] === 'standalone' ? 'Home screen' : ($x['p'] === 'app' ? 'Browser' : '')) . "</td></tr>";
