function b64u($b) { return rtrim(strtr(base64_encode($b), '+/', '-_'), '='); }
function b64u_dec($s) { return base64_decode(strtr($s, '-_', '+/') . str_repeat('=', (4 - strlen($s) % 4) % 4)); }
function der_to_raw($der) {
  $o = 2; if (ord($der[1]) & 0x80) $o += ord($der[1]) & 0x7f;
  $out = '';
  for ($k = 0; $k < 2; $k++) { $o++; $len = ord($der[$o++]); $v = substr($der, $o, $len); $o += $len; $v = ltrim($v, "\0"); $out .= str_pad($v, 32, "\0", STR_PAD_LEFT); }
  return $out;
