function vapid_header($endpoint) {
  $p = parse_url($endpoint); $aud = $p['scheme'] . '://' . $p['host'];
  $h = b64u(json_encode(['typ' => 'JWT', 'alg' => 'ES256'])); $c = b64u(json_encode(['aud' => $aud, 'exp' => time() + 12 * 3600, 'sub' => VAPID_SUB]));
