function point_to_pem($pt) { return "-----BEGIN PUBLIC KEY-----\n" . chunk_split(base64_encode(hex2bin('3059301306072a8648ce3d020106082a8648ce3d030107034200') . $pt), 64, "\n") . "-----END PUBLIC KEY-----\n"; }
function push_encrypt($payload, $p256dh, $auth) {
