function load_subs() { global $DIR; $x = json_decode(@file_get_contents("$DIR/push.json") ?: '[]', true); return is_array($x) ? $x : []; }
function save_subs($s) { global $DIR; atomic_json_write("$DIR/push.json", array_values($s)); }
// $jobs: [ [uids[], title, body, tag], ... ]
function send_pushes($jobs) {
  if (!$jobs || !function_exists('curl_multi_init')) return;
  $subs = load_subs(); if (!$subs) return;
  $mh = curl_multi_init(); $hs = [];
  foreach ($jobs as [$uids, $title, $body, $tag]) {
    $payload = json_encode(['title' => $title, 'body' => mb_substr($body, 0, 180), 'tag' => $tag], JSON_UNESCAPED_UNICODE);
    foreach ($subs as $i => $s) {
      if (!in_array($s['uid'], $uids, true)) continue;
      $enc = push_encrypt($payload, $s['p256dh'], $s['auth']); if ($enc === null) continue;
      $ch = curl_init($s['endpoint']);
      curl_setopt_array($ch, [CURLOPT_POST => true, CURLOPT_POSTFIELDS => $enc, CURLOPT_RETURNTRANSFER => true, CURLOPT_TIMEOUT => 6, CURLOPT_CONNECTTIMEOUT => 3,
        CURLOPT_HTTPHEADER => ['Authorization: ' . vapid_header($s['endpoint']), 'Content-Encoding: aes128gcm', 'Content-Type: application/octet-stream', 'TTL: 86400', 'Urgency: high']]);
      curl_multi_add_handle($mh, $ch); $hs[] = [$ch, $i];
    }
  }
  do { $st = curl_multi_exec($mh, $run); if ($run) curl_multi_select($mh, 1); } while ($run && $st === CURLM_OK);
  $dead = [];
  foreach ($hs as [$ch, $i]) { $code = curl_getinfo($ch, CURLINFO_HTTP_CODE); if (in_array($code, [404, 410], true)) $dead[] = $i; curl_multi_remove_handle($mh, $ch); curl_close($ch); }
  curl_multi_close($mh);
  if ($dead) { $L = lock(); $subs = load_subs(); foreach ($dead as $i) unset($subs[$i]); save_subs($subs); unlock($L); }
}
function finish_then($fn) { // reply to the phone first, then send notifications
