  ignore_user_abort(true); @set_time_limit(30); $fn();
}
// who should hear about what changed
function push_jobs($old, $new, $actor) {
  $jobs = []; $coaches = []; foreach ($new->users as $u) if ($u->role === 'coach' && $u->id !== $actor) $coaches[] = $u->id;
  $ids = fn($arr) => array_flip(array_map(fn($x) => (string)($x->id ?? ''), (array)$arr));
  $parentsOfTeams = function ($teams) use ($new, $actor) { $o = []; foreach ($new->players as $p) if (in_array($p->team, (array)$teams, true)) foreach (pars($p) as $u) if ($u !== $actor) $o[] = $u; return array_values(array_unique($o)); };
  $oldN = $ids($old->notes ?? []); foreach (($new->notes ?? []) as $n) if (!isset($oldN[(string)$n->id]) && ($n->to ?? '') !== $actor) $jobs[] = [[$n->to], 'AG Coaching FC', trim(($n->ic ?? '') . ' ' . ($n->t ?? '')), 'n'];
  $oldM = $ids($old->messages ?? []); foreach (($new->messages ?? []) as $m) if (!isset($oldM[(string)$m->id])) $jobs[] = [$parentsOfTeams($m->teams ?? []), 'Coach Alfie', msg_txt($m), 'club'];
  $og = []; foreach (($old->groups ?? []) as $g) $og[$g->id] = count($g->msgs ?? []);
  foreach (($new->groups ?? []) as $g) { $n0 = $og[$g->id] ?? 0; $msgs = $g->msgs ?? []; if (count($msgs) <= $n0) continue;
    if (!empty($g->coaches)) $to = $coaches; else { $to = $coaches; if (!empty($g->all)) foreach ($new->users as $u) { if ($u->role === 'parent') $to[] = $u->id; } elseif (!empty($g->teams)) $to = array_merge($to, $parentsOfTeams($g->teams)); elseif (!empty($g->camp)) foreach (($new->campBk ?? []) as $b) if ($b->camp === $g->camp) $to[] = $b->uid; }
    $to = array_values(array_diff(array_unique($to), [$actor])); $last = end($msgs);
    $jobs[] = [$to, $g->name, (($last->by ?? '') === 'coach' ? 'Coach' : first_name((string)($last->name ?? 'Parent'))) . ': ' . msg_txt($last), 'g_' . $g->id]; }
  $ot = []; foreach (($old->threads ?? []) as $t) $ot[$t->id] = count($t->msgs ?? []);
  foreach (($new->threads ?? []) as $t) { $msgs = $t->msgs ?? []; if (count($msgs) <= ($ot[$t->id] ?? 0)) continue; $last = end($msgs);
    if (($last->by ?? '') === 'p') $jobs[] = [$coaches, $t->name ?? 'Parent', msg_txt($last), 't_' . $t->id];
    else if (($t->fam ?? '') !== $actor) $jobs[] = [[$t->fam], 'Coach Alfie', msg_txt($last), 't_' . $t->id]; }
  $ob = $ids($old->bookings ?? []); foreach (($new->bookings ?? []) as $b) if (!isset($ob[(string)$b->id])) $jobs[] = [$coaches, 'New taster request', ($b->child ?? '') . ' · ' . ($b->parent ?? ''), 'taster'];
  $oc = $ids($old->campBk ?? []); foreach (($new->campBk ?? []) as $b) if (!isset($oc[(string)$b->id])) $jobs[] = [$coaches, 'Camp booking', ($b->child ?? '') . ' booked onto camp', 'camp'];
  $os = []; foreach (($old->slots ?? []) as $s) $os[$s->id] = !empty($s->booked); foreach (($new->slots ?? []) as $s) if (!empty($s->booked) && empty($os[$s->id]) && ($s->booked->uid ?? '') === $actor) $jobs[] = [$coaches, '1-1 booked', ($s->booked->name ?? '') . ' · ' . date('D j M H:i', (int)($s->at / 1000)), 'one'];
  return array_values(array_filter($jobs, fn($j) => $j[0]));
}
