/* -------- coach removes a player/guardian family and its private chats -------- */
if ($a === 'removefamily') {
  need_ajax();
  if (!$acc || ($acc['role'] ?? '') !== 'coach' || !empty($acc['hidden']) || ($acc['status'] ?? '') !== 'approved') fail('Coach access required', 403);
  $b = body(); $playerId = preg_replace('~[^A-Za-z0-9_-]~', '', (string)($b->playerId ?? '')); $parentId = preg_replace('~[^A-Za-z0-9_-]~', '', (string)($b->parentId ?? ''));
  if (($playerId === '') === ($parentId === '')) fail('Choose one player or parent to remove');
  $L = lock(); $st = load_state(); $S = $st->S; $A = load_accounts();
  $players = $S->players ?? []; $users = $S->users ?? [];
  $playerMap = []; foreach ($players as $pl) $playerMap[(string)($pl->id ?? '')] = $pl;
  $userMap = []; foreach ($users as $u) $userMap[(string)($u->id ?? '')] = $u;
  $parentSet = []; $playerSet = [];
  if ($playerId !== '') { if (!isset($playerMap[$playerId])) { unlock($L); fail('Player not found'); } $playerSet[$playerId] = true; }
  if ($parentId !== '') {
    $valid = false; foreach ($A as $x) if (($x['id'] ?? '') === $parentId && ($x['role'] ?? '') === 'parent' && ($x['status'] ?? '') !== 'removed') { $valid = true; break; }
    if (!$valid || !isset($userMap[$parentId])) { unlock($L); fail('Parent account not found'); }
    $parentSet[$parentId] = true;
  }
  // Remove the connected family: all guardians linked to the selected player(s),
  // and all children linked to those guardians. Iterate for shared guardians safely.
  do { $changed = false;
    foreach ($players as $pl) {
      $pid = (string)($pl->id ?? ''); $pars = pars($pl);
      if (isset($playerSet[$pid])) foreach ($pars as $uid) if ($uid && !isset($parentSet[$uid])) { $parentSet[$uid] = true; $changed = true; }
      foreach ($pars as $uid) if (isset($parentSet[$uid]) && !isset($playerSet[$pid])) { $playerSet[$pid] = true; $changed = true; }
    }
  } while ($changed);
  $parentNames = []; foreach ($parentSet as $uid => $_) if (isset($userMap[$uid])) $parentNames[] = (string)$userMap[$uid]->name;
  $playerNames = []; foreach ($playerSet as $pid => $_) if (isset($playerMap[$pid])) $playerNames[] = (string)$playerMap[$pid]->name;
  if (!$parentSet && !$playerSet) { unlock($L); fail('No linked family records were found'); }
  $old = json_decode(json_encode($S)); $now = (int)(microtime(true) * 1000);
  foreach ($A as $i => $x) if (isset($parentSet[$x['id'] ?? '']) && ($x['role'] ?? '') === 'parent') { $A[$i]['status'] = 'removed'; $A[$i]['tokens'] = []; }
  save_accounts($A);
  $S->users = array_values(array_filter($users, fn($u) => !isset($parentSet[(string)($u->id ?? '')])));
  $S->players = array_values(array_filter($players, fn($pl) => !isset($playerSet[(string)($pl->id ?? '')])));
  $S->threads = array_values(array_filter($S->threads ?? [], fn($t) => !isset($parentSet[(string)($t->fam ?? '')])));
  $S->requests = array_values(array_filter($S->requests ?? [], fn($r) => !isset($parentSet[(string)($r->uid ?? '')])));
  if (isset($S->notes)) $S->notes = array_values(array_filter((array)$S->notes, fn($n) => !isset($parentSet[(string)($n->to ?? '')])));
  $S->removed = array_values(array_unique(array_merge((array)($S->removed ?? []), array_keys($parentSet))));
  $label = implode(', ', array_filter($playerNames)); if ($label === '') $label = implode(', ', array_filter($parentNames));
  array_unshift($S->activity, (object)['ic' => '👋', 't' => $label . ' and linked family removed from the app', 'ts' => $now]);
  $st->S = $S; $st->rev++; save_state($st);
  save_subs(array_values(array_filter(load_subs(), fn($sub) => !isset($parentSet[(string)($sub['uid'] ?? '')]))));
  foreach (array_diff(all_imgs($old), all_imgs($S)) as $f) if (photo_ok($f)) @unlink("$DIR/photos/$f");
  foreach (array_diff(all_audio($old), all_audio($S)) as $f) if (audio_ok($f)) @unlink("$DIR/audio/$f");
  unlock($L);
  out(['ok' => true, 'rev' => $st->rev, 'removedParents' => $parentNames, 'removedPlayers' => $playerNames, 'S' => project($S, $acc)]);
}

