if ($a === 'upAudio') { need_ajax(); if (!$acc || $acc['status'] !== 'approved') fail('Please log in again', 401); if (!empty($acc['hidden'])) fail('View only', 403);
  $bin = file_get_contents('php://input', false, null, 0, 2 * 1024 * 1024 + 1); if (!$bin || strlen($bin) > 2 * 1024 * 1024) fail('Voice note is too large');
  $ct = strtolower(trim(explode(';', (string)($_SERVER['CONTENT_TYPE'] ?? ''))[0])); $ext = '';
  if (substr($bin, 0, 4) === "\x1A\x45\xDF\xA3" && in_array($ct, ['audio/webm', 'video/webm'], true)) $ext = 'webm';
  elseif (substr($bin, 0, 4) === 'OggS' && in_array($ct, ['audio/ogg', 'application/ogg'], true)) $ext = 'ogg';
  elseif (strlen($bin) > 12 && substr($bin, 0, 4) === 'RIFF' && substr($bin, 8, 4) === 'WAVE' && in_array($ct, ['audio/wav', 'audio/x-wav', 'audio/wave'], true)) $ext = 'wav';
  elseif (strlen($bin) > 12 && substr($bin, 4, 4) === 'ftyp' && in_array($ct, ['audio/mp4', 'video/mp4', 'audio/x-m4a'], true)) $ext = 'm4a';
