  if ($ext === '') fail('This voice-note format is not supported on this device');
  if (!is_dir("$DIR/audio")) @mkdir("$DIR/audio", 0750, true); $f = bin2hex(random_bytes(12)) . '.' . $ext;
  if (@file_put_contents("$DIR/audio/$f", $bin, LOCK_EX) === false) fail('Couldn’t save the voice note. Try again.'); out(['ok' => true, 'f' => $f, 'type' => $ct]); }
if ($a === 'audio') { $f = (string)($_GET['f'] ?? '');
  $visible = null; if ($acc && $acc['status'] === 'approved' && audio_ok($f)) $visible = project(load_state()->S, $acc);
  if (!$visible || !in_array($f, all_audio($visible), true)) { http_response_code(404); exit; }
  $ext = pathinfo($f, PATHINFO_EXTENSION); $types = ['webm' => 'audio/webm', 'm4a' => 'audio/mp4', 'ogg' => 'audio/ogg', 'aac' => 'audio/aac', 'wav' => 'audio/wav'];
  $size = filesize("$DIR/audio/$f"); $start = 0; $end = $size - 1; $status = 200;
  if (!empty($_SERVER['HTTP_RANGE']) && preg_match('/^bytes=(\d*)-(\d*)$/', trim($_SERVER['HTTP_RANGE']), $m)) { if ($m[1] === '' && $m[2] !== '') $start = max(0, $size - (int)$m[2]); else { $start = (int)$m[1]; if ($m[2] !== '') $end = min($end, (int)$m[2]); }
    if ($start > $end || $start >= $size) { http_response_code(416); header('Content-Range: bytes */' . $size); exit; } $status = 206; }
  http_response_code($status); header('Content-Type: ' . ($types[$ext] ?? 'application/octet-stream')); header('X-Content-Type-Options: nosniff'); header('Cache-Control: private, no-store'); header('Accept-Ranges: bytes');
