/* ---------------- calendar feed for Google / iPhone (private link per person) ---------------- */
function ics_txt($s) { return str_replace(["\\", ";", ",", "\r\n", "\n"], ["\\\\", "\;", "\\,", "\\n", "\\n"], (string)$s); }
function ics_fold($l) { $o = ''; while (strlen($l) > 74) { $cut = 74; while ($cut > 1 && (ord($l[$cut]) & 0xC0) === 0x80) $cut--; $o .= substr($l, 0, $cut) . "\r\n "; $l = substr($l, $cut); } return $o . $l . "\r\n"; }
function ics_t($ms) { return gmdate('Ymd\THis\Z', (int)floor($ms / 1000)); }
function cal_items($S, $acc) {
  $coach = $acc['role'] === 'coach'; $uid = $acc['id']; [$own, $teams] = $coach ? [[], array_keys((array)$S->teams)] : own_info($S, $uid);
  $T = function ($t) use ($S) { return $S->teams->$t->short ?? $S->teams->$t->name ?? $t; }; $out = [];
  $venue = function ($name) use ($S) { foreach (($S->venues ?? []) as $v) if ($v->name === $name) return trim($v->name . ', ' . ($v->address ?? '') . ' ' . ($v->postcode ?? ''), ', '); return (string)$name; };
  $from = strtotime('today -21 days'); $to = strtotime('today +180 days');
  foreach (($S->sessions ?? []) as $s) { if (!array_intersect((array)$s->teams, $teams)) continue;
    for ($d = $from; $d < $to; $d = strtotime('+1 day', $d)) { if ((int)date('w', $d) !== (int)$s->day) continue; $day = date('Y-m-d', $d);
      [$h, $m] = array_map('intval', explode(':', $s->start)); [$eh, $em] = array_map('intval', explode(':', $s->end));
      $cx = !empty(((array)($S->cancel ?? []))[$s->id . '@' . $day]);
      $out[] = ['k' => "s|{$s->id}|$day", 'a' => mktime($h, $m, 0, (int)date('n', $d), (int)date('j', $d), (int)date('Y', $d)) * 1000, 'b' => mktime($eh, $em, 0, (int)date('n', $d), (int)date('j', $d), (int)date('Y', $d)) * 1000,
        'sum' => ($cx ? 'CANCELLED: ' : '') . '⚽ ' . $s->title, 'loc' => $venue($s->place ?? ''), 'desc' => $cx ? 'This session is cancelled.' : 'Training · ' . implode(', ', array_map($T, (array)$s->teams)), 'cx' => $cx]; } }
  foreach (($S->fixtures ?? []) as $f) { if (!in_array($f->team, $teams, true) || $f->at < $from * 1000) continue; $v = $f->venue ?? null;
    $res = ($f->status ?? '') === 'ft' ? ' · ' . (int)$f->us . '–' . (int)$f->them : '';
    $out[] = ['k' => "f|{$f->id}", 'a' => $f->at, 'b' => $f->at + 90 * 60000, 'sum' => '🏟️ ' . $T($f->team) . ' vs ' . $f->opp . $res,
      'loc' => $v && !empty($v->name) && $v->name !== 'TBC' ? trim($v->name . ', ' . ($v->address ?? '') . ' ' . ($v->postcode ?? ''), ', ') : '',
      'desc' => trim((!empty($f->meet) ? 'Meet ' . $f->meet . ' · ' : '') . 'Kick-off ' . date('H:i', (int)($f->at / 1000)) . ' · ' . (!empty($f->home) ? 'Home' : 'Away') . (!empty($v->notes) ? ' · ' . $v->notes : ''))]; }
  foreach (($S->events ?? []) as $e) { if ($e->at < $from * 1000) continue;
    $out[] = ['k' => "e|{$e->id}", 'a' => $e->at, 'b' => $e->at + 120 * 60000, 'sum' => trim(($e->icon ?? '') . ' ' . $e->title), 'loc' => $venue($e->place ?? ''), 'desc' => (string)($e->desc ?? '')]; }
  foreach (($S->camps ?? []) as $c) foreach (($c->days ?? []) as $i => $day) { if ($day < $from * 1000) continue;
    $kids = []; foreach (($S->campBk ?? []) as $b) if ($b->camp === $c->id && in_array($i, (array)$b->days, true) && ($coach || ($b->uid ?? '') === $uid)) $kids[] = $b->child ?? '';
    if (!$coach && !$kids) continue; $d0 = (int)($day / 1000);
    [$h, $m] = array_map('intval', explode(':', $c->start)); [$eh, $em] = array_map('intval', explode(':', $c->end));
    $out[] = ['k' => "c|{$c->id}|$i", 'a' => mktime($h, $m, 0, (int)date('n', $d0), (int)date('j', $d0), (int)date('Y', $d0)) * 1000, 'b' => mktime($eh, $em, 0, (int)date('n', $d0), (int)date('j', $d0), (int)date('Y', $d0)) * 1000,
      'sum' => trim(($c->icon ?? '') . ' ' . $c->name . ' · Day ' . ($i + 1)), 'loc' => $venue($c->place ?? ''), 'desc' => ($coach ? count($kids) . ' booked' : 'Booked: ' . implode(' & ', $kids)) . '. ' . ($c->info ?? '')]; }
  foreach (($S->slots ?? []) as $s) { if (empty($s->booked) || ($s->at ?? 0) < $from * 1000 || (!$coach && ($s->booked->uid ?? '') !== $uid)) continue;
    $out[] = ['k' => "o|{$s->id}", 'a' => $s->at, 'b' => $s->at + (int)($s->len ?? 45) * 60000, 'sum' => '🎯 1-1 session' . ($coach ? ' · ' . ($s->booked->name ?? '') : ' with Coach Alfie'), 'loc' => '', 'desc' => (string)($s->booked->name ?? '')]; }
  return $out; }
if ($a === 'cal') { $u = (string)($_GET['u'] ?? ''); $k = (string)($_GET['k'] ?? ''); $who = null;
  foreach ($A as $x) if ($x['id'] === $u && empty($x['hidden'])) $who = $x;
  if (!$who || !hash_equals(cal_sig($u), $k) || $who['status'] !== 'approved') { http_response_code(404); header('Content-Type: text/plain'); echo 'Calendar not found'; exit; }
  $st = load_state(); $items = cal_items($st->S, $who); $one = (string)($_GET['one'] ?? '');
  if ($one !== '') $items = array_values(array_filter($items, fn($x) => $x['k'] === $one));
  $L = "BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//North Point Creative//AG Coaching FC//EN\r\nCALSCALE:GREGORIAN\r\nMETHOD:PUBLISH\r\n";
  if ($one === '') $L .= ics_fold('X-WR-CALNAME:AG Coaching FC') . ics_fold('X-WR-CALDESC:Training, matches, events and camps from the AG Coaching FC app') . "X-WR-TIMEZONE:Europe/London\r\nREFRESH-INTERVAL;VALUE=DURATION:PT1H\r\nX-PUBLISHED-TTL:PT1H\r\n";
  $now = gmdate('Ymd\THis\Z');
  foreach ($items as $x) { $L .= "BEGIN:VEVENT\r\n" . ics_fold('UID:' . md5($x['k']) . '@agcoachingfc.co.uk') . "DTSTAMP:$now\r\nDTSTART:" . ics_t($x['a']) . "\r\nDTEND:" . ics_t($x['b']) . "\r\n"
    . ics_fold('SUMMARY:' . ics_txt($x['sum'])) . ($x['loc'] !== '' ? ics_fold('LOCATION:' . ics_txt($x['loc'])) : '') . ($x['desc'] !== '' ? ics_fold('DESCRIPTION:' . ics_txt($x['desc'])) : '')
    . (!empty($x['cx']) ? "STATUS:CANCELLED\r\n" : '') . (empty($x['cx']) && $x['a'] > time() * 1000 && $one === '' && $x['k'][0] !== 's' ? "BEGIN:VALARM\r\nACTION:DISPLAY\r\nDESCRIPTION:Reminder\r\nTRIGGER:-PT2H\r\nEND:VALARM\r\n" : '') . "END:VEVENT\r\n"; }
  $L .= "END:VCALENDAR\r\n";
  header('Content-Type: text/calendar; charset=utf-8'); header('Cache-Control: no-cache, max-age=0'); header('Content-Disposition: ' . ($one !== '' ? 'attachment' : 'inline') . '; filename="' . ($one !== '' ? 'agfc-event' : 'agcoachingfc') . '.ics"');
  echo $L; exit; }

if ($a === 'me') {
