if (in_array($a, ['state', 'ops', 'profilephoto', 'chpw', 'resetpw'], true)) {
  if (!$acc) fail('Please log in again', 401);
  if ($a === 'chpw') { need_ajax(); $b = body(); if (!password_verify((string)($b->old ?? ''), $acc['pass'])) fail('Your current password isn’t right'); if (strlen((string)($b->new ?? '')) < 8) fail('New password needs 8+ characters');
    $L = lock(); $A = load_accounts(); $ai = current_account($A); $A[$ai]['pass'] = password_hash((string)$b->new, PASSWORD_DEFAULT); save_accounts($A); unlock($L); out(['ok' => true]); }
  if ($acc['status'] !== 'approved') fail('Waiting for approval', 403);
  if ($a === 'state' && empty($acc['hidden']) && ($acc['seen'] ?? 0) < time() - 600) { $L2 = lock(); $A2 = load_accounts(); foreach ($A2 as $i => $x) if ($x['id'] === $acc['id']) $A2[$i]['seen'] = time(); save_accounts($A2); unlock($L2); }
  if ($a === 'state') { $st = load_state(); if ((int)($_GET['rev'] ?? 0) === (int)$st->rev) out(['same' => true, 'rev' => $st->rev]); out(['rev' => $st->rev, 'S' => project($st->S, $acc)]); }
  if ($a === 'resetpw') { need_ajax(); if ($acc['role'] !== 'coach') fail('Coaches only', 403); $b = body(); $temp = strtoupper(substr(str_replace(['0', 'O', '1', 'I', 'L'], '', bin2hex(random_bytes(8))), 0, 6));
    $L = lock(); $A = load_accounts(); $ok = false; foreach ($A as $i => $x) if ($x['id'] === ($b->uid ?? '') && $x['role'] === 'parent') { $A[$i]['pass'] = password_hash($temp, PASSWORD_DEFAULT); $A[$i]['tokens'] = []; $ok = true; }
    save_accounts($A); unlock($L); if (!$ok) fail('Account not found'); out(['ok' => true, 'temp' => $temp]); }
  if ($a === 'profilephoto') {
    need_ajax(); if ($acc['role'] !== 'parent' || !empty($acc['hidden'])) fail('Parent account required', 403);
    $b = body();
    if (!keys_ok($b, ['pid', 'photo']) || !property_exists($b, 'photo') || !is_string($b->pid ?? '')) fail('Choose a linked player');
    $pid = $b->pid; $photo = $b->photo;
    $L = lock(); $st = load_state(); $S = $st->S;
    [$own] = own_info($S, $acc['id']);
    $u = get_at($S, ['users', '#' . $acc['id']]);
    $p = $pid !== '' ? get_at($S, ['players', '#' . $pid]) : null;
    // Validate both targets and the uploaded file before changing either record.
    if (!$u || ($pid !== '' && (!$p || !in_array($pid, $own, true))) || ($pid === '' && $own)) { unlock($L); fail('This player is not linked to your account', 403); }
    if ($photo !== null && !photo_ok($photo)) { unlock($L); fail('Photo not found. Please upload it again.'); }
    $old = json_decode(json_encode($S));
    foreach ([$u, $p] as $person) if ($person) { if ($photo === null) unset($person->photo); else $person->photo = $photo; }
    // Never enable consent or change player ownership as a side effect of upload.
    $st->S = $S; $st->rev++; save_state($st);
    foreach (array_diff(all_imgs($old), all_imgs($S)) as $f) if (photo_ok($f)) @unlink("$DIR/photos/$f");
    unlock($L);
