    }
    $jobs = $applied ? push_jobs($old, $S, $acc['id']) : [];
    unlock($L);
    out_then(['ok' => true, 'rev' => $st->rev, 'applied' => $applied, 'rejected' => $rejected, 'S' => project($S, $acc)], $jobs);
