}


/* ---------------- permanent QR check-in ---------------- */
function checkin_token_file() { global $DIR; return "$DIR/checkin-token"; }
function checkin_token_get($create = false) {
  $f = checkin_token_file();
  $t = trim((string)@file_get_contents($f));
  if (!preg_match('/^[a-f0-9]{48}$/', $t) && $create) {
    $t = bin2hex(random_bytes(24));
    @file_put_contents($f, $t, LOCK_EX);
    @chmod($f, 0600);
  }
  return preg_match('/^[a-f0-9]{48}$/', $t) ? $t : '';
}
if ($a === 'checkin-setup') {
  if (!$acc || $acc['role'] !== 'coach' || $acc['status'] !== 'approved' || !empty($acc['hidden'])) fail('Coaches only', 403);
  need_ajax();
  $t = checkin_token_get(true);
