  need_ajax();
  $b = body(); $token = (string)($b->token ?? ''); $pid = (string)($b->pid ?? '');
  $saved = checkin_token_get(false);
  if (!$saved || !hash_equals($saved, $token)) fail('This check-in code is not recognised. Please ask your coach for the club poster.', 403);
  $L = lock(); $st = load_state(); $S = $st->S;
  $player = null;
  foreach (($S->players ?? []) as $pl) if (($pl->id ?? '') === $pid && in_array($acc['id'], pars($pl), true)) { $player = $pl; break; }
  if (!$player) { unlock($L); fail('That player is not linked to your parent account.', 403); }
  $today = date('Y-m-d'); $now = time(); $dow = (int)date('w'); $chosen = null;
  foreach (($S->sessions ?? []) as $session) {
    if (!in_array($player->team, (array)($session->teams ?? []), true) || (int)($session->day ?? -1) !== $dow) continue;
    if (!preg_match('/^([0-2]\d):([0-5]\d)$/', (string)($session->start ?? ''), $sm) ||
        !preg_match('/^([0-2]\d):([0-5]\d)$/', (string)($session->end ?? ''), $em)) continue;
    $start = strtotime($today . ' ' . $sm[1] . ':' . $sm[2] . ' Europe/London');
    $end = strtotime($today . ' ' . $em[1] . ':' . $em[2] . ' Europe/London');
    if ($now < $start - 45 * 60 || $now > $end + 30 * 60) continue;
    $key = $session->id . '@' . $today;
