    $chosen = [$session, $key]; break;
  }
  if (!$chosen) { unlock($L); fail('Check-in is not open right now. Please check the session time with your coach.'); }
  [$session, $key] = $chosen;
  $arr = (array)($S->att->$key ?? []);
  if (in_array($pid, $arr, true)) {
    unlock($L);
    out(['ok' => true, 'already' => true, 'player' => $player->name, 'session' => $session->title, 'message' => $player->name . ' is already checked in.']);
  }
  $arr[] = $pid; $S->att->$key = array_values(array_unique($arr));
  $stamp = false;
  $Lcfg = $S->loyalty ?? (object)['on' => true, 'sessions' => [], 'need' => 11, 'reward' => '£5 off your next block'];
  if (!empty($Lcfg->on) && in_array($session->id, (array)($Lcfg->sessions ?? []), true)) {
