    $c->log = is_array($c->log ?? null) ? $c->log : [];
    $hasStamp = false; foreach ($c->log as $entry) { $esid = is_array($entry) ? ($entry['sid'] ?? '') : ($entry->sid ?? ''); $eday = is_array($entry) ? ($entry['day'] ?? '') : ($entry->day ?? ''); $eb = is_array($entry) ? ($entry['b'] ?? false) : ($entry->b ?? false); $em = is_array($entry) ? ($entry['m'] ?? false) : ($entry->m ?? false); $ea = is_array($entry) ? ($entry['adj'] ?? false) : ($entry->adj ?? false); if ($esid === $session->id && $eday === $today && !$eb && !$em && !$ea) { $hasStamp = true; break; } }
    if (!$hasStamp) { $c->n = (int)($c->n ?? 0) + 1; $c->due = $c->n >= max(1, (int)($Lcfg->need ?? 11)); $c->log[] = ['sid' => $session->id, 'day' => $today, 'ts' => (int)(microtime(true) * 1000)]; $stamp = true; }
    $c->redeemed = $c->redeemed ?? []; $c->pn = $c->pn ?? [];
    $S->stamps->$pid = $c;
  }
  $S->notes = $S->notes ?? [];
  foreach (pars($player) as $parentId) $S->notes[] = (object)['id' => rid('n'), 'to' => $parentId, 'ic' => '✅', 't' => $player->name . ' checked in for ' . $session->title . ' at ' . date('H:i') . '.', 'ts' => (int)(microtime(true) * 1000), 'read' => false];
  $S->activity = $S->activity ?? [];
  array_unshift($S->activity, (object)['ic' => '📲', 't' => $player->name . ' checked in via QR', 'ts' => (int)(microtime(true) * 1000)]);
  $S->activity = array_slice($S->activity, 0, 100);
  $st->S = $S; $st->rev++; save_state($st); $rev = $st->rev; $P = project($S, $acc);
  unlock($L);
  out(['ok' => true, 'already' => false, 'player' => $player->name, 'session' => $session->title, 'stamp' => $stamp, 'rev' => $rev, 'S' => $P, 'message' => $player->name . ' is checked in. Have a brilliant session!']);
}

