// One semantic validator for the equivalent identity/gzip shell representations.
function app_etag_matches($header, $etag) {
  $target = preg_replace('/^W\//', '', $etag);
  // Do not split commas that belong to an opaque quoted validator.
  foreach (preg_split('/,(?=(?:[^\"]*\"[^\"]*\")*[^\"]*$)/', (string)$header) as $candidate) {
    $candidate = trim($candidate);
    if ($candidate === '*' || preg_replace('/^W\//', '', $candidate) === $target) return true;
  }
  return false;
}
function app_accepts_gzip($header) {
  $gzip = null; $wildcard = null;
  foreach (explode(',', (string)$header) as $entry) {
    $parts = explode(';', $entry); $coding = strtolower(trim(array_shift($parts)));
    if ($coding !== 'gzip' && $coding !== '*') continue;
    $q = 1.0;
    foreach ($parts as $parameter) {
      $pair = explode('=', trim($parameter), 2);
      if (strtolower(trim($pair[0])) !== 'q') continue;
      $value = isset($pair[1]) ? trim($pair[1]) : '';
      $quality = preg_match('/^(?:0(?:\.[0-9]{0,3})?|1(?:\.0{0,3})?)$/D', $value) ? (float)$value : 0.0;
      $q = min($q, $quality);
    }
    // Duplicate codings are ambiguous: conservatively honor any explicit refusal.
    if ($coding === 'gzip') $gzip = $gzip === null ? $q : min($gzip, $q);
    else $wildcard = $wildcard === null ? $q : min($wildcard, $q);
  }
  return ($gzip !== null ? $gzip : ($wildcard !== null ? $wildcard : 0.0)) > 0.0;
}
