input,select,textarea{font:inherit;color:inherit}
::selection{background:var(--g);color:#000}

/* ===== viewport shell: native height, no simulated handset or device offsets ===== */
@supports (padding:env(safe-area-inset-top)){
  :root{--safe-top:env(safe-area-inset-top,0px);--safe-right:env(safe-area-inset-right,0px);--safe-bottom:env(safe-area-inset-bottom,0px);--safe-left:env(safe-area-inset-left,0px);--top:calc(16px + var(--safe-top))}
}
.stage{position:fixed;top:0;left:0;right:0;height:100vh;height:100dvh;display:flex;justify-content:center;overflow:hidden;background:var(--bg)}
.phone{width:100%;height:100%;min-width:0;min-height:0;position:relative;overflow:hidden;background:var(--bg)}
.notch,.sbar{display:none}
.by{margin-top:24px;font-size:13px;color:var(--mut);border-top:1px solid var(--line);padding-top:16px}
@media (min-width:861px) and (hover:hover) and (pointer:fine){.phone{max-width:720px;border-left:1px solid var(--line);border-right:1px solid var(--line)}}
html.legacy-viewport .stage{height:var(--legacy-height,100vh)}

/* ===== app shell ===== */
.app{position:absolute;top:0;right:0;bottom:0;left:0;inset:0;display:flex;flex-direction:column;min-width:0;min-height:0;padding-left:var(--safe-left);padding-right:var(--safe-right);background:var(--bg)}
.app::before{content:"";position:absolute;inset:0;pointer-events:none;background:radial-gradient(500px 380px at 85% -5%,rgba(63,243,106,.13),transparent 70%)}
.screen{flex:1 1 0%;min-width:0;min-height:0;overflow-y:auto;overflow-x:hidden;scrollbar-width:none;padding-bottom:16px;scroll-padding:16px;position:relative}
.screen::-webkit-scrollbar{display:none}
.view{animation:viewIn .5s var(--ease)}
@keyframes viewIn{from{opacity:0;transform:translateY(16px) scale(.99)}to{opacity:1;transform:none}}
.stag>*{animation:viewIn .6s var(--ease) both}
.stag>*:nth-child(2){animation-delay:.04s}.stag>*:nth-child(3){animation-delay:.08s}.stag>*:nth-child(4){animation-delay:.12s}.stag>*:nth-child(5){animation-delay:.16s}.stag>*:nth-child(6){animation-delay:.2s}.stag>*:nth-child(7){animation-delay:.24s}.stag>*:nth-child(8){animation-delay:.28s}.stag>*:nth-child(n+9){animation-delay:.32s}

.top{display:flex;align-items:center;gap:12px;padding:calc(var(--top) + 2px) 18px 6px}
.av{width:44px;height:44px;border-radius:15px;display:grid;place-items:center;font-family:var(--disp);font-weight:900;font-size:18px;background:linear-gradient(145deg,var(--g),var(--g3));color:#02110a;flex:0 0 auto;box-shadow:0 6px 20px rgba(63,243,106,.3);overflow:hidden}
.av.hasph img{display:block;width:100%;height:100%;object-fit:cover;border-radius:inherit}
.top .t{flex:1;min-width:0}
.top small{display:block;color:var(--mut);font-size:12px;font-weight:600}
.top b{display:block;font-family:var(--disp);font-size:21px;text-transform:uppercase;letter-spacing:.01em;line-height:1.05;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ib{width:44px;height:44px;border-radius:15px;background:var(--card);border:1px solid var(--line);display:grid;place-items:center;position:relative;flex:0 0 auto;transition:transform .15s}
.ib:active{transform:scale(.92)}
.ib svg{width:20px;height:20px}.account-btn{width:auto;min-width:104px;padding:0 10px;display:flex;align-items:center;justify-content:center;gap:6px;white-space:nowrap;font-size:11px;font-weight:850}.account-btn svg{width:18px;height:18px}
.account-family-card>.kv>div{display:grid;grid-template-columns:24px minmax(0,1fr);gap:5px 10px;align-items:start}
.account-family-card>.kv>div>i{grid-row:1 / span 2;align-self:start}
.account-family-card>.kv>div>span{min-width:0;color:var(--mut);font-size:12px;overflow-wrap:anywhere}
.account-family-card>.kv>div>b{grid-column:2;margin:0;min-width:0;max-width:100%;text-align:left;overflow-wrap:anywhere;word-break:break-word}
.account-family-heading{min-width:0;overflow-wrap:anywhere}
.account-intro{overflow-wrap:anywhere}
@media(max-width:380px){.account-btn{min-width:96px;padding:0 8px;gap:5px}.account-btn svg{width:17px;height:17px}.support-home-card{align-items:flex-start!important;flex-direction:column}.support-home-card .btn{width:100%}}
.dot{position:absolute;top:-4px;right:-4px;min-width:20px;height:20px;padding:0 5px;border-radius:10px;background:var(--g);color:#02110a;font-size:11px;font-weight:800;display:grid;place-items:center;box-shadow:0 0 0 3px var(--bg),0 0 14px rgba(63,243,106,.6)}

.kids{display:flex;gap:8px;padding:6px 18px 0}
.kid-pill{display:flex;align-items:center;gap:8px;padding:6px 12px 6px 6px;border-radius:99px;border:1px solid var(--line);background:var(--card);font-weight:700;font-size:13px;transition:all .25s}
.kid-pill i{width:24px;height:24px;border-radius:50%;display:grid;place-items:center;background:var(--card2);font-style:normal;font-family:var(--disp);font-size:13px}
.kid-pill.on{background:var(--w);color:#05140a;border-color:var(--w)}
.kid-pill.on i{background:var(--g);color:#02110a}

h2.sec{font-family:var(--disp);text-transform:uppercase;font-size:22px;font-weight:800;padding:26px 18px 12px;display:flex;justify-content:space-between;align-items:baseline;letter-spacing:.01em}
h2.sec a{font-family:var(--body);font-size:13px;color:var(--g);text-transform:none;font-weight:700;cursor:pointer}
.ph{padding:calc(var(--top) + 4px) 18px 0}
.ph small{color:var(--g);font-weight:800;letter-spacing:.2em;font-size:11px;text-transform:uppercase}
.ph h1{font-family:var(--disp);font-style:italic;font-weight:900;font-size:48px;text-transform:uppercase;line-height:.9;margin-top:6px}

/* hero */
/* ===== V10 club welcome experience ===== */
.club-welcome{position:relative;overflow:hidden;margin:14px 14px 12px;padding:20px;border:1px solid rgba(94,255,137,.24);border-radius:26px;background:linear-gradient(132deg,#123b20 0%,#0b2414 52%,#07150c 100%);box-shadow:0 16px 42px rgba(0,0,0,.28),inset 0 1px rgba(255,255,255,.07)}
.club-welcome:before{content:"";position:absolute;width:230px;height:230px;right:-90px;top:-115px;border-radius:50%;background:radial-gradient(circle,rgba(63,243,106,.27),transparent 68%);pointer-events:none}
.club-welcome:after{content:"";position:absolute;inset:0;background:repeating-linear-gradient(120deg,transparent 0 34px,rgba(255,255,255,.018) 34px 68px);pointer-events:none}
.cw-kicker{position:relative;z-index:1;display:flex;align-items:center;gap:8px;color:var(--g);font-size:10px;letter-spacing:2.2px;font-weight:900;text-transform:uppercase}
.cw-kicker i{display:inline-block;width:7px;height:7px;border-radius:50%;background:var(--g);box-shadow:0 0 12px var(--g)}
.cw-title{position:relative;z-index:1;font-family:var(--disp);font-size:36px;line-height:.98;font-weight:900;text-transform:uppercase;margin:11px 0 7px;color:#fff}
.cw-copy{position:relative;z-index:1;color:#c4d9c9;font-size:13px;line-height:1.5;max-width:340px}
.cw-foot{position:relative;z-index:1;display:flex;align-items:center;justify-content:space-between;gap:10px;margin-top:16px;padding-top:13px;border-top:1px solid rgba(255,255,255,.10)}
.cw-tag{font-size:10px;letter-spacing:1.3px;text-transform:uppercase;font-weight:800;color:#c4ff4d}
.cw-squad{font-size:11px;font-weight:800;color:#e7f6e9;background:rgba(0,0,0,.22);border:1px solid rgba(255,255,255,.12);border-radius:30px;padding:7px 11px}
.coach-welcome{margin:14px 14px 12px;padding:19px 20px 17px;border-radius:25px;background:linear-gradient(130deg,#173f25,#0a1a10 72%);border:1px solid rgba(63,243,106,.22);box-shadow:0 14px 35px rgba(0,0,0,.22);position:relative;overflow:hidden}
.coach-welcome:after{content:'AG';position:absolute;right:9px;bottom:-26px;font:italic 900 112px var(--disp);color:rgba(255,255,255,.045);pointer-events:none}
.coach-welcome small{color:var(--g);font-size:10px;letter-spacing:2px;font-weight:900;text-transform:uppercase}
.coach-welcome h2{font:900 34px/.98 var(--disp);text-transform:uppercase;margin:8px 0;color:#fff;position:relative;z-index:1}
.coach-welcome p{color:#c4d9c9;font-size:13px;max-width:310px;line-height:1.5;position:relative;z-index:1}
@media(max-width:390px){.cw-title{font-size:32px}.club-welcome,.coach-welcome{margin-left:10px;margin-right:10px;padding:17px}}
.hero{margin:10px 14px 0;border-radius:30px;position:relative;overflow:hidden;padding:20px;isolation:isolate;
  background:linear-gradient(155deg,#124a24 0%,#082111 50%,#040c07 100%);border:1px solid var(--line2);box-shadow:0 30px 60px rgba(0,0,0,.45)}
.hero::before{content:"";position:absolute;right:-90px;top:-120px;width:340px;height:340px;background:radial-gradient(circle,rgba(196,255,77,.42),transparent 62%);z-index:-1;animation:flood 7s ease-in-out infinite}
.hero::after{content:"";position:absolute;inset:0;z-index:-1;background:repeating-linear-gradient(115deg,transparent 0 26px,rgba(63,243,106,.045) 26px 52px)}
@keyframes flood{50%{transform:translate(-40px,30px) scale(1.12);opacity:.75}}
.hero.cx{background:linear-gradient(155deg,#4a1212,#200808 50%,#0c0404);border-color:rgba(255,93,93,.4)}
.hero.cx::before{background:radial-gradient(circle,rgba(255,93,93,.4),transparent 62%)}
.hero.lv{background:linear-gradient(155deg,#5a1010,#1c0606 55%,#0b0303);border-color:rgba(255,93,93,.45)}
.pill{display:inline-flex;gap:7px;align-items:center;font-size:11px;font-weight:800;letter-spacing:.16em;text-transform:uppercase;background:rgba(63,243,106,.14);color:var(--g);padding:7px 11px;border-radius:99px;border:1px solid rgba(63,243,106,.25)}
.pill::before{content:"";width:7px;height:7px;border-radius:50%;background:currentColor;animation:pulse 1.4s infinite}
.pill.red{background:rgba(255,93,93,.15);color:#ff8a8a;border-color:rgba(255,93,93,.35)}
.pill.static::before{animation:none}
@keyframes pulse{50%{opacity:.2}}
.hero h3{font-family:var(--disp);font-style:italic;font-weight:900;font-size:44px;line-height:.88;text-transform:uppercase;margin:14px 0 8px;letter-spacing:-.005em}
.hero h3.strike{text-decoration:line-through;text-decoration-color:var(--red);text-decoration-thickness:4px;opacity:.75}
.hero .meta{color:#d2e6d6;font-size:14px;display:grid;gap:2px}
.cd{display:flex;gap:7px;margin-top:16px}
.cd div{flex:1;background:rgba(0,0,0,.38);border:1px solid var(--line);border-radius:15px;padding:9px 0 8px;text-align:center;backdrop-filter:blur(8px)}
.cd b{display:block;font-family:var(--disp);font-size:31px;font-weight:800;line-height:1;font-variant-numeric:tabular-nums}
.cd span{font-size:9px;letter-spacing:.18em;color:var(--mut);text-transform:uppercase;font-weight:700}
.duo{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:8px;margin-top:12px}
.seg{padding:13px 8px;border-radius:15px;font-weight:800;font-size:14px;border:1px solid var(--line);background:rgba(0,0,0,.3);transition:all .3s var(--spring)}
.seg.yes.on{background:var(--g);color:#02110a;border-color:var(--g);box-shadow:0 10px 28px rgba(63,243,106,.4);transform:scale(1.02)}
.seg.no.on{background:rgba(255,93,93,.2);border-color:var(--red);color:#ffb4b4}

/* buttons */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;background:linear-gradient(180deg,#5cff84,var(--g2));color:#02110a;font-weight:800;border-radius:15px;padding:13px 17px;font-size:14px;box-shadow:0 10px 26px rgba(63,243,106,.3),inset 0 1px 0 rgba(255,255,255,.5);transition:transform .15s}
.btn:active{transform:scale(.96)}
.btn.sm{padding:9px 13px;font-size:13px;border-radius:12px}
.btn.gh{background:rgba(255,255,255,.04);color:var(--w);border:1px solid var(--line);box-shadow:none}
.btn.rd{background:rgba(255,93,93,.15);color:#ff9d9d;border:1px solid rgba(255,93,93,.35);box-shadow:none}
.btn.full{width:100%}
.btn.big{padding:17px;font-size:16px;border-radius:18px}
.btn[disabled]{opacity:.5}
.photo-onboard h3{font-family:var(--disp);font-size:30px;text-transform:uppercase;line-height:.95}
.photo-steps{display:grid;gap:9px;margin-top:16px}
.photo-steps>div{display:flex;align-items:center;gap:11px;padding:11px 12px;border:1px solid var(--line);border-radius:15px;background:rgba(63,243,106,.06)}
.photo-steps b{width:26px;height:26px;display:grid;place-items:center;flex:0 0 26px;border-radius:50%;background:var(--g);color:#02110a;font-family:var(--disp);font-size:17px}
.photo-steps span{font-size:13px;line-height:1.35;color:#d2e6d6}

/* cards & lists */
.card{margin:0 14px;background:var(--card);border:1px solid var(--line);border-radius:24px;padding:16px;position:relative;overflow:hidden}
.card+.card{margin-top:10px}
.list{margin:0 14px;display:grid;gap:9px}
.row{display:flex;gap:12px;align-items:center;background:var(--card);border:1px solid var(--line);border-radius:20px;padding:13px 14px;transition:all .35s var(--ease);width:100%;text-align:left}
.row:active{transform:scale(.985)}
.row .ic{flex:0 0 44px;height:44px;border-radius:14px;display:grid;place-items:center;font-size:20px;background:rgba(63,243,106,.1);text-align:center;line-height:1}
.row .grow{flex:1;min-width:0}
.row b{font-size:15px;display:block}
.row p{font-size:13px;color:var(--mut);margin-top:2px;line-height:1.4}
.row time{font-size:11px;color:var(--g);font-weight:700;letter-spacing:.06em;text-transform:uppercase}
.row.unread{border-color:var(--line2);background:linear-gradient(120deg,#11281a,var(--card))}
.row.unread::after{content:"";position:absolute;right:14px;top:14px;width:9px;height:9px;border-radius:50%;background:var(--g);box-shadow:0 0 10px var(--g)}
.row{position:relative}
.row.gone{opacity:0;transform:translateX(70px) scale(.9);max-height:0;padding:0 14px;margin:-9px 0 0;border-width:0}
.chips{display:flex;flex-wrap:wrap;gap:6px}
.chip{font-size:12px;font-weight:700;padding:7px 11px;border-radius:99px;background:rgba(255,255,255,.05);border:1px solid var(--line);transition:all .2s}
.chip.hot{background:rgba(63,243,106,.14);color:var(--g);border-color:rgba(63,243,106,.35)}
.chip.warn{background:rgba(255,201,60,.12);color:var(--amber);border-color:rgba(255,201,60,.35)}
.chip.red{background:rgba(255,93,93,.12);color:#ff9d9d;border-color:rgba(255,93,93,.35)}
button.chip.on{background:var(--g);color:#02110a;border-color:var(--g)}
.hscroll{display:flex;gap:8px;overflow-x:auto;padding:0 14px;scrollbar-width:none}
.hscroll::-webkit-scrollbar{display:none}
.hscroll>*{flex:0 0 auto}

/* result card */
.res{margin:0 14px;border-radius:24px;padding:16px 18px;background:linear-gradient(160deg,#10301b,#081109);border:1px solid var(--line2);position:relative;overflow:hidden}
.res .lg{font-size:11px;font-weight:800;letter-spacing:.16em;color:var(--g);text-transform:uppercase;text-align:center}
.vs{display:grid;grid-template-columns:minmax(0,1fr) auto minmax(0,1fr);align-items:center;text-align:center;margin-top:10px}
.vs img{width:54px;height:54px;object-fit:contain}
.crest{width:50px;height:50px;margin:0 auto;border-radius:16px 16px 26px 26px;display:grid;place-items:center;font-family:var(--disp);font-weight:900;font-size:19px;border:2px solid rgba(255,255,255,.2)}
.vs .nm{font-family:var(--disp);font-weight:800;font-size:15px;text-transform:uppercase;margin-top:6px;line-height:1}
.sc{font-family:var(--disp);font-weight:900;font-size:58px;line-height:1;font-variant-numeric:tabular-nums;letter-spacing:.01em}
.sc.bump{animation:bump .6s var(--spring)}
@keyframes bump{40%{transform:scale(1.3);color:var(--g);text-shadow:0 0 40px var(--g)}}
.wdl{display:inline-block;font-family:var(--disp);font-weight:900;font-size:13px;padding:3px 8px;border-radius:7px;margin-top:4px}
.wdl.W{background:var(--g);color:#02110a}.wdl.D{background:var(--amber);color:#1a1200}.wdl.L{background:var(--red);color:#fff}

/* kpis */
.kpis{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:10px;padding:14px 14px 0}
.kpi{background:var(--card);border:1px solid var(--line);border-radius:24px;padding:15px 16px;position:relative;overflow:hidden;text-align:left;min-height:118px}
.kpi small{color:var(--mut);font-size:12px;font-weight:700}
.kpi b{display:block;font-family:var(--disp);font-weight:900;font-size:46px;line-height:1;margin-top:8px;font-variant-numeric:tabular-nums}
.kpi em{font-style:normal;font-size:12px;font-weight:700;color:var(--g)}
.kpi.hl{background:linear-gradient(150deg,#1b5e31,#0a2213);border-color:rgba(63,243,106,.35)}
.ring{transform:rotate(-90deg)}
.ring circle{fill:none;stroke-width:7}
.ring .bg{stroke:rgba(255,255,255,.08)}
.ring .fg{stroke:var(--g);stroke-linecap:round;transition:stroke-dashoffset 1.2s var(--ease)}

/* loyalty cards */
.loy{margin:0 14px;background:radial-gradient(120% 90% at 50% 0%,#1d5f33 0%,#0b2213 55%,#06120a 100%);border:1px solid var(--line2);border-radius:20px;padding:16px}
.loy.full{border-color:var(--lime);box-shadow:0 0 28px rgba(196,255,77,.18)}
.loy-h{display:flex;align-items:center;gap:12px;margin-bottom:14px}
.loy-h img{width:42px;height:42px;object-fit:contain}
.loy-h b{display:block;font-family:var(--disp);font-weight:900;font-size:30px;line-height:1}
.loy-h small{color:var(--mut);font-size:12px;font-weight:700}
.stamps{display:grid;gap:9px;justify-items:center}
.stamps i{width:100%;max-width:46px;aspect-ratio:1;border-radius:50%;border:2px dashed rgba(255,255,255,.22);display:grid;place-items:center;font-style:normal;font-family:var(--disp);font-weight:800;font-size:17px;color:var(--dim)}
.stamps i.on{border:2px solid var(--g);background:#0a2814 var(--badge) center/72% no-repeat;color:transparent;box-shadow:0 0 14px rgba(63,243,106,.35);animation:stp .5s var(--spring) both}
@keyframes stp{from{transform:scale(.4);opacity:0}to{transform:scale(1);opacity:1}}
.loy-win{margin-top:14px;background:rgba(196,255,77,.14);border:1px solid rgba(196,255,77,.4);border-radius:14px;padding:12px;text-align:center;font-weight:800;color:var(--lime)}
.loy-win small{display:block;color:var(--w);font-weight:600;margin-top:3px}
.loy .hint{margin:12px 0 0}
.rk small.stp{font-size:10px;color:var(--lime);font-weight:800}
.rk small.stp.due{color:var(--amber)}

.loyhero{display:flex;align-items:center;gap:14px;margin:14px;width:calc(100% - 28px);text-align:left;color:var(--w);background:radial-gradient(120% 120% at 0% 0%,#1d5f33 0%,#0b2213 60%,#06120a 100%);border:1px solid var(--line2);border-radius:20px;padding:14px 16px}
.loyhero.due{border-color:var(--lime);box-shadow:0 0 26px rgba(196,255,77,.16)}
.loyhero img{width:46px;height:46px;object-fit:contain;flex:0 0 46px}
.loyhero b{display:block;font-family:var(--disp);font-weight:900;font-size:20px;text-transform:uppercase;line-height:1.05}
.loyhero p{color:var(--mut);font-size:12.5px;margin-top:3px;font-weight:600}
.loyhero.due p{color:var(--lime);font-weight:800}
.loyhero .go{margin-left:auto;font-size:26px;color:var(--g)}
.lsum{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;padding:12px 14px 0}
.lsum div{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:12px;text-align:center}
.lsum b{display:block;font-family:var(--disp);font-weight:900;font-size:28px;line-height:1}
.lsum small{display:block;color:var(--mut);font-size:11px;font-weight:700;margin-top:5px}
.lbar{height:6px;border-radius:6px;background:rgba(255,255,255,.1);margin-top:7px;overflow:hidden}
.lbar i{display:block;height:100%;background:var(--g);border-radius:6px}
.lbar.due i{background:var(--lime)}
.stb{margin-left:auto;flex:0 0 auto;font-size:12px;font-weight:800;color:var(--lime);background:rgba(196,255,77,.1);border:1px solid rgba(196,255,77,.25);border-radius:20px;padding:5px 10px;white-space:nowrap}
.stb.due{color:var(--amber);background:rgba(255,190,60,.12);border-color:rgba(255,190,60,.4)}
.stb.zero{color:var(--mut);background:transparent;border-color:var(--line)}
.loy.tap{cursor:pointer}
.loy-meta{display:flex;justify-content:space-between;gap:8px;margin-top:12px;color:var(--mut);font-size:12px;font-weight:700}

/* register */
.reg-h{display:flex;align-items:center;gap:14px;margin-bottom:14px}
.reg-h .rw{position:relative;width:66px;height:66px;flex:0 0 66px}
.reg-h .rw b{position:absolute;inset:0;display:grid;place-items:center;font-family:var(--disp);font-weight:900;font-size:20px}
.reg-h h4{font-family:var(--disp);font-weight:800;font-size:21px;text-transform:uppercase;line-height:1}
.reg-h p{color:var(--mut);font-size:12px;margin-top:4px;line-height:1.35}
.regg{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px 6px}
.rk{display:flex;flex-direction:column;align-items:center;gap:5px;font-size:11px;font-weight:700;color:var(--mut)}
.rk .a{width:48px;height:48px;border-radius:50%;display:grid;place-items:center;font-family:var(--disp);font-weight:900;font-size:18px;background:var(--card2);border:2px solid var(--line);color:var(--w);transition:all .35s var(--spring);position:relative}
.rk.in .a{background:var(--g);color:#02110a;border-color:var(--g);transform:scale(1.08);box-shadow:0 0 22px rgba(63,243,106,.55)}
.rk.in .a::after{content:"✓";position:absolute;right:-3px;bottom:-3px;width:19px;height:19px;border-radius:50%;background:#fff;color:var(--g3);font-size:11px;display:grid;place-items:center;font-family:var(--body);font-weight:900}
.rk.in{color:var(--w)}

/* activity */
.act{display:flex;gap:10px;align-items:flex-start;padding:10px 0;border-bottom:1px solid var(--line);font-size:13px;line-height:1.4}
.act:last-child{border:0}
.act i{font-style:normal;width:30px;height:30px;border-radius:10px;background:rgba(63,243,106,.1);display:grid;place-items:center;flex:0 0 30px}
.act span{flex:1}
.act small{color:var(--dim);font-size:11px;white-space:nowrap}
.act.new{animation:flashIn 1.2s var(--ease)}
@keyframes flashIn{0%{background:rgba(63,243,106,.25)}100%{background:transparent}}

/* player cards */
.pc{width:150px;aspect-ratio:2.6/3.7;border-radius:20px;position:relative;cursor:pointer;perspective:900px;flex:0 0 auto}
.pc .in{position:absolute;inset:0;border-radius:inherit;transition:transform .8s var(--ease);transform-style:preserve-3d}
.pc.flip .in{transform:rotateY(180deg)!important}
.face{position:absolute;inset:0;border-radius:inherit;backface-visibility:hidden;-webkit-backface-visibility:hidden;overflow:hidden;padding:2px;
  background:conic-gradient(from var(--a,0deg),#3ff36a,#c4ff4d,#f0fff2,#1fd14f,#0f7a2c,#3ff36a);animation:spin 5s linear infinite}
@property --a{syntax:'<angle>';inherits:false;initial-value:0deg}
@keyframes spin{to{--a:360deg}}
.face .fi{position:absolute;inset:2px;border-radius:18px;background:radial-gradient(120% 70% at 50% 0%,#1f6a37 0%,#0b2213 50%,#040a06 100%);overflow:hidden}
.face .fi::before{content:"";position:absolute;inset:0;background:repeating-linear-gradient(115deg,transparent 0 14px,rgba(63,243,106,.05) 14px 28px)}
.face .fi::after{content:"";position:absolute;inset:-50%;background:linear-gradient(115deg,transparent 42%,rgba(255,255,255,.2) 50%,transparent 58%);animation:shine 4s ease-in-out infinite}
@keyframes shine{0%{transform:translateX(-60%)}55%,100%{transform:translateX(60%)}}
.pc .face.back{transform:rotateY(180deg)}
.pc-n{position:absolute;left:11px;top:9px;font-family:var(--disp);font-weight:900;font-size:36px;line-height:.85;color:var(--g);text-shadow:0 0 20px rgba(63,243,106,.5)}
.pc-p{position:absolute;left:12px;top:43px;font-size:10px;font-weight:800;letter-spacing:.14em}
.pc-b{position:absolute;right:9px;top:9px;width:30px}
.pc-s{position:absolute;left:50%;top:17%;transform:translateX(-50%);width:60%}
.pc-nm{position:absolute;left:4px;right:4px;top:57%;z-index:4;text-align:center;font-family:var(--disp);font-weight:900;font-size:22px;text-transform:uppercase;line-height:1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.pc-st{position:absolute;left:8px;right:8px;bottom:8px;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:4px 2px;border-top:1px solid rgba(63,243,106,.28);padding-top:6px}
.pc-st div{text-align:center;font-family:var(--disp);font-weight:800;font-size:17px;line-height:1}
.pc-st small{display:block;font-family:var(--body);font-size:7.5px;letter-spacing:.1em;color:var(--mut);font-weight:800;margin-top:2px}
.pc .face.back .fi{padding:14px 12px;display:flex;flex-direction:column;gap:7px;overflow-y:auto;overscroll-behavior:contain}
.back h5{font-family:var(--disp);font-size:18px;text-transform:uppercase;font-weight:800;line-height:1;position:relative}
.back .ach{font-size:11px;font-weight:700;background:rgba(63,243,106,.1);border:1px solid rgba(63,243,106,.18);border-radius:9px;padding:6px 8px;position:relative}
.back p{font-size:11px;color:#cfe3d2;line-height:1.35;font-style:italic;position:relative}
.pc.lg{width:270px;margin:0 auto}
.pc.lg .pc-n{font-size:60px}.pc.lg .pc-p{top:66px;font-size:13px}.pc.lg .pc-b{width:48px}
.pc.lg .pc-nm{font-size:36px}.pc.lg .pc-st div{font-size:28px}.pc.lg .pc-st small{font-size:10px}
.pc.lg .back h5{font-size:28px}.pc.lg .back .ach{font-size:14px;padding:9px 11px}.pc.lg .back p{font-size:14px}
.cgrid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:12px;padding:0 14px}
.cgrid .pc{width:100%}

/* agenda */
.day{padding:0 14px}
.day h4{font-family:var(--disp);font-weight:800;font-size:15px;letter-spacing:.12em;text-transform:uppercase;color:var(--mut);margin:18px 4px 8px;display:flex;gap:8px;align-items:center}
.day h4.today{color:var(--g)}
.ev{display:flex;gap:12px;align-items:stretch;background:var(--card);border:1px solid var(--line);border-radius:20px;padding:12px;margin-bottom:8px;width:100%;text-align:left}
.ev .tm{flex:0 0 58px;border-radius:14px;background:var(--card2);display:grid;place-items:center;text-align:center;font-family:var(--disp);font-weight:800;font-size:19px;line-height:1}
.ev .tm small{display:block;font-family:var(--body);font-size:10px;color:var(--mut);font-weight:700;margin-top:3px}
.ev.fx .tm{background:linear-gradient(160deg,var(--g),var(--g3));color:#02110a}
.ev.fx .tm small{color:#063}
.ev.cx{opacity:.7}
.ev.cx b{text-decoration:line-through;text-decoration-color:var(--red)}
.ev .grow{flex:1;min-width:0;padding:2px 0}
.ev b{font-size:15px}
.ev p{font-size:12px;color:var(--mut);margin-top:3px}

/* forms */
.field{display:block;margin-bottom:12px}
.field span{display:block;font-size:12px;color:var(--mut);margin-bottom:6px;font-weight:700}
.field input,.field textarea,.field select{width:100%;background:var(--bg2);border:1px solid var(--line);border-radius:14px;padding:13px 14px;font-size:16px;outline:none;resize:none;appearance:none}
.field input:focus,.field textarea:focus,.field select:focus{border-color:var(--g);box-shadow:0 0 0 4px rgba(63,243,106,.12)}
.g2{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:10px}
.g3{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}
.opt{border:1px solid var(--line);background:var(--bg2);border-radius:15px;padding:12px 6px;text-align:center;font-weight:800;font-size:14px;transition:all .2s var(--spring)}
.opt small{display:block;color:var(--mut);font-weight:600;font-size:11px;margin-top:2px}
.opt.on{border-color:var(--g);background:rgba(63,243,106,.13);color:var(--g);box-shadow:0 0 0 4px rgba(63,243,106,.1);transform:scale(1.03)}
.steps{display:flex;gap:6px;padding:16px 18px 4px}
.steps i{flex:1;height:5px;border-radius:9px;background:rgba(255,255,255,.08);overflow:hidden;position:relative}
.steps i.done::after{content:"";position:absolute;inset:0;background:var(--g);animation:grow .5s ease forwards;transform-origin:left}
@keyframes grow{from{transform:scaleX(0)}}
.panel{margin:14px;background:var(--card);border:1px solid var(--line);border-radius:26px;padding:18px}
.panel h3{font-family:var(--disp);font-size:24px;font-weight:800;text-transform:uppercase;line-height:1}
.hint{color:var(--mut);font-size:13px;margin:6px 0 14px;line-height:1.45}
.bar{height:6px;border-radius:9px;background:rgba(255,255,255,.08);overflow:hidden}
.bar i{display:block;height:100%;background:linear-gradient(90deg,var(--g),var(--lime));border-radius:9px;transition:width 1s var(--ease)}
.sess{display:flex;gap:12px;align-items:center;border:1px solid var(--line);border-radius:18px;padding:12px;margin-bottom:8px;background:var(--bg2);width:100%;text-align:left;transition:all .2s}
.sess.on{border-color:var(--g);background:rgba(63,243,106,.1)}

/* ticket */
.ticket{margin:16px 14px;border-radius:28px;overflow:hidden;background:linear-gradient(160deg,#1b522f,#0a1a0f);border:1px solid rgba(63,243,106,.35);animation:pop .7s var(--spring)}
@keyframes pop{from{transform:scale(.7) rotate(-4deg);opacity:0}to{transform:none;opacity:1}}
.ticket .tp{padding:20px;display:flex;gap:14px;align-items:center}
.ticket .tp img{width:62px}
.ticket .tp h3{font-family:var(--disp);font-style:italic;font-weight:900;font-size:30px;line-height:.9;text-transform:uppercase}
.tear{height:0;border-top:2px dashed rgba(255,255,255,.2);margin:0 18px;position:relative}
.tear::before,.tear::after{content:"";position:absolute;top:-14px;width:26px;height:26px;border-radius:50%;background:var(--bg)}
.tear::before{left:-32px}.tear::after{right:-32px}
.ticket .bt{padding:18px 20px 20px;display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:12px}
.ticket .bt small{display:block;color:var(--mut);font-size:10px;letter-spacing:.12em;text-transform:uppercase;font-weight:700}
.ticket .bt b{font-size:15px}

/* pitch */
.pitch{margin:12px 14px 0;border-radius:26px;aspect-ratio:3/4;position:relative;overflow:hidden;touch-action:none;
  background:radial-gradient(120% 60% at 50% 50%,rgba(255,255,255,.06),transparent 70%),repeating-linear-gradient(180deg,#1d7334 0 10%,#186530 10% 20%);border:2px solid rgba(255,255,255,.25);box-shadow:inset 0 0 60px rgba(0,0,0,.4)}
.pitch .ln{position:absolute;border:2px solid rgba(255,255,255,.38);pointer-events:none}
.pl{position:absolute;transform:translate(-50%,-50%);text-align:center;width:76px;transition:left .55s var(--ease),top .55s var(--ease);touch-action:none;user-select:none;-webkit-user-select:none}
.pl.drag{transition:none;z-index:5}
.pl.drag .sh{transform:scale(1.22);box-shadow:0 16px 28px rgba(0,0,0,.5),0 0 0 3px #0b0b0b,0 0 0 5px var(--lime)}
.coach .pl{cursor:grab}
.sh{width:44px;height:44px;margin:0 auto;border-radius:50%;background:radial-gradient(circle at 32% 28%,#fff,#d5dad4);color:#08200f;display:grid;place-items:center;font-family:var(--disp);font-weight:900;font-size:20px;box-shadow:0 7px 16px rgba(0,0,0,.45),0 0 0 3px #0b0b0b,0 0 0 5px var(--g);transition:transform .25s var(--spring)}
.pl.gk .sh{background:radial-gradient(circle at 32% 28%,#ffe98a,#ffb21d)}
.pl.me .sh{box-shadow:0 7px 16px rgba(0,0,0,.45),0 0 0 3px #0b0b0b,0 0 0 5px var(--lime),0 0 24px var(--lime)}
.pl span{display:inline-block;margin-top:5px;font-size:11px;font-weight:800;background:rgba(0,0,0,.62);padding:2px 8px;border-radius:7px}
.pl .gl{position:absolute;top:-6px;right:12px;font-size:13px}
.feed{display:grid;gap:6px;margin:12px 14px 0}
.fe{display:flex;gap:10px;align-items:center;font-size:13px;background:var(--card);border-radius:13px;padding:9px 12px;border:1px solid var(--line);animation:viewIn .4s var(--ease)}
.fe b{font-family:var(--disp);color:var(--g);font-size:16px;min-width:32px}
.tog{width:52px;height:30px;border-radius:99px;background:#2a3a2e;position:relative;transition:background .25s;flex:0 0 52px}
.tog::after{content:"";position:absolute;top:3px;left:3px;width:24px;height:24px;border-radius:50%;background:#fff;transition:transform .3s var(--spring);box-shadow:0 2px 6px rgba(0,0,0,.3)}
.tog.on{background:var(--g)}
.tog.on::after{transform:translateX(22px)}
.resimg{width:100%;border-radius:18px;display:block;box-shadow:0 24px 60px rgba(0,0,0,.6);animation:pop .7s var(--spring)}

/* Navigation owns layout space; safe-area padding is outside its touch targets. */
.tabbar{position:relative;flex:0 0 auto;display:flex;align-items:stretch;min-height:74px;height:auto;margin:8px 12px calc(8px + var(--safe-bottom));padding:8px 4px;border-radius:28px;z-index:40;background:#09140c;border:1px solid rgba(63,243,106,.24);box-shadow:0 8px 24px rgba(0,0,0,.35)}
.tabbar:empty{display:none}
.tb{display:flex;flex:1 1 0%;min-width:0;min-height:56px;flex-direction:column;align-items:center;justify-content:center;gap:4px;padding:4px 1px 9px;font-size:.625rem;line-height:1.2;font-weight:800;color:var(--mut);letter-spacing:0;transition:color .25s;position:relative}
.tb svg{width:22px;height:22px;flex:0 0 22px}
.tb-label{display:block;max-width:100%;white-space:normal;overflow-wrap:anywhere;text-align:center}
.tb.on{color:var(--g)}
.tb.on::after{content:"";position:absolute;bottom:3px;left:50%;transform:translateX(-50%);width:5px;height:5px;border-radius:50%;background:var(--g);box-shadow:0 0 8px var(--g)}
.tb .dot{top:0;right:calc(50% - 25px);min-width:16px;height:16px;font-size:9px;line-height:1}

/* sheet */
.scrim{position:absolute;inset:0;background:rgba(0,0,0,.66);z-index:60;opacity:0;pointer-events:none;transition:opacity .35s;backdrop-filter:blur(3px)}
.scrim.on{opacity:1;pointer-events:auto}
.sheet{position:absolute;left:var(--safe-left);right:var(--safe-right);bottom:0;z-index:61;background:linear-gradient(180deg,#0d1c12,var(--bg2) 30%);border-radius:32px 32px 0 0;border-top:1px solid rgba(63,243,106,.3);transform:translateY(105%);transition:transform .55s var(--ease);max-height:calc(100% - var(--safe-top) - 12px);overflow-y:auto;overflow-x:hidden;padding:10px 0 calc(18px + var(--safe-bottom));scrollbar-width:none;overscroll-behavior:contain;scroll-padding:16px;visibility:hidden}
.sheet::-webkit-scrollbar{display:none}
.sheet.on{transform:none;visibility:visible}
.grab{width:44px;height:5px;border-radius:9px;background:rgba(255,255,255,.2);margin:0 auto 12px}
.shb{padding:4px 20px 0}
.shb h3{font-family:var(--disp);font-weight:900;font-style:italic;font-size:32px;text-transform:uppercase;line-height:.95}
.kv{display:grid;gap:8px;margin:14px 0}
.kv div{display:flex;gap:12px;align-items:center;background:var(--card);border-radius:14px;padding:12px 14px;font-size:14px}
.kv i{font-style:normal;font-size:18px;width:24px;text-align:center}
.kv b{margin-left:auto}
.ok{text-align:center;padding:26px 0 8px}
.ok .tk{width:100px;height:100px;margin:0 auto;border-radius:50%;background:var(--g);display:grid;place-items:center;animation:pop .7s var(--spring);box-shadow:0 0 60px rgba(63,243,106,.6)}
.ok .tk svg{width:54px;height:54px;stroke:#02110a;stroke-width:3.5;fill:none;stroke-dasharray:40;stroke-dashoffset:40;animation:draw .5s .35s forwards}
@keyframes draw{to{stroke-dashoffset:0}}
@keyframes rot{to{transform:rotate(360deg)}}

/* push / toast / fx */
.push{position:absolute;top:calc(var(--top) - 4px);left:10px;right:10px;z-index:250;border-radius:24px;padding:12px 14px;display:flex;gap:12px;align-items:center;
  background:rgba(32,38,34,.88);backdrop-filter:blur(24px) saturate(1.6);-webkit-backdrop-filter:blur(24px) saturate(1.6);border:1px solid rgba(255,255,255,.08);box-shadow:0 18px 44px rgba(0,0,0,.55);
  transform:translateY(-180%) scale(.96);transition:transform .6s var(--spring)}
.push.on{transform:none}
.push img{width:40px;height:40px;border-radius:11px}
.push b{font-size:13px}
.push p{font-size:13px;color:#d2dbd4;margin-top:1px;line-height:1.3}
.push small{font-size:11px;color:var(--mut);margin-left:auto;align-self:flex-start}
.pwa-note{position:absolute;left:12px;right:12px;top:max(10px,env(safe-area-inset-top));z-index:260;display:none;align-items:center;justify-content:space-between;gap:10px;padding:11px 14px;border-radius:16px;background:#15251a;border:1px solid var(--line2);box-shadow:0 12px 35px #0009;font-size:13px;font-weight:700}.pwa-note.on{display:flex}.pwa-note button{flex:0 0 auto;color:#061009;background:var(--g);padding:8px 11px;border-radius:10px;font-weight:900}
.toast{position:absolute;left:50%;bottom:var(--nav-clearance);max-width:calc(100% - 32px);text-align:center;overflow-wrap:anywhere;transform:translate(-50%,30px) scale(.9);opacity:0;z-index:240;background:var(--w);color:#05140a;font-weight:800;font-size:13px;padding:11px 16px;border-radius:15px;transition:all .4s var(--spring);white-space:normal;box-shadow:0 12px 30px rgba(0,0,0,.45);pointer-events:none}
.toast.on{opacity:1;transform:translate(-50%,0)}
#fx{position:absolute;inset:0;pointer-events:none;z-index:230}
.goal{position:absolute;inset:0;z-index:228;display:grid;place-items:center;pointer-events:none;opacity:0;background:radial-gradient(circle,rgba(63,243,106,.25),transparent 60%)}
.goal.on{animation:gf 2s ease}
.goal b{font-family:var(--disp);font-style:italic;font-weight:900;font-size:120px;color:var(--g);text-shadow:0 0 70px rgba(63,243,106,.9);transform:skewX(-8deg);line-height:.8;text-align:center}
.goal b small{display:block;font-size:30px;color:#fff;text-shadow:none;margin-top:10px;letter-spacing:.04em}
@keyframes gf{0%{opacity:0;transform:scale(.3)}18%{opacity:1;transform:scale(1.12)}30%{transform:scale(1)}80%{opacity:1}100%{opacity:0;transform:scale(1.05)}}

/* intro */
.intro{position:absolute;inset:0;z-index:280;background:#010302;display:grid;place-items:center;overflow:hidden;transition:opacity .8s,visibility .8s}
.intro.gone{opacity:0;visibility:hidden}
.intro canvas{position:absolute;inset:0;width:100%;height:100%}
.beam{position:absolute;top:-20%;width:190px;height:140%;background:linear-gradient(180deg,rgba(196,255,77,.42),rgba(63,243,106,.08) 55%,transparent 75%);filter:blur(22px);transform-origin:top center;mix-blend-mode:screen}
.beam.l{left:-60px;animation:bl 3s var(--ease) both}
.beam.r{right:-60px;animation:br 3s var(--ease) both}
@keyframes bl{0%{transform:rotate(-55deg);opacity:0}40%{opacity:1}100%{transform:rotate(-14deg);opacity:.85}}
@keyframes br{0%{transform:rotate(55deg);opacity:0}40%{opacity:1}100%{transform:rotate(14deg);opacity:.85}}
.ii{position:relative;text-align:center;perspective:800px}
.crestwrap{position:relative;width:190px;margin:0 auto;animation:crest 1.6s var(--ease) both .2s}
@keyframes crest{0%{transform:rotateY(-90deg) scale(.4);opacity:0;filter:blur(10px)}60%{opacity:1;filter:none}100%{transform:none}}
.crestwrap img{width:100%;display:block;filter:drop-shadow(0 0 50px rgba(63,243,106,.6))}
.crestwrap::after{content:"";position:absolute;inset:0;background:linear-gradient(110deg,transparent 35%,rgba(255,255,255,.75) 50%,transparent 65%);mix-blend-mode:overlay;-webkit-mask:var(--m) center/contain no-repeat;mask:var(--m) center/contain no-repeat;animation:sweep 1.4s 1.3s ease both;background-size:250% 100%}
@keyframes sweep{from{background-position:120% 0}to{background-position:-120% 0}}
.words{margin-top:22px;font-family:var(--disp);font-style:italic;font-weight:900;font-size:34px;text-transform:uppercase;line-height:1;display:flex;gap:9px;justify-content:center;flex-wrap:wrap}
.words span{display:inline-block;animation:word .6s var(--spring) both}
.words span:nth-child(1){animation-delay:1.5s}.words span:nth-child(2){animation-delay:1.62s}.words span:nth-child(3){animation-delay:1.74s;color:var(--g)}.words span:nth-child(4){animation-delay:1.86s;color:var(--g)}
@keyframes word{from{opacity:0;transform:translateY(30px) skewX(-10deg)}}
.intro .sub{margin-top:12px;color:var(--mut);font-size:12px;letter-spacing:.32em;text-transform:uppercase;font-weight:700;animation:viewIn .8s 2.1s both}

/* login */
.login{position:absolute;inset:0;z-index:270;display:flex;flex-direction:column;overflow-y:auto;scrollbar-width:none;
  background:radial-gradient(420px 360px at 50% 8%,rgba(63,243,106,.26),transparent 70%),linear-gradient(180deg,#06140a,#020604);transition:opacity .6s,transform .6s var(--ease)}
.login.gone{opacity:0;visibility:hidden;pointer-events:none;transform:scale(1.06)}
.login::-webkit-scrollbar{display:none}
.lg-pitch{position:absolute;left:-20%;right:-20%;bottom:-8%;height:62%;transform:perspective(500px) rotateX(58deg);transform-origin:bottom;
  background:repeating-linear-gradient(90deg,rgba(63,243,106,.07) 0 12%,rgba(63,243,106,.03) 12% 24%);border-top:2px solid rgba(63,243,106,.3);pointer-events:none}
.lg-pitch::before{content:"";position:absolute;left:50%;top:20%;width:180px;height:180px;border:2px solid rgba(63,243,106,.25);border-radius:50%;transform:translateX(-50%)}
.lg-pitch::after{content:"";position:absolute;left:0;right:0;top:calc(20% + 90px);height:2px;background:rgba(63,243,106,.25)}
.lg-in{position:relative;padding:calc(var(--top) + 18px) 22px calc(30px + var(--safe-bottom));display:flex;flex-direction:column;min-height:100%}
.lg-head{text-align:center}
.lg-head img{width:96px;filter:drop-shadow(0 0 30px rgba(63,243,106,.5))}
.lg-head h1{font-family:var(--disp);font-style:italic;font-weight:900;font-size:40px;text-transform:uppercase;line-height:.9;margin-top:10px}
.lg-head p{color:var(--mut);font-size:14px;margin-top:6px}
@keyframes shake{20%,60%{transform:translateX(-10px)}40%,80%{transform:translateX(10px)}}
.keys{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;max-width:290px;margin:0 auto}
.key{height:60px;border-radius:20px;background:rgba(255,255,255,.05);border:1px solid var(--line);font-family:var(--disp);font-size:28px;font-weight:700;transition:all .12s}
.key:active{background:var(--g);color:#02110a;transform:scale(.94)}
.key.fn{font-family:var(--body);font-size:13px;font-weight:700;color:var(--mut);background:none;border:0}

/* install */
.ihd{display:flex;gap:14px;align-items:center}
.ihd img{width:78px;height:78px;border-radius:21px;box-shadow:0 12px 30px rgba(63,243,106,.4),0 0 0 1px rgba(63,243,106,.4);animation:wob 2.6s ease-in-out infinite}
@keyframes wob{50%{transform:translateY(-5px) rotate(-2deg)}}
.ihd p{color:var(--mut);font-size:13px;margin-top:4px}
.stars{color:var(--amber);font-size:13px;letter-spacing:2px}
.perks{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin:18px 0}
.perks div{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:12px 6px;text-align:center;font-size:11px;font-weight:800;line-height:1.25}
.perks span{display:block;font-size:22px;margin-bottom:4px}
.home{margin:14px 0 4px;border-radius:28px;padding:22px 18px;background:linear-gradient(160deg,#2b4a8a,#6a3d8c 60%,#1a1f3f)}
.hg{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px 10px}
.ha{display:flex;flex-direction:column;align-items:center;gap:5px;font-size:10px;color:#fff;font-weight:600}
.ha i{width:54px;height:54px;border-radius:15px;background:rgba(255,255,255,.22);display:block}
.ha img{width:54px;height:54px;border-radius:15px;display:block}
.ha.new{animation:drop 1s var(--spring) both .3s}
@keyframes drop{from{transform:translateY(-160px) scale(1.7);opacity:0}}
.ha.new img{box-shadow:0 0 0 3px rgba(255,255,255,.9),0 0 30px rgba(63,243,106,.95)}
.ipill{position:absolute;left:14px;right:14px;bottom:var(--nav-clearance);z-index:41;display:flex;align-items:center;gap:10px;padding:10px 10px 10px 12px;border-radius:20px;
  background:rgba(18,40,25,.9);backdrop-filter:blur(18px);-webkit-backdrop-filter:blur(18px);border:1px solid rgba(63,243,106,.4);box-shadow:0 16px 34px rgba(0,0,0,.55);
  transform:translateY(170px);opacity:0;transition:all .7s var(--spring)}
.ipill.on{transform:none;opacity:1}
.ipill img{width:40px;height:40px;border-radius:11px}
.ipill div{flex:1;min-width:0;font-size:13px;line-height:1.25}
.ipill small{display:block;color:var(--mut);font-size:11px}
.ipill .x{width:28px;height:28px;color:var(--mut);font-size:20px}
.empty{color:var(--mut);font-size:14px;text-align:center;padding:24px 10px}
.hide{display:none!important}

/* ===== v4 additions ===== */
body{font-size:15px}
.stepper{display:flex;gap:6px;padding:14px 14px 0}
.stp{flex:1;display:flex;flex-direction:column;gap:6px;align-items:flex-start;font-size:11px;font-weight:800;color:var(--dim);letter-spacing:.04em;text-transform:uppercase;text-align:left}
.stp i{display:block;width:100%;height:5px;border-radius:9px;background:rgba(255,255,255,.08);overflow:hidden;position:relative}
.stp.done i::after,.stp.on i::after{content:"";position:absolute;inset:0;background:var(--g);border-radius:9px}
.stp.on i::after{animation:grow .5s ease both;transform-origin:left}
.stp.on,.stp.done{color:var(--w)}
.stp.on{color:var(--g)}
.qhead{padding:20px 18px 6px}
.qhead h2{font-family:var(--disp);font-style:italic;font-weight:900;font-size:38px;text-transform:uppercase;line-height:.92}
.qhead p{color:var(--mut);font-size:14px;margin-top:6px;line-height:1.45}
.tiles{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;padding:12px 14px 0}
.tile{border-radius:22px;padding:26px 6px 12px;background:var(--card);border:2px solid var(--line);display:flex;flex-direction:column;align-items:center;gap:6px;transition:all .3s var(--spring);position:relative}
.tile .a{width:54px;height:54px;border-radius:50%;display:grid;place-items:center;font-family:var(--disp);font-weight:900;font-size:24px;background:var(--card2);color:var(--mut);transition:all .3s var(--spring)}
.tile b{font-size:15px;font-weight:800}
.tile small{font-size:11px;color:var(--mut);font-weight:700}
.tile.in{border-color:var(--g);background:linear-gradient(160deg,#173d22,var(--card))}
.tile.in .a{background:var(--g);color:#02110a;box-shadow:0 0 20px rgba(63,243,106,.45)}
.tile.out{opacity:.45}
.tile .tag{position:absolute;top:7px;left:50%;transform:translateX(-50%);white-space:nowrap;font-size:8.5px;font-weight:900;letter-spacing:.08em;padding:3px 6px;border-radius:6px;background:rgba(255,201,60,.16);color:var(--amber)}
.tile .tag.ok{background:rgba(63,243,106,.16);color:var(--g)}
.summary{margin:14px 14px 0;padding:14px 16px;border-radius:20px;background:var(--card);border:1px solid var(--line);display:flex;align-items:center;gap:14px}
.summary b.n{font-family:var(--disp);font-weight:900;font-size:40px;line-height:1;color:var(--g)}
.summary p{font-size:13px;color:var(--mut);line-height:1.4}
.summary p strong{color:var(--w)}
.cta{padding:18px 14px 8px}
.cta.static{position:static;background:none;padding-top:16px}
.cta .btn{width:100%;padding:17px;font-size:16px;border-radius:19px}
.segc{display:flex;background:var(--card);border:1px solid var(--line);border-radius:16px;padding:4px;margin:12px 14px 0}
.segc button{flex:1;padding:11px 6px;border-radius:12px;font-weight:800;font-size:13px;color:var(--mut);transition:all .25s}
.segc button.on{background:var(--w);color:#05140a}
.toolrow{display:flex;gap:8px;padding:12px 14px 0}
.toolrow .btn{flex:1}
.pl.sel .sh{transform:scale(1.2);box-shadow:0 0 0 3px #0b0b0b,0 0 0 6px var(--lime),0 0 30px var(--lime)}
.pl .lk{position:absolute;top:-8px;left:10px;font-size:13px;filter:drop-shadow(0 2px 3px rgba(0,0,0,.6))}
.bench{display:flex;gap:8px;flex-wrap:wrap;padding:10px 14px 0;align-items:center}
.bench>span{font-size:11px;font-weight:800;letter-spacing:.14em;color:var(--mut);text-transform:uppercase;margin-right:2px}
.bch{display:flex;align-items:center;gap:7px;padding:6px 12px 6px 6px;border-radius:99px;background:var(--card);border:1px solid var(--line);font-weight:800;font-size:13px;transition:all .2s}
.bch i{width:26px;height:26px;border-radius:50%;display:grid;place-items:center;font-style:normal;font-family:var(--disp);background:var(--card2);font-size:14px}
.bch.sel{border-color:var(--lime);box-shadow:0 0 0 3px rgba(196,255,77,.25)}
.selbar{margin:10px 14px 0;padding:12px 14px;border-radius:16px;background:rgba(196,255,77,.1);border:1px solid rgba(196,255,77,.35);display:flex;align-items:center;gap:10px;font-size:13px;font-weight:700;animation:viewIn .3s var(--ease)}
.selbar span{flex:1}
.plan{margin:12px 14px 0;background:var(--card);border:1px solid var(--line);border-radius:22px;padding:14px 12px;overflow:hidden}
.prow{display:grid;grid-template-columns:70px minmax(0,1fr) 38px;gap:8px;align-items:center;padding:4px 0}
.prow .nm{font-size:13px;font-weight:800;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.prow .nm small{color:var(--mut);font-weight:700;font-size:10px;margin-left:3px}
.blks{display:grid;gap:3px}
.blk{height:20px;border-radius:5px;background:rgba(255,255,255,.05)}
.blk.on{background:linear-gradient(180deg,#5cff84,var(--g2));animation:blkIn .5s var(--spring) both}
.blk.gk{background:linear-gradient(180deg,#ffe98a,#e9a514)}
.blk.now{outline:2px solid #fff;outline-offset:1px}
@keyframes blkIn{from{transform:scaleY(0)}}
.prow em{font-style:normal;font-family:var(--disp);font-weight:800;font-size:16px;text-align:right}
.phead{display:grid;grid-template-columns:70px minmax(0,1fr) 38px;gap:8px;font-size:10px;font-weight:800;color:var(--dim);letter-spacing:.08em;padding-bottom:6px;border-bottom:1px solid var(--line);margin-bottom:4px}
.phead .ticks{display:grid}
.fair{display:flex;gap:10px;align-items:center;margin:12px 14px 0;padding:12px 14px;border-radius:16px;background:rgba(63,243,106,.1);border:1px solid rgba(63,243,106,.3);font-size:13px;font-weight:700;line-height:1.35}
.fair i{font-style:normal;font-size:22px}
.optrow{display:flex;gap:6px;flex-wrap:wrap}
.lab{font-size:11px;font-weight:800;letter-spacing:.14em;color:var(--mut);text-transform:uppercase;margin:16px 0 8px}
.board{margin:12px 14px 0;border-radius:28px;padding:18px 16px;background:linear-gradient(165deg,#0f3a1d,#050d08);border:1px solid var(--line2);position:relative;overflow:hidden}
.board.live{border-color:rgba(255,93,93,.45);box-shadow:0 0 0 1px rgba(255,93,93,.15),0 20px 50px rgba(0,0,0,.5)}
.board .clk{font-family:var(--disp);font-weight:900;font-size:22px;color:var(--g);text-align:center;font-variant-numeric:tabular-nums;letter-spacing:.04em}
.bigbtns{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:10px;margin:12px 14px 0}
.bigbtns button{padding:18px 8px;border-radius:20px;font-weight:900;font-size:16px;font-family:var(--disp);letter-spacing:.04em;text-transform:uppercase}
.bigbtns .us{background:linear-gradient(180deg,#5cff84,var(--g2));color:#02110a;box-shadow:0 12px 28px rgba(63,243,106,.35)}
.bigbtns .them{background:var(--card);border:1px solid var(--line)}
.subcard{margin:12px 14px 0;border-radius:24px;padding:16px;background:var(--card);border:1px solid var(--line);transition:all .4s var(--ease)}
.subcard.due{background:linear-gradient(160deg,#3d5c10,#142208);border-color:var(--lime);box-shadow:0 0 0 4px rgba(196,255,77,.15);animation:duePulse 1.4s ease-in-out infinite}
@keyframes duePulse{50%{box-shadow:0 0 0 10px rgba(196,255,77,.05),0 0 40px rgba(196,255,77,.25)}}
.subhd{display:flex;justify-content:space-between;align-items:baseline}
.subhd b{font-family:var(--disp);font-weight:900;font-size:20px;text-transform:uppercase}
.subhd em{font-style:normal;font-family:var(--disp);font-weight:900;font-size:30px;color:var(--lime);font-variant-numeric:tabular-nums}
.pair{display:grid;grid-template-columns:minmax(0,1fr) auto minmax(0,1fr) auto;gap:8px;align-items:center;margin-top:10px;padding:10px 12px;border-radius:14px;background:rgba(0,0,0,.28);font-weight:800;font-size:14px}
.pair .in{color:var(--g)}.pair .out{color:#ff9d9d;text-align:right}
.pair small{display:block;font-size:10px;font-weight:800;letter-spacing:.12em;opacity:.8}
.pair .sw{font-size:11px;padding:6px 9px;border-radius:9px;background:rgba(255,255,255,.08);font-weight:800}
.minbar{display:grid;grid-template-columns:72px minmax(0,1fr) 44px;gap:8px;align-items:center;font-size:13px;font-weight:700;padding:4px 0}
.minbar .bar{height:10px;position:relative}
.minbar .bar b{position:absolute;top:-3px;bottom:-3px;width:2px;background:#fff;opacity:.6}
.minbar em{font-style:normal;text-align:right;color:var(--mut);font-variant-numeric:tabular-nums}
.minbar.onf span::after{content:" ●";color:var(--g);font-size:10px}
.speed{display:flex;justify-content:center;gap:6px;margin-top:10px}
.speed button{font-size:11px;font-weight:800;padding:5px 10px;border-radius:9px;background:rgba(255,255,255,.06);color:var(--mut)}
.speed button.on{background:var(--w);color:#05140a}
.tbl{margin:12px 14px 0;background:var(--card);border:1px solid var(--line);border-radius:22px;overflow:hidden}
.tbl table{width:100%;border-collapse:collapse;font-size:14px;table-layout:fixed}
.tbl th:first-child{width:32%}
.tbl td:first-child{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.tbl th{font-size:10px;letter-spacing:.1em;color:var(--mut);font-weight:800;padding:12px 6px;text-align:center;cursor:pointer;user-select:none}
.tbl th:first-child,.tbl td:first-child{text-align:left;padding-left:14px}
.tbl th.on{color:var(--g)}
.tbl td{padding:11px 6px;text-align:center;border-top:1px solid var(--line);font-weight:700;font-variant-numeric:tabular-nums}
.tbl td:first-child{font-weight:800}
.tbl td.hi{color:var(--g);font-family:var(--disp);font-size:18px;font-weight:900}
.tbl tr.lead td:first-child{color:var(--lime)}
.bibs{display:grid;gap:10px;padding:12px 14px 0}
.bib{border-radius:22px;padding:14px;border:1px solid var(--line);background:var(--card);animation:viewIn .5s var(--ease) both}
.bib h4{display:flex;align-items:center;gap:10px;font-family:var(--disp);font-weight:900;font-size:20px;text-transform:uppercase}
.bib h4 i{width:22px;height:22px;border-radius:7px;display:block;border:2px solid rgba(255,255,255,.3)}
.bib h4 small{margin-left:auto;font-family:var(--body);font-size:11px;color:var(--mut);font-weight:800;letter-spacing:.06em}
.bib .chips{margin-top:10px}
.bib .chip{cursor:pointer;font-size:13px;padding:8px 11px}
.stars{display:flex;gap:6px}
.stars button{font-size:26px;filter:grayscale(1) opacity(.35);transition:all .2s var(--spring)}
.stars button.on{filter:none;transform:scale(1.1)}
.role{display:flex;gap:16px;align-items:center;text-align:left;padding:18px;border-radius:26px;background:var(--glass);border:1px solid var(--line2);backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px);transition:all .25s var(--spring);width:100%}
.role:active{transform:scale(.97)}
.role .av{width:58px;height:58px;border-radius:19px;font-size:22px}
.role b{font-family:var(--disp);font-size:26px;text-transform:uppercase;display:block;line-height:1}
.role small{color:var(--mut);font-size:13px;line-height:1.35;display:block;margin-top:4px}
.role .go{margin-left:auto;font-size:22px;color:var(--g)}
.undo{margin-left:auto;font-size:11px;font-weight:800;padding:5px 9px;border-radius:8px;background:rgba(255,255,255,.08)}


.thread .badge{min-width:22px;height:22px;border-radius:11px;background:var(--g);color:#02110a;font-size:11px;font-weight:900;display:grid;place-items:center;padding:0 6px}
.chathead{display:flex;gap:12px;align-items:center;padding:4px 0 6px}
.chathead .av{width:46px;height:46px}
.seen{align-self:flex-end;font-size:10px;color:var(--mut);font-weight:700;margin-top:-4px}
.cal{padding:14px 12px}
.calh{display:flex;align-items:center;justify-content:space-between;margin-bottom:10px}
.calh b{font-family:var(--disp);font-weight:900;font-size:22px;text-transform:uppercase}
.cgrid7{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:4px;text-align:center}
.cgrid7>small{font-size:10px;font-weight:800;color:var(--dim);padding-bottom:4px}
.cday{aspect-ratio:1;border-radius:12px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;font-weight:800;font-size:14px;transition:all .2s}
.cday.today span{color:var(--g)}
.cday.sel{background:var(--w);color:#05140a}
.cday i{display:flex;gap:2px;height:6px}
.cday i b{width:6px;height:6px;border-radius:50%}
.legend{display:flex;flex-wrap:wrap;gap:10px;justify-content:center;margin-top:10px;font-size:11px;font-weight:700;color:var(--mut)}
.legend span{display:flex;align-items:center;gap:5px}.legend b{width:8px;height:8px;border-radius:50%}
.campc{border-radius:24px;padding:16px;background:linear-gradient(150deg,#13324a,#0a1622);border:1px solid rgba(90,168,255,.3);cursor:pointer}
.camph{display:flex;gap:12px;align-items:center}.camph>span{font-size:34px}
.camph b{font-family:var(--disp);font-weight:900;font-size:22px;text-transform:uppercase;line-height:1;display:block}
.camph p{font-size:12px;color:var(--mut);margin-top:4px;line-height:1.35}
.campdays{display:grid;grid-auto-flow:column;grid-auto-columns:1fr;gap:6px;margin:14px 0 12px}
.campdays>div{text-align:center}.campdays small{font-size:10px;font-weight:800;color:var(--mut)}
.campdays .bar{margin:5px 0 4px;height:5px}.campdays .bar i{background:linear-gradient(90deg,#5aa8ff,#9fd0ff)}
.campdays em{font-style:normal;font-size:10px;font-weight:800;color:#9fd0ff}
.campf{display:flex;justify-content:space-between;align-items:center;font-size:13px;font-weight:700;color:#d2e6d6}
.rk small{display:block}
.ppbtn{display:flex;align-items:center;justify-content:center;gap:0;width:100%;padding:16px;border-radius:99px;background:#ffc439;text-decoration:none;font-family:Verdana,Arial,sans-serif;font-style:italic;font-weight:900;font-size:24px;box-shadow:0 10px 26px rgba(255,196,57,.25);transition:transform .15s}
.ppbtn:active{transform:scale(.97)}
a.btn{text-decoration:none}
.pp1{color:#003087}.pp2{color:#009cde}
.ppmark{width:84px;height:84px;margin:0 auto;border-radius:24px;background:#ffc439;display:grid;place-items:center;font-family:Verdana,Arial,sans-serif;font-style:italic;font-weight:900;font-size:44px;animation:wob 2s ease-in-out infinite}
.row.thread.unread::after{display:none}
.list>*{min-width:0}.list{grid-template-columns:minmax(0,1fr)}

.auth{display:grid;gap:12px;margin-top:22px}
.auth .field{margin:0}
.auth .lnk{color:var(--g);font-weight:700;text-align:center;font-size:14px;padding:6px}
.auth .err{background:rgba(255,93,93,.12);border:1px solid rgba(255,93,93,.35);color:#ffb0b0;border-radius:14px;padding:10px 12px;font-size:14px}
.kidrow{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr) 44px;gap:8px;align-items:end}
.kidrow .x{height:46px;border-radius:12px;background:rgba(255,255,255,.06);color:var(--mut)}
.req{background:var(--card);border:1px solid var(--line2);border-radius:20px;padding:14px;margin:0 14px 10px}
.req h4{font-family:var(--disp);font-size:20px;text-transform:uppercase}
.req .kr{display:grid;grid-template-columns:minmax(0,1fr) 1.3fr;gap:8px;align-items:center;margin-top:8px;font-weight:700;font-size:14px}
.req select{width:100%;background:var(--card2);border:1px solid var(--line);border-radius:12px;padding:10px;color:var(--w)}
.ro{text-align:center;color:var(--mut);font-size:13px;padding:14px 20px 26px}
.sync{position:absolute;top:calc(var(--top) + 2px);right:14px;z-index:250;width:8px;height:8px;border-radius:50%;background:var(--amber);opacity:0;transition:opacity .3s}
.sync.on{opacity:1}
.login{overflow-x:hidden}
.inst{position:absolute;inset:0;z-index:400;display:none;overflow-y:auto;background:radial-gradient(90% 60% at 50% 20%,rgba(63,243,106,.22),transparent 70%),var(--bg)}
.inst.on{display:block}
.iin{min-height:100%;display:flex;flex-direction:column;align-items:center;text-align:center;padding:calc(var(--top) + 28px) 24px calc(28px + var(--safe-bottom));overflow-wrap:anywhere}
.iin img{width:150px;filter:drop-shadow(0 0 30px rgba(63,243,106,.45));animation:float 5s ease-in-out infinite}
@keyframes float{50%{transform:translateY(-8px)}}
.ieb{margin-top:14px;font-family:var(--disp);font-weight:800;font-size:13px;letter-spacing:.28em;text-transform:uppercase;color:var(--g)}
.iin h2{font-family:var(--disp);font-weight:900;font-style:italic;text-transform:uppercase;font-size:40px;line-height:.92;margin:8px 0 10px}
.iin>p{color:var(--mut);font-size:15px;line-height:1.5;margin-bottom:18px}
.ist{display:flex;gap:14px;align-items:center;text-align:left;width:100%;background:var(--card);border:1px solid var(--line2);border-radius:18px;padding:14px 16px;margin-bottom:10px;font-size:15px;line-height:1.4}
.ist i{flex:none;width:34px;height:34px;border-radius:50%;display:grid;place-items:center;font-style:normal;font-family:var(--disp);font-weight:900;font-size:18px;background:var(--g);color:#04140a}
.iarrow{font-size:40px;color:var(--g);margin-top:8px;animation:bob 1.2s ease-in-out infinite}
@keyframes bob{50%{transform:translateY(10px)}}
.iweb{margin-top:auto;padding-top:26px;color:var(--dim);font-size:13px;text-decoration:underline}
/* chat extras: reactions, edits, photos, read receipts */
.tk{font-style:normal;margin-left:5px;letter-spacing:-4px;font-weight:900;font-size:11px;opacity:.55;padding-right:4px}
.tk.rd{opacity:1;color:#0b62e8}.bub.them .tk.rd,.sec .tk.rd{color:#4fb4ff}
.bub[data-m]{position:relative;-webkit-user-select:none;user-select:none;-webkit-touch-callout:none}
.bub.hasrx{margin-bottom:12px}
.bub .rx{position:absolute;bottom:-14px;right:10px;background:var(--card2);border:1px solid var(--line);border-radius:99px;padding:2px 7px;font-size:12px;line-height:18px;color:var(--ink);font-weight:800;white-space:nowrap;box-shadow:0 4px 12px rgba(0,0,0,.35)}
.bub.them .rx{right:auto;left:10px}
.bub.gone{font-style:italic;opacity:.6;background:transparent!important;border:1px dashed var(--line)!important;color:var(--mut)!important;font-weight:500}
.bub.pic{padding:4px 4px 8px}.bub.pic .mt,.bub.pic>b{padding:4px 8px 0;display:block}.bub.pic small{padding:0 8px}
.mimg{display:block;width:100%;max-width:240px;min-height:80px;max-height:320px;object-fit:cover;border-radius:15px;background:rgba(255,255,255,.06);-webkit-touch-callout:none}
.row .mimg{max-width:100%;margin-top:8px;border-radius:12px}
.bub.lp{transform:scale(.96);transition:transform .2s}
.rxbar{display:flex;justify-content:space-between;gap:4px;background:var(--card);border:1px solid var(--line);border-radius:99px;padding:6px 8px;margin:4px 0 14px}
.rxbar button{font-size:26px;width:40px;height:40px;border-radius:50%;display:grid;place-items:center;transition:transform .15s}
.rxbar button:active{transform:scale(1.25)}.rxbar button.on{background:rgba(63,243,106,.22)}
.mprev{background:var(--card2);border-radius:14px;padding:10px 12px;font-size:14px;color:var(--mut);margin-bottom:12px;max-height:70px;overflow:hidden}
.att{width:44px;height:44px;flex:0 0 44px;border-radius:50%;display:grid;place-items:center;font-size:20px;background:var(--card);border:1px solid var(--line);cursor:pointer}
.phprev{width:100%;max-height:52vh;object-fit:contain;border-radius:16px;background:#000;margin:4px 0 12px}
.consent{background:rgba(255,201,60,.12);border:1px solid rgba(255,201,60,.4);color:#ffd970;border-radius:12px;padding:10px 12px;font-size:13px;line-height:1.45;margin-bottom:12px}
#lb{position:fixed;inset:0;z-index:9999;background:rgba(0,0,0,.94);display:none;place-items:center;padding:calc(64px + var(--safe-top)) calc(16px + var(--safe-right)) calc(56px + var(--safe-bottom)) calc(16px + var(--safe-left))}
#lb.on{display:grid}#lb img{display:block;max-width:100%;max-height:100%;object-fit:contain;border-radius:10px}
#lb button{position:absolute;top:calc(14px + env(safe-area-inset-top));right:14px;width:44px;height:44px;border-radius:50%;background:rgba(255,255,255,.14);color:#fff;font-size:20px}
#lb p{position:absolute;bottom:calc(16px + env(safe-area-inset-bottom));left:0;right:0;text-align:center;color:#aaa;font-size:12px}
.calsv{width:36px!important;height:36px!important;border-radius:12px!important;font-size:16px;align-self:flex-start}
.mthumb{position:relative;margin:0 0 12px}.mthumb img{width:100%;max-height:200px;object-fit:cover;border-radius:14px}.mthumb button{position:absolute;top:8px;right:8px;width:32px;height:32px;border-radius:50%;background:rgba(0,0,0,.7);color:#fff}
/* ---------- shared in-app messaging surface ---------- */
/* One flex column owns the conversation: fixed header/footer, scrollable messages. */
.screen.chatv{display:flex;flex-direction:column;min-height:0;overflow:hidden;padding-bottom:0;overscroll-behavior:contain}
.screen.chatv>.view{flex:1 1 auto;width:100%;height:100%;min-height:0;display:flex;flex-direction:column;overflow:hidden}
.chat-shell{display:flex;flex:1 1 auto;flex-direction:column;width:100%;height:100%;min-height:0;overflow:hidden;background:linear-gradient(180deg,#06130b,#041009)}
.chathead.modern{position:relative;z-index:2;display:flex;flex:0 0 auto;align-items:center;gap:11px;min-height:70px;margin:0;padding:calc(9px + env(safe-area-inset-top)) 14px 10px;background:#07140c;border-bottom:1px solid rgba(63,243,106,.13)}
.chathead.modern .back{width:42px;height:42px;flex:0 0 42px;border-radius:14px;display:grid;place-items:center;background:rgba(255,255,255,.055);border:1px solid rgba(255,255,255,.09);font-size:28px;line-height:1;color:#fff}
.chathead.modern .av{width:46px;height:46px;flex:0 0 46px;border:2px solid rgba(63,243,106,.3)}
.chathead.modern .grow{min-width:0}
.chathead.modern .grow>b{font-size:18px!important;letter-spacing:.01em}
.chathead.modern .status{margin-top:3px;font-size:11px;color:#91a497;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.chat-toolbar{display:flex;align-items:center;gap:6px;margin-left:auto}
.chat-toolbar .iconbtn{width:40px;height:40px;border-radius:13px;display:grid;place-items:center;background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.08);color:#e5eee7;font-size:18px}
.chat{position:relative;display:flex;flex:1 1 auto;flex-direction:column;justify-content:flex-start;gap:7px;min-height:0;height:auto;overflow-x:hidden;overflow-y:auto;overscroll-behavior:contain;-webkit-overflow-scrolling:touch;scroll-behavior:auto;padding:16px 13px;background:linear-gradient(180deg,#06130b,#030a06)}
.chat:before{content:"AG";position:fixed;left:50%;top:52%;transform:translate(-50%,-50%);font-size:92px;font-weight:1000;letter-spacing:-.08em;color:rgba(63,243,106,.025);pointer-events:none}
.chat>*{position:relative;z-index:1;flex-shrink:0}
.chat::-webkit-scrollbar{display:none}.chat{scrollbar-width:none}
.chat-date{align-self:center;margin:8px 0 5px;padding:6px 11px;border-radius:99px;background:rgba(255,255,255,.055);border:1px solid rgba(255,255,255,.07);font-size:9px;font-weight:900;letter-spacing:.13em;text-transform:uppercase;color:#92a297}
.daysep{align-self:center;margin:6px 0;padding:6px 11px;border-radius:99px;background:rgba(255,255,255,.045);font-size:10px;font-weight:800;letter-spacing:.08em;color:#91a497}
.bub{position:relative;align-self:flex-start;max-width:min(84%,460px);padding:10px 12px;border-radius:18px;font-size:14px;line-height:1.42;box-shadow:0 6px 18px rgba(0,0,0,.18);animation:viewIn .25s var(--ease)}
.bub.me{align-self:flex-end;background:linear-gradient(145deg,#61ff87,#27dc5b);color:#02110a;border-bottom-right-radius:5px}
.bub.them{background:linear-gradient(145deg,#1c2a20,#101b14);border:1px solid rgba(255,255,255,.085);border-bottom-left-radius:5px}
.bub small{display:flex;justify-content:flex-end;align-items:center;gap:3px;margin-top:5px;font-size:9px;opacity:.68}
.bub.me small{color:#0b3b1c}.bub.me+.bub.me{margin-top:-3px;border-top-right-radius:8px}.bub.them+.bub.them{margin-top:-3px;border-top-left-radius:8px}
.bub .tk{font-size:12px;font-style:normal;letter-spacing:-3px;margin-left:1px}.bub .tk.rd{color:#087c3a}
.bub .mt{display:block}.chat .bub.pic .mimg{display:block;width:100%;max-width:240px;border-radius:13px;margin:-2px -2px 7px;box-shadow:0 8px 24px rgba(0,0,0,.25)}
.bub.lp{transform:scale(.98);filter:brightness(1.08)}
.chat-empty{margin:auto;text-align:center;max-width:300px;padding:28px 18px;color:#dce8df}
.chat-empty .big{width:64px;height:64px;margin:0 auto 14px;border-radius:22px;display:grid;place-items:center;background:rgba(63,243,106,.1);border:1px solid rgba(63,243,106,.18);font-size:28px}
.chat-empty b{font-size:20px;text-transform:uppercase}.chat-empty .hint{font-size:13px;color:#91a497}
.unread-divider{display:flex;align-items:center;gap:10px;flex:0 0 auto;margin:9px 6px 3px;color:#b9ff78;font-size:10px;font-weight:900;letter-spacing:.14em;text-transform:uppercase}
.unread-divider:before,.unread-divider:after{content:'';height:1px;flex:1;background:linear-gradient(90deg,transparent,rgba(63,243,106,.36))}.unread-divider:after{background:linear-gradient(90deg,rgba(63,243,106,.36),transparent)}
.chat-quick{display:flex;flex:0 0 auto;gap:8px;overflow-x:auto;padding:8px 12px;background:#06110a;border-top:1px solid rgba(255,255,255,.045);scrollbar-width:none}
.chat-quick::-webkit-scrollbar{display:none}.chat-quick button{flex:0 0 auto;min-height:38px;padding:8px 13px;border-radius:999px;background:rgba(255,255,255,.045);border:1px solid rgba(63,243,106,.16);color:#dce9df;font-size:11px;font-weight:800;white-space:nowrap}
.chat-composer{position:relative;z-index:2;display:flex;flex:0 0 auto;align-items:flex-end;gap:8px;min-height:60px;padding:8px 12px;background:#07110a;border-top:1px solid rgba(255,255,255,.08)}
.chat-composer .att{width:44px;height:44px;flex:0 0 44px;border-radius:15px;display:grid;place-items:center;background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.09);color:#fff;font-size:18px}
.chat-composer .voice-btn{width:44px;height:44px;flex:0 0 44px;border-radius:15px;display:grid;place-items:center;background:rgba(63,243,106,.10);border:1px solid rgba(63,243,106,.24);color:#b9ff78;font-size:19px}
.chat-composer input{height:44px!important;min-width:0!important;flex:1 1 auto!important;border-radius:15px!important;background:rgba(255,255,255,.07)!important;border:1px solid rgba(255,255,255,.11)!important;padding:10px 14px!important;color:#fff!important;font-size:16px!important;outline:none!important;box-shadow:none!important}
.chat-composer input::placeholder{color:#91a096}.chat-composer input:focus{border-color:rgba(63,243,106,.6)!important}
.chat-composer .send{width:44px;height:44px;flex:0 0 44px;border-radius:15px;background:linear-gradient(145deg,#65ff8a,#27d957);color:#02110a;font-size:21px;font-weight:1000;box-shadow:0 7px 18px rgba(63,243,106,.18)}
.chat-composer .send:active{transform:scale(.95)}
.bub .voice-player{display:block;width:min(280px,70vw);max-width:100%;height:40px;margin:4px 0 2px;color-scheme:dark}
.chat-sheet{position:absolute!important;top:0!important;bottom:0!important;left:var(--safe-left)!important;right:var(--safe-right)!important;width:auto!important;height:100%!important;max-height:none!important;margin:0!important;padding:0!important;border:0!important;border-radius:0!important;background:#06130b!important;overflow:hidden!important;transform:translateY(105%)!important}
.chat-sheet.on{transform:none!important}.chat-sheet .grabz{display:none!important}.chat-sheet .shb{display:flex!important;flex:1;flex-direction:column;width:100%;height:100%;min-height:0;padding:0!important;overflow:hidden!important}.chat-sheet .chat-shell{height:100%;min-height:0}
.group-chat-screen,.private-chat-screen{height:100%;min-height:0;overflow:hidden}.group-chat-screen>.chat,.private-chat-screen>.chat{flex:1 1 auto;min-height:0}
.group-chat-screen .ro{flex:0 0 auto}
.chat-search{display:flex;align-items:center;gap:8px;margin:0 14px 12px;padding:0 13px;border:1px solid rgba(63,243,106,.16);border-radius:15px;background:rgba(255,255,255,.045)}
.chat-search input{width:100%;height:44px;border:0!important;background:transparent!important;box-shadow:none!important;outline:0!important;font-size:16px}
.chat-directory-empty{display:none;margin:12px 14px;padding:22px;text-align:center;border:1px dashed rgba(63,243,106,.22);border-radius:18px;color:var(--mut)}
.pc-photo-slot{position:absolute;left:50%;top:14%;transform:translateX(-50%);width:46%;aspect-ratio:1/1;z-index:2;display:block;overflow:visible}
.pc-photo-slot .pc-ph{position:relative;display:block;left:auto;top:auto;transform:none;width:100%;height:100%;box-sizing:border-box;object-fit:cover;object-position:center;border-radius:50%;border:2px solid rgba(63,243,106,.55);box-shadow:0 4px 18px #0008;background:#0a1a10}
.pc-photo-slot .pc-s{position:relative;left:auto;top:auto;transform:none;width:100%;height:100%}
.phpick{display:flex;align-items:center;gap:14px;margin:4px 0 14px;padding:12px;background:var(--card);border:1px solid var(--line);border-radius:16px}.phpick .av{width:64px;height:64px;font-size:22px;flex:0 0 64px}.phpick .grow{flex:1;min-width:0}.phpick .hint{margin:0;font-size:12px}
@media(max-width:860px){.bub{max-width:88%}.chat{padding-left:11px;padding-right:11px}.chat-composer{padding-left:9px;padding-right:9px}}
/* The keyboard shrinks the common shell for chats, forms, login and sheets alike. */
html.viewport-adjusted .stage{top:var(--keyboard-top,0px);height:var(--keyboard-height,100vh)}
html.keyboard-open .tabbar,html.keyboard-open .ipill{display:none}
html.keyboard-open .chat-composer{padding-bottom:8px}
html.keyboard-open .sheet{padding-bottom:16px}
html.keyboard-open .chat{scroll-behavior:auto;overflow-anchor:none}
html.keyboard-open{--safe-bottom:0px;--top:calc(8px + var(--safe-top))}
.chat-sheet .chat-composer{padding-bottom:calc(8px + var(--safe-bottom))}
html.keyboard-open .chat-sheet .chat-composer{padding-bottom:8px}

/* Birthday celebration */
.bdayveil{position:fixed;inset:0;z-index:10000;background:radial-gradient(ellipse at 50% 18%,#1d5c30 0,#07140b 58%,#020704 100%);display:flex;align-items:center;justify-content:center;padding:22px;overflow:hidden}
.bdayveil:before,.bdayveil:after{content:'⚽';position:absolute;font-size:clamp(90px,22vw,190px);opacity:.10;pointer-events:none;transform:rotate(-18deg)}
.bdayveil:before{top:5%;left:-5%}.bdayveil:after{bottom:2%;right:-5%;transform:rotate(18deg)}
.bdaycard{position:relative;z-index:1;width:min(100%,440px);text-align:center;padding:34px 24px 28px;border:1px solid rgba(196,255,77,.5);border-radius:28px;background:linear-gradient(160deg,rgba(15,39,22,.98),rgba(3,12,6,.98));box-shadow:0 24px 90px #000b,0 0 50px #3ff36a22}
.bdayballs{font-size:36px;letter-spacing:9px;margin-bottom:14px}.bdaybrand{font-size:11px;letter-spacing:4px;font-weight:900;color:#c4ff4d}.bdaytitle{font-family:var(--disp);font-weight:1000;font-size:clamp(32px,9vw,48px);line-height:.98;color:#fff;margin:14px 0 10px;text-transform:uppercase}.bdayname{font-family:var(--disp);font-weight:1000;font-size:clamp(38px,11vw,58px);line-height:1;color:#c4ff4d;text-transform:uppercase;overflow-wrap:anywhere}.bdaymsg{font-size:16px;line-height:1.55;color:#e8f4e9;margin:18px 0 24px}.bdaybtn{width:100%;border:0;border-radius:14px;padding:16px 18px;background:linear-gradient(100deg,#3ff36a,#c4ff4d);color:#061009;font-weight:1000;font-size:15px;letter-spacing:1px}

/* ---------- mobile finish: iPhone and Android ---------- */
html{-webkit-text-size-adjust:100%;text-size-adjust:100%}
body{-webkit-overflow-scrolling:touch}
button,a,input,select,textarea{-webkit-appearance:none;touch-action:manipulation}
/* Privacy consent checkbox: a real checkbox (kept for accessibility and tapping) with a drawn box that follows :checked, so it never depends on the browser's native checkbox look. */
.privacy-consent{display:flex;gap:12px;align-items:flex-start;font-size:13px;color:var(--mute);margin:4px 0 12px;line-height:1.45;text-align:left;cursor:pointer;position:relative;-webkit-user-select:none;user-select:none}
.privacy-consent .pc-in{position:absolute;left:0;top:0;width:24px;height:24px;margin:0;opacity:0;cursor:pointer;z-index:2;-webkit-appearance:none;appearance:none}
.privacy-consent .pc-box{flex:0 0 26px;width:26px;height:26px;border:2px solid #3ff36a;border-radius:7px;background:#061009;box-sizing:border-box;position:relative;margin-top:0}
.privacy-consent .pc-box:after{content:"";position:absolute;left:7px;top:2px;width:7px;height:13px;border:solid #061009;border-width:0 3px 3px 0;transform:rotate(45deg);opacity:0}
.privacy-consent .pc-in:checked+.pc-box{background:#3ff36a}
.privacy-consent .pc-in:checked+.pc-box:after{opacity:1}
.privacy-consent .pc-in:focus-visible+.pc-box{outline:3px solid rgba(63,243,106,.35);outline-offset:3px}
.privacy-consent .pc-txt{flex:1;display:block}
.privacy-consent .pc-txt a{color:var(--g);font-weight:700}
button{user-select:none}
input,select,textarea{font-size:16px;max-width:100%}
:focus-visible{outline:2px solid var(--lime);outline-offset:3px}
button:disabled{cursor:not-allowed;filter:saturate(.55)}
.screen{overscroll-behavior-y:contain;-webkit-overflow-scrolling:touch}
.card,.row,.hero,.sheet,.tabbar,.bdaycard{backface-visibility:hidden}
@media (max-width:860px){
  .sheet{padding-bottom:calc(18px + var(--safe-bottom))}
  .bdayveil{padding:calc(18px + env(safe-area-inset-top)) 18px calc(18px + env(safe-area-inset-bottom))}
  .bdaycard{max-height:calc(100vh - 36px - var(--safe-top) - var(--safe-bottom));max-height:calc(100dvh - 36px - var(--safe-top) - var(--safe-bottom));overflow-y:auto;padding:clamp(22px,6vh,34px) 20px}
  .bdayballs{font-size:clamp(28px,8vw,36px);letter-spacing:5px}
  .bdaymsg{font-size:15px}
  .bdaybtn{min-height:52px}
}
@media (max-width:360px){
  .top{padding-left:14px;padding-right:14px;gap:9px}
  .ph h1{font-size:42px}
  h2.sec{font-size:20px;padding-left:14px;padding-right:14px}
  .card,.list{margin-left:10px;margin-right:10px}
  .hero{margin-left:10px;margin-right:10px;padding:17px}
}
@media (prefers-reduced-motion:reduce){
  *,*::before,*::after{scroll-behavior:auto!important;animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}
}




.season-layout{display:flex;gap:14px;padding:0 14px;align-items:center;min-width:0}
.season-metrics{flex:1;min-width:0;display:grid;gap:8px}
.baseline-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px}
.baseline-grid>*{min-width:0}
.score-entry{display:flex;flex-wrap:wrap;justify-content:space-around;align-items:center;gap:12px;background:var(--card);border:1px solid var(--line);border-radius:18px;padding:12px 6px;margin-bottom:14px}
.score-entry>div{min-width:0;max-width:100%;overflow-wrap:anywhere}
.score-stepper{display:flex;align-items:center;justify-content:center;gap:10px}
.stats-scroll{overflow-x:auto;margin-top:8px;-webkit-overflow-scrolling:touch;overscroll-behavior-x:contain}
.stats-scroll>.row{min-width:370px}.stats-scroll span{overflow-wrap:anywhere}
.support-home-card{flex-wrap:wrap}.support-home-card>div{flex:1 1 180px;min-width:0}.support-home-card .btn{flex:1 1 150px!important}
.kv>div{flex-wrap:wrap;min-width:0;overflow-wrap:anywhere}
.kv>div>b{flex:1 1 100%;margin-left:36px;max-width:calc(100% - 36px)!important;text-align:left!important;overflow-wrap:anywhere}
.account-family-card>.kv>div>b{margin-left:0;max-width:100%!important}
.camph>div,.campf>*{min-width:0;overflow-wrap:anywhere}.campf{flex-wrap:wrap;gap:8px}
.bub,.bub .mt,.meta,.vs .nm{overflow-wrap:anywhere}.vs>*{min-width:0}
.chathead.modern .grow{flex:1 1 0%;min-width:0}.chat-toolbar{flex:0 0 auto}
.bdayveil{padding-left:calc(18px + var(--safe-left));padding-right:calc(18px + var(--safe-right))}
@media(max-width:380px){
  .season-layout{flex-direction:column;align-items:stretch}.season-layout>.pc{align-self:center}.season-metrics{width:100%}
  .baseline-grid,.g3:not(#posg),.tiles{grid-template-columns:repeat(2,minmax(0,1fr))}
  .kidrow,.req .kr{grid-template-columns:minmax(0,1fr)}
  .score-entry{flex-direction:column}.score-divider{display:none}
  .row .duo{grid-template-columns:minmax(0,1fr)}
}


/* Absolute authentication/install surfaces own their horizontal safe gutters. */
.lg-in{padding-left:calc(22px + var(--safe-left));padding-right:calc(22px + var(--safe-right));min-width:0;flex-shrink:0}
.iin{padding-left:calc(24px + var(--safe-left));padding-right:calc(24px + var(--safe-right));min-width:0}
.login{overflow-x:hidden}.lg-pitch{left:0;right:0;transform:none;overflow:hidden}
.chat-sheet .shb{padding-left:0;padding-right:0}
@media(max-width:380px){.support-home-card>div,.support-home-card .btn{flex:0 0 auto!important}}

/* Content reflow: narrow phones, long names and user-enlarged text. */
.view,.grow,.t,.field,.card>div,.panel>div,.row>div,.ev>div,.sess>div,.ihd>div,.ticket .tp>div{min-width:0}
img,video,audio,canvas{max-width:100%}
.row b,.row p,.ev b,.ev p,.hint,.cw-title,.cw-copy,.cw-squad,.coach-welcome h2,.hero h3,.ph h1,.qhead h2,.shb h3,.kv b,.kv span,.loyhero b,.loyhero p,.reg-h h4,.reg-h p,.role b,.role small{overflow-wrap:anywhere}
.btn,.seg,.opt,.chip{min-height:44px;max-width:100%;white-space:normal;overflow-wrap:anywhere;line-height:1.25}
.btn{flex-shrink:1}
.g2>*,.g3>*,.duo>*,.kpis>*,.cgrid>*,.lsum>*,.tiles>*,.perks>*,.cd>*,.stamps>*{min-width:0}
.cw-foot,.loy-meta,.subhd,h2.sec{flex-wrap:wrap}
h2.sec{gap:8px 12px}h2.sec a{flex:0 0 auto}
.toolrow{flex-wrap:wrap}.toolrow .btn{flex:1 1 120px}
.kids{overflow-x:auto;scrollbar-width:none}.kid-pill{flex:0 0 auto}
.top b{white-space:normal;overflow:visible;text-overflow:clip;font-size:clamp(17px,4.6vw,21px)}
.cd div{min-width:0}.cd span{letter-spacing:.08em}
.pc.lg{width:min(270px,100%)}
.tbl{overflow-x:auto;-webkit-overflow-scrolling:touch}.tbl table{min-width:320px}
.role>div,.loyhero>div,.reg-h>div,.ihd>div,.ticket .tp>div{flex:1 1 auto;min-width:0}
.rk{min-width:0;text-align:center;overflow-wrap:anywhere}
.act span,.selbar span{min-width:0;overflow-wrap:anywhere}
.act{flex-wrap:wrap}.act small{margin-left:auto}
.stamps i{height:40px;height:auto;min-height:24px}
.cday{min-height:38px}.pitch{height:auto;min-height:320px}
.ipill:not(.on){visibility:hidden;pointer-events:none}.ipill.on{visibility:visible}
.sheet .grab{width:54px;height:6px;margin:4px auto 10px;background:rgba(255,255,255,.32)}
.sheet .grabz{position:sticky;top:-10px;z-index:3;min-height:44px;padding:10px 0 6px;margin-top:-10px;touch-action:none;background:var(--bg2)}
.sheet .shx{position:absolute;right:14px;top:4px;width:44px;height:44px;border-radius:50%;border:1px solid var(--line);background:#13241a;color:var(--w);font-size:16px;line-height:1;z-index:4;cursor:pointer}
#incogB{white-space:normal!important;overflow-wrap:anywhere}
@media(max-width:380px){
  .top{gap:8px;padding-left:12px;padding-right:12px;flex-wrap:wrap}
  .top .t{flex:1 1 110px}.account-btn{min-width:44px;max-width:100%;min-height:44px}
  .regg{grid-template-columns:repeat(4,minmax(0,1fr))}
  .g2{grid-template-columns:minmax(0,1fr)}
  .ihd img{width:60px;height:60px;flex:0 0 60px}.ihd{gap:10px}
  .hg{grid-template-columns:repeat(3,minmax(0,1fr))}
  .home{padding:18px 12px}.ha i,.ha img{width:48px;height:48px}
  .ipill{flex-wrap:wrap}.ipill div{flex-basis:calc(100% - 60px)}
  .ipill .btn{margin-left:auto}.ipill .x{min-width:44px;min-height:44px}
  .goal b{font-size:80px}.goal b small{font-size:22px}
  .pair{grid-template-columns:minmax(0,1fr) auto;gap:8px}
}
@media(max-height:480px){
  :root{--top:calc(8px + var(--safe-top))}
  .tabbar{min-height:60px;margin-top:4px;margin-bottom:calc(4px + var(--safe-bottom));padding:4px}
  .tb{min-height:50px}.chathead.modern{min-height:56px}
  .lg-head img{width:64px}.lg-head h1{font-size:30px}
  .sheet{max-height:calc(100% - var(--safe-top) - 6px)}
}
@supports not (aspect-ratio:1){
  .pc{height:213.46px}.pc.lg{height:384.23px}
  .cgrid .pc{height:calc((100vw - 40px)*.71154)}
  .pitch{height:calc((100vw - 28px)*1.33333)}
  .stamps i{height:38px}.cday{height:40px}
}

.checkin-admin #checkinPoster{box-shadow:0 12px 32px rgba(0,0,0,.28)}
.checkin-admin #checkinQR img,.checkin-admin #checkinQR canvas{display:block;width:210px!important;max-width:100%!important;height:auto!important;aspect-ratio:1;image-rendering:pixelated}
.checkin-admin .btn.full{width:100%}
</style>
</head>
<body>
<div class="stage">
  <div class="phone">
    <div class="notch"></div>
    <div class="sbar"><span id="clk">9:41</span><i>●●● 5G ▮</i></div>
    <div class="app" id="app">
      <div class="screen" id="screen"></div>
      <nav class="tabbar" id="tabbar" aria-label="Main navigation"></nav>
      <div class="ipill" id="ipill"><img src="?a=icon&amp;s=192" alt=""><div><b>Get the AG FC app</b><small>Free · on your home screen in 2 seconds</small></div><button class="btn sm" onclick="openInstall()">Install</button><button class="x" onclick="hidePill()" aria-label="Dismiss">×</button></div>
      <div class="scrim" id="scrim" onclick="closeSheet()"></div>
      <div class="sheet" id="sheet" role="dialog" aria-label="Club information" aria-modal="true" aria-hidden="true" tabindex="-1"><div class="grab"></div><div id="shb"></div></div>
      <div class="goal" id="goal"><b>GOAL!<small id="goalWho"></small></b></div>
      <canvas id="fx"></canvas>
      <div class="push" id="push"><img src="?a=icon&amp;s=192" alt=""><div><b id="pushT">AG Coaching FC</b><p id="pushX"></p></div><small>now</small></div>
      <div class="pwa-note" id="pwaNote" role="status" aria-live="polite"></div><div class="toast" id="toast"></div><div class="sync" id="sync" title="Saving"></div>
      <div class="login gone" id="login"><div class="lg-pitch"></div><div class="lg-in" id="lgIn"></div></div>
      <div class="intro" id="intro">
        <canvas id="introFx"></canvas>
        <div class="beam l"></div><div class="beam r"></div>
        <div class="ii"><div class="crestwrap" id="crestwrap"><img src="?a=icon&amp;s=badge" alt="AG Coaching FC"></div>
          <div class="words"><span>One</span><span>club,</span><span>one</span><span>family</span></div></div>
      </div>
    </div>
  </div>
</div>

<script>
/* AG Coaching FC · responsive club app · North Point Creative */
if(!Array.prototype.at){Object.defineProperty(Array.prototype,'at',{value:function(i){i=Math.trunc(Number(i)||0);if(i<0)i+=this.length;return this[i];},writable:true,configurable:true});}
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const BADGE=document.querySelector('.crestwrap img').src, ICON=document.querySelector('.push img').src; document.documentElement.style.setProperty('--badge',`url(${BADGE})`);
$('#crestwrap').style.setProperty('--m',`url(${BADGE})`);
const pad=n=>String(n).padStart(2,'0');
const DAYS=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'],DAYL=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'],MON=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const ymd=d=>`${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;
const dayStart=d=>new Date(d.getFullYear(),d.getMonth(),d.getDate());
const addDays=(d,n)=>new Date(d.getFullYear(),d.getMonth(),d.getDate()+n);
const fmtD=d=>`${DAYS[d.getDay()]} ${d.getDate()} ${MON[d.getMonth()]}`;
const hm=d=>`${pad(d.getHours())}:${pad(d.getMinutes())}`;
const mmss=s=>`${pad(Math.floor(s/60))}:${pad(Math.floor(s%60))}`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=p=>p+Math.random().toString(36).slice(2,8);
const newPlayerRef=()=>{const used=new Set((S?.players||[]).map(p=>p.playerRef).filter(Boolean));let n=1,ref='';do{ref='AGFC-'+String(n++).padStart(6,'0')}while(used.has(ref));return ref;};

const ago=ts=>{const s=(Date.now()-ts)/1000;if(s<60)return'just now';if(s<3600)return Math.floor(s/60)+'m ago';if(s<86400)return Math.floor(s/3600)+'h ago';return Math.floor(s/86400)+'d ago'};
const monthKey=()=>{const d=new Date();return `${d.getFullYear()}-${pad(d.getMonth()+1)}`};
const greet=()=>{const h=new Date().getHours();return h<12?'Good morning':h<18?'Good afternoon':'Good evening'};
const FEE=20;

/* ---------- teams & formats (FA pathway) ---------- */
let TEAMS={}, TK=[];
const FMT={5:[['GK',50,86],['DEF',50,66],['MID',22,45],['MID',78,45],['ST',50,23]],
           7:[['GK',50,87],['DEF',28,68],['DEF',72,68],['MID',17,46],['MID',50,49],['MID',83,46],['ST',50,22]]};

/* ---------- live store: the server is the source of truth ---------- */
let S=null, base=null, REV=0, outbox=[], inflight=false, pending=null, JOIN='', pollT=null, introDone=false, authReady=false;
const clone=o=>JSON.parse(JSON.stringify(o));
const isObj=x=>x!==null&&typeof x==='object'&&!Array.isArray(x);
const idArr=a=>a.every(x=>isObj(x)&&x.id!=null);
const J=x=>JSON.stringify(x);
function diff(a,b,path,out){
  if(a===b) return out;
  if(isObj(a)&&isObj(b)){
    for(const k in b){ if(b[k]===undefined) continue; if(!(k in a)||a[k]===undefined) out.push({op:'set',path:[...path,k],value:b[k]}); else diff(a[k],b[k],[...path,k],out); }
    for(const k in a) if(a[k]!==undefined&&(!(k in b)||b[k]===undefined)) out.push({op:'del',path:[...path,k]});
    return out;
  }
  if(Array.isArray(a)&&Array.isArray(b)){
    if((a.length||b.length)&&idArr(a)&&idArr(b)){
      const m=new Map(a.map(x=>[String(x.id),x])), seen=new Set();
      for(const x of b){ const k=String(x.id); seen.add(k); if(!m.has(k)) out.push({op:'upsert',path,value:x}); else diff(m.get(k),x,[...path,'#'+k],out); }
      for(const x of a) if(!seen.has(String(x.id))) out.push({op:'remove',path,id:x.id});
      return out;
    }
    const ja=J(a); if(ja===J(b)) return out;
    if(b.length>a.length&&J(b.slice(0,a.length))===ja){ out.push({op:'append',path,items:b.slice(a.length)}); return out; }
    for(let k=1;k<b.length;k++){ const rest=b.slice(k); if(J(rest)===J(a.slice(0,rest.length))){ out.push({op:'prepend',path,items:b.slice(0,k),max:b.length}); return out; } }
    out.push({op:'set',path,value:b}); return out;
  }
  if(J(a)!==J(b)) out.push({op:'set',path,value:b});
  return out;
}
function save(){ if(!S||!base) return; const ops=diff(base,S,[],[]); base=clone(S); if(ops.length){ outbox.push(...ops); flush(); } }
async function api(a,body){
  const r=await fetch('?a='+a,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json','X-AGFC':'1'}:{'X-AGFC':'1'},body:body?JSON.stringify(body):undefined,credentials:'same-origin',cache:'no-store'});
  let j=null; try{ j=await r.json(); }catch(e){}
  if(r.status===401&&a!=='login'&&a!=='me'){ onLoggedOut(); throw new Error('auth'); }
  if(!r.ok||!j) throw new Error(j?.error||'Can’t reach the club server. Check your signal and try again.');
  return j;
}
let flushT; function flush(){ clearTimeout(flushT); flushT=setTimeout(doFlush,250); }
async function doFlush(){
  if(inflight||!outbox.length) return; inflight=true; $('#sync')?.classList.add('on');
  const batch=outbox.splice(0); let reply=null;
  try{ const j=await api('ops',{ops:batch}); reply=j; REV=j.rev; if(!outbox.length) pending=j.S; }
  catch(e){ if(e.message!=='auth'){ outbox.unshift(...batch); setTimeout(flush,4000); toast('Offline · will save when you’re back online'); } }
  inflight=false; if(outbox.length) flush(); else { $('#sync')?.classList.remove('on'); flushPending(); }
  return reply;
}
function busy(){ const a=document.activeElement; return !!ui.profilePhotoBusy||$('#sheet')?.classList.contains('on')||(a&&/^(INPUT|TEXTAREA|SELECT)$/.test(a.tagName))||!!(typeof L!=='undefined'&&L.timer); }
function receive(st){ pending=st; flushPending(); }
function flushPending(){ if(!pending||inflight||outbox.length||busy()) return; const st=pending; pending=null; adopt(st); }
function adopt(st){
  S=st; base=clone(st); TEAMS=S.teams||{}; TK=Object.keys(TEAMS).filter(t=>!TEAMS[t].campsOnly); if(!TEAMS[ui.sq]) ui.sq=TK[0];
  if(me){ const u=(S.users||[]).find(x=>x.id===me.id); if(u){ me={...me,...u}; if(!u.photo) delete me.photo; } }
  if(me&&introDone&&$('#login').classList.contains('gone')) paint(true);
}
async function poll(){ if(!me||me.status!=='approved'||inflight||outbox.length||document.hidden) return; try{ const j=await api('state&rev='+REV); if(j.same||Number(j.rev)<REV) return; REV=j.rev; receive(j.S); }catch(e){} }
document.addEventListener('focusout',()=>setTimeout(flushPending,60));
document.addEventListener('visibilitychange',()=>{ if(!document.hidden) poll(); });

const log=(ic,t)=>{ S.activity.unshift({ic,t,ts:Date.now()}); S.activity=S.activity.slice(0,40); };
const note=(to,ic,t)=>[].concat(to).filter(Boolean).forEach(x=>S.notes.push({id:uid('n'),to:x,ic,t,ts:Date.now(),read:false}));
const pars=p=>[...new Set([p?.parent,...(p?.parents||[])].filter(Boolean))];
const tell=(team,text)=>S.messages.push({id:uid('m'),from:'coach',teams:Array.isArray(team)?team:[team],text,ts:Date.now(),read:[]});

/* ---------- data helpers ---------- */
const P=id=>S.players.find(p=>p.id===id);
const playerTeams=p=>Array.isArray(p.teams)&&p.teams.length?p.teams:[p.team].filter(Boolean);
const inTeam=(p,t)=>playerTeams(p).includes(t);
const sessionAssigned=(p,sid)=>Array.isArray(p.sessionIds)?p.sessionIds.includes(sid):(()=>{const x=S.sessions.find(s=>s.id===sid);return !!x&&(x.teams||[]).some(t=>playerTeams(p).includes(t));})();
const numFor=(p,t)=>Number((p.squadNums||{})[t]??p.num)||0;
const teamPlayers=(t,all)=>S.players.filter(p=>inTeam(p,t)&&(all||!p.tr)).sort((a,b)=>(numFor(a,t)||99)-(numFor(b,t)||99)||a.name.localeCompare(b.name));
const F=id=>S.fixtures.find(f=>f.id===id);
function occ(from,days,filter){
  const out=[], base=dayStart(from);
  for(let i=0;i<days;i++){ const d=addDays(base,i);
    S.sessions.filter(s=>s.day===d.getDay()&&(!filter||filter(s))).forEach(s=>{ const [h,m]=s.start.split(':'),[eh,em]=s.end.split(':'); const a=new Date(d),e=new Date(d); a.setHours(+h,+m,0,0); e.setHours(+eh,+em,0,0); const key=s.id+'@'+ymd(d); out.push({kind:'s',s,at:a,end:e,key,cx:!!S.cancel[key]}); }); }
  return out.sort((a,b)=>a.at-b.at);
}
function stats(p, team=p.team){
  // Match statistics are scoped to the selected squad. Legacy imported totals stay
  // attached only to the player's original/main squad, never duplicated elsewhere.
  const fin=S.fixtures.filter(f=>f.team===team&&f.status==='ft');
  const apps=fin.filter(f=>(f.squad||[]).includes(p.id)).length;
  let goals=0,ast=0; fin.forEach(f=>(f.events||[]).forEach(e=>{ if(e.type==='goal'){ if(e.who===p.id)goals++; if(e.ast===p.id)ast++; } }));
  const potm=fin.filter(f=>f.potm===p.id).length, mins=Math.round(fin.reduce((a,f)=>a+((f.mins||{})[p.id]||0),0)/60);
  const cs=p.pos==='GK'?fin.filter(f=>(f.squad||[]).includes(p.id)&&f.them===0).length:0;
  const ss=S.sessions.filter(s=>(s.teams||[]).includes(team)&&sessionAssigned(p,s.id)).map(s=>s.id), ks=Object.keys(S.att||{}).filter(k=>ss.includes(k.split('@')[0]));
  const train=ks.length?Math.round(ks.filter(k=>(S.att[k]||[]).includes(p.id)).length/ks.length*100):null;
  const hat=fin.some(f=>(f.events||[]).filter(e=>e.type==='goal'&&e.who===p.id).length>=3);
  const b=(p.squadBase||{})[team] || (team===p.team?(p.base||{}):{});
  return {apps:apps+(+b.apps||0),goals:goals+(+b.goals||0),ast:ast+(+b.ast||0),potm:potm+(+b.potm||0),cs,mins,train,hat};
}
function sessionAttendance(p, sid){
  const keys=Object.keys(S.att||{}).filter(k=>k.split('@')[0]===sid);
  const attended=keys.filter(k=>(S.att[k]||[]).includes(p.id)).length;
  return {attended,total:keys.length,rate:keys.length?Math.round(attended/keys.length*100):null};
}
/* ---------- loyalty cards ---------- */
const LY=()=>({on:true,sessions:[],need:11,reward:'£5 off your next block',...(S.loyalty||{})});
const stOf=id=>{ const c=(S.stamps||{})[id]||{}; return {n:c.n||0,red:(c.redeemed||[]).length}; };
const stCard=id=>{ S.stamps=S.stamps||{}; const c=(S.stamps[id]??={n:0,log:[],due:false,redeemed:[],pn:[]}); c.log=c.log||[]; c.redeemed=c.redeemed||[]; c.pn=c.pn||[]; return c; };
const stDue=()=>S.players.filter(p=>stOf(p.id).n>=LY().need);
function stampNote(id,key,extra){ const p=P(id), c=stCard(id), L=LY(); if(!p||!pars(p).length||c.pn.includes(key)) return; c.pn.push(key); c.pn=c.pn.slice(-40);
  note(pars(p),c.n>=L.need?'🎉':'🎟️',c.n>=L.need?`${p.name}'s loyalty card is full! Reward unlocked: ${L.reward}. Show Alfie at the next session.`:`${p.name}'s loyalty card: ${c.n} of ${L.need} stamps${extra?'. '+extra:''}`); }
function stampSync(key){
  const L=LY(); if(!L.on) return; const [sid,day]=key.split('@'); if(!L.sessions.includes(sid)) return;
  const att=S.att[key]||[], mine=e=>e.sid===sid&&e.day===day&&!e.b&&!e.m&&!e.adj, fresh=[];
  S.players.forEach(p=>{ const here=att.includes(p.id), e0=((S.stamps||{})[p.id]?.log||[]).find(mine);
    if(here&&!e0){ const c=stCard(p.id); c.log.push({sid,day,ts:Date.now()}); c.n++; c.due=c.n>=L.need; fresh.push(p.id); }
    else if(!here&&e0){ const c=stCard(p.id); c.log=c.log.filter(e=>!mine(e)); if(!e0.void) c.n=Math.max(0,c.n-1); c.due=c.n>=L.need; } });
  fresh.forEach(id=>stampNote(id,key)); }
function giveReward(id,stay){ const p=P(id), c=stCard(id), L=LY(); if(c.n<L.need) return; c.n-=L.need; c.due=c.n>=L.need; c.redeemed.push(Date.now());
  log('🎁',`Reward given to ${p.name}: ${L.reward}`); save(); buzz(); toast(`Reward given to ${p.name} ✓ Card reset`); paint(true); if(stay) stampSheet(id,true); else closeSheet(); }
function loyDueHTML(){ const d=stDue(); if(!d.length) return '';
  return `<h2 class="sec">Rewards due <a>${d.length}</a></h2><div class="list">${d.map(p=>`<div class="row"><span class="ic">🎁</span><div class="grow"><b>${esc(p.name)}${p.last?' '+esc(p.last):''}</b><p>${esc(LY().reward)} · ${TEAMS[p.team]?.short||''}</p></div><button class="btn sm" onclick="giveReward('${p.id}')">Reward given</button></div>`).join('')}</div>`; }
const stNames=k=>S.sessions.filter(x=>LY().sessions.includes(x.id)&&(!k||x.teams.includes(k.team))).map(x=>x.title).join(' or ');
const stLast=cc=>(cc.log||[]).filter(e=>!e.void&&!e.adj).sort((a,b)=>(b.ts||0)-(a.ts||0))[0];
const stDay=e=>{ try{ return fmtD(new Date(e.day+'T12:00')); }catch(_){ return ''; } };
const STWHY=['By hand','Camp','1-1 session','Other'];
const stWhy=e=>e.adj?'Card corrected':e.b?'Bonus · brought a friend':e.m?(e.why||'Added by hand'):((S.sessions.find(x=>x.id===e.sid)||{}).title||'Session');
function loyBox(k,tap){ const L=LY(), c=stOf(k.id), cc=(S.stamps||{})[k.id]||{}, n=Math.min(c.n,L.need), due=c.n>=L.need, cols=L.need<=6?L.need:L.need%5===0?5:6, names=stNames(k), last=stLast(cc);
  return `<div class="loy ${due?'full':''} ${tap?'tap':''}" ${tap?`onclick="loyInfo('${k.id}')"`:''}><div class="loy-h"><img src="${BADGE}" alt=""><div><b>${n} of ${L.need}</b><small>${due?'Reward unlocked':(L.need-n)+' more to go'}</small></div></div>
   <div class="stamps" style="grid-template-columns:repeat(${cols},1fr)">${Array.from({length:L.need},(_,i)=>`<i class="${i<n?'on':''}">${i+1}</i>`).join('')}</div>
   ${due?`<div class="loy-win">🎉 Reward unlocked: ${esc(L.reward)}<small>Show Alfie at the next session</small></div>`:`<p class="hint">${names?`Every ${esc(names)} session earns a stamp. `:'Ask Alfie how to earn stamps. '}Full card: ${esc(L.reward)}.</p>`}
   <div class="loy-meta"><span>${last?'Last stamp: '+esc(stDay(last)):'No stamps yet'}</span><span>${c.red?'🎁 '+c.red+' reward'+(c.red>1?'s':'')+' earned':(tap?'Tap for history ›':'')}</span></div></div>`; }
function stampCardHTML(k){ const L=LY(); if(!L.on) return '';
  return `<h2 class="sec">${esc(k.name)}'s loyalty card <a onclick="loyInfo('${k.id}')">Stamp history</a></h2>`+loyBox(k,true); }
function loyInfo(id){ const k=P(id); if(!k) return; const L=LY(), cc=(S.stamps||{})[id]||{}, live=(cc.log||[]).filter(e=>!e.void&&!e.adj).sort((a,b)=>(b.ts||0)-(a.ts||0)).slice(0,15), names=stNames(k);
  openSheet(`<div class="shb"><h3>🎟️ ${esc(k.name)}'s loyalty card</h3><p class="hint">${names?`Come along to ${esc(names)} and collect a stamp every time. `:'Coach Alfie adds a stamp each time you earn one. '}${L.need} stamps earns: <b>${esc(L.reward)}</b>. Bringing a friend to a free taster earns a bonus stamp.</p>${loyBox(k,false)}
   <div class="lab" style="margin-top:18px">Recent stamps</div><div class="list">${live.map(e=>`<div class="row"><span class="ic">${e.b?'🤝':e.m?'🖐️':'✅'}</span><div class="grow"><b>${esc(stWhy(e))}</b><p>${esc(stDay(e))}</p></div></div>`).join('')||'<div class="empty">No stamps yet. Your first one is waiting.</div>'}</div></div>`); }
function attInfo(p){ const ss=S.sessions.filter(x=>x.teams.includes(p.team)).map(x=>x.id), from=S.seasonFrom||'';
  const ks=Object.keys(S.att).filter(k=>ss.includes(k.split('@')[0])&&k.split('@')[1]>=from&&(me?.role!=='coach'||(S.att[k]||[]).length)).sort((a,b)=>a.split('@')[1].localeCompare(b.split('@')[1]));
  const n=ks.filter(k=>S.att[k].includes(p.id)).length; let streak=0; for(let i=ks.length-1;i>=0&&S.att[ks[i]].includes(p.id);i--) streak++; return {n,streak}; }
function loyaltySheet(){ const L=LY();
  openSheet(`<div class="shb"><h3>⚙️ Loyalty settings</h3><p class="hint">A stamp is added when you tick a child in on the register for a session below. Un-tick the same day and it's removed. To add or take off stamps by hand, open the child's card from the Loyalty screen.</p>
   <div style="display:flex;align-items:center;gap:12px;margin:0 0 14px"><span style="flex:1;font-size:14px;font-weight:700">Loyalty cards on</span><button class="tog ${L.on?'on':''}" id="lyOn" onclick="this.classList.toggle('on')"></button></div>
   <div class="lab">Sessions that earn a stamp <a onclick="$$('#lyS .chip').forEach(c=>c.classList.add('on'))" style="float:right;color:var(--g)">Select all</a></div><div class="chips" id="lyS" style="margin-bottom:6px">${S.sessions.map(x=>`<button class="chip ${L.sessions.includes(x.id)?'on':''}" data-s="${x.id}" onclick="this.classList.toggle('on')">${esc(x.title)} · ${DAYL[x.day]}</button>`).join('')}</div>
   <p class="hint" style="margin:0 0 12px">These are your weekly sessions (Club → Sessions). Add a new session there and it shows up here. Camps and 1-1s don't have a register, so give those stamps by hand from the child's card.</p>
   <div class="g2"><label class="field"><span>Stamps for a reward</span><input id="lyN" type="number" min="1" max="50" value="${L.need}"></label><label class="field"><span>Reward</span><input id="lyR" value="${esc(L.reward)}"></label></div>
   <button class="btn full" onclick="saveLoyalty()">Save</button></div>`); }
function saveLoyalty(){ const sessions=$$('#lyS .chip.on').map(c=>c.dataset.s), need=Math.max(1,Math.min(50,+$('#lyN').value||11)), reward=$('#lyR').value.trim()||'£5 off your next block';
