function stampSheet(id,keep){ const p=P(id); if(!p) return; const L=LY(), cc=(S.stamps||{})[id]||{n:0,log:[],redeemed:[]}, n=cc.n||0, due=n>=L.need, sc=keep?$('#sheet').scrollTop:0, red=cc.redeemed||[];
