  openSheet(`<div class="shb"><h3>🎟️ ${esc(p.name+(p.last?' '+p.last:''))}</h3><p class="hint">${esc(TEAMS[p.team]?.short||'')} · Full card: ${esc(L.reward)}</p>${loyBox(p,false)}
