   <div class="lab" style="margin-top:20px">History</div>
   <div class="list">${rows.map(({e,i})=>`<div class="row" style="${e.void?'opacity:.55':''}"><span class="ic">${e.adj?'✏️':e.b?'🤝':e.m?'🖐️':'✅'}</span><div class="grow"><b style="${e.void?'text-decoration:line-through':''}">${esc(stWhy(e))}${e.adj?' ('+(e.adj>0?'+':'')+e.adj+')':''}</b><p>${esc(stDay(e))}${e.void?' · removed':''}</p></div>${e.adj?'':`<button class="btn sm gh" onclick="stampVoid('${id}',${i})">${e.void?'Put back':'Remove'}</button>`}</div>`).join('')||'<div class="empty">No stamps yet</div>'}</div>
   <p class="hint" style="margin-top:12px">Rewards given: ${red.length}${red.length?' · last '+esc(fmtD(new Date(red.at(-1)))):''}${red.length?` · <a onclick="undoReward('${id}')" style="color:var(--g)">Undo last reward</a>`:''}</p>
