function stampDone(id){ const c=stCard(id); c.due=c.n>=LY().need; save(); buzz(); paint(true); stampSheet(id,true); }
function stampAdj(id,d){ const p=P(id), c=stCard(id), day=ymd(new Date());
  if(d>0){ const why=$('#stWhy')?.value||'By hand'; c.log.push({m:1,why,day,ts:Date.now()}); c.n++; stampNote(id,'m_'+Date.now()); log('🎟️',`Stamp added for ${p.name} (${why})`); toast(`${p.name}: ${Math.min(c.n,LY().need)} of ${LY().need} ✓`); }
  else { if(c.n<1) return; const live=c.log.map((e,i)=>({e,i})).filter(x=>!x.e.void&&!x.e.adj).sort((a,b)=>(b.e.ts||0)-(a.e.ts||0)||b.i-a.i)[0];
    if(live) live.e.void=1; else c.log.push({adj:-1,day,ts:Date.now()}); c.n=Math.max(0,c.n-1); log('🎟️',`Stamp taken off ${p.name}`); toast(`Stamp taken off ${p.name}`); }
  stampDone(id); }
function stampSet(id){ const p=P(id), c=stCard(id), L=LY(), day=ymd(new Date()), v=Math.max(0,Math.min(L.need,Math.floor(+$('#stSet').value||0))), d=v-c.n; if(!d) return toast('Already on '+v);
  if(d>0){ for(let i=0;i<d;i++) c.log.push({m:1,why:'Paper card',day,ts:Date.now()}); } else c.log.push({adj:d,day,ts:Date.now()});
  c.n=v; log('🎟️',`${p.name}'s card set to ${v} of ${L.need}`); toast(`${p.name}: ${v} of ${L.need} ✓`); stampDone(id); }
function stampVoid(id,i){ const c=stCard(id), e=c.log[i]; if(!e||e.adj) return; e.void=e.void?0:1; c.n=Math.max(0,c.n+(e.void?-1:1)); log('🎟️',`Stamp ${e.void?'removed from':'put back on'} ${P(id).name}'s card`); stampDone(id); }
function undoReward(id){ const c=stCard(id); if(!c.redeemed.length) return; c.redeemed.pop(); c.n+=LY().need; log('↩️',`Reward undone for ${P(id).name}`); stampDone(id); }
