// auto-pick: fill FA-format slots from available players. mode: balanced|strongest. Respects locks.
function autoPick(f,mode,shuffle){
  const slots=FMT[TEAMS[f.team].fmt], av=teamPlayers(f.team).filter(p=>f.avail[p.id]);
  const lu={}, used=new Set(), locks=f.locks||[];
  // keep locked players in their current slot
  Object.entries(f.lineup||{}).forEach(([s,id])=>{ if(locks.includes(id)&&f.avail[id]){ lu[s]=id; used.add(id); } });
  const score=p=>(mode==='strongest'?p.lvl*10:0)+(shuffle?Math.random()*(mode==='strongest'?9:30):0)+(mode==='balanced'?(p.lvl===2?5:0):0);
  const order=[...av].sort((a,b)=>score(b)-score(a));
  slots.forEach(([pos],i)=>{ if(lu[i]) return; const p=order.find(x=>!used.has(x.id)&&x.pos===pos); if(p){lu[i]=p.id;used.add(p.id);} });
  slots.forEach(([pos],i)=>{ if(lu[i]) return; const p=order.find(x=>!used.has(x.id)&&(pos==='GK'?true:x.pos!=='GK')); if(p){lu[i]=p.id;used.add(p.id);} });
  f.lineup=lu; f.plan=null;
}
// fair game-time plan: blocks of f.int minutes; equal outfield blocks; continuity; like-for-like slots
function buildPlan(f,from=0,startOn=null,base=null){
  const slots=FMT[TEAMS[f.team].fmt], B=Math.max(1,Math.round(f.len/f.int));
  const on0=startOn||f.lineup; const gk=on0[0];
  const av=teamPlayers(f.team).filter(p=>f.avail[p.id]).map(p=>p.id);
  const out=av.filter(id=>id!==gk), nOut=slots.length-1;
  const cnt={}; out.forEach(id=>cnt[id]=base?Math.round((base[id]||0)/(f.int*60)):0);
  const blocks=(f.plan&&from>0)?f.plan.blocks.slice(0,from):[];
  let prev={...on0};
  for(let b=from;b<B;b++){
    let pick;
    if(b===from&&!base){ pick=Object.entries(prev).filter(([s])=>s!=='0').map(([,id])=>id); }
    else { const curr=Object.entries(prev).filter(([s])=>s!=='0').map(([,id])=>id);
      pick=[...out].sort((a,c)=>(cnt[a]-cnt[c])||((curr.includes(c)?1:0)-(curr.includes(a)?1:0))).slice(0,nOut); }
    // slot assignment: stayers keep slot, newcomers fill freed slots preferring same position
    const asg={0:gk}; const stay=Object.entries(prev).filter(([s,id])=>s!=='0'&&pick.includes(id)); stay.forEach(([s,id])=>asg[s]=id);
    const free=slots.map((x,i)=>i).filter(i=>i>0&&!asg[i]); const newc=pick.filter(id=>!Object.values(asg).includes(id));
    newc.sort((a,c)=>0).forEach(id=>{ const p=P(id); let k=free.findIndex(i=>slots[i][0]===p.pos); if(k<0) k=0; asg[free[k]]=id; free.splice(k,1); });
    pick.forEach(id=>cnt[id]++); blocks.push(asg); prev=asg;
  }
  f.plan={blocks,B};
  return f.plan;
}
function planMinutes(f){ const m={}; f.plan.blocks.forEach(b=>Object.values(b).forEach(id=>m[id]=(m[id]||0)+f.int)); return m; }
function pairs(a,b){ const out=[]; Object.keys(b).forEach(s=>{ if(a[s]!==b[s]) out.push({s:+s,on:b[s],off:a[s]}); }); return out; }

