let chatDrafts={};
function draftValue(kind,id){return chatDrafts[me.id+'|'+kind+id]||'';}
function rememberComposer(){
  for(const input of document.querySelectorAll('.chat-composer input[data-draft-key]')){
    chatDrafts[input.dataset.draftKey]=input.value;if(input.id==='cIn')ui.draft=input.value;
  }
}
