function go(v){
  rememberComposer();
  if($('#sheet').classList.contains('on'))closeSheet();
  if(view===v){const sc=$('#screen');if(sc.scrollTo)sc.scrollTo({top:0,behavior:'smooth'});else sc.scrollTop=0;refreshViewport();return;}
  blurWithin($('#screen'));view=v;ui.sel=null;paint();
}
function paint(soft){
  if(!me) return; $('#app').classList.toggle('coach',me.role==='coach');
  const fn=V[me.role+'_'+view]||V[me.role+'_home']; const sc=$('#screen'), y=sc.scrollTop;
  try{ tidyData(); }catch(e){}
  let html; try{ html=fn(); }catch(e){ try{ html=recover(e); }catch(e2){ html=crashView(e2); } }
  rememberComposer();blurWithin(sc);
  sc.innerHTML=`<div class="view${soft?'':' stag'}">${html}</div>`;
  if(soft){ sc.scrollTop=y; sc.firstChild.style.animation='none'; } else sc.scrollTop=0;
  after(); tabs();refreshViewport();
  // Fresh open of a chat: jump to the newest message once (soft updates handled separately).
  if(!soft && (view==='group' || view==='private' || (view==='inbox' && ui.ib==='chat') || view==='chats')){
    requestAnimationFrame(()=>scrollChatToEnd(true));
  }
}
