const coachUnread=()=>S.threads.reduce((a,t)=>a+(t.cu||0),0);
function myThread(){ if(!me||me.role!=='parent') return null; let t=S.threads.find(x=>x.fam===me.id); if(!t){ t={id:uid('t_'),fam:me.id,name:me.name,kid:kids()[0]?.name||'',msgs:[],cu:0,pu:0}; S.threads.push(t);} return t; }
