function tabs(){ const n=unread(), ci=me?.role==='coach'?(coachUnread()+groupsUnread()):0; $('#tabbar').classList.toggle('six',TABS[me.role].length>5); $('#tabbar').innerHTML=TABS[me.role].map(([k,l,ic])=>`<button type="button" class="tb ${primaryTab()===k?'on':''}" aria-label="${l}" ${primaryTab()===k?'aria-current="page"':''} onclick="go('${k}')">${svg(ic,'aria-hidden="true"')}<span class="tb-label">${l}</span>${k==='chats'&&n?`<span class="dot">${n}</span>`:''}${k==='groups'&&groupsUnread()?`<span class="dot">${groupsUnread()}</span>`:''}${k==='inbox'&&ci?`<span class="dot">${ci}</span>`:''}${k==='club'&&me.role==='coach'&&coachUnread()?`<span class="dot">${coachUnread()}</span>`:''}${k==='match'&&S.fixtures.some(f=>f.status==='live')?'<span class="dot" style="background:var(--red);color:#fff">●</span>':''}</button>`).join(''); }
