function after(){
  clearInterval(cdT); const tick=()=>$$('[data-cd]').forEach(el=>{ const d=Math.max(0,+el.dataset.cd-Date.now()); el.innerHTML=`<div><b>${Math.floor(d/864e5)}</b><span>Days</span></div><div><b>${pad(Math.floor(d/36e5)%24)}</b><span>Hrs</span></div><div><b>${pad(Math.floor(d/6e4)%60)}</b><span>Mins</span></div><div><b>${pad(Math.floor(d/1e3)%60)}</b><span>Secs</span></div>`; });
  tick(); cdT=setInterval(tick,1000);
  $$('[data-count]').forEach(el=>{ const to=+el.dataset.count; let t0; const st=ts=>{t0??=ts; const k=Math.min(1,(ts-t0)/1100); el.textContent=Math.round(to*(1-Math.pow(1-k,3))); if(k<1) requestAnimationFrame(st);}; requestAnimationFrame(st); });
  $$('[data-ring]').forEach(el=>{ const c=+el.getAttribute('stroke-dasharray'); requestAnimationFrame(()=>requestAnimationFrame(()=>el.style.strokeDashoffset=c*(1-(+el.dataset.ring)))); });
  $$('[data-w]').forEach(el=>requestAnimationFrame(()=>requestAnimationFrame(()=>el.style.width=el.dataset.w)));
  $$('.pc[data-tilt]').forEach(tilt);
}

/* Measure the navigation for transient banners only; content is in normal flex flow. */
(function(){
  const nav=document.getElementById('tabbar'), root=document.documentElement;
  const sync=()=>{
    const r=nav.getBoundingClientRect(), app=document.getElementById('app').getBoundingClientRect();
    root.style.setProperty('--nav-height',Math.ceil(r.height)+'px');
    root.style.setProperty('--nav-clearance',Math.max(16,Math.ceil(app.bottom-r.top+12))+'px');
  };
  if(window.ResizeObserver)new ResizeObserver(sync).observe(nav);
  else new MutationObserver(sync).observe(nav,{childList:true});
  window.addEventListener('resize',sync);requestAnimationFrame(sync);
})();

/* ---------- fragments ---------- */
function selectedPhotoPlayer(){ return me?.role==='parent'?(kids()[kidIdx]||kids()[0]||null):null; }
function accountAvatarPhoto(){ const k=selectedPhotoPlayer(); return k?.photo&&k.info?.photo!==false?k.photo:me.photo; }
function topbar(sub,title,right=''){ const c=me.role==='coach'; return `<div class="top">${avHTML(me.name,accountAvatarPhoto(),c?'':`background:linear-gradient(145deg,#5aa8ff,#2453a8);color:#fff`)}<div class="t"><small>${sub}</small><b>${title}</b></div>${right}<button class="ib account-btn" onclick="accountSheet()" aria-label="Your account"><span>${svg('user')}</span><span>Your account</span></button></div>`; }
function supportHomeCard(){ return `<div class="card support-home-card" style="margin:10px 14px;padding:14px 16px;display:flex;align-items:center;justify-content:space-between;gap:12px;border-color:rgba(63,243,106,.38)"><div><b style="display:block">Need help with the app?</b><p class="hint" style="margin:3px 0 0">Report a technical problem to Dan.</p></div><button class="btn gh" style="flex:0 0 auto" onclick="reportProblem()">Report a problem</button></div>`; }
function cardHTML(p){
  const s=stats(p), tr=s.train===null?'—':s.train+'%';
  const st=p.pos==='GK'?[['APPS',s.apps],['CLEAN',s.cs],['POTM',s.potm],['ASSIST',s.ast],['MINS',s.mins],['TRAIN',tr]]:[['APPS',s.apps],['GOALS',s.goals],['ASSIST',s.ast],['POTM',s.potm],['MINS',s.mins],['TRAIN',tr]];
  return `<div class="in"><div class="face"><div class="fi"><div class="pc-n">${p.num}</div><div class="pc-p">${p.pos}</div><img class="pc-b" src="${BADGE}" alt="">${faceHTML(p)}<div class="pc-nm">${esc(p.name)}</div><div class="pc-st">${st.map(x=>`<div>${x[1]}<small>${x[0]}</small></div>`).join('')}</div></div></div>
   <div class="face back"><div class="fi"><h5>${esc(p.name)}'s season</h5>${(()=>{const q=attInfo(p);return `<div class="ach">📅 ${q.n} session${q.n===1?'':'s'}${q.streak>1?` · 🔥 ${q.streak} in a row`:''}</div>`})()}${achievements(p,s).slice(0,3).map(a=>`<div class="ach">${a}</div>`).join('')}<p>"${esc(NOTES[p.id]||'Works hard, listens and improves every week.')}"<br>— Coach Alfie</p></div></div></div>`;
}
function tilt(c){ c.onpointermove=e=>{ if(c.classList.contains('flip')) return; const r=c.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5; c.querySelector('.in').style.transform=`rotateY(${x*24}deg) rotateX(${-y*24}deg)`; }; c.onpointerleave=()=>c.querySelector('.in').style.transform=''; }
const crest=(f,sz=50)=>`<div class="crest" style="width:${sz}px;height:${sz}px;background:linear-gradient(160deg,${f.col},#111)">${f.opp.split(' ').map(w=>w[0]).join('').slice(0,2).toUpperCase()}</div>`;
function scoreboard(f,extra=''){ return `<div class="vs"><div><img src="${BADGE}" alt=""><div class="nm">AG ${TEAMS[f.team].short}</div></div><div><div class="sc" id="msc">${f.us}–${f.them}</div>${extra}</div><div>${crest(f,54)}<div class="nm">${esc(f.opp)}</div></div></div>`; }
function resultCard(f,hl){
  const r=f.us>f.them?'W':f.us===f.them?'D':'L'; const sc={}; f.events.filter(e=>e.type==='goal').forEach(e=>sc[e.who]=(sc[e.who]||0)+1);
  return `<div class="res" onclick="resultGraphic('${f.id}')" style="cursor:pointer"><div class="lg">${fmtD(new Date(f.at))} · ${TEAMS[f.team].short} · Full time</div>${scoreboard(f,`<span class="wdl ${r}">${r==='W'?'WIN':r==='D'?'DRAW':'LOSS'}</span>`)}
   <div class="chips" style="justify-content:center;margin-top:12px">${Object.entries(sc).map(([id,n])=>`<span class="chip ${hl===id?'hot':''}">⚽ ${esc(P(id)?.name)}${n>1?' ×'+n:''}</span>`).join('')}${P(f.potm)?`<span class="chip warn">⭐ ${esc(P(f.potm).name)}</span>`:''}</div></div>`;
}
function pitchHTML(f,on,opts={}){
  const slots=FMT[TEAMS[f.team].fmt], sc={}; f.events.forEach(e=>{ if(e.type==='goal') sc[e.who]=(sc[e.who]||0)+1; });
  return `<div class="pitch" id="pitch"><div class="ln" style="left:-2px;right:-2px;top:50%;height:0"></div><div class="ln" style="left:50%;top:50%;width:96px;height:96px;border-radius:50%;transform:translate(-50%,-50%)"></div><div class="ln" style="left:27%;right:27%;top:-2px;height:13%"></div><div class="ln" style="left:27%;right:27%;bottom:-2px;height:13%"></div>
   ${slots.map(([pos,x,y],i)=>{ const p=P(on[i]); if(!p) return `<div class="pl" style="left:${x}%;top:${y}%"><div class="sh" style="background:rgba(255,255,255,.15);color:#fff">?</div><span>${pos}</span></div>`;
     return `<div class="pl ${pos==='GK'?'gk':''} ${ui.sel===p.id?'sel':''} ${opts.hl===p.id?'me':''}" style="left:${x}%;top:${y}%" ${opts.tap?`onclick="tapPl('${p.id}')"`:''}><div class="sh">${p.num}</div><span>${esc(p.name)}</span>${(f.locks||[]).includes(p.id)?'<i class="lk">🔒</i>':''}${sc[p.id]?`<i class="gl">${'⚽'.repeat(Math.min(3,sc[p.id]))}</i>`:''}</div>`; }).join('')}</div>`;
}

