    <h3>${TEAMS[nf.team].short} vs<br>${esc(nf.opp)}</h3><div class="meta"><span>${fmtD(new Date(nf.at))} · ${nf.meet?`Meet ${nf.meet} · `:''}KO ${hm(new Date(nf.at))} · ${nf.home?'Home':'Away'} · ${TEAMS[nf.team].fmt}v${TEAMS[nf.team].fmt}</span>${fxVenueLine(nf)}<span>🙋 ${avN} available${noR?` · ${noR} not replied`:''}</span></div>
    ${nf.status==='live'?'':`<div class="cd" data-cd="${nf.at}"></div>`}<div style="margin-top:14px"><span class="btn">${nf.status==='live'?'Back to the match →':'Get matchday ready →'}</span></div></div>`:'')+
