    <button class="kpi hl" onclick="go('training')"><small>${next?esc(next.s.title):'Training'}</small><b style="font-size:30px;margin-top:10px">${next?DAYS[next.at.getDay()]+' '+next.s.start:'—'}</b><em>Take the register →</em></button>
    <button class="kpi" onclick="go('club')"><small>Taster requests</small><b data-count="${pend.length}">0</b><em>${pend.length?'waiting for you':'all sorted'}</em></button>
