    <button class="kpi" onclick="go('squad')"><small>Players</small><b data-count="${S.players.length}">0</b><em>${TK.length} squads</em></button></div>
  ${loyHeroHTML()}<div class="toolrow"><button class="btn gh" onclick="openCompose()">📣 Message parents</button><button class="btn gh" onclick="go('calendar')">📅 Calendar</button><button class="btn gh" onclick="openCheckinAdmin()">📲 QR check-in</button></div>
  <h2 class="sec">Club activity</h2><div class="card" style="padding:6px 16px">${S.activity.slice(0,8).map(a=>`<div class="act"><i>${a.ic}</i><span>${esc(a.t)}</span><small>${ago(a.ts)}</small></div>`).join('')}</div>`+supportHomeCard();
