/* ---------- COACH · Matchday ---------- */
V.coach_match=()=>{
  const ups=S.fixtures.filter(f=>f.status!=='ft').sort((a,b)=>a.at-b.at);
  if(!F(ui.fx)||F(ui.fx).status==='ft'&&!ui.ftView) ui.fx=(ups.find(f=>f.status==='live')||ups[0])?.id;
  const f=F(ui.fx);
  const pick=`<div class="hscroll" style="padding-top:12px">${ups.map(x=>`<button class="chip ${x.id===ui.fx?'on':''}" onclick="ui.fx='${x.id}';ui.ftView=0;ui.sel=null;paint(true)">${x.status==='live'?'🔴 ':''}${TEAMS[x.team].short} v ${esc(x.opp.split(' ')[0])} · ${DAYS[new Date(x.at).getDay()]}</button>`).join('')}<button class="chip" onclick="addFixture()">＋ Fixture</button><button class="chip hot" onclick="addResult()">📝 Add a result</button></div>`;
  if(!f) return `<div class="ph"><small>Matchday</small><h1>No fixtures</h1></div>${pick}`;
  if(f.status==='ft') return ftView(f);
  f.step??=1; if(f.status==='live') f.step=4;
  const steps=['Who\'s here','Pick team','Game time','Live'];
  const head=`<div class="ph"><small>${TEAMS[f.team].name} · ${fmtD(new Date(f.at))} · ${f.meet?`Meet ${f.meet} · `:''}KO ${hm(new Date(f.at))}</small><h1>vs ${esc(f.opp)}</h1>${fxDetails(f,true)}</div>${pick}
   <div class="stepper">${steps.map((s,i)=>`<button class="stp ${f.step===i+1?'on':f.step>i+1?'done':''}" onclick="${f.status==='live'?'':`goStep(${i+1})`}"><i></i>${i+1}. ${s}</button>`).join('')}</div>`;
  return head+[null,step1,step2,step3,step4][f.step](f);
};
function goStep(n){ const f=F(ui.fx); if(n>=2&&teamPlayers(f.team).filter(p=>f.avail[p.id]).length<TEAMS[f.team].fmt){ if(f.step!==1){ f.step=1; paint(); } buzz(40); return toast(`Mark at least ${TEAMS[f.team].fmt} players available first`); }
  if(n>=2&&(!f.lineup||!Object.keys(f.lineup).length)) autoPick(f,ui.mode);
  if(n>=3&&!f.plan) buildPlan(f);
  f.step=n; ui.sel=null; save(); paint(); }
/* step 1 */
function step1(f){
  const ps=teamPlayers(f.team), fmt=TEAMS[f.team].fmt, av=ps.filter(p=>f.avail[p.id]).length, noR=ps.filter(p=>f.avail[p.id]===undefined);
  return `<div class="qhead"><h2>Who's here?</h2><p>Parents reply in the app. Tap anyone to change it.</p></div>
  <div class="tiles">${ps.map(p=>{const v=f.avail[p.id];return `<button class="tile ${v?'in':v===false?'out':''}" onclick="togAvail('${p.id}')"><span class="tag ${v!==undefined?'ok':''}">${v===undefined?'NO REPLY':v?'PARENT ✓':'OUT'}</span><span class="a">${p.num}</span><b>${esc(p.name)}</b><small>${p.pos}</small></button>`}).join('')}</div>
  <div class="summary"><b class="n">${av}</b><p><strong>${av} available</strong> for ${fmt}v${fmt}<br>${av>=fmt?`${av-fmt} sub${av-fmt===1?'':'s'} · everyone gets fair minutes`:`<span style="color:var(--amber)">Need ${fmt-av} more to play</span>`}</p></div>
  <div class="toolrow">${noR.length?`<button class="btn gh" onclick="nudge('${f.id}')">🔔 Nudge ${noR.length} parent${noR.length>1?'s':''}</button>`:''}<button class="btn gh" onclick="allAvail('${f.id}')">✅ Mark everyone available</button></div>
  ${av<fmt?`<p class="hint" style="text-align:center;padding:0 24px;margin-top:10px">Tap players to mark them available, or tap <b>Mark everyone available</b>. You need ${fmt} for ${fmt}v${fmt}.</p>`:''}
  <div class="cta"><button class="btn" ${av<fmt?'style="opacity:.55"':''} onclick="goStep(2)">Next: pick the team →</button></div>`;
}
function togAvail(pid){ const f=F(ui.fx); f.avail[pid]=!f.avail[pid]; if(f.lineup){ Object.keys(f.lineup).forEach(s=>{ if(f.lineup[s]===pid&&!f.avail[pid]) delete f.lineup[s]; }); } f.plan=null; buzz(12); save(); paint(true); }
function nudge(fid){ const f=F(fid); const miss=teamPlayers(f.team).filter(p=>f.avail[p.id]===undefined); miss.forEach(p=>p.parent&&note(pars(p),'🔔',`Can ${p.name} play ${DAYL[new Date(f.at).getDay()]} vs ${f.opp}? Tap to reply.`)); log('🔔',`Nudged parents/guardians of ${miss.length} player${miss.length>1?'s':''} about ${f.opp}`); save(); toast(`Parents/guardians nudged 🔔`); }
/* step 2 */
function step2(f){
  const ps=teamPlayers(f.team).filter(p=>f.avail[p.id]), on=Object.values(f.lineup||{}), bench=ps.filter(p=>!on.includes(p.id)), sel=P(ui.sel);
  return `<div class="qhead"><h2>Pick your team</h2><p>One tap picks it. Tap two players to swap them. Lock anyone you want to keep in place.</p></div>
  <div class="segc">${[['balanced','⚖️ Balanced'],['strongest','💪 Strongest']].map(([k,l])=>`<button class="${ui.mode===k?'on':''}" onclick="ui.mode='${k}';autoPick(F(ui.fx),'${k}',true);save();paint(true)">${l}</button>`).join('')}</div>
  <div class="toolrow"><button class="btn" onclick="repick()">⚡ Auto-pick</button><button class="btn gh" onclick="undo()" ${ui.hist?.length?'':'disabled'}>↩︎ Undo</button></div>
  ${sel?`<div class="selbar"><span><b style="color:var(--lime)">${esc(sel.name)}</b> selected · tap another player to swap</span><button class="btn sm gh" onclick="toggleLock('${sel.id}')">${(f.locks||[]).includes(sel.id)?'🔓 Unlock':'🔒 Lock'}</button></div>`:''}
  ${pitchHTML(f,f.lineup,{tap:1})}
  <div class="bench"><span>Subs</span>${bench.map(p=>`<button class="bch ${ui.sel===p.id?'sel':''}" onclick="tapPl('${p.id}')"><i>${p.num}</i>${esc(p.name)}</button>`).join('')||'<small style="color:var(--mut)">No subs today</small>'}</div>
  <div class="toolrow"><button class="btn gh" onclick="teamSheet('${f.id}')">📋 Team sheet graphic</button></div>
  <div class="cta"><button class="btn" onclick="goStep(3)">Next: plan game time →</button></div>`;
}
function snap(){ (ui.hist??=[]).push(JSON.stringify(F(ui.fx).lineup)); ui.hist=ui.hist.slice(-20); }
function undo(){ const f=F(ui.fx); if(!ui.hist?.length) return; f.lineup=JSON.parse(ui.hist.pop()); f.plan=null; save(); paint(true); }
function repick(){ snap(); autoPick(F(ui.fx),ui.mode,true); save(); buzz(20); toast(ui.mode==='strongest'?'Strongest XI picked 💪':'Balanced team picked ⚖️'); paint(true); }
function toggleLock(id){ const f=F(ui.fx); f.locks??=[]; const i=f.locks.indexOf(id); i>=0?f.locks.splice(i,1):f.locks.push(id); ui.sel=null; save(); paint(true); }
function tapPl(id){
  const f=F(ui.fx); if(!ui.sel){ ui.sel=id; buzz(8); return paint(true); }
  if(ui.sel===id){ ui.sel=null; return paint(true); }
  snap(); const lu=f.lineup, sa=Object.keys(lu).find(s=>lu[s]===ui.sel), sb=Object.keys(lu).find(s=>lu[s]===id);
  if(sa!==undefined&&sb!==undefined){ [lu[sa],lu[sb]]=[lu[sb],lu[sa]]; } else if(sa!==undefined){ lu[sa]=id; } else if(sb!==undefined){ lu[sb]=ui.sel; }
  toast(`Swapped ${P(ui.sel).name} ↔ ${P(id).name}`); ui.sel=null; f.plan=null; buzz(20); save(); paint(true);
}
/* step 3 */
function step3(f){
  if(!f.plan) buildPlan(f);
  const m=planMinutes(f), ps=teamPlayers(f.team).filter(p=>f.avail[p.id]).sort((a,b)=>(a.pos==='GK'?-1:0)-(b.pos==='GK'?-1:0)||(m[b.id]||0)-(m[a.id]||0));
  const outM=ps.filter(p=>p.id!==f.lineup[0]).map(p=>m[p.id]||0), lo=Math.min(...outM), hi=Math.max(...outM);
  const B=f.plan.B, subsN=f.plan.blocks.slice(1).reduce((a,b,i)=>a+pairs(f.plan.blocks[i],b).length,0);
  return `<div class="qhead"><h2>Game time</h2><p>Who plays when, planned before kick-off. Every green block is ${f.int} minutes on the pitch.</p></div>
  <div class="card" style="margin-top:12px"><div class="lab" style="margin-top:0">Match length</div><div class="optrow">${[20,30,40,50,60].map(n=>`<button class="chip ${f.len===n?'on':''}" onclick="setLen(${n})">${n} min</button>`).join('')}</div>
   <div class="lab">Rolling subs every</div><div class="optrow">${[4,5,8,10].map(n=>`<button class="chip ${f.int===n?'on':''}" onclick="setInt(${n})">${n} min</button>`).join('')}</div></div>
  <div class="fair"><i>⚖️</i><span>${hi-lo<=f.int?`Fair minutes ✓ Every outfield player gets <b style="color:var(--g)">${lo}${hi!==lo?'–'+hi:''} mins</b>. FA equal-minutes for mini soccer.`:`Minutes range ${lo}–${hi}`} ${subsN} subs across ${B-1} changes.</span></div>
  <div class="plan"><div class="phead"><span>PLAYER</span><span class="ticks" style="grid-template-columns:repeat(${B},1fr)">${Array.from({length:B},(_,i)=>`<span style="text-align:center">${i%2===0?i*f.int+"'":''}</span>`).join('')}</span><span style="text-align:right">MINS</span></div>
   ${ps.map(p=>`<div class="prow"><span class="nm">${esc(p.name)}<small>${p.pos}</small></span><div class="blks" style="grid-template-columns:repeat(${B},1fr)">${f.plan.blocks.map((b,i)=>`<i class="blk ${Object.values(b).includes(p.id)?(b[0]===p.id?'gk':'on'):''}" style="animation-delay:${i*.03}s"></i>`).join('')}</div><em>${m[p.id]||0}</em></div>`).join('')}</div>
  <div class="toolrow"><button class="btn gh" onclick="F(ui.fx).plan=null;buildPlan(F(ui.fx));save();paint(true);toast('Plan rebuilt')">↻ Rebuild plan</button><button class="btn gh" onclick="goStep(2)">Change team</button></div>
  <div class="cta"><button class="btn" onclick="kickOff()">▶ Kick off</button></div>`;
}
function setLen(n){ const f=F(ui.fx); f.len=n; f.plan=null; save(); paint(true); }
function setInt(n){ const f=F(ui.fx); f.int=n; f.plan=null; save(); paint(true); }
/* step 4 · live */
const L={timer:null,speed:10};
function kickOff(){ const f=F(ui.fx); if(!f.plan) buildPlan(f);
  f.status='live'; f.step=4; f.live={secs:0,on:{...f.lineup},blk:0,due:false,mins:{}}; f.us=0; f.them=0; f.events=[];
  whistle(1); buzz([40,30,40]); log('🔴',`Kick-off: ${TEAMS[f.team].short} vs ${f.opp}`); tell(f.team,`🔴 We're LIVE vs ${f.opp}! Follow the score in the app.`); save(); startClock(); paint(); }
function startClock(){ clearInterval(L.timer); L.last=Date.now(); L.timer=setInterval(tickLive,250); }
function tickLive(){
  const f=S.fixtures.find(x=>x.status==='live'); if(!f){clearInterval(L.timer);L.timer=null;return;}
  if(!f.live||!f.plan||!f.plan.blocks){ fixFx(f); if(!f.live||!f.plan) return; }
  const now=Date.now(), d=Math.min(900,Math.max(0,(now-(L.last||now))/1000)); L.last=now; f.live.secs+=d; Object.values(f.live.on).forEach(id=>f.live.mins[id]=(f.live.mins[id]||0)+d);
  const bl=f.int*60, cur=Math.min(f.plan.B-1,Math.floor(f.live.secs/bl));
  if(cur>f.live.blk&&!f.live.due&&pairs(f.live.on,f.plan.blocks[cur]).length){ f.live.due=true; buzz([80,50,80,50,80]); const ps=pairs(f.live.on,f.plan.blocks[cur]); push('🔁 Subs due',ps.map(x=>`${P(x.on).name} on for ${P(x.off).name}`).join(' · ')); save(); if(view==='match') paint(true); }
  else if(cur>f.live.blk&&!f.live.due){ f.live.blk=cur; }
  if(view==='match'&&ui.fx===f.id){ const c=$('#lclk'); if(c) c.textContent=mmss(f.live.secs);
    const nx=$('#lnext'); if(nx) nx.textContent=f.live.due?'NOW':mmss(Math.max(0,(f.live.blk+1)*bl-f.live.secs));
    $$('[data-mb]').forEach(el=>{ const id=el.dataset.mb; const s=f.live.mins[id]||0; el.querySelector('i').style.width=Math.min(100,s/60/f.len*100)+'%'; el.querySelector('em').textContent=Math.floor(s/60)+"'"; }); }
  if(now-(L.sv||0)>10000){ L.sv=now; save(); }
  if(f.live.secs>=f.len*60) fullTime();
}
function step4(f){
  const lv=f.live, bl=f.int*60, nb=Math.min(f.plan.B-1,lv.blk+1), dueB=lv.due?Math.min(f.plan.B-1,Math.floor(lv.secs/bl)):nb;
  const ps=pairs(lv.on,f.plan.blocks[dueB]||lv.on), target=planMinutes(f);
  const all=teamPlayers(f.team).filter(p=>f.avail[p.id]);
  return `<div class="board live"><div style="text-align:center"><span class="pill red">Live</span></div><div style="margin-top:10px">${scoreboard(f,`<div class="clk" id="lclk">${mmss(lv.secs)}</div>`)}</div>
    <div class="speed" style="display:none">${[[10,'Real time']].map(([s,l])=>`<button class="${L.speed===s?'on':''}" onclick="L.speed=${s};paint(true)">${l}</button>`).join('')}<button onclick="toggleClock()">${L.timer?'⏸ Pause':'▶ Resume'}</button></div></div>
  <div class="bigbtns"><button class="us" onclick="goalUs()">⚽ We scored</button><button class="them" onclick="goalThem()">They scored</button></div>
  ${dueB>lv.blk||lv.due?`<div class="subcard ${lv.due?'due':''}"><div class="subhd"><b>${lv.due?'🔁 Subs due':'Next subs'}</b><em id="lnext">${lv.due?'NOW':mmss(Math.max(0,(lv.blk+1)*bl-lv.secs))}</em></div>
    ${ps.length?ps.map(x=>`<div class="pair"><span class="in"><small>ON</small>${esc(P(x.on).name)}</span><span>⇄</span><span class="out"><small>OFF</small>${esc(P(x.off).name)}</span><button class="sw" onclick="swapSub(${x.s},'${x.on}')">Swap</button></div>`).join(''):'<p class="hint" style="margin:8px 0 0">No changes this rotation</p>'}
    <button class="btn full" style="margin-top:12px" onclick="makeSubs(${dueB})">${lv.due?'✓ Make subs':'Make subs early'}</button></div>`:''}
  ${pitchHTML(f,lv.on)}
  <h2 class="sec">Minutes played <a>white line = plan</a></h2>
  <div class="card">${all.map(p=>{const s=lv.mins[p.id]||0;return `<div class="minbar ${Object.values(lv.on).includes(p.id)?'onf':''}" data-mb="${p.id}"><span>${esc(p.name)}</span><div class="bar"><i style="width:${Math.min(100,s/60/f.len*100)}%"></i><b style="left:${(target[p.id]||0)/f.len*100}%"></b></div><em>${Math.floor(s/60)}'</em></div>`}).join('')}</div>
  <h2 class="sec">Match feed</h2><div class="feed" style="margin-top:0">${f.events.slice().reverse().map((e,i)=>`<div class="fe"><b>${e.t}′</b><span>${e.type==='goal'?`⚽ <b style="color:var(--w);font-family:var(--body);font-size:13px">${esc(P(e.who)?.name)}</b>${e.ast?` · assist ${esc(P(e.ast)?.name)}`:''}`:e.type==='opp'?`${esc(f.opp)} score`:`🔁 ${esc(e.txt)}`}</span>${i===0&&e.type!=='sub'?`<button class="undo" onclick="undoEvent()">Undo</button>`:''}</div>`).join('')||'<div class="fe"><b>0′</b>Kick-off! Come on Greens 💚</div>'}</div>
  <div class="cta static"><button class="btn rd" style="background:rgba(255,93,93,.2)" onclick="fullTime()">🏁 Full time</button></div>`;
}
function toggleClock(){ if(L.timer){clearInterval(L.timer);L.timer=null;save();} else startClock(); paint(true); }
function makeSubs(b){ const f=F(ui.fx), lv=f.live, ps=pairs(lv.on,f.plan.blocks[b]);
  lv.on={...f.plan.blocks[b]}; lv.blk=b; lv.due=false; const t=Math.floor(lv.secs/60);
  ps.forEach(x=>{ f.events.push({t,type:'sub',txt:`${P(x.on).name} on for ${P(x.off).name}`}); const p=P(x.on); if(p.parent) note(pars(p),'🔁',`${p.name} is on! (${t}′ vs ${f.opp})`); });
  buzz(30); save(); toast(`✓ ${ps.length} sub${ps.length===1?'':'s'} made`); paint(true); }
function swapSub(slot,onId){
  const f=F(ui.fx), lv=f.live, onField=Object.values(lv.on);
  const opts=teamPlayers(f.team).filter(p=>f.avail[p.id]&&!onField.includes(p.id)&&p.id!==onId&&p.pos!=='GK');
  openSheet(`<div class="shb"><h3>Swap sub</h3><p class="hint">Bring someone else on instead of ${esc(P(onId).name)}. The plan re-balances everyone's minutes.</p><div class="g3">${opts.map(p=>`<button class="opt" onclick="doSwap(${slot},'${p.id}')">${esc(p.name)}<small>${Math.floor((lv.mins[p.id]||0)/60)}′ played</small></button>`).join('')||'<p class="hint">No one else on the bench</p>'}</div></div>`);
}
function doSwap(slot,newId){
  const f=F(ui.fx), lv=f.live, bl=f.int*60, b=lv.due?Math.floor(lv.secs/bl):lv.blk+1, off=lv.on[slot];
  lv.on={...f.plan.blocks[b]}; lv.on[slot]=newId; lv.blk=Math.min(b,f.plan.B-1); lv.due=false; const t=Math.floor(lv.secs/60);
  f.plan.blocks[lv.blk]={...lv.on}; f.events.push({t,type:'sub',txt:`${P(newId).name} on for ${P(off).name}`});
  if(lv.blk+1<f.plan.B) buildPlan(f,lv.blk+1,lv.on,lv.mins);
  closeSheet(); save(); toast('Swapped · plan re-balanced ⚖️'); paint(true); }
function goalUs(){ const f=F(ui.fx); const on=FMT[TEAMS[f.team].fmt].map((x,i)=>P(f.live.on[i])).filter(Boolean);
  openSheet(`<div class="shb"><h3>Who scored? ⚽</h3><p class="hint">One tap. Their player card updates instantly.</p><div class="g3">${on.map(p=>`<button class="opt" onclick="pickAst('${p.id}')">${esc(p.name)}<small>#${p.num} · ${p.pos}</small></button>`).join('')}</div></div>`); }
function pickAst(sid){ const f=F(ui.fx); const on=Object.values(f.live.on).filter(id=>id!==sid).map(P);
  $('#shb').innerHTML=`<div class="shb"><h3>Who set it up?</h3><p class="hint">One more tap for the assist.</p><button class="btn gh full" style="margin-bottom:10px" onclick="commitGoal('${sid}','')">No assist</button><div class="g3">${on.map(p=>`<button class="opt" onclick="commitGoal('${sid}','${p.id}')">${esc(p.name)}<small>#${p.num}</small></button>`).join('')}</div></div>`; }
function commitGoal(sid,aid){ const f=F(ui.fx), p=P(sid); f.us++; f.events.push({t:Math.floor(f.live.secs/60),type:'goal',who:sid,ast:aid||null});
  log('⚽',`GOAL! ${p.name} vs ${f.opp} (${f.us}–${f.them})`); if(p.parent) note(pars(p),'⚽',`GOAL! ${p.name} just scored! AG ${f.us}–${f.them} ${f.opp}`); save(); closeSheet();
  $('#goalWho').textContent=p.name.toUpperCase(); const g=$('#goal'); g.classList.remove('on'); void g.offsetWidth; g.classList.add('on'); confetti(); cheer(); buzz([60,40,140]);
  setTimeout(()=>{ paint(true); $('#msc')?.classList.add('bump'); },300); }
function goalThem(){ const f=F(ui.fx); f.them++; f.events.push({t:Math.floor(f.live.secs/60),type:'opp'}); save(); paint(true); toast('Heads up, Greens 💪'); }
function undoEvent(){ const f=F(ui.fx); const e=f.events.pop(); if(e?.type==='goal') f.us--; if(e?.type==='opp') f.them--; save(); toast('Undone ↩︎'); paint(true); }
function fullTime(){ const f=S.fixtures.find(x=>x.status==='live'); if(!f) return; clearInterval(L.timer); L.timer=null; whistle(3);
  f.status='ft'; f.mins=Object.fromEntries(Object.entries(f.live.mins).map(([k,v])=>[k,Math.round(v)])); f.squad=Object.keys(f.mins).filter(k=>f.mins[k]>0); ui.fx=f.id; ui.ftView=1; save(); paint();
  setTimeout(()=>potmSheet(f.id),500); }
function potmSheet(fid){ const f=F(fid); openSheet(`<div class="shb"><h3>Full time 🏁</h3><p class="hint">AG ${f.us}–${f.them} ${esc(f.opp)}. Who's your player of the match?</p><div class="g3">${f.squad.map(P).filter(Boolean).map(p=>`<button class="opt" onclick="setPotm('${f.id}','${p.id}')">${esc(p.name)}<small>#${p.num}</small></button>`).join('')}</div></div>`); }
function setPotm(fid,pid){ const f=F(fid), p=P(pid); f.potm=pid; tell(f.team,`🏁 FT: AG ${f.us}–${f.them} ${f.opp}. ⭐ Player of the Match: ${p.name}! Minutes & stats updated in the app.`);
  log('🏆',`Result: AG ${TEAMS[f.team].short} ${f.us}–${f.them} ${f.opp} · ⭐ ${p.name}`); save(); if(f.us>=f.them) confetti(); resultGraphic(fid); paint(true); }
function ftView(f){
  const top=Object.entries(f.mins||{}).sort((a,b)=>b[1]-a[1]);
  return `<div class="ph"><small>${TEAMS[f.team].name} · Full time</small><h1>Result</h1></div><div style="height:12px"></div>${resultCard(f)}
  <div class="toolrow"><button class="btn" onclick="resultGraphic('${f.id}')">📸 Instagram result</button>${f.potm?'':`<button class="btn gh" onclick="potmSheet('${f.id}')">⭐ Pick POTM</button>`}</div>
  <h2 class="sec">Minutes played</h2><div class="card">${top.map(([id,s])=>`<div class="minbar"><span>${esc(P(id)?.name)}</span><div class="bar"><i style="width:0" data-w="${s/60/f.len*100}%"></i></div><em>${Math.round(s/60)}'</em></div>`).join('')}</div>
  <div class="toolrow"><button class="btn gh" onclick="ui.sqView='table';ui.sq='${f.team}';go('squad')">📊 Season table</button><button class="btn gh" onclick="ui.ftView=0;ui.fx=null;paint()">Next fixture →</button></div>`;
}



/* ---------- COACH · Training ---------- */
V.coach_training=()=>{
  const now=new Date(), sess=occ(now,7).filter(o=>o.end>now&&!o.cx); ui.ts=sess.find(o=>o.key===ui.ts)?ui.ts:sess[0]?.key; const o=sess.find(x=>x.key===ui.ts);
  if(!o) return `<div class="ph"><small>Training</small><h1>No sessions</h1></div>`;
  const teams=o.s.teams.length===1?o.s.teams:[ui.tt&&o.s.teams.includes(ui.tt)?ui.tt:o.s.teams[0]]; ui.tt=teams[0];
  const ps=teamPlayers(teams[0],1).filter(p=>sessionAssigned(p,o.s.id)), att=S.att[o.key]||[], going=Object.entries(S.rsvp[o.key]||{}).filter(([,v])=>v).map(([k])=>k);
  const group=att.length>=4?att.filter(id=>ps.some(p=>p.id===id)):ps.map(p=>p.id), sp=S.splits[o.key];
  const COL=[['Green','#3ff36a'],['White','#f3f7f1'],['Black','#111'],['Yellow','#ffd43b']];
  return `<div class="ph"><small>${fmtD(o.at)} · ${o.s.start}–${o.s.end} · ${esc(o.s.place)}</small><h1>${esc(o.s.title)}</h1></div>
  <div class="hscroll" style="padding-top:12px">${sess.map(x=>`<button class="chip ${x.key===ui.ts?'on':''}" onclick="ui.ts='${x.key}';paint(true)">${DAYS[x.at.getDay()]} ${x.s.start} · ${esc(x.s.title.replace(' Training',''))}</button>`).join('')}</div>
  ${o.s.teams.length>1?`<div class="segc">${o.s.teams.map(t=>`<button class="${ui.tt===t?'on':''}" onclick="ui.tt='${t}';paint(true)">${TEAMS[t].short}</button>`).join('')}</div>`:''}
  <div class="qhead"><h2>Register</h2><p>Tap players in as they arrive. Parents get an "arrived safely" ping. ${going.length?`<b style="color:var(--g)">${going.filter(id=>ps.some(p=>p.id===id)).length} said they're coming.</b>`:''}</p></div>
  <div class="card"><div class="reg-h" style="margin-bottom:12px"><div class="rw"><svg class="ring" viewBox="0 0 66 66" width="66" height="66"><circle class="bg" cx="33" cy="33" r="28"/><circle class="fg" cx="33" cy="33" r="28" stroke-dasharray="175.9" stroke-dashoffset="175.9" data-ring="${att.filter(id=>ps.some(p=>p.id===id)).length/Math.max(1,ps.length)}"/></svg><b>${att.filter(id=>ps.some(p=>p.id===id)).length}/${ps.length}</b></div><div><h4>${TEAMS[teams[0]].name}</h4><p>${att.length?'Tap again to undo':'Nobody in yet'}</p></div></div>
   <div class="regg">${ps.map(p=>{const r=(S.rsvp[o.key]||{})[p.id];return `<button class="rk ${att.includes(p.id)?'in':''}" onclick="tapReg('${o.key}','${p.id}')"><span class="a">${esc(p.name.slice(0,2))}</span>${esc(p.name)}${medFlag(p)}<small style="font-size:9px;color:${r===true?'var(--g)':r===false?'#ff9d9d':'var(--dim)'}">${r===true?'✓ coming':r===false?'✗ out':'no reply'}</small>${(()=>{const L=LY(),c=stOf(p.id);return L.on&&L.sessions.includes(o.s.id)?`<small class="stp ${c.n>=L.need?'due':''}">${c.n>=L.need?'🎁 reward due':'🎟️ '+c.n+'/'+L.need}</small>`:''})()}</button>`}).join('')}</div>
   <button class="btn sm gh full" style="margin-top:14px" onclick="allIn('${o.key}','${teams[0]}')">Everyone's here</button></div>
  <div class="qhead"><h2>Split into teams</h2><p>Fair teams in one tap: ability and positions balanced, a keeper on every side. Tap a player to move them.</p></div>
  <div class="segc">${[2,3,4].map(n=>`<button class="${ui.split===n?'on':''}" onclick="ui.split=${n};doSplit('${o.key}')">${n} teams</button>`).join('')}</div>
  <div class="toolrow"><button class="btn" onclick="doSplit('${o.key}')">🎽 ${sp?'Reshuffle':'Split'} ${group.length} players</button></div>
  ${sp?`<div class="bibs">${sp.map((t,i)=>`<div class="bib" style="animation-delay:${i*.08}s"><h4><i style="background:${COL[i][1]}"></i>${COL[i][0]} bibs<small>${t.length} players · ${t.reduce((a,id)=>a+(P(id)?.lvl||0),0)} pts</small></h4><div class="chips">${t.map(id=>`<button class="chip ${P(id)?.pos==='GK'?'warn':''}" onclick="moveBib('${o.key}','${id}')">${P(id)?.pos==='GK'?'🧤 ':''}${esc(P(id)?.name)}</button>`).join('')}</div></div>`).join('')}</div>`:''}
  <div style="height:20px"></div>`;
};
function tapReg(key,pid){ const a=(S.att[key]??=[]), p=P(pid), i=a.indexOf(pid);
  if(i>=0) a.splice(i,1); else { a.push(pid); buzz(); toast(`✓ ${p.name} in · parent notified`); if(p.parent) note(pars(p),'✅',`${p.name} arrived safely at training (${hm(new Date())})`); }
  delete S.splits[key]; stampSync(key); save(); paint(true); }
function allIn(key,t){ const s=S.sessions.find(x=>key.startsWith(x.id+'@')); const ps=teamPlayers(t,1).filter(p=>!s||sessionAssigned(p,s.id)); S.att[key]=[...new Set([...(S.att[key]||[]),...ps.map(p=>p.id)])]; ps.forEach(p=>p.parent&&note(pars(p),'✅',`${p.name} arrived safely at training`)); stampSync(key); save(); confetti(); toast('Full house tonight! 🔥'); paint(true); }
function doSplit(key){
  const o=occ(new Date(),7).find(x=>x.key===key); const t=ui.tt, ps=teamPlayers(t,1), att=(S.att[key]||[]).filter(id=>ps.some(p=>p.id===id));
  const group=(att.length>=4?att:ps.map(p=>p.id)).map(P), k=ui.split, teams=Array.from({length:k},()=>[]), pts=Array(k).fill(0);
  const add=(p,i)=>{teams[i].push(p.id);pts[i]+=p.lvl;};
  const r=()=>Math.random()-.5;
  group.filter(p=>p.pos==='GK').sort((a,b)=>b.lvl-a.lvl||r()).forEach((p,i)=>add(p,i%k));
  for(const pos of ['DEF','MID','ST']) group.filter(p=>p.pos===pos).sort((a,b)=>b.lvl-a.lvl||r()).forEach(p=>{ let best=0; for(let i=1;i<k;i++){ if(teams[i].length<teams[best].length||(teams[i].length===teams[best].length&&pts[i]<pts[best])) best=i; } add(p,best); });
  S.splits[key]=teams; save(); buzz(25); toast(`${k} fair teams ✓`); paint(true); }
function moveBib(key,id){ const sp=S.splits[key]; const i=sp.findIndex(t=>t.includes(id)); sp[i]=sp[i].filter(x=>x!==id); sp[(i+1)%sp.length].push(id); save(); paint(true); }

/* ---------- COACH · Squad ---------- */
V.coach_squad=()=>{
  if(!TEAMS[ui.sq]) ui.sq=TK[0]; const ps=teamPlayers(ui.sq,1), rows=ps.map(p=>({p,s:stats(p,ui.sq)}));
  const cols=[['apps','APPS'],['mins','MINS'],['goals','G'],['ast','A'],['potm','⭐']];
  rows.sort((a,b)=>(b.s[ui.sort]-a.s[ui.sort])||(b.s.goals-a.s.goals));
  return `<div class="ph"><small>${ps.length} players · ${TEAMS[ui.sq].sub}</small><h1>Squad</h1></div>
  <div class="hscroll" style="padding-top:12px">${TK.map(t=>`<button class="chip ${ui.sq===t?'on':''}" onclick="ui.sq='${t}';paint(true)">${TEAMS[t].short}</button>`).join('')}</div>
  <div class="segc">${[['table','📊 Season table'],['cards','🃏 Player cards']].map(([k,l])=>`<button class="${ui.sqView===k?'on':''}" onclick="ui.sqView='${k}';paint(true)">${l}</button>`).join('')}</div>
  ${ui.sqView==='table'?`<div class="tbl"><table><tr><th>PLAYER</th>${cols.map(([k,l])=>`<th class="${ui.sort===k?'on':''}" onclick="ui.sort='${k}';paint(true)">${l}</th>`).join('')}</tr>
    ${rows.map((r,i)=>`<tr class="${i===0&&r.s[ui.sort]>0?'lead':''}" onclick="playerSheet('${r.p.id}')"><td>${i===0&&r.s[ui.sort]>0?'👑 ':''}${esc(r.p.name)}</td>${cols.map(([k])=>`<td class="${ui.sort===k?'hi':''}">${r.s[k]}</td>`).join('')}</tr>`).join('')}</table></div>
    <p class="hint" style="text-align:center;margin-top:10px">Tap a column to sort · updates after every match</p>`
  :`<div class="cgrid" style="padding-top:12px">${ps.map(p=>`<div class="pc" onclick="playerSheet('${p.id}')">${cardHTML(p)}</div>`).join('')}</div>`}
  <div class="toolrow"><button class="btn" onclick="editPlayer()">＋ Add player</button></div>`;
};
function playerSheet(id){ const p=P(id), ps=pars(p).map(u=>S.users.find(x=>x.id===u)).filter(Boolean);
  openSheet(`<div class="shb" style="text-align:center"><div class="pc lg" data-tilt id="bigc">${cardHTML(p)}</div><p class="hint" style="margin-top:10px">Tap to flip</p></div>
   <div class="shb"><div class="kv">${p.last?`<div><i>🪪</i>Full name<b>${esc(p.name+' '+p.last)}</b></div>`:''}<div><i>👕</i>#${p.num} · ${p.pos}<b>${playerTeams(p).map(t=>esc(TEAMS[t]?.short||t)).join(' · ')}</b></div><div><i>⭐</i>Coach rating (private)<b>${'★'.repeat(p.lvl)}${'☆'.repeat(3-p.lvl)}</b></div><div><i>👨‍👩‍👧</i>Parents / guardians<b style="max-width:60%;text-align:right">${ps.length?ps.map(u=>esc(u.name)+(u.mobile?' · <a href="tel:'+esc(u.mobile)+'" style="color:var(--g)">'+esc(u.mobile)+'</a>':'')).join('<br>'):'Not joined yet'}</b></div><div><i>⚕️</i>Medical<b style="max-width:60%;text-align:right">${esc(p.info?.med||'None given')}</b></div><div><i>📞</i>Emergency<b style="max-width:60%;text-align:right">${esc(p.info?.emer||'—')}</b></div><div><i>📸</i>Photo consent<b style="color:${p.info?.photo===false?'var(--red)':'var(--g)'}">${p.info?.photo===false?'NO PHOTOS':'Yes'}</b></div>${p.tr?'<div><i>🎽</i>Training only<b>No matches</b></div>':''}</div>
   <h2 class="sec" style="margin-top:16px">Session attendance &amp; development</h2><div class="kv">${S.sessions.filter(x=>sessionAssigned(p,x.id)).map(x=>{const a=sessionAttendance(p,x.id);return `<div><i>📅</i>${esc(x.title)}<b>${a.attended} attended${a.total?` of ${a.total} recorded sessions · ${a.rate}%`: ' · no attendance recorded yet'}</b></div>`}).join('')||'<div><i>📅</i>Sessions<b>No sessions assigned through this player’s squads</b></div>'}</div>
   ${LY().on?`<h2 class="sec" style="margin-top:16px">Loyalty card</h2>${loyBox(p,false)}<button class="btn full" style="margin-top:12px" onclick="stampSheet('${p.id}')">🎟️ Add, remove or see history</button><div style="height:14px"></div>`:''}
   <div class="g2"><button class="btn gh" onclick="editPlayer('${p.id}')">Edit</button><button class="btn rd" onclick="removePlayerFromSquad('${p.id}','${ui.sq}')">Remove from ${esc(TEAMS[ui.sq]?.short||'squad')}</button></div><button class="btn rd full" style="margin-top:10px" onclick="removePlayer('${p.id}')">Remove player &amp; linked family from app</button></div>`);
  const c=$('#bigc'); tilt(c); c.onclick=()=>c.classList.toggle('flip'); }
function editPlayer(id){ const p=id?P(id):{name:'',num:Math.max(0,...teamPlayers(ui.sq).map(x=>x.num))+1,pos:'MID',team:ui.sq,lvl:2}; ui.ep={pos:p.pos,lvl:p.lvl,photo:p.photo||null};
  openSheet(`<div class="shb"><h3>${id?'Edit player':'New player'}</h3><p class="hint">${id?'Changes show everywhere instantly.':'They get a player card straight away and their parent gets an invite.'}</p>
   <div class="phpick"><span id="epAv">${avHTML((p.name||'?')+' '+(p.last||''),ui.ep.photo)}</span><div class="grow"><b>Profile photo</b><p class="hint">Shown on their player card and in the squad list</p>
     <div style="display:flex;gap:8px;margin-top:8px;flex-wrap:wrap"><label class="chip" style="cursor:pointer">📷 ${ui.ep.photo?'Change':'Add photo'}<input type="file" accept="image/*" hidden onchange="pickProfilePhoto(this,'player')"></label>${ui.ep.photo?`<button class="chip" style="color:#ff6b6b" onclick="ui.ep.photo=null;$('#epAv').innerHTML=avHTML(($('#eN')?.value||'?')+' '+($('#eL')?.value||''),null)">Remove</button>`:''}</div></div></div>
   <div class="field" style="margin-bottom:12px"><span style="display:block;font-size:12px;color:var(--mute);margin-bottom:4px">Permanent Player ID</span><strong style="font-size:16px;letter-spacing:.08em">${esc(p.playerRef||'Assigned automatically when saved')}</strong><small style="display:block;color:var(--mute);margin-top:4px">Keep this reference when the player changes squads.</small></div>
