   <label class="field"><span>Date of birth</span><input id="eDob" type="date" value="${esc(p.dob||'')}"></label>
   <div class="g2"><label class="field"><span>Shirt number (main squad)</span><input id="eNum" type="number" value="${p.num||0}"></label><label class="field"><span>Main squad</span><select id="eT">${TK.map(t=>`<option value="${t}" ${p.team===t?'selected':''}>${TEAMS[t].name}</option>`).join('')}</select></label></div>
   <div class="lab" style="margin-top:10px">Squads this player belongs to</div><div class="list" id="eTeams">${TK.map(t=>`<label class="row" style="cursor:pointer"><input type="checkbox" class="eTeam" value="${t}" ${(playerTeams(p).includes(t)||p.team===t)?'checked':''} style="width:20px;height:20px;accent-color:var(--g)"><span class="grow">${esc(TEAMS[t].name)}</span></label>`).join('')}</div>
   <div class="lab" style="margin-top:10px">Training sessions this player attends</div><p class="hint">Choose sessions independently of squad membership. Existing players initially inherit sessions from their squads.</p><div class="list" id="eSessions">${S.sessions.map(x=>`<label class="row" style="cursor:pointer"><input type="checkbox" class="eSession" value="${x.id}" ${sessionAssigned(p,x.id)?'checked':''} style="width:20px;height:20px;accent-color:var(--g)"><span class="grow">${esc(x.title)}<small style="display:block;color:var(--mute)">${DAYL[x.day]} · ${x.start}–${x.end}</small></span></label>`).join('')||'<p class="hint">No sessions have been created yet.</p>'}</div>
   <div class="lab" style="margin-top:4px">Position</div><div class="g3" id="posg" style="grid-template-columns:repeat(4,minmax(0,1fr))">${['GK','DEF','MID','ST'].map(x=>`<button class="opt ${p.pos===x?'on':''}" onclick="ui.ep.pos='${x}';$$('#posg .opt').forEach(o=>o.classList.toggle('on',o.textContent==='${x}'))">${x}</button>`).join('')}</div>
   <div class="lab">Coach rating · private, only used to balance teams</div><div class="stars" id="stg">${[1,2,3].map(n=>`<button class="${n<=p.lvl?'on':''}" onclick="ui.ep.lvl=${n};$$('#stg button').forEach((b,i)=>b.classList.toggle('on',i<${n}))">⭐</button>`).join('')}</div>
   <div class="lab" style="margin-top:14px">Earlier this season (before the app)</div><div class="baseline-grid"><label class="field"><span>Apps</span><input id="eBa" type="number" min="0" value="${((p.squadBase||{})[p.team]||p.base||{}).apps||0}"></label><label class="field"><span>Goals</span><input id="eBg" type="number" min="0" value="${((p.squadBase||{})[p.team]||p.base||{}).goals||0}"></label><label class="field"><span>Assists</span><input id="eBs" type="number" min="0" value="${((p.squadBase||{})[p.team]||p.base||{}).ast||0}"></label><label class="field"><span>MOTM</span><input id="eBm" type="number" min="0" value="${((p.squadBase||{})[p.team]||p.base||{}).potm||0}"></label></div>
