   <label class="field"><span>Emergency contact</span><input id="eEm" value="${esc(p.info?.emer||'')}" placeholder="Name · phone"></label>
   <div style="display:flex;align-items:center;gap:12px;margin:0 0 4px"><span style="flex:1;font-size:14px;font-weight:700">📸 Photo consent</span><button class="tog ${p.info?.photo!==false?'on':''}" id="ePh" onclick="this.classList.toggle('on')"></button></div>
   <button class="btn full big" style="margin-top:18px" onclick="savePlayer('${id||''}')">${id?'Save':'Add to squad'}</button></div>`); }
function savePlayer(id){ const name=$('#eN').value.trim(), dob=$('#eDob')?.value||''; if(!name) return toast('Add a name'); if(dob&&!/^\d{4}-\d{2}-\d{2}$/.test(dob)) return toast('Check the date of birth'); const mainTeam=$('#eT').value, chosen=[...document.querySelectorAll('.eTeam:checked')].map(x=>x.value); if(!chosen.includes(mainTeam)) chosen.push(mainTeam); const old=id?P(id):null; const chosenSessions=[...document.querySelectorAll('.eSession:checked')].map(x=>x.value); const squadNums={...(old?.squadNums||{})}; squadNums[mainTeam]=+$('#eNum').value||0; const d={name,dob,num:+$('#eNum').value||0,pos:ui.ep.pos,lvl:ui.ep.lvl,team:mainTeam,teams:chosen,sessionIds:chosenSessions,squadNums,tr:$('#eTr').classList.contains('on'),last:$('#eL').value.trim(),photo:ui.ep.photo||null,base:{apps:+$('#eBa').value||0,goals:+$('#eBg').value||0,ast:+$('#eBs').value||0,potm:+$('#eBm').value||0},squadBase:{...(old?.squadBase||{}),[mainTeam]:{apps:+$('#eBa').value||0,goals:+$('#eBg').value||0,ast:+$('#eBs').value||0,potm:+$('#eBm').value||0}},info:{...((id&&P(id).info)||{}),med:$('#eMed').value.trim(),emer:$('#eEm').value.trim(),photo:$('#ePh').classList.contains('on')}};
  if(id){ const target=P(id); if(!target.playerRef) target.playerRef=newPlayerRef(); Object.assign(target,d); toast('Saved ✓'); } else { S.players.push({id:uid('p_'),playerRef:newPlayerRef(),parent:null,parents:[],info:{med:'',emer:'',photo:true},...d}); log('🆕',`${name} joined ${TEAMS[d.team].name}`); toast(`${name} added 🎉`); confetti(); }
  ui.sq=d.team; save(); closeSheet(); paint(true); }
function removePlayerFromSquad(id, team){ const p=P(id); if(!p||!team) return; const ts=playerTeams(p); if(!ts.includes(team)) return toast('Player is not assigned to this squad'); if(ts.length===1) return toast('This is the player’s only squad. Edit the player to reassign them, or use the full profile removal action.'); if(!confirm(`Remove ${p.name} from ${TEAMS[team]?.name||team}? Their profile, parent details, loyalty card and historical data will be kept.`)) return; p.teams=ts.filter(t=>t!==team); if(p.team===team){ p.team=p.teams[0]; p.num=numFor(p,p.team); } log('↔️',`${p.name} removed from ${TEAMS[team]?.short||team}`); save(); closeSheet(); toast(`${p.name} removed from squad ✓`); paint(true); }
function familyRemovalScope(playerId='',parentId=''){
  const parentIds=new Set(parentId?[parentId]:[]), playerIds=new Set(playerId?[playerId]:[]);let changed=true;
  while(changed){changed=false;for(const p of S.players){const ps=pars(p);if(playerIds.has(p.id))for(const id of ps)if(id&&!parentIds.has(id)){parentIds.add(id);changed=true;}if(ps.some(id=>parentIds.has(id))&&!playerIds.has(p.id)){playerIds.add(p.id);changed=true;}}}
  return {parents:[...parentIds].map(id=>S.users.find(u=>u.id===id)).filter(Boolean),players:[...playerIds].map(id=>S.players.find(p=>p.id===id)).filter(Boolean)};
}
async function removeFamilyFromApp(playerId='',parentId=''){
  if(!me||me.role!=='coach')return toast('Coach access required');
  const scope=familyRemovalScope(playerId,parentId);if(!scope.parents.length&&!scope.players.length)return toast('No linked family records found');
  const who=[...scope.players.map(p=>p.name),...scope.parents.map(u=>u.name)];
  const details=`This removes ${scope.players.length} player${scope.players.length===1?'':'s'} and ${scope.parents.length} parent/guardian account${scope.parents.length===1?'':'s'}: ${who.join(', ')}. They will be signed out and cannot log in. Their private chats with Alfie will be deleted. This cannot be undone.`;
  if(!confirm(details))return;
  try{const j=await api('removefamily',playerId?{playerId}:{parentId});REV=j.rev;adopt(j.S);closeSheet();toast(`${scope.players.length} player(s) and ${scope.parents.length} parent account(s) removed`);paint(true);}catch(e){toast(e.message||'Could not remove this family');}
}
function removePlayer(id){const p=P(id);if(!p)return;return removeFamilyFromApp(id,'');}


