V.coach_club=()=>{
  const now=new Date(), up=occ(now,8).filter(o=>o.end>now), pend=S.bookings.filter(b=>b.status==='pending'), reqs=(S.requests||[]).filter(r=>r.status==='pending');
  return `<div class="ph"><small>Run the club</small><h1>Club</h1></div>
  <div class="toolrow"><button class="btn" onclick="openCompose()">📣 Message all parents</button></div>${loyHeroHTML()}<div class="list"><button class="row" onclick="go('bookings')"><span class="ic">🎟️</span><div class="grow"><b>Bookings &amp; payments</b><p>Camps · 1-1s · events · money</p></div></button></div>${reqs.length?`<h2 class="sec">New sign-ups <a>${reqs.length} waiting</a></h2>${reqs.map(reqCard).join('')}`:''}
  ${loyDueHTML()}<h2 class="sec">Parent messages ${coachUnread()?`<a>${coachUnread()} unread</a>`:''}</h2><div class="list">${S.threads.filter(t=>t.msgs.length).sort((a,b)=>b.msgs.at(-1).ts-a.msgs.at(-1).ts).map(t=>{const l=t.msgs.at(-1);return `<button class="row thread ${t.cu?'unread':''}" onclick="openThread('${t.id}')">${avHTML(t.name,(S.users.find(u=>u.id===t.fam)||{}).photo,'width:44px;height:44px;font-size:16px;background:linear-gradient(145deg,#5aa8ff,#2453a8);color:#fff')}<div class="grow"><b>${esc(t.name)} <span style="color:var(--mut);font-weight:600;font-size:12px">· ${esc(t.kid)}'s parent</span></b><p style="white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${l.by==='c'?'You: ':''}${esc(prevTxt(l))}</p></div><small style="color:var(--dim);font-size:11px;font-weight:700">${ago(l.ts)}</small></button>`}).join('')||'<div class="empty">No messages from parents yet</div>'}</div>
  <div class="list" style="margin-top:10px"><button class="row" onclick="go('squad')"><span class="ic">🃏</span><div class="grow"><b>Squads, stats &amp; player cards</b><p>${S.players.length} players · medical info ⚕️ · season table</p></div></button></div>
  <h2 class="sec">Taster requests ${pend.length?`<a>${pend.length} new</a>`:''}</h2><div class="list">${pend.map(b=>`<div class="row" id="r_${b.id}"><span class="ic">${b.user?'🆕':'📩'}</span><div class="grow"><b>${esc(b.child)} <span style="color:var(--mut);font-weight:600;font-size:13px">· ${esc(b.year)}</span></b><p>${esc(sessName(b))}<br>Parent: ${esc(b.parent)}${b.note?' · '+esc(b.note):''}</p></div><div style="display:grid;gap:6px"><button class="btn sm" onclick="decide('${b.id}',1)">Accept</button><button class="btn sm gh" onclick="decide('${b.id}',0)">Decline</button></div></div>`).join('')||'<div class="empty">All caught up ✅</div>'}</div>
  ${tasterAttHTML()}<h2 class="sec">Sessions <a onclick="newSession()">＋ Add</a></h2><div class="list">${S.sessions.map(s=>`<button class="row" onclick="editSession('${s.id}')"><span class="ic">🗓️</span><div class="grow"><b>${esc(s.title)}</b><p>Every ${DAYL[s.day]} · ${s.start}–${s.end} · ${esc(s.place)}</p></div></button>`).join('')||'<div class="empty">No weekly sessions yet</div>'}</div><h2 class="sec">Coming up</h2><div class="list">${up.map(o=>`<div class="row" style="${o.cx?'opacity:.7':''}"><span class="ic" style="font-family:var(--disp);font-weight:800;font-size:13px;color:var(--g);line-height:1.1">${DAYS[o.at.getDay()].toUpperCase()}<br>${o.at.getDate()}</span><div class="grow"><b style="${o.cx?'text-decoration:line-through;text-decoration-color:var(--red)':''}">${esc(o.s.title)}</b><p>${o.s.start}–${o.s.end} · ${o.s.teams.map(t=>TEAMS[t].short).join(', ')}</p></div><button class="btn sm ${o.cx?'':'rd'}" onclick="toggleCancel('${o.key}')">${o.cx?'Restore':'Cancel'}</button></div>`).join('')}</div>
    <h2 class="sec">Parents &amp; guardians <a>${S.users.filter(u=>u.role==='parent').length} joined</a></h2><div class="list"><button class="row" onclick="go('parents')"><span class="ic">👪</span><div class="grow"><b>All parents &amp; guardians</b><p>${S.users.filter(u=>u.role==='parent').length} joined · search by name or child</p></div><span class="go" style="color:var(--mut);font-size:22px">›</span></button></div>
  <h2 class="sec">Club</h2><div class="list"><button class="row" onclick="go('loyalty')"><span class="ic">🎟️</span><div class="grow"><b>Loyalty cards</b><p>${LY().on?`Stamp cards on · ${LY().need} stamps for a reward`:'Off'}${stDue().length?` · ${stDue().length} reward${stDue().length>1?'s':''} due`:''}</p></div></button><button class="row" onclick="clubSettings()"><span class="ic">⚙️</span><div class="grow"><b>Club settings</b><p>PayPal, 1-1 price, club info, join code</p></div></button><button class="row" onclick="seasonSheet()"><span class="ic">🏁</span><div class="grow"><b>End of season</b><p>Save this season's stats and start the new one</p></div></button><button class="row" onclick="window.open('?a=privacy','_blank')"><span class="ic">🔒</span><div class="grow"><b>Privacy notice</b><p>What parents agree to when they join</p></div></button><button class="row" onclick="sentMsgs()"><span class="ic">📣</span><div class="grow"><b>Sent messages</b><p>See or delete messages you've sent parents</p></div></button><button class="row" onclick="calSync()"><span class="ic">📅</span><div class="grow"><b>Sync to my phone's calendar</b><p>The whole club calendar in iPhone or Google Calendar</p></div></button><button class="row" onclick="venuesSheet()"><span class="ic">📍</span><div class="grow"><b>Venues</b><p>Add, edit or remove your venues</p></div></button><button class="row" onclick="openInstall()"><span class="ic">📲</span><div class="grow"><b>Install the app</b><p>On your home screen</p></div></button><button class="row" onclick="accountSheet()"><span class="ic">👤</span><div class="grow"><b>Your account</b><p>${esc(me.name)} · change password · log out</p></div></button></div>
  <p class="hint" style="text-align:center;margin-top:20px">AG Coaching FC · One club, one family</p>${npcCredit()}`;
};
const sessName=b=>{const s=S.sessions.find(x=>x.id===b.sid);return `${s?s.title:'Session'} · ${fmtD(new Date(b.date+'T12:00'))}${s?' · '+s.start:''}`};
function decide(id,yes){ const b=S.bookings.find(x=>x.id===id); b.status=yes?'confirmed':'declined';
  if(b.user) note(b.user,yes?'✅':'ℹ️',yes?`${b.child}'s free taster is confirmed: ${sessName(b)}. See you there!`:`Sorry, ${b.child}'s session is full. Alfie will be in touch.`);
  log(yes?'✅':'↩️',`${yes?'Confirmed':'Declined'} taster for ${b.child}`); save(); $('#r_'+id)?.classList.add('gone'); buzz(); setTimeout(()=>paint(true),420); if(yes) push('Booking confirmed ✅',`${b.parent} has been sent the details.`); }
function toggleCancel(key){ const was=!!S.cancel[key], [sid,d]=key.split('@'), s=S.sessions.find(x=>x.id===sid), dt=new Date(d+'T12:00');
  if(was){ delete S.cancel[key]; tell(s.teams,`✅ Good news: ${s.title} on ${fmtD(dt)} is back ON. ${s.start}–${s.end}.`); log('✅',`Restored ${s.title} (${fmtD(dt)})`); }
  else { S.cancel[key]=1; tell(s.teams,`❌ ${s.title} on ${fmtD(dt)} is CANCELLED, pitch unplayable. See you next session!`); log('❌',`Cancelled ${s.title} (${fmtD(dt)})`); }
  save(); buzz([40,30,40]); paint(true); push(was?'Back on ✅':'Session cancelled ❌',`${S.players.filter(p=>s.teams.includes(p.team)).length} players’ parents/guardians told instantly.`); }
function openCompose(){ const tpl=['✅ Training is ON tonight. Bring water & shin pads!','❌ Training cancelled tonight, pitch is waterlogged.','🏟️ Sunday: meet 9:30 for a 10:00 KO. Full kit please.','🎉 Massive well done this weekend. So proud of you all!'];
  ui.to??=[...TK];
  openSheet(`<div class="shb"><h3>Message parents</h3><p class="hint">Goes straight to their inbox in the app.</p>
   <div class="chips" style="margin-bottom:14px"><button class="chip ${ui.to.length===TK.length?'on':''}" onclick="ui.msg=$('#cMsg').value;ui.to=[...TK];openCompose()">Whole club</button>${TK.map(t=>`<button class="chip ${ui.to.includes(t)&&ui.to.length<TK.length?'on':''}" onclick="ui.msg=$('#cMsg').value;ui.to=ui.to.length===TK.length?['${t}']:(ui.to.includes('${t}')?ui.to.filter(x=>x!=='${t}'):[...ui.to,'${t}']);openCompose()">${TEAMS[t].short}</button>`).join('')}</div>
   <label class="field"><span>Message</span><textarea id="cMsg" rows="3">${esc(ui.msg??tpl[0])}</textarea></label>
   ${ui.mph?`<div class="mthumb"><img src="${ui.mph.prev}" alt=""><button onclick="ui.msg=$('#cMsg').value;ui.mph=null;openCompose()" aria-label="Remove photo">✕</button></div>${consentNote(S.players.filter(p=>ui.to.includes(p.team)))}`:`<label class="btn gh full" style="margin-bottom:12px;cursor:pointer">📷 Add a photo<input type="file" accept="image/*" hidden onchange="ui.msg=$('#cMsg').value;pickPhoto(this,'m')"></label>`}
   <div style="display:grid;gap:6px;margin-bottom:16px">${tpl.map(t=>`<button class="chip" style="text-align:left;border-radius:13px;padding:10px 12px" onclick="$('#cMsg').value=this.textContent">${t}</button>`).join('')}</div>
   <button class="btn full big" onclick="sendMsg()">📣 Send to parents of ${S.players.filter(p=>ui.to.includes(p.team)).length} players</button></div>`); }
async function sendMsg(){ const txt=$('#cMsg').value.trim(); if((!txt&&!ui.mph)||!ui.to.length) return toast('Write a message & pick a squad'); const n=S.players.filter(p=>ui.to.includes(p.team)).length;
  let img=null; if(ui.mph){ const b=$('#shb .btn.big'); if(b){b.disabled=true;b.textContent='Sending photo…';} try{ img=await uploadPhoto(ui.mph.blob); }catch(e){ if(b){b.disabled=false;b.textContent='📣 Try again';} return toast(e.message); } ui.mph=null; }
  tell([...ui.to],txt); if(img) S.messages.at(-1).img=img; log('📣',`Message to ${ui.to.length===TK.length?'whole club':ui.to.map(t=>TEAMS[t].short).join(', ')}`); ui.msg=null; save(); closeSheet(); setTimeout(()=>{push('AG Coaching FC',txt);buzz([30,30,60]);},400); setTimeout(()=>toast(`Sent to parents of ${n} players ✓`),1400); paint(true); }

/* ---------- PARENT ---------- */
const kids=()=>me?S.players.filter(p=>pars(p).includes(me.id)):[];
V.parent_home=()=>{
  const ks=kids(); if(!ks.length) return noKids()+supportHomeCard(); if(kidIdx>=ks.length) kidIdx=0; const k=ks[kidIdx], t=TEAMS[k.team], now=new Date();
  const live=S.fixtures.find(f=>f.team===k.team&&f.status==='live');
  const nextS=occ(now,14,s=>s.teams.includes(k.team)).find(o=>o.end>now), nextF=S.fixtures.filter(f=>f.team===k.team&&f.status==='up'&&f.at>Date.now()).sort((a,b)=>a.at-b.at)[0];
  let hero;
  if(live){ const m=Math.floor((live.live?.mins?.[k.id]||0)/60), on=Object.values(live.live?.on||{}).includes(k.id);
    hero=`<div class="hero lv"><span class="pill red">Live · ${mmss(live.live?.secs||0)}</span><div style="margin-top:12px">${scoreboard(live)}</div><div class="meta" style="margin-top:12px;text-align:center"><span>${on?`🟢 ${esc(k.name)} is on the pitch`:`🪑 ${esc(k.name)} is on the bench`} · ${m}′ played so far</span></div>
      <div class="feed" style="margin:12px 0 0">${live.events.slice(-3).reverse().map(e=>`<div class="fe"><b>${e.t}′</b>${e.type==='goal'?`⚽ ${esc(P(e.who)?.name)} scores!`:e.type==='opp'?`${esc(live.opp)} score`:`🔁 ${esc(e.txt)}`}</div>`).join('')}</div></div>`; }
  else if(nextF&&(!nextS||nextF.at<nextS.at)){ const v=nextF.avail[k.id];
    hero=`<div class="hero"><span class="pill">${esc(k.name)}'s next match</span><h3>vs ${esc(nextF.opp)}</h3><div class="meta"><span>${fmtD(new Date(nextF.at))} · ${nextF.meet?`Meet ${nextF.meet} · `:''}KO ${hm(new Date(nextF.at))} · ${nextF.home?'Home':'Away'}</span>${fxVenueLine(nextF)}</div><div class="cd" data-cd="${nextF.at}"></div>
