     :`<div class="hero"><span class="pill">${esc(k.name)}'s next session</span><h3>${esc(nextS.s.title)}</h3><div class="meta"><span>${fmtD(nextS.at)} · ${nextS.s.start}–${nextS.s.end}</span><span>📍 ${esc(nextS.s.place)}</span></div><div class="cd" data-cd="${+nextS.at}"></div>
      <div class="duo"><button class="seg yes ${r===true?'on':''}" onclick="setRsvp('${nextS.key}','${k.id}',true)">✅ Coming</button><button class="seg no ${r===false?'on':''}" onclick="setRsvp('${nextS.key}','${k.id}',false)">Can't make it</button></div></div>`; }
  if(!hero){ const nx=calItems(Date.now(),Date.now()+60*864e5,true)[0];
    hero=nx?`<div class="hero"><span class="pill">Coming up</span><h3>${esc(nx.type==='e'?nx.e.icon+' '+nx.e.title:nx.type==='c'?nx.c.icon+' '+nx.c.name:nx.type==='s'?nx.o.s.title:nx.type==='f'?TEAMS[nx.f.team].short+' vs '+nx.f.opp:'1-1 session')}</h3><div class="meta"><span>${fmtL(nx.at)} · ${hm(new Date(nx.at))}${nx.type==='e'?' · '+esc(nx.e.place):nx.type==='c'?' · '+esc(nx.c.place):''}</span></div><div class="cd" data-cd="${nx.at}"></div><div style="margin-top:14px"><span class="btn" onclick="go('calendar')">Open the calendar →</span></div></div>`
    :`<div class="hero"><span class="pill">Welcome</span><h3>You're in!</h3><div class="meta"><span>${esc(k.name)}'s matches and training will show here as soon as Alfie adds them.</span></div></div>`; }
  const ts=new Set(ks.map(p=>p.team)), latest=S.messages.filter(m=>m.teams.some(x=>ts.has(x))).sort((a,b)=>b.ts-a.ts)[0];
  const last=S.fixtures.filter(f=>f.team===k.team&&f.status==='ft').sort((a,b)=>b.at-a.at)[0], s=stats(k);
  return topbar(greet()+', '+esc(me.first),'Your football family')+
  `<div class="card" id="parentHomeCheckin" style="margin:14px 14px 16px;padding:18px;background:linear-gradient(135deg,#123b20,#08140c);border:1px solid rgba(63,243,106,.55);box-shadow:0 8px 24px rgba(0,0,0,.22)"><div style="display:flex;align-items:center;gap:12px"><div style="font-size:32px">📷</div><div class="grow"><b style="font-family:var(--disp);font-size:21px;color:#fff">TRAINING CHECK-IN</b><p class="hint" style="margin:3px 0 0">Scan the club QR poster to check ${esc(k.name)} in.</p></div></div><button class="btn full" style="margin-top:14px;min-height:50px;font-size:16px" onclick="startParentQRScan()">▦ SCAN QR CODE TO CHECK IN</button></div>`+
  (ks.length>1?`<div class="kids">${ks.map((c,i)=>`<button class="kid-pill ${i===kidIdx?'on':''}" onclick="kidIdx=${i};paint(true)"><i>${c.num}</i>${esc(c.name)}</button>`).join('')}</div>`:'')+`<section class="club-welcome"><div class="cw-kicker"><i></i> WELCOME TO THE AG FAMILY</div><div class="cw-title">Good to see you, ${esc(me.first)}.</div><p class="cw-copy">Your family's football life, all in one place. Keep up with ${esc(k.name)}'s training, matches, messages and milestones.</p><div class="cw-foot"><span class="cw-tag">ONE CLUB. ONE FAMILY.</span><span class="cw-squad">${esc(t?.short||'AG Coaching FC')}</span></div></section>`+hero+
  `<div class="toolrow"><button class="btn gh" onclick="ui.ib='chat';go('inbox')">💬 Message Coach Alfie${myThread().pu?` · ${myThread().pu} new`:''}</button><button class="btn gh" onclick="ui.st='${k.team}';go('stats')">📊 Squad stats</button></div>`+stampCardHTML(k)+(latest?`<h2 class="sec">From Coach Alfie <a onclick="ui.ib='upd';go('inbox')">All updates</a></h2><div class="list"><button class="row ${latest.read.includes(me.id)?'':'unread'}" onclick="go('inbox')"><span class="ic">📣</span><div class="grow"><time>${ago(latest.ts)}</time><p style="color:var(--w);font-size:14px;margin-top:3px">${esc(latest.text)}</p></div></button></div>`:'')+
  `<h2 class="sec">${esc(k.name)}'s season <a onclick="ui.st='${k.team}';go('stats')">Squad stats</a></h2><div class="season-layout"><div class="pc" data-tilt onclick="this.classList.toggle('flip')">${cardHTML(k)}</div>
   <div class="season-metrics">${[['Minutes played',s.mins+"'"],['Goals · Assists',`${s.goals} · ${s.ast}`],['Training',s.train===null?'—':s.train+'%']].map(([l,v])=>`<div style="background:var(--card);border:1px solid var(--line);border-radius:16px;padding:10px 12px"><small style="color:var(--mut);font-size:11px;font-weight:700">${l}</small><div style="font-family:var(--disp);font-weight:900;font-size:24px;line-height:1.1">${v}</div></div>`).join('')}</div></div>
   <p class="hint" style="padding:0 18px;margin-top:10px">Every child gets fair minutes. Tap the card to flip it.</p><div class="toolrow"><button class="btn gh" onclick="ui.st='${k.team}';go('stats')">📊 See the whole squad's goals &amp; assists →</button></div>`+
  (last?`<h2 class="sec">Last result</h2>`+resultCard(last,k.id):'')+
  `${comingUp()}
  <h2 class="sec">Know a player?</h2><div class="card" style="background:linear-gradient(130deg,#163d22,#0a160d)"><b style="font-family:var(--disp);font-size:22px;text-transform:uppercase">Free taster sessions</b><p class="hint">${esc(S.club?.taster||'First session free')}. All abilities welcome. Know someone who'd love it? Book them in.</p><button class="btn sm" onclick="startBook()">Book a free taster →</button></div>`+supportHomeCard();
};
function saveInfo(pid){ if(ui.profilePhotoBusy) return toast('Please wait for the photo to finish saving'); const p=P(pid), dob=$('#ciDob')?.value||''; if(dob&&!/^\d{4}-\d{2}-\d{2}$/.test(dob)) return toast('Check the date of birth'); p.dob=dob; p.info={...(p.info||{}),med:$('#ciM').value.trim(),emer:$('#ciE').value.trim(),photo:$('#ciP').classList.contains('on')}; log('🩺',`${me.first} updated ${p.name}'s details`); save(); paint(true); toast('Saved ✓ Alfie can see this'); }
function setRsvp(key,pid,v){ (S.rsvp[key]??={})[pid]=v; log(v?'🙋':'🙅',`${P(pid).name} ${v?'is coming to':"can't make"} training`); save(); buzz(); toast(v?'Alfie knows ✅':'Thanks, Alfie has been told'); paint(true); }
function setAvail(fid,pid,v){ const f=F(fid); f.avail[pid]=v; f.plan=null; log(v?'✅':'❌',`${P(pid).name} ${v?'available':'unavailable'} vs ${f.opp}`); save(); buzz(); toast(v?`${P(pid).name} is available ✅`:'Marked as unavailable'); paint(true); }
V.parent_schedule=()=>{
  const ts=[...new Set(kids().map(p=>p.team))], now=new Date();
  const items=[...occ(now,14,s=>s.teams.some(t=>ts.includes(t))).filter(o=>o.end>now),...S.fixtures.filter(f=>ts.includes(f.team)&&f.status!=='ft').map(f=>({kind:'f',f,at:new Date(f.at)}))].sort((a,b)=>a.at-b.at);
  const by={}; items.forEach(o=>(by[ymd(o.at)]??=[]).push(o)); const td=ymd(now);
  return `<div class="ph"><small>Next two weeks</small><h1>Schedule</h1></div>`+Object.keys(by).map(d=>{const dt=new Date(d+'T12:00');return `<div class="day"><h4 class="${d===td?'today':''}">${d===td?'Today':DAYL[dt.getDay()]} · ${dt.getDate()} ${MON[dt.getMonth()]}</h4>`+
   by[d].map(o=>o.kind==='f'?`<div class="ev fx"><div class="tm">${hm(o.at)}<small>KO</small></div><div class="grow"><b>${o.f.status==='live'?'🔴 LIVE · ':''}${TEAMS[o.f.team].short} vs ${esc(o.f.opp)}</b><p>${o.f.home?'Home':'Away'} · ${TEAMS[o.f.team].fmt}v${TEAMS[o.f.team].fmt}</p></div></div>`
   :`<div class="ev ${o.cx?'cx':''}"><div class="tm">${o.s.start}<small>${o.s.end}</small></div><div class="grow"><b>${esc(o.s.title)}</b><p>📍 ${esc(o.s.place)}</p>${o.cx?'<span class="chip red" style="margin-top:6px;display:inline-block">Cancelled</span>':''}</div></div>`).join('')+'</div>'}).join('');
};
V.parent_inbox=()=>{
  ui.ib??='chat';
  const ts=new Set(kids().map(p=>p.team)), th=myThread();
  const seg=`<div class="segc">${[['chat',`💬 Coach Alfie${th.pu?` (${th.pu})`:''}`],['upd','📣 Club updates']].map(([k,l])=>`<button class="${ui.ib===k?'on':''}" onclick="ui.ib='${k}';paint(true)">${l}</button>`).join('')}</div>`;
  if(ui.ib==='chat'){
    const unreadAt=th.pu||0;
    if(th.pu){ th.pu=0; save(); setTimeout(tabs,50); }
    return `<div class="chat-shell">
    <div class="chathead modern"><button class="back" onclick="go('chats')" aria-label="Back">‹</button>${avHTML('Alfie Greenwood',(S.users.find(u=>u.id==='coach')||{}).photo,'background:linear-gradient(145deg,#5aa8ff,#2453a8);color:#fff')}<div class="grow"><b style="font-family:var(--disp);font-size:20px;text-transform:uppercase">Coach Alfie</b><div class="status">● Club coach · private chat</div></div><div class="chat-toolbar"><button class="iconbtn" onclick="toast('Private chat with Coach Alfie')" aria-label="Chat info">ⓘ</button></div></div>
    ${chatHTML(th,'p',unreadAt)}
    <div class="chat-quick">${['Running 10 mins late 🏃',`${kids()[0]?.name||'My child'}'s poorly today 🤒`,`${kids()[0]?.name||'My child'} can't make it today`,'Thanks Alfie! 🙌'].map(q=>`<button onclick="$('#cIn').value=this.textContent;$('#cIn').focus()">${esc(q)}</button>`).join('')}</div>
    <div class="chat-composer">${attBtn('tp')}${voiceBtn('tp')}<input id="cIn" data-draft-key="${me.id}|t${th.id}" placeholder="Message Coach Alfie…" value="${esc(ui.draft||'')}" onkeydown="if(event.key==='Enter'&&!event.shiftKey&&!event.isComposing&&event.keyCode!==229&&!event.repeat){event.preventDefault();sendChat()}"><button class="send" onclick="sendChat()" aria-label="Send">↑</button></div></div>`;
  }
  const items=[...S.messages.filter(m=>m.teams.some(t=>ts.has(t))).map(m=>({ts:m.ts,ic:'📣',who:'Coach Alfie',txt:m.text,u:!m.read.includes(me.id),r:1,link:m.link,img:m.img})),...S.notes.filter(n=>n.to===me.id).map(n=>({ts:n.ts,ic:n.ic,who:'AG Coaching FC',txt:n.t,u:!n.read}))].sort((a,b)=>b.ts-a.ts);
  setTimeout(()=>{ let c=0; S.messages.forEach(m=>{ if(m.teams.some(t=>ts.has(t))&&!m.read.includes(me.id)){m.read.push(me.id);c++;} }); S.notes.forEach(n=>{ if(n.to===me.id&&!n.read){n.read=true;c++;} }); if(c){save();tabs();} },1500);
  return `<div class="ph"><button class="chip" onclick="go('chats')" style="margin-bottom:10px">← Chats</button><small style="display:block">From the club</small><h1>Messages</h1></div>${seg}<div style="height:12px"></div><div class="list">${items.map(i=>`<div class="row ${i.u?'unread':''}"><span class="ic">${i.ic}</span><div class="grow"><time>${i.who} · ${ago(i.ts)}</time>${i.txt?`<p style="color:var(--w);font-size:14px;margin-top:4px;line-height:1.45">${esc(i.txt)}</p>`:''}${i.img?`<img class="mimg" src="?a=img&f=${i.img}" loading="lazy" alt="Photo" onclick="viewImg('${i.img}')">`:''}${i.link?payBtn(i.link):''}${i.r?`<button class="chip" style="margin-top:8px" onclick="ui.ib='chat';ui.draft='Re: ${esc((i.txt||'your photo').slice(0,28)).replace(/'/g,'')}… ';paint(true)">↩︎ Reply to Alfie</button>`:''}</div></div>`).join('')||'<div class="empty">No messages yet</div>'}</div>`;
};
function chatHTML(t,side,unreadOverride=null,contentsOnly=false){
  const MAX=160;
  const all=t.msgs||[];
  const start=Math.max(0,all.length-MAX);
  const msgs=all.slice(start);
  const out=[]; let lastDay='';
  const unread=unreadOverride??((side==='p'?t.pu:t.cu)||0);
  const incomingIdx=all.map((m,i)=>((side==='p'&&m.by==='c')||(side==='c'&&m.by==='p'))?i:-1).filter(i=>i>=0);
  const unreadSet=new Set(unread?incomingIdx.slice(-unread):[]);
  if(start>0) out.push(`<div class="daysep">↑ ${start} earlier messages</div>`);
  msgs.forEach((m,local)=>{
    const i=start+local, d=new Date(m.ts), dk=ymd(d);
    if(dk!==lastDay){ out.push(`<div class="chat-date">${dk===ymd(new Date())?'Today':fmtD(d)}</div>`); lastDay=dk; }
    if(unreadSet.has(i) && !out.some(x=>x.includes('unread-divider'))){ out.push('<div class="unread-divider" role="separator"><span>New messages</span></div>'); }
    const mine=(side==='p'&&m.by==='p')||(side==='c'&&m.by==='c');
    const prev=msgs[local-1], same=prev&&prev.by===m.by&&((m.ts-prev.ts)<300000);
    out.push(bubHTML(m,mine,`t|${t.id}|${i}`,same?'':(mine?'':'<b style="display:block;font-size:11px;color:var(--g);margin-bottom:2px">'+esc(side==='p'?'Coach Alfie':t.name)+'</b>'),mine?(unreadSet.has(i)?'sent':'read'):null));
  });
  if(!all.length) out.push(`<div class="chat-empty"><div class="big">👋</div><b>Start the conversation</b><p class="hint" style="margin:6px 0 0">${side==='p'?'Message Coach Alfie directly.':'Your private conversation with '+esc(t.name)+'.'}</p></div>`);
  return contentsOnly?out.join(''):`<div class="chat" id="chatbox">${out.join('')}</div>`;
}
function sendChat(){ const i=$('#cIn'), t=i.value.trim(); if(!t) return; i.value=''; postDM(t); }
function postDM(t,img,audio,dur,media=null){ const th=media?S.threads.find(x=>x.id===media.threadId&&x.fam===media.sender.id):myThread(); if(!th)return; th.msgs.push({by:'p',t,ts:Date.now(),...(img?{img}:{}),...(audio?{audio,dur}:{})}); th.cu=(th.cu||0)+1; if(!media?.quiet)ui.draft='';
  log('💬',`${media?.sender.first??me.first}: "${(img?'📷 ':'')+t.slice(0,60)}"`); save(); if(!media?.quiet){buzz(15);paint(true);scrollChatToEnd(true);} }
function openThread(id){ const t=S.threads.find(x=>x.id===id); if(!t) return;
  if(me?.role==='coach'){ ui.th=id; view='private'; paint(); return; }
  const unreadAt=t.pu||0; t.pu=0; save(); tabs();
  openSheet(`<div class="shb"><div class="chat-shell">
    <div class="chathead modern"><button class="back" onclick="closeSheet()" aria-label="Back">‹</button>${avHTML(t.name,(S.users.find(u=>u.id===t.fam)||{}).photo,'background:linear-gradient(145deg,#5aa8ff,#2453a8);color:#fff')}<div class="grow"><b style="font-family:var(--disp);font-size:20px;text-transform:uppercase">${esc(t.name)}</b><div class="status">● Parent · ${esc(t.kid||'child')}</div></div><div class="chat-toolbar"><button class="iconbtn" onclick="familySheet('${t.fam}')" aria-label="Parent details">ⓘ</button></div></div>
    ${chatHTML(t,'c',unreadAt)}
    <div class="chat-quick">${['On my way 👍','Training is still on ✅','No problem, get well soon!','Trainers are fine 👟'].map(q=>`<button onclick="$('#cIn2').value=this.textContent;$('#cIn2').focus()">${esc(q)}</button>`).join('')}</div>
    <div class="chat-composer">${attBtn('tc|'+t.id)}${voiceBtn('tc|'+t.id)}<input id="cIn2" data-draft-key="${me.id}|t${t.id}" value="${esc(draftValue('t',t.id))}" placeholder="Reply to ${esc(t.name)}…" onkeydown="if(event.key==='Enter'&&!event.shiftKey&&!event.isComposing&&event.keyCode!==229&&!event.repeat){event.preventDefault();coachReply('${t.id}')}"><button class="send" onclick="coachReply('${t.id}')" aria-label="Send">↑</button></div></div></div>`);
  $('#sheet').classList.add('chat-sheet');
  setTimeout(()=>{scrollChatToEnd(true);$('#cIn2')?.focus({preventScroll:true});},80); }
function coachReply(id){ const i=$('#cIn2'), x=i.value.trim(); if(!x) return; i.value='';postReply(id,x); }
function postReply(id,x,img,audio,dur,media=null){ const t=S.threads.find(y=>y.id===id); if(!t)return; t.msgs.push({by:'c',t:x,ts:Date.now(),...(img?{img}:{}),...(audio?{audio,dur}:{})}); t.pu=(t.pu||0)+1;
  save();if(!media?.quiet){buzz(15);if($('#sheet').classList.contains('on'))closeSheet();if(me?.role==='coach'&&view==='private'&&ui.th===id){paint(true);scrollChatToEnd(true);}else openThread(id);} }
