  `<div style="padding:20px 0 0"><div class="pc lg" data-tilt onclick="this.classList.toggle('flip')">${cardHTML(k)}</div><p class="hint" style="text-align:center;margin-top:10px">Tap to flip · tilt to shine</p><div class="toolrow"><button class="btn gh" onclick="ui.st='${k.team}';go('stats')">📊 Squad stats: goals, assists, matches</button></div></div>
   ${stampCardHTML(k)}<h2 class="sec">${esc(k.name)}'s details</h2><div class="card"><p class="hint" style="margin:0 0 12px">Only Alfie and his coaches can see this. Vital for camps and matchdays.</p>
