    <div class="phpick"><span id="ciAv" data-player-id="${k.id}">${avHTML(k.name,k.info?.photo===false?null:k.photo)}</span><div class="grow"><b>${esc(k.name)}'s player photo</b><p class="hint">One upload updates your avatar and this player's card and squad stats. Photos save automatically; no coach action needed.${k.info?.photo===false?' Turn on photo consent and save details to display the photo.':''}</p><div style="display:flex;gap:8px;margin-top:8px;flex-wrap:wrap"><label class="chip" style="cursor:pointer">📷 Add / change photo<input type="file" accept="image/*" hidden onchange="pickProfilePhoto(this,'child','${k.id}')"></label>${k.photo?`<button class="chip" style="color:#ff6b6b" onclick="removeProfilePhoto('${k.id}')">Remove from both</button>`:''}</div></div></div>
    <div style="display:flex;align-items:center;gap:12px;margin:4px 0 14px"><span style="flex:1;font-size:14px;font-weight:700">📸 Happy for ${esc(k.name)} to appear in club photos</span><button class="tog ${k.info?.photo!==false?'on':''}" id="ciP" onclick="this.classList.toggle('on')"></button></div>
    <button class="btn full" onclick="saveInfo('${k.id}')">Save details</button></div>
   ${(()=>{const cb=S.campBk.filter(b=>b.uid===me.id), sl=S.slots.filter(x=>x.booked?.uid===me.id), pays=S.payments.filter(p=>p.uid===me.id);return (cb.length||sl.length?`<h2 class="sec">My bookings</h2><div class="list">${cb.map(b=>{const c=S.camps.find(x=>x.id===b.camp);return `<div class="row"><span class="ic">${c.icon}</span><div class="grow"><b>${esc(b.child)} · ${esc(c.name)}</b><p>${b.days.map(i=>fmtD(new Date(c.days[i]))).join(', ')}</p></div><span class="chip hot">Paid</span></div>`}).join('')}${sl.map(x=>`<div class="row"><span class="ic">🎯</span><div class="grow"><b>1-1 · ${esc(x.booked.name)}</b><p>${fmtL(x.at)} · ${hm(new Date(x.at))}</p></div><span class="chip hot">Paid</span></div>`).join('')}</div>`:'')+(pays.length?`<h2 class="sec">Payments</h2><div class="card" style="padding:6px 16px">${pays.map(p=>`<div class="act"><i>🧾</i><span>${esc(p.what)}</span><small style="font-weight:800;font-size:13px;color:var(--w)">${money(p.amount)}</small></div>`).join('')}</div>`:'')})()}
   ${mine.length?`<h2 class="sec">My taster bookings</h2><div class="list">${mine.map(b=>`<div class="row"><span class="ic">${b.status==='confirmed'?'✅':'⏳'}</span><div class="grow"><b>${esc(b.child)}</b><p>${esc(sessName(b))}</p></div><span class="chip ${b.status==='confirmed'?'hot':'warn'}">${b.status==='confirmed'?'Confirmed':'Pending'}</span></div>`).join('')}</div>`:''}
   <h2 class="sec">App</h2><div class="list"><button class="row" onclick="startBook()"><span class="ic">🎟️</span><div class="grow"><b>Book a free taster</b><p>For a friend or sibling</p></div></button><button class="row" onclick="calSync()"><span class="ic">📅</span><div class="grow"><b>Sync to my phone's calendar</b><p>iPhone or Google Calendar · updates by itself</p></div></button><button class="row" onclick="openInstall()"><span class="ic">📲</span><div class="grow"><b>Install the app</b><p>Home screen, alerts, works offline</p></div></button><button class="row" onclick="accountSheet()"><span class="ic">👤</span><div class="grow"><b>Your account</b><p>Change password · log out</p></div></button></div>${clubInfo()}`; };
/* booking */
const YEARS=[['Reception','age 4–5',5],['Year 1','age 5–6',6],['Year 2','age 6–7',7],['Year 3','age 7–8',8],['Year 4','age 8–9',9],['Year 5','age 9–10',10]];
let bk={};
function startBook(){ bk={step:0,year:null,sel:null,child:'',parent:me.name}; view='book'; paint(); }
V.parent_book=()=>{ if(typeof bk==='undefined'||!bk||bk.step==null){ bk={step:0,year:null,sel:null,child:'',parent:me.name}; } if(bk.step>=1&&bk.year==null) bk.step=0;
  const st=`<div class="ph"><small>Free · no commitment</small><h1>Book a<br>free taster</h1></div><div class="steps">${[0,1,2].map(i=>`<i class="${i<bk.step?'done':''}"></i>`).join('')}</div>`;
  if(bk.step===0) return st+`<div class="panel"><h3>Who's coming?</h3><p class="hint">Pick their school year and we'll match the right session.</p><label class="field"><span>Child's first name</span><input id="bChild" value="${esc(bk.child)}" placeholder="e.g. Mason" oninput="bk.child=this.value"></label>
     <div class="g3">${YEARS.map((y,i)=>`<button class="opt ${bk.year===i?'on':''}" onclick="bk.year=${i};paint(true)">${y[0]}<small>${y[1]}</small></button>`).join('')}</div></div><div class="cta"><button class="btn" onclick="bkNext()">Find sessions →</button></div>`;
  if(bk.step===1){ const age=YEARS[bk.year][2], now=new Date(); bk.list=occ(now,21).filter(o=>o.at>now&&!o.cx).slice(0,6);
    return st+`<div class="panel"><h3>Pick a session</h3><p class="hint">Right for ${esc(bk.child||'your child')} (${YEARS[bk.year][0]}).</p>${(bk.list.length?'':'<div class="empty">No sessions in the next 3 weeks. Message Alfie and he\'ll sort a date.</div>')+bk.list.map((o,i)=>{return `<button class="sess ${bk.sel===i?'on':''}" onclick="bk.sel=${i};paint(true)"><div class="ev" style="margin:0;padding:0;border:0;background:none;flex:0 0 58px"><div class="tm" style="flex:1;height:58px">${o.at.getDate()}<small>${DAYS[o.at.getDay()].toUpperCase()}</small></div></div><div style="flex:1"><b>${esc(o.s.title)}</b><p style="font-size:12px;color:var(--mut);margin-top:2px">${o.s.start}–${o.s.end} · ${esc(o.s.place)}</p></div></button>`}).join('')}</div>
     <div class="cta" style="display:flex;gap:10px"><button class="btn gh" style="width:auto" onclick="bk.step=0;paint()">Back</button><button class="btn" onclick="bkNext()">Continue →</button></div>`; }
  if(bk.step===2) return st+`<div class="panel"><h3>Your details</h3><p class="hint">Alfie confirms in the app and you'll get a notification.</p><label class="field"><span>Parent / guardian name</span><input value="${esc(bk.parent)}" oninput="bk.parent=this.value"></label><label class="field"><span>Who told you about us? (optional)</span><input value="${esc(bk.ref||'')}" placeholder="A friend at the club? Their name gets them a bonus stamp" oninput="bk.ref=this.value"></label><p class="hint" style="margin:0">⚽ ${esc(S.club?.taster||"First session free")}</p></div>
     <div class="cta" style="display:flex;gap:10px"><button class="btn gh" style="width:auto" onclick="bk.step=1;paint()">Back</button><button class="btn" onclick="bkNext()">Confirm booking ✓</button></div>`;
  const b=bk.done, o=bk.list[bk.sel];
  return `<div class="ph"><small>Booking received</small><h1>See you<br>there!</h1></div><div class="ticket"><div class="tp"><img src="${BADGE}" alt=""><div><small style="color:var(--g);font-weight:800;letter-spacing:.16em;font-size:11px">FREE TASTER · ${b.ref}</small><h3>${esc(b.child)}</h3></div></div><div class="tear"></div>
   <div class="bt"><div><small>Session</small><b>${esc(o.s.title)}</b></div><div><small>When</small><b>${fmtD(o.at)} · ${o.s.start}</b></div><div><small>Where</small><b>${esc(o.s.place)}</b></div><div><small>Status</small><b style="color:var(--amber)">Awaiting Alfie</b></div></div></div><div class="cta"><button class="btn" onclick="go('home')">Done</button></div>`;
};
function bkNext(){ if(bk.step===0){ if(!bk.child.trim()) return toast('Add their first name'); if(bk.year===null) return toast('Pick a school year'); bk.step=1; bk.sel=null; }
  else if(bk.step===1){ if(bk.sel===null) return toast('Choose a session'); bk.step=2; }
  else { if(!bk.parent.trim()) return toast('Add your name'); const o=bk.list[bk.sel], b={id:uid('b'),ref:'AG-'+Math.random().toString(36).slice(2,6).toUpperCase(),child:bk.child.trim(),year:YEARS[bk.year][0],note:'',sid:o.s.id,date:ymd(o.at),parent:bk.parent.trim(),status:'pending',ts:Date.now(),user:me.id,refBy:(bk.ref||'').trim().slice(0,60)};
    S.bookings.unshift(b); log('📩',`${b.parent} booked a free taster for ${b.child}`); save(); bk.done=b; bk.step=3; confetti(); buzz([30,40,80]); setTimeout(()=>push('Booking received 📩',`Alfie will confirm ${b.child}'s place shortly.`),1400); }
  paint(); }

/* =========================================================
   v5 · Alfie's wishlist: calendar & events, group chats,
   camps, 1-1 bookings, payments & payment links, child info
   ========================================================= */
function D(y,m,d,h=0,mi=0){ return new Date(y,m,d,h,mi).getTime(); }
const fmtL=t=>{const d=new Date(t);return `${DAYL[d.getDay()]} ${d.getDate()} ${MON[d.getMonth()]}`};
const money=n=>'£'+(Number.isInteger(n)?n:n.toFixed(2));
const medFlag=p=>p?.info?.med&&!/^none$/i.test(p.info.med.trim())?' ⚕️':'';

/* ---------- groups ---------- */
function myGroups(){ if(!me) return []; if(me.role==='coach') return S.groups;
  const ts=new Set(kids().map(p=>p.team)); return S.groups.filter(g=>!g.coaches&&(g.all||(g.teams&&g.teams.some(t=>ts.has(t)))||(g.camp&&S.campBk.some(b=>b.camp===g.camp&&b.uid===me.id)))); }
const gUnread=(g,id)=>g.msgs.slice((g.read||{})[id]||0).filter(m=>m.uid!==id&&!(me?.role==='coach'&&m.by==='coach'&&!m.uid)).length;
const groupsUnread=()=>me?myGroups().reduce((a,g)=>a+gUnread(g,me.id),0):0;
function groupChatHTML(g,meId,readAtOverride=null,contentsOnly=false){
  const MAX=160, all=g.msgs||[], start=Math.max(0,all.length-MAX), msgs=all.slice(start), out=[]; let last='';
  if(start>0) out.push(`<div class="daysep">↑ ${start} earlier messages</div>`);
  const readAt=readAtOverride??((g.read||{})[meId]||0);
  msgs.forEach((m,local)=>{ const gi=start+local,d=new Date(m.ts),dk=ymd(d); if(dk!==last){out.push(`<div class="chat-date">${dk===ymd(new Date())?'Today':fmtD(d)}</div>`);last=dk;}
    if(gi===readAt && gi<all.length && !out.some(x=>x.includes('unread-divider'))){ out.push('<div class="unread-divider" role="separator"><span>New messages</span></div>'); }
    const mine=m.uid?m.uid===meId:(me.role==='coach'&&m.by==='coach'); const prev=msgs[local-1], same=prev&&prev.uid===m.uid&&((m.ts-prev.ts)<300000);
    out.push(bubHTML(m,mine,`g|${g.id}|${gi}`,same?'':`<b style="display:block;font-size:11px;color:${m.by==='coach'?'var(--g)':'#7fb6ff'};margin-bottom:2px">${esc(m.name||'Member')}${m.by==='coach'?' · Coach':''}</b>`,mine?(seenBy(g,gi).all?'read':'sent'):null)); });
  const content=out.join('')||'<div class="chat-empty"><div class="big">💬</div><b>Start the group chat</b><p class="hint" style="margin:6px 0 0">Messages here are visible to the group members.</p></div>';
  return contentsOnly?content:`<div class="chat" id="groupChatbox">${content}</div>`;
}
V.parent_chats=()=>{
  const th=myThread(), gs=myGroups(), ts=new Set(kids().map(p=>p.team));
  const upd=S.messages.filter(m=>m.teams.some(t=>ts.has(t))), updU=upd.filter(m=>!m.read.includes(me.id)).length+S.notes.filter(n=>n.to===me.id&&!n.read).length, lu=upd.sort((a,b)=>b.ts-a.ts)[0];
  const row=(ic,name,sub,u,on,ts)=>`<button class="row thread ${u?'unread':''}" onclick="${on}"><span class="ic" style="font-size:22px">${ic}</span><div class="grow"><b>${name}</b><p style="white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${sub}</p></div><div style="display:grid;gap:4px;justify-items:end"><small style="color:var(--dim);font-size:11px;font-weight:700">${ts?ago(ts):''}</small>${u?`<span class="badge">${u}</span>`:''}</div></button>`;
  const lt=th.msgs.at(-1);
  return `<div class="ph"><small>Coach Alfie &amp; club updates</small><h1>Inbox</h1></div><div style="height:12px"></div>
  <div class="list">${row('🧑‍🏫','Coach Alfie',lt?esc((lt.by==='p'?'You: ':'')+prevTxt(lt)):'Private chat · message Alfie directly',th.pu,"ui.ib='chat';go('inbox')",lt?.ts)}
  ${row('📣','Club updates',lu?esc(lu.text||(lu.img?'📷 Photo':'')):'Announcements from the club',updU,"ui.ib='upd';go('inbox')",lu?.ts)}</div>

  <div class="list" style="margin-top:10px"><button class="row" onclick="go('groups')"><span class="ic">👥</span><div class="grow"><b>Group chats</b><p>Squads, sessions &amp; camps · now in the Groups tab</p></div></button></div>`;
};
function groupMembers(g){ if(g.all) return S.users.filter(u=>u.role==='parent').length; if(g.coaches) return S.users.filter(u=>u.role==='coach').length; return g.teams?new Set(S.players.filter(p=>g.teams.includes(p.team)).map(p=>p.id)).size:(g.camp?S.campBk.filter(b=>b.camp===g.camp).length+(S.camps.find(c=>c.id===g.camp)?.taken[0]||0):(g.members||0)); }
function groupsView(embedded=false){ const gs=myGroups(), coach=me.role==='coach';
  const head=embedded?'':`<div class="ph"><small>${coach?'You\'re the admin of every group':'Squads, sessions &amp; camps'}</small><h1>Group chats</h1></div><div style="height:12px"></div>`;
  const list=`<div class="list">${gs.slice().sort((a,b)=>(b.msgs.at(-1)?.ts||0)-(a.msgs.at(-1)?.ts||0)).map(g=>{const l=g.msgs.at(-1),u=gUnread(g,me.id);return `<button class="row thread ${u?'unread':''}" onclick="ui.grp='${g.id}';go('group')"><span class="ic" style="font-size:24px">${g.icon}</span><div class="grow"><b>${esc(g.name)}</b><p style="white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${l?esc((l.by==='coach'?'Coach':l.name.split(' ')[0])+': '+prevTxt(l)):'No messages yet'}</p><p style="font-size:11px;color:var(--dim);margin-top:2px">${g.coaches?groupMembers(g)+' coach'+(groupMembers(g)===1?'':'es'):groupMembers(g)+(g.all?(groupMembers(g)===1?' member':' members'):g.camp?' booked':(groupMembers(g)===1?' player':' players'))}${g.all?' · whole club':g.teams?' · '+g.teams.map(t=>TEAMS[t]?.short||t).join(', '):g.camp?' · camp':''}${g.ro?' · 📣 announcements':''}</p></div><div style="display:grid;gap:4px;justify-items:end"><small style="color:var(--dim);font-size:11px;font-weight:700">${l?ago(l.ts):''}</small>${u?`<span class="badge">${u}</span>`:''}</div></button>`}).join('')}</div>`;
  return head+list+(coach?`<div class="toolrow"><button class="btn" onclick="newGroup()">＋ New group chat</button></div>`:`<p class="hint" style="text-align:center;margin-top:14px;padding:0 20px">You're added automatically for your children's squads and any camps you book.</p>`)+`<div style="height:12px"></div>`;
}
V.parent_groups=groupsView; V.coach_groups=groupsView;
function coachPrivateInbox(){
  const q=(ui.cq||'').trim().toLowerCase();
  const rows=S.threads.filter(t=>!q||`${t.name} ${t.kid||''} ${prevTxt(t.msgs.at(-1)||{})}`.toLowerCase().includes(q)).sort((a,b)=>(b.msgs.at(-1)?.ts||0)-(a.msgs.at(-1)?.ts||0));
  return `<div class="chat-search"><span style="font-size:17px">⌕</span><input value="${esc(ui.cq||'')}" placeholder="Search parents or children…" oninput="ui.cq=this.value;filterCoachThreads(this.value)"></div><div class="list chat-directory">${rows.map(t=>{const l=t.msgs.at(-1),u=t.cu||0;return `<button class="row thread ${u?'unread':''}" onclick="openThread('${t.id}')">${avHTML(t.name,(S.users.find(x=>x.id===t.fam)||{}).photo,'width:48px;height:48px;font-size:17px;background:linear-gradient(145deg,#5aa8ff,#2453a8);color:#fff')}<div class="grow"><b>${esc(t.name)}</b><p style="font-size:12px;color:var(--mut)">${esc(t.kid||'Private conversation')}</p><p style="white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin-top:4px">${l?(l.by==='c'?'You: ':'')+esc(prevTxt(l)):'No messages yet'}</p></div><div style="display:grid;gap:5px;justify-items:end"><small style="color:var(--dim);font-size:11px;font-weight:700">${l?ago(l.ts):''}</small>${u?`<span class="badge">${u}</span>`:''}</div></button>`}).join('')||'<div class="empty">No private conversations yet</div>'}</div>`;
}
V.coach_inbox=()=>{ ui.ci??='private'; return `<div class="ph"><small>Private parent conversations and group chats</small><h1>Inbox</h1></div><div class="segc inbox-switch"><button class="${ui.ci==='private'?'on':''}" onclick="ui.ci='private';paint(true)">Private inbox ${coachUnread()?`<b>${coachUnread()}</b>`:''}</button><button class="${ui.ci==='groups'?'on':''}" onclick="ui.ci='groups';paint(true)">Group messages ${groupsUnread()?`<b>${groupsUnread()}</b>`:''}</button></div>${ui.ci==='groups'?groupsView(true):coachPrivateInbox()}`; };
V.coach_private=()=>{ const t=S.threads.find(x=>x.id===ui.th); if(!t){ view='inbox'; ui.ci='private'; return V.coach_inbox(); }
  const unreadAt=t.cu||0; if(unreadAt){ t.cu=0; save(); setTimeout(tabs,30); }
  return `<div class="chat-shell private-chat-screen">
  <div class="chathead modern"><button class="back" onclick="go('inbox')" aria-label="Back to Inbox">‹</button>${avHTML(t.name,(S.users.find(u=>u.id===t.fam)||{}).photo,'background:linear-gradient(145deg,#5aa8ff,#2453a8);color:#fff')}<div class="grow"><b style="font-family:var(--disp);font-size:20px;text-transform:uppercase">${esc(t.name)}</b><div class="status">● Parent · ${esc(t.kid||'private chat')}</div></div><div class="chat-toolbar"><button class="iconbtn" onclick="familySheet('${t.fam}')" aria-label="Parent details" title="Parent details">ⓘ</button><button class="iconbtn" onclick="deletePrivateThread('${t.id}')" aria-label="Delete private conversation" title="Delete private conversation">🗑</button></div></div>
  ${chatHTML(t,'c',unreadAt)}
  <div class="chat-quick">${['On my way 👍','Training is still on ✅','No problem, get well soon!','Trainers are fine 👟'].map(q=>`<button onclick="$('#cIn2').value=this.textContent;$('#cIn2').focus()">${esc(q)}</button>`).join('')}</div>
  <div class="chat-composer">${attBtn('tc|'+t.id)}${voiceBtn('tc|'+t.id)}<input id="cIn2" data-draft-key="${me.id}|t${t.id}" value="${esc(draftValue('t',t.id))}" placeholder="Reply to ${esc(t.name)}…" onkeydown="if(event.key==='Enter'&&!event.shiftKey&&!event.isComposing&&event.keyCode!==229&&!event.repeat){event.preventDefault();coachReply('${t.id}')}" autocomplete="off"><button class="send" onclick="coachReply('${t.id}')" aria-label="Send">↑</button></div></div>`;
};
V.parent_group=V.coach_group=()=>{ const g=S.groups.find(x=>x.id===ui.grp); if(!g) return groupsView();
  g.read??={}; const readAt=g.read[me.id]||0; if(readAt<g.msgs.length){ g.read[me.id]=g.msgs.length; save(); setTimeout(tabs,30); }
  return `<div class="chat-shell group-chat-screen">
  <div class="chathead modern"><button class="back" onclick="go(${me.role==='coach'?'\'inbox\'':'\'groups\''})" aria-label="Back">‹</button><div class="grow"><b style="font-family:var(--disp);font-size:20px;text-transform:uppercase">${g.icon} ${esc(g.name)}</b><div class="status">● ${g.coaches?groupMembers(g)+' coach'+(groupMembers(g)===1?'':'es'):groupMembers(g)+' members'}${g.ro?' · announcements':''}</div></div>${me.role==='coach'?`<div class="chat-toolbar"><button class="iconbtn" onclick="editGroup('${g.id}')" aria-label="Group settings">⚙</button></div>`:''}</div>
  ${groupChatHTML(g,me.id,readAt)}${me.role==='coach'?`<div class="chat-quick">${['Training is ON tonight ✅','Training cancelled tonight ❌','Great session today 👏','Reminder: bring water & shin pads'].map(q=>`<button onclick="$('#gIn').value=this.textContent;$('#gIn').focus()">${q}</button>`).join('')}</div>`:''}
  ${g.ro&&me.role!=='coach'?'<p class="ro" style="margin:8px 14px">📣 Announcements only. Coaches post here.</p>':`<div class="chat-composer">${attBtn('g|'+g.id)}${voiceBtn('g|'+g.id)}<input id="gIn" data-draft-key="${me.id}|g${g.id}" value="${esc(draftValue('g',g.id))}" placeholder="Message ${esc(g.name)}…" onkeydown="if(event.key==='Enter'&&!event.shiftKey&&!event.isComposing&&event.keyCode!==229&&!event.repeat){event.preventDefault();sendGroup('${g.id}','gIn')}"><button class="send" onclick="sendGroup('${g.id}','gIn')" aria-label="Send">↑</button></div>`}</div>`; };
function newGroup(){ ui.ng={teams:[]}; openSheet(`<div class="shb"><h3>New group chat</h3><p class="hint">For a weekly session, a squad, a tournament, anything. Parents and guardians of players in the squads you pick are added automatically.</p>
   <label class="field"><span>Group name</span><input id="ngN" placeholder="e.g. Wednesday Shooting Session"></label>
   <div class="lab">Icon</div><div class="chips" id="ngI">${['⚽','🎯','🏆','🧤','🌟','🔥','🏃','📣'].map((e,i)=>`<button class="chip ${i===0?'on':''}" onclick="$$('#ngI .chip').forEach(c=>c.classList.remove('on'));this.classList.add('on')">${e}</button>`).join('')}</div>
   <div class="lab">Who's in it?</div><div class="chips" id="ngT"><button class="chip" data-t="*" onclick="this.classList.toggle('on')">Whole club</button>${TK.map(t=>`<button class="chip" data-t="${t}" onclick="this.classList.toggle('on')">${TEAMS[t].name}</button>`).join('')}</div>
   <div style="display:flex;align-items:center;gap:12px;margin:16px 0 0"><span style="flex:1;font-size:14px;font-weight:700">📣 Announcements only (just coaches post)</span><button class="tog" id="ngR" onclick="this.classList.toggle('on')"></button></div><button class="btn full big" style="margin-top:18px" onclick="saveGroup()">Create group</button></div>`); }
function saveGroup(){ const n=$('#ngN').value.trim(); if(!n) return toast('Name the group'); const teams=$$('#ngT .chip.on').map(c=>c.dataset.t); if(!teams.length) return toast('Pick at least one squad');
  const all=teams.includes('*'), ro=$('#ngR').classList.contains('on');
  const g={id:uid('g_'),name:n,icon:$('#ngI .chip.on').textContent,...(all?{all:true}:{teams}),...(ro?{ro:true}:{}),read:{},msgs:[{by:'coach',uid:me.id,name:'Coach '+me.first,t:ro?`Welcome to ${n}! 👋 Updates will be posted here.`:`Welcome to ${n}! 👋 I'll post updates here and you can chat with the other parents.`,ts:Date.now()}]};
  g.read[me.id]=1; S.groups.push(g); log('👥',`New group chat: ${n}`); save(); closeSheet(); toast(`${n} created · ${groupMembers(g)} players’ parents added ✓`); ui.grp=g.id; go('group'); }
function sendGroup(gid,inp){ const i=$('#'+inp), t=i.value.trim(); if(!t) return; i.value=''; postGroup(gid,t); }
function postGroup(gid,t,img,audio,dur,media=null){ const g=S.groups.find(x=>x.id===gid); if(!g)return; const x={...(img?{img}:{}),...(audio?{audio,dur}:{})};
  const sender=media?.sender||{id:me.id,role:me.role,first:me.first,kidName:kids()[0]?.name||''}; g.msgs.push(sender.role==='coach'?{by:'coach',uid:sender.id,name:'Coach '+sender.first,t,ts:Date.now(),...x}:{by:'p',uid:sender.id,name:`${sender.first} (${sender.kidName})`,t,ts:Date.now(),...x});
  (g.read??={})[sender.id]=g.msgs.length; log('💬',`${sender.role==='coach'?'You':sender.first} in ${g.name}: "${(img?'📷 ':'')+t.slice(0,50)}"`); save();
  if(!media?.quiet){buzz(15);paint(true);scrollChatToEnd(true);} }
