/* ---------- payments ---------- */
function payBtn(lid){ const l=S.links.find(x=>x.id===lid); return l?`<button class="btn sm" style="margin-top:8px;display:flex" onclick="payLink('${lid}')">Pay ${money(l.amount)} with PayPal · ${esc(l.title)}</button>`:''; }
function payLink(lid){ const l=S.links.find(x=>x.id===lid); checkout({title:l.title,lines:[[l.title,l.amount]],onPaid:()=>{ log('💷',`${me.first} paid ${money(l.amount)} · ${l.title}`); }}); }
function checkout({title,lines,onPaid}){
  const total=lines.reduce((a,[,v])=>a+v,0); ui.co={onPaid,title,total};
  openSheet(`<div class="shb" id="coBox"><small style="color:var(--g);font-weight:800;letter-spacing:.16em;font-size:11px">CHECKOUT · AG COACHING FC</small><h3 style="margin-top:6px">${esc(title)}</h3>
   <div class="kv">${lines.map(([l,v])=>`<div><i>•</i>${esc(l)}<b>${money(v)}</b></div>`).join('')}<div style="background:rgba(63,243,106,.12)"><i>💷</i><b style="margin-left:0">Total</b><b>${money(total)}</b></div></div>
   ${ppUrl(total)?`<a class="ppbtn" href="${ppUrl(total)}" target="_blank" rel="noopener" onclick="ppOpened()"><span class="pp1">Pay</span><span class="pp2">Pal</span></a><p class="hint" style="text-align:center;margin:10px 0 14px">Pay securely by PayPal or card.</p>`:`<p class="hint" style="text-align:center;margin:8px 0 14px">Online PayPal payments aren't currently available.</p>`}<div class="card" style="margin:0;text-align:center"><b>Prefer to pay Alfie directly?</b><p class="hint" style="margin:6px 0 12px">Book now and pay Alfie separately. This will be marked as awaiting payment confirmation, not paid.</p><button class="btn full" onclick="ppDone(true)">Pay Alfie direct</button></div></div>
   <div class="shb hide" id="coWait" style="text-align:center;padding-top:20px"><div class="ppmark"><span class="pp1">P</span></div><h3 style="margin-top:16px">Finish paying in PayPal</h3><p class="hint">PayPal has opened in a new tab. Once you've paid, come back here.</p>
   <button class="btn full big" onclick="ppDone()">✓ I've paid ${money(total)}</button><a class="btn gh full" style="margin-top:10px" href="${ppUrl(total)||'#'}" target="_blank" rel="noopener">Open PayPal again</a>
   <p class="hint" style="margin-top:10px">Alfie checks every payment against his PayPal account.</p></div>
   <div class="shb ok hide" id="coOk"><div class="tk"><svg viewBox="0 0 24 24"><path d="M5 12.5l4.5 4.5L19 7.5"/></svg></div><h3 style="margin-top:20px" id="coOkT">Paid. You're all set!</h3><p class="hint" id="coOkP">PayPal sends your receipt by email. Alfie can see it in his payments.</p><button class="btn full" onclick="closeSheet();paint(true)">Done</button></div>`);
}
function ppOpened(){ setTimeout(()=>{ $('#coBox')?.classList.add('hide'); $('#coWait')?.classList.remove('hide'); },300); }
function ppDone(direct){ const c=ui.co; S.payments.unshift({id:uid('pay'),who:me.name,uid:me.id,what:c.title,amount:c.total,ts:Date.now(),via:direct?'Pay Alfie direct · awaiting confirmation':'PayPal',status:direct?'pending':'reported'}); c.onPaid&&c.onPaid(); save();
  $('#coBox').classList.add('hide'); $('#coWait').classList.add('hide'); $('#coOk').classList.remove('hide'); if(direct){ $('#coOkT').textContent="Booking recorded"; $('#coOkP').textContent=`Your booking is reserved, but payment is still outstanding. Please arrange payment of ${money(c.total)} directly with Alfie.`; } confetti(); buzz([30,40,80]); }


/* ---------- calendar ---------- */
function calItems(from,to,forParent){
  const ts=forParent?new Set(kids().map(p=>p.team)):null, out=[];
  occ(new Date(from),Math.ceil((to-from)/864e5)+1,s=>!ts||s.teams.some(t=>ts.has(t))).forEach(o=>{ if(o.at>=from&&o.at<to) out.push({type:'s',at:+o.at,o}); });
  S.fixtures.filter(f=>(!ts||ts.has(f.team))&&f.at>=from&&f.at<to).forEach(f=>out.push({type:'f',at:f.at,f}));
  S.events.filter(e=>e.at>=from&&e.at<to).forEach(e=>out.push({type:'e',at:e.at,e}));
  S.camps.forEach(c=>c.days.forEach((d,i)=>{ if(d>=from&&d<to){ const [h,m]=c.start.split(':'); const at=new Date(d); at.setHours(+h,+m); out.push({type:'c',at:+at,c,i}); } }));
  S.slots.filter(s=>s.booked&&(!forParent||s.booked.uid===me.id)&&s.at>=from&&s.at<to).forEach(s=>out.push({type:'o',at:s.at,s}));
  return out.sort((a,b)=>a.at-b.at);
}
const TC={s:'#3ff36a',f:'#c4ff4d',e:'#ffc93c',c:'#5aa8ff',o:'#c77dff'};
function calendarView(forParent){
  ui.cm??=0; const base=new Date(); const m0=new Date(base.getFullYear(),base.getMonth()+ui.cm,1), m1=new Date(m0.getFullYear(),m0.getMonth()+1,1);
  const items=calItems(+m0,+m1,forParent), by={}; items.forEach(x=>(by[ymd(new Date(x.at))]??=[]).push(x));
  ui.cd??=ymd(base); const lead=(m0.getDay()+6)%7, n=new Date(m0.getFullYear(),m0.getMonth()+1,0).getDate(), td=ymd(base);
  let cells=''; for(let i=0;i<lead;i++) cells+='<div></div>';
  for(let d=1;d<=n;d++){ const k=ymd(new Date(m0.getFullYear(),m0.getMonth(),d)), its=by[k]||[], types=[...new Set(its.map(x=>x.type))];
    cells+=`<button class="cday ${k===ui.cd?'sel':''} ${k===td?'today':''}" onclick="ui.cd='${k}';paint(true)"><span>${d}</span><i>${types.map(t=>`<b style="background:${TC[t]}"></b>`).join('')}</i></button>`; }
  const day=calItems(+new Date(ui.cd+'T00:00'),+new Date(ui.cd+'T23:59'),forParent);
  return `<div class="cal card" style="margin-top:12px"><div class="calh"><button class="ib" style="width:38px;height:38px" onclick="ui.cm--;paint(true)">‹</button><b>${['January','February','March','April','May','June','July','August','September','October','November','December'][m0.getMonth()]} ${m0.getFullYear()}</b><button class="ib" style="width:38px;height:38px" onclick="ui.cm++;paint(true)">›</button></div>
   <div class="cgrid7">${['M','T','W','T','F','S','S'].map(x=>`<small>${x}</small>`).join('')}${cells}</div>
   <div class="legend">${[['s','Training'],['f','Match'],['e','Event'],['c','Camp'],['o','1-1']].map(([k,l])=>`<span><b style="background:${TC[k]}"></b>${l}</span>`).join('')}</div></div>
  <h2 class="sec">${ui.cd===td?'Today':fmtL(new Date(ui.cd+'T12:00'))}</h2><div class="list">${day.map(x=>calRow(x,forParent)).join('')||'<div class="empty">Nothing on this day</div>'}</div>`;
}
function calRow(x,fp){ const h=calRow0(x,fp); if(!h||!me?.cal) return h; let k='';
  if(x.type==='s') k=`s|${x.o.s.id}|${ymd(x.o.at)}`; else if(x.type==='f') k=`f|${x.f.id}`; else if(x.type==='e') k=`e|${x.e.id}`; else if(x.type==='o') k=`o|${x.s.id}`;
  else if(x.type==='c'&&(!fp||S.campBk.some(b=>b.camp===x.c.id&&b.uid===me.id&&b.days.includes(x.i)))) k=`c|${x.c.id}|${x.i}`;
  if(!k||(x.type==='s'&&x.o.cx)) return h; return h.slice(0,-6)+`<button class="ib calsv" aria-label="Add to my calendar" title="Add to my calendar" onclick="saveEv('${k}')">📅</button></div>`; }
function calRow0(x,fp){
  const k=fp?kids()[kidIdx]||kids()[0]:null, bar=c=>`<span class="ic" style="background:${c}22;color:${c};font-family:var(--disp);font-weight:900;font-size:15px">${hm(new Date(x.at))}</span>`;
  if(x.type==='s'){ const o=x.o, r=k?(S.rsvp[o.key]||{})[k.id]:undefined; const going=Object.values(S.rsvp[o.key]||{}).filter(Boolean).length;
    return `<div class="row" style="${o.cx?'opacity:.7':''}">${bar(TC.s)}<div class="grow"><b style="${o.cx?'text-decoration:line-through;text-decoration-color:var(--red)':''}">${esc(o.s.title)}</b><p>${o.s.start}–${o.s.end} · ${esc(o.s.place)}${o.cx?' · <span style="color:#ff9d9d">Cancelled</span>':fp?'':` · 🙋 ${going} coming`}</p>
      ${fp&&!o.cx?`<div class="duo" style="margin-top:8px"><button class="seg yes ${r===true?'on':''}" style="padding:9px" onclick="setRsvp('${o.key}','${k.id}',true)">✅ ${esc(k.name)} coming</button><button class="seg no ${r===false?'on':''}" style="padding:9px" onclick="setRsvp('${o.key}','${k.id}',false)">Can't</button></div>`:''}</div></div>`; }
  if(x.type==='f'){ const f=x.f, v=k?f.avail[k.id]:undefined, av=Object.values(f.avail).filter(Boolean).length;
    return `<div class="row">${bar(TC.f)}<div class="grow"><b>${TEAMS[f.team].short} vs ${esc(f.opp)}</b><p>${f.home?'Home':'Away'}${f.venue?.name?` at ${esc(f.venue.name)}`:''} · ${f.meet?`Meet ${f.meet} · `:''}KO ${hm(new Date(f.at))}${fp?'':` · 🙋 ${av} available`}</p>
      ${fp&&k&&k.team===f.team&&f.status==='up'?`<div class="duo" style="margin-top:8px"><button class="seg yes ${v===true?'on':''}" style="padding:9px" onclick="setAvail('${f.id}','${k.id}',true)">✅ Can play</button><button class="seg no ${v===false?'on':''}" style="padding:9px" onclick="setAvail('${f.id}','${k.id}',false)">Can't</button></div>`:''}</div></div>`; }
  if(x.type==='e'){ const e=x.e, r=e.rsvp[me.id], yes=Object.values(e.rsvp).filter(Boolean).length;
    return `<div class="row">${bar(TC.e)}<div class="grow"><b>${e.icon} ${esc(e.title)}</b><p>${esc(e.place)} · ${yes} going${e.price?` · ${money(e.price)} a ticket`:''}</p>
      ${fp?`<div class="duo" style="margin-top:8px"><button class="seg yes ${r===true?'on':''}" style="padding:9px" onclick="rsvpEvent('${e.id}',true)">${r===true?'✅ Going':e.price?`🎟️ Going · ${money(e.price)}`:'✅ We\'re going'}</button><button class="seg no ${r===false?'on':''}" style="padding:9px" onclick="rsvpEvent('${e.id}',false)">Can't</button></div>`:`<button class="chip" style="margin-top:8px" onclick="eventSheet('${e.id}')">See who's going →</button>`}</div></div>`; }
  if(x.type==='c'){ const c=x.c, mine=fp?S.campBk.filter(b=>b.camp===c.id&&b.uid===me.id&&b.days.includes(x.i)):[], cnt=c.taken[x.i]+S.campBk.filter(b=>b.camp===c.id&&b.days.includes(x.i)).length;
    return `<div class="row">${bar(TC.c)}<div class="grow"><b>${c.icon} ${esc(c.name)} · Day ${x.i+1}</b><p>${c.start}–${c.end} · ${cnt}/${c.cap} booked</p>${mine.length?`<span class="chip hot" style="margin-top:6px;display:inline-block">✓ ${mine.map(b=>esc(b.child)).join(' & ')} booked</span>`:fp?`<button class="chip" style="margin-top:8px" onclick="campSheet('${c.id}')">Book a place →</button>`:`<button class="chip" style="margin-top:8px" onclick="campDay('${c.id}',${x.i})">Register →</button>`}</div></div>`; }
  if(x.type==='o'){ const s=x.s; return `<div class="row">${bar(TC.o)}<div class="grow"><b>1-1 session · ${esc(s.booked.name)}</b><p>${s.len} mins with Coach Alfie · ${money(s.price)}</p></div></div>`; }
}
V.parent_calendar=()=>`<div class="ph"><small>Training, matches, events &amp; camps</small><h1>Calendar</h1></div>${kids().length>1?`<div class="kids">${kids().map((c,i)=>`<button class="kid-pill ${i===kidIdx?'on':''}" onclick="kidIdx=${i};paint(true)"><i>${c.num}</i>${esc(c.name)}</button>`).join('')}</div>`:''}${calendarView(true)}`;
V.coach_calendar=()=>`<div class="ph"><button class="chip" onclick="go('home')" style="margin-bottom:10px">← Today</button><small style="display:block">Whole club</small><h1>Club calendar</h1></div>${calendarView(false)}<div class="toolrow"><button class="btn" onclick="newEvent()">＋ Add club event</button></div>`;
function rsvpEvent(id,v){ const e=S.events.find(x=>x.id===id);
  if(v&&e.price&&e.rsvp[me.id]!==true){ const n=kids().length+1; return checkout({title:`${e.title} tickets`,lines:[[`${e.title} · ticket ×${n}`,e.price*n]],onPaid:()=>{ const e2=S.events.find(x=>x.id===id)||e; e2.rsvp[me.id]=true; log('🎟️',`${me.first} bought ${n} tickets · ${e.title}`); }}); }
  e.rsvp[me.id]=v; log(v?'🎉':'🙅',`${me.first} ${v?'is going to':"can't make"} ${e.title}`); save(); buzz(); toast(v?'See you there 🎉':'Thanks for letting Alfie know'); paint(true); }
function eventSheet(id){ const e=S.events.find(x=>x.id===id), yes=Object.entries(e.rsvp).filter(([,v])=>v).length, no=Object.values(e.rsvp).filter(v=>v===false).length;
  openSheet(`<div class="shb"><h3>${e.icon} ${esc(e.title)}</h3><p class="hint">${fmtL(e.at)} · ${hm(new Date(e.at))} · ${esc(e.place)}</p><p style="font-size:14px;line-height:1.5;color:#d2e6d6">${esc(e.desc)}</p>
   <div class="kpis" style="padding:14px 0 0"><div class="kpi hl"><small>Going</small><b>${yes}</b><em>parents</em></div><div class="kpi"><small>Can't make it</small><b>${no}</b><em>parents</em></div></div>
   ${e.price?`<div class="kv"><div><i>🎟️</i>Ticket price<b>${money(e.price)}</b></div><div><i>💷</i>If everyone going pays<b>${money(yes*e.price)}</b></div></div>`:''}
   <button class="btn full" style="margin-top:12px" onclick="tell(TK,'${e.icon} Reminder: ${esc(e.title).replace(/'/g,'')} on ${fmtL(e.at)}. Please RSVP in the app!');log('📣','Event reminder sent');save();closeSheet();toast('Reminder sent to every parent ✓')">📣 Remind everyone to RSVP</button></div>`); }



/* ---------- camps ---------- */
const campPrice=(c,n)=>c.tiers?(c.tiers[n-1]??c.tiers.at(-1)):(n===c.days.length?c.week:n*c.price);
const campCount=(c,i)=>(c.taken?.[i]||0)+S.campBk.filter(b=>b.camp===c.id&&b.days.includes(i)).length;
function campCard(c,fp){ const tot=c.days.reduce((a,_,i)=>a+campCount(c,i),0), mine=fp?S.campBk.filter(b=>b.camp===c.id&&b.uid===me.id):[];
  return `<div class="campc" onclick="${fp?`campSheet('${c.id}')`:`campAdmin('${c.id}')`}"><div class="camph"><span>${c.icon}</span><div><b>${esc(c.name)}</b><p>${fmtD(new Date(c.days[0]))} – ${fmtD(new Date(c.days.at(-1)))} · ${c.start}–${c.end} · ${esc(c.ages)}</p></div></div>
   <div class="campdays">${c.days.map((d,i)=>{const n=campCount(c,i);return `<div><small>${DAYS[new Date(d).getDay()]} ${new Date(d).getDate()}</small><div class="bar"><i style="width:${n/c.cap*100}%;${n>=c.cap?'background:var(--red)':''}"></i></div><em>${n>=c.cap?'FULL':c.cap-n+' left'}</em></div>`}).join('')}</div>
   <div class="campf"><span>${money(campPrice(c,1))} a day · ${money(campPrice(c,c.days.length))} all ${c.days.length} days</span>${fp?(mine.length?`<span class="chip hot">✓ Booked</span>`:`<span class="btn sm">Book →</span>`):`<span class="chip hot">${tot} places booked</span>`}</div></div>`; }
function campSheet(id){ const c=S.camps.find(x=>x.id===id), ks=kids(); ui.cb??={}; if(!ks.length) return toast('No children linked yet'); ui.cb={camp:id,kids:ui.cb.camp===id?ui.cb.kids:[ks[0].id],days:ui.cb.camp===id?ui.cb.days:[]};
  const price=()=>{ const n=ui.cb.days.length; return n?campPrice(c,n)*ui.cb.kids.length:0; };
  openSheet(`<div class="shb"><h3>${c.icon} ${esc(c.name)}</h3><p class="hint">${esc(c.info)}</p>
   <div class="lab">Who's coming?</div><div class="chips">${ks.map(k=>`<button class="chip ${ui.cb.kids.includes(k.id)?'on':''}" onclick="ui.cb.kids=ui.cb.kids.includes('${k.id}')?ui.cb.kids.filter(x=>x!=='${k.id}'):[...ui.cb.kids,'${k.id}'];campSheet('${id}')">${esc(k.name)}</button>`).join('')}</div>
   <div class="lab">Pick your days</div><div class="g3">${c.days.map((d,i)=>{const n=campCount(c,i),full=n>=c.cap;return `<button class="opt ${ui.cb.days.includes(i)?'on':''}" ${full?'disabled style="opacity:.4"':''} onclick="ui.cb.days=ui.cb.days.includes(${i})?ui.cb.days.filter(x=>x!==${i}):[...ui.cb.days,${i}].sort();campSheet('${id}')">${DAYS[new Date(d).getDay()]} ${new Date(d).getDate()}<small>${full?'Full · waiting list':c.cap-n+' places left'}</small></button>`}).join('')}</div>
   <button class="chip" style="margin-top:10px" onclick="ui.cb.days=[${c.days.map((_,i)=>i).join(',')}];campSheet('${id}')">All ${c.days.length} days · ${money(campPrice(c,c.days.length))}${c.days.length*campPrice(c,1)>campPrice(c,c.days.length)?' · save '+money(c.days.length*campPrice(c,1)-campPrice(c,c.days.length)):''}</button>
   <div class="kv" style="margin-top:16px"><div><i>👟</i>${esc(c.place)} · ${c.start}–${c.end}<b></b></div><div style="background:rgba(63,243,106,.12)"><i>💷</i>Total<b>${money(price())}</b></div></div>
   <button class="btn full big" onclick="bookCamp()" ${ui.cb.days.length&&ui.cb.kids.length?'':'disabled'}>Book &amp; pay ${money(price())}</button></div>`); }
function bookCamp(){ const c=S.camps.find(x=>x.id===ui.cb.camp), sel={...ui.cb}, n=sel.days.length, per=campPrice(c,n);
  checkout({title:c.name,lines:sel.kids.map(k=>[`${P(k).name} · ${n===c.days.length?'all '+n+' days':n+' day'+(n>1?'s':'')}`,per]),onPaid:()=>{
    sel.kids.forEach(k=>S.campBk.push({id:uid('cb'),camp:c.id,uid:me.id,pid:k,child:P(k).name,days:sel.days,ts:Date.now()}));
    log('☃️',`${me.first} booked ${sel.kids.map(k=>P(k).name).join(' & ')} on ${c.name} (${n} day${n>1?'s':''})`);
    setTimeout(()=>push(c.name,`You're booked in! You've been added to the ${c.name} group chat.`),1600); }}); }
function campAdmin(id){ const c=S.camps.find(x=>x.id===id);
  openSheet(`<div class="shb"><h3>${c.icon} ${esc(c.name)}</h3><p class="hint">${fmtD(new Date(c.days[0]))} – ${fmtD(new Date(c.days.at(-1)))} · cap ${c.cap} a day</p>
   <div class="list" style="margin:0">${c.days.map((d,i)=>`<button class="row" onclick="campDay('${id}',${i})"><span class="ic" style="font-family:var(--disp);font-weight:900;font-size:14px;line-height:1.1">${DAYS[new Date(d).getDay()].toUpperCase()}<br>${new Date(d).getDate()}</span><div class="grow"><b>Day ${i+1}</b><div class="bar" style="margin-top:6px"><i style="width:${campCount(c,i)/c.cap*100}%"></i></div></div><b style="font-family:var(--disp);font-size:20px">${campCount(c,i)}/${c.cap}</b></button>`).join('')}</div>
   <div class="toolrow" style="padding:12px 0 0"><button class="btn gh" onclick="openGroup('g_${c.id}')">💬 Camp group chat</button><button class="btn gh" onclick="tell(TK,'${c.icon} ${esc(c.name).replace(/'/g,'')} is now booking! Places go fast, book in the app.');save();toast('Sent to every parent ✓')">📣 Promote</button></div></div>`); }
function campDay(id,i){ const c=S.camps.find(x=>x.id===id), bk=S.campBk.filter(b=>b.camp===id&&b.days.includes(i));
  const fake=[];
  openSheet(`<div class="shb"><h3>Day ${i+1} · ${fmtD(new Date(c.days[i]))}</h3><p class="hint">${campCount(c,i)} booked · ⚕️ = medical info, tap to view</p>
   <div class="chips">${bk.map(b=>`<button class="chip hot" onclick="childInfo('${b.pid}')">${esc(b.child)}${medFlag(P(b.pid))}</button>`).join('')||'<span class="hint">No bookings yet</span>'}${fake.map(n=>`<span class="chip">${n}</span>`).join('')}</div>
   <button class="btn full" style="margin-top:16px" onclick="closeSheet()">Done</button></div>`); }
function childInfo(pid){ const p=P(pid), i=p.info||{};
  openSheet(`<div class="shb"><h3>${esc(p.name)}</h3><p class="hint">${TEAMS[p.team].name} · visible to coaches only</p><div class="kv"><div><i>⚕️</i>Medical / allergies<b style="max-width:55%;text-align:right">${esc(i.med||'None given')}</b></div><div><i>📞</i>Emergency<b style="max-width:55%;text-align:right">${esc(i.emer||'—')}</b></div><div><i>📸</i>Photo consent<b style="color:${i.photo?'var(--g)':'var(--red)'}">${i.photo?'Yes':'NO PHOTOS'}</b></div></div></div>`); }



/* ---------- 1-1s ---------- */
function slotsByDay(fp){ const now=Date.now(), by={}; S.slots.filter(s=>s.at>now).sort((a,b)=>a.at-b.at).forEach(s=>(by[ymd(new Date(s.at))]??=[]).push(s)); return by; }
function oneToOneParent(){ const by=slotsByDay(true);
  return `<div class="card"><p class="hint" style="margin:0 0 12px">${S.club?.oneLen||45}-minute 1-1 coaching with Alfie · ${money(S.club?.onePrice||30)} · pick a free slot</p>${Object.entries(by).slice(0,6).map(([d,ss])=>`<div class="lab" style="margin:10px 0 6px">${fmtL(new Date(d+'T12:00'))}</div><div class="chips">${ss.map(s=>s.booked?`<span class="chip" style="opacity:.4;text-decoration:line-through">${hm(new Date(s.at))}</span>`:`<button class="chip hot" onclick="bookSlot('${s.id}')">${hm(new Date(s.at))}</button>`).join('')}</div>`).join('')||'<div class="empty">No slots open right now</div>'}</div>`; }
function bookSlot(id){ const s=S.slots.find(x=>x.id===id), k=kids()[kidIdx]||kids()[0]; if(!k) return toast('No children linked yet'); if(s.booked) return toast('Sorry, that slot has just gone');
  checkout({title:'1-1 session with Coach Alfie',lines:[[`${k.name} · ${fmtD(new Date(s.at))} ${hm(new Date(s.at))} · ${s.len} mins`,s.price]],onPaid:()=>{ const s2=S.slots.find(x=>x.id===id)||s; s2.booked={name:k.name,uid:me.id,pid:k.id}; log('🎯',`${me.first} booked a 1-1 for ${k.name}, ${fmtD(new Date(s.at))} ${hm(new Date(s.at))}`);
    myThread()?.msgs.push({by:'c',t:`Looking forward to ${k.name}'s 1-1 on ${fmtD(new Date(s.at))} at ${hm(new Date(s.at))} 👊 (automatic confirmation)`,ts:Date.now()}); }}); }
function oneToOneCoach(){ const by=slotsByDay(false), booked=S.slots.filter(s=>s.booked&&s.at>Date.now()).length, open=S.slots.filter(s=>!s.booked&&s.at>Date.now()).length;
  return `<div class="kpis" style="padding:12px 14px 0"><div class="kpi hl"><small>Booked</small><b>${booked}</b><em>${money(S.slots.filter(s=>s.booked&&s.at>Date.now()).reduce((a,s)=>a+s.price,0))} coming in</em></div><div class="kpi"><small>Open slots</small><b>${open}</b><em>parents can book</em></div></div>
  <div class="toolrow"><button class="btn" onclick="addSlots()">＋ Add availability</button></div>
  <div class="card" style="margin-top:12px">${Object.entries(by).map(([d,ss])=>`<div class="lab" style="margin:10px 0 6px">${fmtL(new Date(d+'T12:00'))}</div><div class="chips">${ss.map(s=>s.booked?`<button class="chip on" onclick="slotSheet('${s.id}')">${hm(new Date(s.at))} · ${esc(s.booked.name)}</button>`:`<button class="chip" onclick="removeSlot('${s.id}')">${hm(new Date(s.at))} · open ×</button>`).join('')}</div>`).join('')||'<div class="empty">No slots yet</div>'}</div>
  <p class="hint" style="text-align:center;margin-top:10px">Tap an open slot to remove it, or a booked one to cancel it. Parents book and pay in the app.</p>`; }
function removeSlot(id){ S.slots=S.slots.filter(s=>s.id!==id); save(); toast('Slot removed'); paint(true); }
function addSlots(){ const days=Array.from({length:14},(_,i)=>addDays(new Date(),i+1));
  openSheet(`<div class="shb"><h3>Add 1-1 availability</h3><p class="hint">Parents see these straight away and can book and pay.</p>
   <label class="field"><span>Day</span><select id="slD">${days.map(d=>`<option value="${ymd(d)}">${fmtL(+d)}</option>`).join('')}</select></label>
   <div class="g2"><label class="field"><span>Start time</span><input id="slT" type="time" value="16:00"></label><label class="field"><span>Back-to-back slots</span><select id="slN">${[1,2,3,4].map(n=>`<option ${n===3?'selected':''}>${n}</option>`).join('')}</select></label></div>
   <div class="g2"><label class="field"><span>Length</span><select id="slL">${[30,45,60].map(n=>`<option ${n===(S.club?.oneLen||45)?'selected':''}>${n}</option>`).join('')}</select></label><label class="field"><span>Price £</span><input id="slP" type="number" value="${S.club?.onePrice||30}"></label></div>
   <button class="btn full big" onclick="saveSlots()">Open slots</button></div>`); }
function saveSlots(){ const d=$('#slD').value, [h,m]=$('#slT').value.split(':').map(Number), N=+$('#slN').value, L=+$('#slL').value, pr=+$('#slP').value||S.club?.onePrice||30;
  for(let i=0;i<N;i++){ const at=new Date(d+'T00:00'); at.setHours(h,m+i*L,0,0); S.slots.push({id:uid('sl'),at:+at,len:L,price:pr,booked:null}); }
  log('🎯',`${N} new 1-1 slot${N>1?'s':''} opened (${d})`); save(); closeSheet(); toast(`${N} slot${N>1?'s':''} open for booking ✓`); paint(true); }

/* ---------- payments (coach) ---------- */
function paymentsCoach(){ const mk=new Date(); const month=S.payments.filter(p=>new Date(p.ts).getMonth()===mk.getMonth()&&p.via!=='To pay Alfie'), tot=month.reduce((a,p)=>a+p.amount,0), owed=S.payments.filter(p=>p.via==='To pay Alfie').reduce((a,p)=>a+p.amount,0);
  return `<div class="kpis" style="padding:12px 14px 0"><div class="kpi hl"><small>Taken this month</small><b>${money(tot)}</b><em>${month.length} via PayPal${owed?` · ${money(owed)} to collect`:''}</em></div><button class="kpi" onclick="clubSettings()"><small>Paid into</small><b style="font-size:26px;margin-top:14px">PayPal</b><em>${S.club?.paypal?esc(S.club.paypal):'Tap to add your PayPal.me'}</em></button></div>
  <h2 class="sec">Payment links <a onclick="newLink()">＋ New</a></h2><div class="list">${S.links.length?'':'<div class="row"><div class="grow"><p>No payment links. Tap ＋ New to make one.</p></div></div>'}${S.links.map(l=>`<div class="row"><span class="ic">🔗</span><div class="grow" onclick="editLink('${l.id}')" style="cursor:pointer"><b>${esc(l.title)} · ${money(l.amount)}</b><p>PayPal payment link · <span style="color:var(--g)">tap to edit or delete</span></p></div><div style="display:grid;gap:6px"><button class="btn sm" onclick="sendLink('${l.id}')">Send</button><button class="btn sm gh" onclick="ppUrl(${l.amount})?copy(ppUrl(${l.amount}),'PayPal link copied'):toast('Add your PayPal.me in Club settings first')">Copy</button></div></div>`).join('')}</div>
  <h2 class="sec">Recent payments</h2><div class="card" style="padding:6px 16px">${S.payments.length?'':'<div class="empty">No payments yet</div>'}${S.payments.slice(0,20).map(p=>`<div class="act"><i>💷</i><span><b>${esc(p.who)}</b> · ${esc(p.what)}${p.via&&p.via!=='PayPal'?' · <b style="color:var(--amber)">'+esc(p.via)+'</b>':''}</span><small style="color:var(--g);font-weight:800;font-size:13px">+${money(p.amount)}</small></div>`).join('')}</div>`; }
function copy(v,msg){ try{ navigator.clipboard.writeText(v).then(()=>toast(msg+' ✓'),()=>toast(v)); }catch(e){ toast(v); } }
function newLink(){ openSheet(`<div class="shb"><h3>New payment link</h3><p class="hint">For anything: kit, tournaments, trips. Share it in a chat or on Facebook. Parents pay through PayPal (account or card).</p>
   <label class="field"><span>What's it for?</span><input id="lkT" placeholder="e.g. Tournament entry"></label><label class="field"><span>Amount £</span><input id="lkA" type="number" value="10"></label>
   <button class="btn full big" onclick="saveLink()">Create link</button></div>`); }
function saveLink(){ const t=$('#lkT').value.trim(); if(!t) return toast('What is it for?'); S.links.unshift({id:uid('l_'),title:t,amount:+$('#lkA').value||10}); save(); closeSheet(); toast('Payment link created ✓'); paint(true); }
function sendLink(id){ const l=S.links.find(x=>x.id===id); S.messages.push({id:uid('m'),from:'coach',teams:TK,text:`💳 ${l.title}: ${money(l.amount)}. Tap below to pay in the app.`,link:id,ts:Date.now(),read:[]}); log('🔗',`Payment link sent: ${l.title}`); save(); toast('Sent to every parent ✓'); }

/* ---------- views: Bookings ---------- */
V.coach_bookings=()=>{ ui.bt??='camps';
  return `<div class="ph"><small>Camps · 1-1s · events · payments</small><h1>Bookings</h1></div>
  <div class="segc">${[['camps','🏕️ Camps'],['ones','🎯 1-1s'],['events','🎉 Events'],['pay','💷 Money']].map(([k,l])=>`<button class="${ui.bt===k?'on':''}" onclick="ui.bt='${k}';paint(true)">${l}</button>`).join('')}</div>
  ${ui.bt==='camps'?`<div style="display:grid;gap:12px;padding:12px 14px 0">${S.camps.map(c=>campCard(c,false)).join('')}</div><div class="toolrow"><button class="btn" onclick="newCamp()">＋ New camp</button></div>`:''}
  ${ui.bt==='ones'?oneToOneCoach():''}
  ${ui.bt==='events'?`<div class="list" style="margin-top:12px">${S.events.sort((a,b)=>a.at-b.at).map(e=>`<button class="row" onclick="eventSheet('${e.id}')"><span class="ic">${e.icon}</span><div class="grow"><b>${esc(e.title)}</b><p>${fmtL(e.at)} · ${hm(new Date(e.at))} · ${esc(e.place)}</p></div><span class="chip hot">${Object.values(e.rsvp).filter(Boolean).length} going</span></button>`).join('')}</div><div class="toolrow"><button class="btn" onclick="newEvent()">＋ New event</button><button class="btn gh" onclick="go('calendar')">📅 Calendar</button></div>`:''}
  ${ui.bt==='pay'?paymentsCoach():''}<div style="height:16px"></div>`; };
V.parent_bookings=()=>`<div class="ph"><small>Camps · 1-1s · tasters</small><h1>Book</h1></div>
  <h2 class="sec">Holiday camps</h2><div style="display:grid;gap:12px;padding:0 14px">${S.camps.filter(c=>c.days.at(-1)>Date.now()).map(c=>campCard(c,true)).join('')}</div>
  <h2 class="sec">1-1 coaching with Alfie</h2>${oneToOneParent()}
  <h2 class="sec">Bring a friend</h2><div class="card" style="background:linear-gradient(130deg,#163d22,#0a160d)"><b style="font-family:var(--disp);font-size:22px;text-transform:uppercase">Free taster session</b><p class="hint">For friends, siblings and classmates. All abilities welcome.</p><button class="btn sm" onclick="startBook()">Book a free taster →</button></div><div style="height:12px"></div>`;
function comingUp(){ const ev=S.events.filter(e=>e.at>Date.now()).sort((a,b)=>a.at-b.at).slice(0,2), cp=S.camps.find(c=>c.days.at(-1)>Date.now());
  return `<h2 class="sec">Coming up <a onclick="go('calendar')">Calendar</a></h2><div class="list">${ev.map(e=>{const d=new Date(e.at),mo=(d.getFullYear()-new Date().getFullYear())*12+d.getMonth()-new Date().getMonth();return `<button class="row" onclick="ui.cd='${ymd(d)}';ui.cm=${mo};go('calendar')"><span class="ic">${e.icon}</span><div class="grow"><b>${esc(e.title)}</b><p>${fmtL(e.at)} · ${hm(d)}${e.rsvp[me.id]===true?' · <span style="color:var(--g)">✓ You\'re going</span>':' · tap to RSVP'}</p></div></button>`}).join('')}</div>${cp?`<div style="padding:10px 14px 0">${campCard(cp,true)}</div>`:''}`; }

/* ---------- graphics ---------- */
async function canvasBase(W,H){ const c=document.createElement('canvas'); c.width=W;c.height=H; const x=c.getContext('2d');
  try{ await Promise.all(['italic 900 120px "Barlow Condensed"','900 200px "Barlow Condensed"','800 40px "Barlow Condensed"','600 34px Barlow','800 28px Barlow'].map(s=>document.fonts.load(s))); }catch(e){}
  const g=x.createLinearGradient(0,0,0,H); g.addColorStop(0,'#134a25'); g.addColorStop(.55,'#06120a'); g.addColorStop(1,'#010302'); x.fillStyle=g; x.fillRect(0,0,W,H);
  x.save(); x.globalAlpha=.07; x.fillStyle='#3ff36a'; for(let i=-H;i<W+H;i+=110){x.beginPath();x.moveTo(i,0);x.lineTo(i+55,0);x.lineTo(i+55-H*.47,H);x.lineTo(i-H*.47,H);x.fill();} x.restore();
  for(const cx of [W*.08,W*.92]){ const rg=x.createRadialGradient(cx,0,0,cx,0,620); rg.addColorStop(0,'rgba(196,255,77,.35)'); rg.addColorStop(1,'rgba(196,255,77,0)'); x.fillStyle=rg; x.fillRect(0,0,W,H); }
  const img=await new Promise(r=>{const i=new Image();i.onload=()=>r(i);i.src=BADGE;}); return {c,x,img}; }
const DF='"Barlow Condensed","Arial Narrow",sans-serif', BF='Barlow,Arial,sans-serif';

async function teamSheet(fid){ const f=F(fid), W=1080,H=1350, {c,x,img}=await canvasBase(W,H), slots=FMT[TEAMS[f.team].fmt];
  x.drawImage(img,60,50,150,150*img.height/img.width); x.textAlign='left'; x.fillStyle='#3ff36a'; x.font=`italic 900 84px ${DF}`; x.fillText('TEAM SHEET',240,120);
  x.fillStyle='#fff'; x.font=`800 40px ${DF}`; x.fillText(`AG ${TEAMS[f.team].short.toUpperCase()} v ${f.opp.toUpperCase()}`,240,170); x.fillStyle='#8ea292'; x.font=`600 28px ${BF}`; x.fillText(`${fmtD(new Date(f.at))} · ${f.meet?`Meet ${f.meet} · `:''}KO ${hm(new Date(f.at))} · ${f.venue?.name||(f.home?'Home':'Away')}`,240,212);
  const px=90,py=270,pw=900,ph=900; const pg=x.createLinearGradient(0,py,0,py+ph); pg.addColorStop(0,'#1d7334'); pg.addColorStop(1,'#145a28'); x.fillStyle=pg; x.beginPath(); roundedRect(x,px,py,pw,ph,36); x.fill();
  x.strokeStyle='rgba(255,255,255,.4)'; x.lineWidth=4; x.beginPath(); roundedRect(x,px+20,py+20,pw-40,ph-40,20); x.stroke(); x.beginPath(); x.moveTo(px+20,py+ph/2); x.lineTo(px+pw-20,py+ph/2); x.stroke(); x.beginPath(); x.arc(px+pw/2,py+ph/2,90,0,7); x.stroke();
  x.strokeRect(px+pw*.27,py+20,pw*.46,110); x.strokeRect(px+pw*.27,py+ph-130,pw*.46,110);
  x.textAlign='center'; slots.forEach(([pos,sx,sy],i)=>{ const p=P(f.lineup[i]); if(!p) return; const cx=px+pw*sx/100, cy=py+ph*sy/100;
    x.fillStyle='rgba(0,0,0,.35)'; x.beginPath(); x.arc(cx,cy+8,52,0,7); x.fill(); x.fillStyle=pos==='GK'?'#ffc93c':'#fff'; x.beginPath(); x.arc(cx,cy,50,0,7); x.fill(); x.lineWidth=6; x.strokeStyle='#3ff36a'; x.stroke();
    x.fillStyle='#062010'; x.font=`900 52px ${DF}`; x.fillText(p.num,cx,cy+18); x.fillStyle='rgba(0,0,0,.7)'; x.beginPath(); roundedRect(x,cx-80,cy+62,160,46,12); x.fill(); x.fillStyle='#fff'; x.font=`800 30px ${BF}`; x.fillText(p.name,cx,cy+95); });
  const bench=teamPlayers(f.team).filter(p=>f.avail[p.id]&&!Object.values(f.lineup).includes(p.id)).map(p=>p.name);
  x.fillStyle='#c4ff4d'; x.font=`800 30px ${BF}`; x.fillText('SUBS: '+(bench.join('  ·  ')||'none').toUpperCase(),W/2,1235); x.fillStyle='#8ea292'; x.font=`600 26px ${BF}`; x.fillText(`${f.meet?'Meet '+f.meet:'Meet 30 mins before KO'}${f.venue?.name&&f.venue.name!=='TBC'?' · '+f.venue.name:''} · Full kit · One club, one family`,W/2,1290);
  openSheet(`<div class="shb"><img class="resimg" src="${c.toDataURL('image/png')}" alt="Team sheet"><p class="hint" style="text-align:center;margin-top:12px">Press and hold to save, or send it to parents in the app.</p><button class="btn full" onclick="tell('${f.team}','📋 Team sheet for ${fmtD(new Date(f.at))} vs ${esc(f.opp).replace(/'/g,'')} is up! Meet 30 mins before KO.');log('📋','Team sheet sent');save();closeSheet();toast('Team sheet sent to parents ✓')">📣 Send to parents</button></div>`); }

/* ---------- accounts & login ---------- */
const initials=n=>String(n||'?').split(/\s+/).filter(Boolean).map(w=>w[0]).slice(0,2).join('').toUpperCase()||'?';
const RESET_TOK=(new URLSearchParams(location.search)).get('reset')||''; let authMode=RESET_TOK?'reset':'login', authMsg='', signupKids=[{name:'',team:''}], TEAMLIST=null, pendT=null;
async function startAuth(){
  try{ const j=await api('me'); setMe(j); }catch(e){ me=null; if(!navigator.onLine) authMsg='You’re offline. Reconnect to sign in and load club information.'; }
  if(RESET_TOK&&me){ /* already logged in on this phone: still let them set a new password */ me=null; }
  authReady=true; route();
}
function setMe(j){ me=j.user||null; JOIN=j.join||''; if(j.S){ REV=j.rev; adopt(j.S); } }
function route(){
  if(!introDone||!authReady) return; if($('#inst')?.classList.contains('on')) return;
  if(!me) return showLogin();
  if(me.status!=='approved') return showPending();
  if(!S) return api('me').then(j=>{ setMe(j); route(); }).catch(()=>showLogin('Can’t reach the club server. Try again in a moment.'));
  clearInterval(pendT); $('#login').classList.add('gone'); view='home'; kidIdx=0; paint();
  if(me.role==='coach'&&S.fixtures.some(f=>f.status==='live')) startClock();
  clearInterval(pollT); pollT=setInterval(poll,5000); setTimeout(showPill,9000); if(CHECKIN_TOKEN&&me.role==='parent') setTimeout(promptCheckin,500);
  setTimeout(showPhotoOnboarding,1100);
}
const val=id=>($('#'+id)?.value||'').trim();
async function loadTeams(){ if(TEAMLIST) return; try{ TEAMLIST=(await api('teams')).teams; }catch(e){ TEAMLIST=[]; } if(authMode==='join') showLogin(); }
function showLogin(msg){
  if($('#sheet').classList.contains('on'))closeSheet();
  blurWithin($('#login'));$('#login').classList.remove('gone');$('#login').scrollTop=0;if(msg!==undefined)authMsg=msg;
  const err=authMsg?`<div class="err">${esc(authMsg)}</div>`:'';
  const head=`<div class="lg-head stag"><img src="${BADGE}" alt=""><h1>AG Coaching FC</h1><p>${{login:'Log in to the club app',join:'Join the club app',coach:'Coach sign up',forgot:'Forgotten your password?',sent:'Link sent',reset:'Choose a new password'}[authMode]||''}</p></div>`;
  let body='';
  if(authMode==='login') body=`<div class="auth stag">
    <label class="field"><span>Email</span><input id="aE" type="email" autocomplete="email" inputmode="email"></label>
    <label class="field"><span>Password</span><input id="aP" type="password" autocomplete="current-password" onkeydown="if(event.key==='Enter'&&!event.isComposing&&event.keyCode!==229&&!event.repeat)doLogin()"></label>
    ${err}<button class="btn full big" id="aGo" onclick="doLogin()">Log in</button>
    <button class="lnk" onclick="authMode='join';showLogin('')">New to the app? Join the club here →</button>
    <button class="lnk" style="color:var(--mut);font-weight:600" onclick="authMode='forgot';showLogin('')">Forgotten your password?</button></div>`;
  if(authMode==='forgot') body=`<div class="auth stag"><p class="hint" style="margin:0 0 6px">Enter the email you joined with and we'll email you a link to choose a new password.</p>
    <label class="field"><span>Email</span><input id="fE" type="email" autocomplete="email" inputmode="email" value="${esc(val('aE')||val('fE'))}" onkeydown="if(event.key==='Enter'&&!event.isComposing&&event.keyCode!==229&&!event.repeat)doForgot()"></label>
    ${err}<button class="btn full big" id="aGo" onclick="doForgot()">Email me a link</button>
    <p class="hint" style="text-align:center;margin:0">No email after 5 minutes? Check your junk folder, or message Alfie.</p>
    <button class="lnk" onclick="authMode='login';showLogin('')">Back to log in</button></div>`;
  if(authMode==='sent') body=`<div class="auth stag" style="text-align:center"><div style="font-size:54px">📧</div><h3 style="margin:6px 0">Check your email</h3><p class="hint">If <b>${esc(val('fE')||window.__fE||'')}</b> is registered, a link to choose a new password is on its way. It works for 1 hour.</p><p class="hint">Can't see it? Check your junk folder.</p><button class="lnk" onclick="authMode='login';showLogin('')">Back to log in</button></div>`;
  if(authMode==='reset') body=`<div class="auth stag"><p class="hint" style="margin:0 0 6px">Choose a new password for the club app.</p>
    <label class="field"><span>New password</span><input id="rP" type="password" autocomplete="new-password" placeholder="At least 8 characters"></label>
    <label class="field"><span>Type it again</span><input id="rP2" type="password" autocomplete="new-password" onkeydown="if(event.key==='Enter'&&!event.isComposing&&event.keyCode!==229&&!event.repeat)doReset()"></label>
    ${err}<button class="btn full big" id="aGo" onclick="doReset()">Save new password</button>
    <button class="lnk" onclick="history.replaceState(null,'',location.pathname);authMode='login';showLogin('')">Back to log in</button></div>`;
  if(authMode==='join'){ if(!TEAMLIST){ loadTeams(); }
    const tl=TEAMLIST||[];
    body=`<div class="auth stag">
    <label class="field"><span>Your name</span><input id="jN" autocomplete="name" placeholder="First and last name" value="${esc(val('jN'))}"></label>
    <label class="field"><span>Email</span><input id="jE" type="email" autocomplete="email" inputmode="email" value="${esc(val('jE'))}"></label>
    <label class="field"><span>Mobile</span><input id="jM" type="tel" autocomplete="tel" value="${esc(val('jM'))}"></label>
    <label class="field"><span>Create a password</span><input id="jP" type="password" autocomplete="new-password" placeholder="At least 8 characters" value="${esc($('#jP')?.value||'')}"></label>
    <label class="field"><span>Club code</span><input id="jC" autocapitalize="characters" placeholder="From Alfie" value="${esc(val('jC'))}"></label>
    <div class="lab" style="margin:6px 0 0">Your children</div>
    ${signupKids.map((k,i)=>`<div class="kidrow"><label class="field" style="margin:0"><span>First name</span><input value="${esc(k.name)}" oninput="signupKids[${i}].name=this.value"></label><label class="field" style="margin:0"><span>Squad</span><select onchange="signupKids[${i}].team=this.value"><option value="">Not sure yet</option>${tl.map(t=>`<option value="${t.id}" ${k.team===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label><button class="x" onclick="signupKids.splice(${i},1);if(!signupKids.length)signupKids.push({name:'',team:''});showLogin()" aria-label="Remove">×</button></div>`).join('')}
    <button class="lnk" onclick="signupKids.push({name:'',team:''});showLogin()">＋ Add another child</button>
    <label class="privacy-consent">
      <input type="checkbox" class="pc-in" id="jPr" ${window.__jPr?'checked':''} onchange="window.__jPr=this.checked" aria-label="Agree to the club privacy notice">
      <span class="pc-box" aria-hidden="true"></span>
      <span class="pc-txt">I agree to the club's <a href="?a=privacy" target="_blank" rel="noopener">privacy notice</a>, including the coaches keeping my child's medical and emergency details to keep them safe.</span>
    </label>
    ${err}<button class="btn full big" id="aGo" onclick="doJoin()">Join the club</button>
