async function startParentQRScan(){
  if(!me||me.role!=='parent'){toast('Please log in with your parent account first.');return;}
  if(!navigator.mediaDevices?.getUserMedia){toast('Camera access needs a secure connection. Open the app using its HTTPS address.');return;}
  if(qrSession&&!qrSession.disposed&&qrSession.generation===sheetGeneration)return;
  openSheet(`<div class="shb"><div class="pill static">AG Coaching FC · Check-in</div><h3 style="margin-top:12px">Scan club QR code</h3><p class="hint">Hold your camera over the permanent check-in poster.</p><video id="parentQRVideo" autoplay playsinline muted style="width:100%;border-radius:18px;background:#000;max-height:55vh;object-fit:cover"></video><p id="parentQRStatus" class="hint" style="text-align:center;margin-top:10px">Starting camera…</p><button class="btn gh full" onclick="stopParentQRScan();closeSheet()">Cancel</button></div>`);
  const q={request:++qrRequest,generation:sheetGeneration,accountId:me.id,stream:null,frame:null,detector:null,video:$('#parentQRVideo'),status:$('#parentQRStatus'),disposed:false};
  qrSession=q;
  const live=()=>qrSession===q&&!q.disposed&&q.request===qrRequest&&q.generation===sheetGeneration&&q.video?.isConnected&&$('#sheet')?.classList.contains('on')&&me?.id===q.accountId&&me?.role==='parent';
  setSheetDisposer(()=>disposeParentQRSession(q));
  const nativeCamera='QR scanning is not supported by this browser. Open your phone’s Camera app, point it at the club poster and tap the check-in link, then log in to this app.';
  try{
    if(!('BarcodeDetector' in window))throw new Error(nativeCamera);
    if(typeof BarcodeDetector.getSupportedFormats==='function'){
      let formats;try{formats=await BarcodeDetector.getSupportedFormats();}catch(e){throw new Error(nativeCamera);}
      if(!live())return;
      if(!formats?.includes('qr_code'))throw new Error(nativeCamera);
    }
    try{q.detector=new BarcodeDetector({formats:['qr_code']});}catch(e){throw new Error(nativeCamera);}
    if(!live())return;
    const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});
    if(!live()){stream.getTracks().forEach(t=>t.stop());return;}
    q.stream=stream;qrStream=stream;qrDetector=q.detector;q.video.srcObject=stream;
    await q.video.play();
    if(!live())return;
    const scan=async()=>{
      q.frame=null;qrFrame=null;if(!live())return;
      try{
        const codes=await q.detector.detect(q.video);
        if(!live())return;
        if(codes.length){
          const u=new URL(codes[0].rawValue,location.href),t=u.searchParams.get('checkin');
          if(t){CHECKIN_TOKEN=t;stopParentQRScan();closeSheet();checkinPrompted=false;promptCheckin();return;}
          q.status.textContent='That code is not an AG Coaching FC check-in code.';
        }
      }catch(e){}
      if(live()){q.frame=requestAnimationFrame(scan);qrFrame=q.frame;}
    };
    q.status.textContent='Camera ready. Point it at the club QR code.';q.frame=requestAnimationFrame(scan);qrFrame=q.frame;
  }catch(e){
    if(!live())return;
    q.status.textContent=e?.name==='NotAllowedError'?'Allow camera access in your browser settings, or scan the poster using your phone’s Camera app.':(e.message||'Could not start the camera.');
    disposeParentQRSession(q);
  }
}
function disposeParentQRSession(q){
  if(!q||q.disposed)return;q.disposed=true;
  if(q.frame!==null)cancelAnimationFrame(q.frame);q.frame=null;
  if(q.stream)q.stream.getTracks().forEach(t=>t.stop());q.stream=null;q.detector=null;
  if(q.video){try{q.video.pause();}catch(e){}q.video.srcObject=null;}
  if(qrSession===q){qrSession=null;qrRequest++;qrStream=null;qrFrame=null;qrDetector=null;}
}
function stopParentQRScan(){disposeParentQRSession(qrSession);}
function promptCheckin(){
  if(checkinPrompted||!CHECKIN_TOKEN||!me||me.role!=='parent'||!S)return;
  checkinPrompted=true;
