  const parts=new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/London',month:'2-digit',day:'2-digit'}).formatToParts(new Date()), mm=parts.find(x=>x.type==='month')?.value, dd=parts.find(x=>x.type==='day')?.value;
