   <button class="btn gh full" style="margin-top:16px" onclick="logout()">Log out</button></div>`); }
async function saveParentPhoto(photo,pid){
  const accountId=me?.id, deadline=Date.now()+15000;
  while(inflight){ if(Date.now()>deadline) throw new Error('Still saving. Please try again in a moment.'); await new Promise(r=>setTimeout(r,50)); }
  if(me?.role!=='parent'||!S||!base||me?.id!==accountId) throw new Error('Parent session required');
  const u=S.users.find(x=>x.id===accountId);
  const p=kids().find(x=>x.id===pid);
  if(!u||!p) throw new Error('Choose one of your linked players');
  if(outbox.length){ clearTimeout(flushT); await doFlush(); if(outbox.length) throw new Error('Please reconnect and finish saving before uploading the photo.'); }
  inflight=true; $('#sync')?.classList.add('on');
  try{
    const reply=await api('profilephoto',{pid,photo:photo||null});
    if(!reply.photoSaved||reply.playerId!==pid||me?.id!==accountId) throw new Error('Photo save was not confirmed. Please try again.');
    REV=Math.max(REV,reply.rev); pending=reply.S;
    for(const [collection,id] of [['users',accountId],['players',pid]]){
      const canonical=reply.S?.[collection]?.find(x=>x.id===id);
      for(const state of [S,base]){ const target=state?.[collection]?.find(x=>x.id===id); if(target){ if(canonical?.photo) target.photo=canonical.photo; else delete target.photo; } }
    }
    const savedUser=S.users.find(x=>x.id===accountId); if(savedUser?.photo) me.photo=savedUser.photo; else delete me.photo;
    ui.mePhoto=photo||null;
    const consentOff=reply.S?.players?.find(x=>x.id===pid)?.info?.photo===false;
    toast(photo?(consentOff?'Photo saved. Enable photo consent and save details to show it on the card.':'Photo saved to avatar and player card ✓'):'Photo removed from avatar and player card');
  }finally{ inflight=false; if(outbox.length) flush(); else $('#sync')?.classList.remove('on'); }
}
async function saveCoachPhoto(photo){
  if(me?.role!=='coach'||!S||!base) throw new Error('Coach session required');
  const put=person=>{ if(photo) person.photo=photo; else delete person.photo; };
  const u=S.users.find(x=>x.id===me.id); if(!u) throw new Error('Please log in again');
  put(u); put(me); const s=S.staff?.find(x=>x.name===me.name||(x.email&&x.email===me.email)); if(s) put(s);
  save(); clearTimeout(flushT); const reply=await doFlush();
  if(!reply||outbox.length) throw new Error('Photo is not confirmed yet. Keep the app open and try again.');
  ui.mePhoto=photo||null; toast(photo?'Photo saved ✓':'Photo removed');
}
function refreshProfilePhotoUI(){
  if(!me||!S) return;
  $$('.pc-photo-slot[data-player-photo]').forEach(slot=>{ const p=P(slot.dataset.playerPhoto); if(p) slot.outerHTML=faceHTML(p); });
  $$('.top .av').forEach(av=>{ av.outerHTML=avHTML(me.name,accountAvatarPhoto(),av.getAttribute('style')||''); });
  for(const id of ['ciAv','meAv']){ const el=$('#'+id); if(!el) continue; const p=el.dataset.playerId?P(el.dataset.playerId):null; el.innerHTML=avHTML(p?.name||me.name,id==='meAv'?(p?.photo||me.photo):(p?(p.info?.photo===false?null:p.photo):me.photo)); }
}
async function removeProfilePhoto(pid=''){
  if(ui.profilePhotoBusy) return toast('Please wait for the photo to finish saving');
  ui.profilePhotoBusy=true;
  try{ if(me.role==='parent') await saveParentPhoto(null,pid); else await saveCoachPhoto(null); }catch(e){ toast(e.message); }
  finally{ ui.profilePhotoBusy=false; refreshProfilePhotoUI(); }
}
