/* ---------- sheet / fx ---------- */
let sheetGeneration=0, sheetDisposer=null, sheetReturnFocus=null;
function setSheetDisposer(fn){sheetDisposer=fn;}
function disposeSheetResources(){sheetGeneration++;const f=sheetDisposer;sheetDisposer=null;if(f)try{f();}catch(e){}}
function refreshViewport(){if(window.AppViewport)window.AppViewport.refresh();}
function blurWithin(el){const a=document.activeElement;if(el&&a&&el.contains(a)&&a.blur)a.blur();}
function safeFocus(el){if(!el||!el.isConnected)return;try{el.focus({preventScroll:true});}catch(e){el.focus();}}
function resetSheetDrag(){const sh=$('#sheet');sh.style.transform='';sh.style.transition='';$('#scrim').style.opacity='';}
function openSheet(h,options){
  const sh=$('#sheet'),already=sh.classList.contains('on'),a=document.activeElement;
  if(!already)sheetReturnFocus=a&&a!==document.body?a:null;
  if(!options||!options.preserveMedia)disposeSheetResources();
  blurWithin(sh);resetSheetDrag();sh.classList.remove('chat-sheet');
  $('#shb').innerHTML=h;sh.scrollTop=0;sh.inert=false;sh.setAttribute('aria-hidden','false');
  $('#scrim').classList.add('on');sh.classList.add('on');safeFocus(sh);refreshViewport();
}
function closeSheet(){
  const sh=$('#sheet'),wasOpen=sh.classList.contains('on'),trigger=sheetReturnFocus;sheetReturnFocus=null;
  disposeSheetResources();blurWithin(sh);resetSheetDrag();
  $('#scrim').classList.remove('on');sh.classList.remove('on','chat-sheet');sh.inert=true;sh.setAttribute('aria-hidden','true');
  if(wasOpen&&trigger&&!sh.contains(trigger)&&trigger.isConnected&&trigger.getClientRects().length)safeFocus(trigger);
  refreshViewport();setTimeout(flushPending,350);
}
document.addEventListener('keydown',e=>{
  const sh=$('#sheet');if(!sh.classList.contains('on')||!$('#login').classList.contains('gone'))return;
  if(e.key==='Escape'&&!e.isComposing){e.preventDefault();closeSheet();return;}
  if(e.key!=='Tab')return;
  const nodes=Array.from(sh.querySelectorAll('button,a[href],input,select,textarea,[tabindex]')).filter(el=>!el.disabled&&el.tabIndex>=0&&getComputedStyle(el).visibility!=='hidden'&&el.getClientRects().length);
  if(!nodes.length){e.preventDefault();safeFocus(sh);return;}
  const first=nodes[0],last=nodes[nodes.length-1],a=document.activeElement;
  if(e.shiftKey&&(a===first||a===sh)){e.preventDefault();safeFocus(last);}else if(!e.shiftKey&&(a===last||a===sh)){e.preventDefault();safeFocus(first);}
});
let tt; function toast(t){ const e=$('#toast'); e.textContent=t; e.classList.add('on'); clearTimeout(tt); tt=setTimeout(()=>e.classList.remove('on'),2300); }
let ptm; function push(t,x){ $('#pushT').textContent=t; $('#pushX').textContent=x; const p=$('#push'); p.classList.remove('on'); void p.offsetWidth; p.classList.add('on'); clearTimeout(ptm); ptm=setTimeout(()=>p.classList.remove('on'),4200); }
function buzz(p){ try{ navigator.vibrate&&navigator.vibrate(p||25); }catch(e){} }
function confetti(){ const c=$('#fx'), r=c.getBoundingClientRect(); c.width=r.width*2; c.height=r.height*2; const x=c.getContext('2d'); x.scale(2,2); const cols=['#3ff36a','#c4ff4d','#fff','#1fd14f','#0f7a2c','#ffc93c'];
  const Q=Array.from({length:160},()=>({x:r.width/2+(Math.random()-.5)*60,y:r.height*.42,vx:(Math.random()-.5)*16,vy:-Math.random()*16-5,s:Math.random()*8+4,c:cols[Math.random()*6|0],a:Math.random()*6,va:(Math.random()-.5)*.45}));
  let f=0; (function loop(){ x.clearRect(0,0,r.width,r.height); Q.forEach(p=>{p.vy+=.36;p.x+=p.vx;p.y+=p.vy;p.vx*=.985;p.a+=p.va;x.save();x.translate(p.x,p.y);x.rotate(p.a);x.fillStyle=p.c;x.fillRect(-p.s/2,-p.s/4,p.s,p.s/2);x.restore();}); if(++f<150) requestAnimationFrame(loop); else x.clearRect(0,0,r.width,r.height); })(); }
let AC; const ac=()=>AC||(AC=new (window.AudioContext||window.webkitAudioContext)());
function whistle(n){ try{ const A=ac(), t0=A.currentTime; for(let i=0;i<n;i++){ const st=t0+i*.42, len=i===n-1?.65:.28, o=A.createOscillator(), l=A.createOscillator(), lg=A.createGain(), g=A.createGain(); o.frequency.value=2900; l.frequency.value=38; lg.gain.value=190; l.connect(lg); lg.connect(o.frequency); g.gain.setValueAtTime(0,st); g.gain.linearRampToValueAtTime(.16,st+.02); g.gain.setValueAtTime(.16,st+len-.05); g.gain.linearRampToValueAtTime(0,st+len); o.connect(g); g.connect(A.destination); o.start(st); l.start(st); o.stop(st+len); l.stop(st+len);} }catch(e){} }
function cheer(){ try{ const A=ac(), len=2.2, b=A.createBuffer(1,A.sampleRate*len,A.sampleRate), d=b.getChannelData(0); for(let i=0;i<d.length;i++) d[i]=Math.random()*2-1; const s=A.createBufferSource(); s.buffer=b; const bp=A.createBiquadFilter(); bp.type='bandpass'; bp.frequency.value=1100; bp.Q.value=.6; const g=A.createGain(), t=A.currentTime; g.gain.setValueAtTime(0,t); g.gain.linearRampToValueAtTime(.22,t+.25); g.gain.setValueAtTime(.22,t+.9); g.gain.exponentialRampToValueAtTime(.001,t+len); s.connect(bp); bp.connect(g); g.connect(A.destination); s.start(); }catch(e){} }

