function newSession(){ editSession(null); }
function editSession(id){ const s=id?S.sessions.find(x=>x.id===id):{title:'',day:1,start:'17:00',end:'18:00',place:(S.venues||[])[0]?.name||'',teams:[],price:''}; ui.ss=[...s.teams];
  openSheet(`<div class="shb"><h3>${id?'Edit session':'New weekly session'}</h3><p class="hint">Shows in every parent's calendar for the squads you pick, every week.</p>
   <label class="field"><span>Name</span><input id="ssT" value="${esc(s.title)}" placeholder="e.g. U9 Blacks Training"></label>
   <div class="g2"><label class="field"><span>Day</span><select id="ssD">${[1,2,3,4,5,6,0].map(d=>`<option value="${d}" ${s.day===d?'selected':''}>${DAYL[d]}</option>`).join('')}</select></label><label class="field"><span>Price £ (optional)</span><input id="ssP" type="number" step="0.5" value="${s.price??''}"></label></div>
   <div class="g2"><label class="field"><span>Start</span><input id="ssS" type="time" value="${s.start}"></label><label class="field"><span>Finish</span><input id="ssE" type="time" value="${s.end}"></label></div>
   <label class="field"><span>Venue</span><input id="ssV" list="ssVl" value="${esc(s.place)}"><datalist id="ssVl">${(S.venues||[]).map(v=>`<option value="${esc(v.name)}">`).join('')}</datalist></label>
   <div class="lab">Squads</div><div class="chips" id="ssTm">${TK.map(t=>`<button class="chip ${s.teams.includes(t)?'on':''}" data-t="${t}" onclick="this.classList.toggle('on')">${esc(TEAMS[t].short)}</button>`).join('')}</div>
   <button class="btn full big" style="margin-top:18px" onclick="saveSession('${id||''}')">${id?'Save':'Add session'}</button>${id?`<button class="btn rd full" style="margin-top:10px" onclick="deleteSession('${id}')">Delete session</button>`:''}</div>`); }
function saveSession(id){ const t=$('#ssT').value.trim(), teams=$$('#ssTm .chip.on').map(c=>c.dataset.t); if(!t) return toast('Name the session'); if(!teams.length) return toast('Pick at least one squad');
  const d={title:t,day:+$('#ssD').value,start:$('#ssS').value||'17:00',end:$('#ssE').value||'18:00',place:$('#ssV').value.trim()||'TBC',teams,price:+$('#ssP').value||0};
  if(id) Object.assign(S.sessions.find(x=>x.id===id),d); else { S.sessions.push({id:uid('s_'),...d}); tell(teams,`🗓️ New session: ${t}, every ${DAYL[d.day]} ${d.start}–${d.end} at ${d.place}. It's in your calendar.`); }
  log('🗓️',`${id?'Updated':'Added'} session: ${t}`); save(); closeSheet(); toast('Saved ✓'); paint(true); }
function deleteSession(id){ const s=S.sessions.find(x=>x.id===id); if(!confirm(`Delete ${s.title}? It comes off everyone's calendar.`)) return; S.sessions=S.sessions.filter(x=>x.id!==id); log('🗑️',`Deleted session: ${s.title}`); save(); closeSheet(); paint(true); }

/* coach: every player in one place */
V.coach_players=()=>{ ui.pf??='all'; const list=S.players.filter(p=>ui.pf==='all'||inTeam(p,ui.pf)).sort((a,b)=>(TK.indexOf(a.team)-TK.indexOf(b.team))||((a.num||99)-(b.num||99))||a.name.localeCompare(b.name));
  const noEm=S.players.filter(p=>!p.info?.emer).length;
  return `<div class="ph"><small>${S.players.length} players · ${(n=>n+(n===1?' parent / guardian':' parents &amp; guardians'))(S.users.filter(u=>u.role==='parent').length)}</small><h1>Players</h1></div>
  <div class="toolrow" style="margin-top:4px"><button class="btn gh" onclick="ui.st=(ui.pf&&ui.pf!=='all')?ui.pf:TK[0];go('stats')">📊 Squad stats</button><button class="btn gh" onclick="impStart()">📥 Import stats spreadsheet</button></div>
  <div class="toolrow" style="margin-top:0"><button class="btn gh" onclick="go('loyalty')">🎟️ Loyalty cards${stDue().length?' · '+stDue().length+' due':''}</button></div>
  <div style="padding:12px 14px 0"><input id="pSearch" placeholder="🔍 Search players or parents" oninput="filterPlayers(this.value)" style="width:100%;background:var(--card);border:1px solid var(--line);border-radius:14px;padding:13px 14px;color:var(--w)"></div>
  <div class="hscroll" style="padding-top:10px"><button class="chip ${ui.pf==='all'?'on':''}" onclick="ui.pf='all';paint(true)">All</button>${TK.map(t=>`<button class="chip ${ui.pf===t?'on':''}" onclick="ui.pf='${t}';paint(true)">${esc(TEAMS[t].short)}</button>`).join('')}</div>
  ${noEm?`<p class="hint" style="padding:0 18px;margin:8px 0 0">📞 ${noEm} player${noEm>1?'s have':' has'} no emergency contact yet. Parents add these in their Profile, or tap a player → Edit.</p>`:''}
  <div class="list" id="pList" style="margin-top:10px">${list.map(p=>{ const ps=pars(p).map(u=>S.users.find(x=>x.id===u)).filter(Boolean);
    return `<button class="row" data-q="${esc((p.name+' '+(p.last||'')+' '+ps.map(u=>u.name).join(' ')+' '+(TEAMS[p.team]?.name||'')).toLowerCase())}" onclick="playerSheet('${p.id}')">${p.photo?avHTML(p.name+' '+(p.last||''),p.photo,'width:44px;height:44px;font-size:16px'):`<span class="ic" style="font-family:var(--disp);font-weight:900;font-size:18px">${p.num||'–'}</span>`}<div class="grow"><b>${esc(p.name)}${p.last?' '+esc(p.last):''}${medFlag(p)}${p.info?.photo===false?' 📵':''}</b><p>${esc(TEAMS[p.team]?.short||'')}${p.tr?' · training only':''} · ${ps.length?esc(ps.map(u=>u.name).join(', ')):'<span style="color:var(--amber)">no parent/guardian yet</span>'}</p></div>${(()=>{const L=LY(),c=stOf(p.id);return L.on?`<span class="stb ${c.n>=L.need?'due':c.n?'':'zero'}">${c.n>=L.need?'🎁 due':'🎟️ '+c.n+'/'+L.need}</span>`:''})()}</button>`; }).join('')||'<div class="empty">No players</div>'}</div>
  <div class="toolrow"><button class="btn" onclick="ui.sq=ui.pf==='all'?TK[0]:ui.pf;editPlayer()">＋ Add player</button><button class="btn gh" onclick="ui.sq=ui.pf==='all'?TK[0]:ui.pf;go('squad')">📊 Stats &amp; cards</button></div><div style="height:16px"></div>`; };
V.coach_loyalty=()=>{ const L=LY(); ui.lf??='all'; ui.lq??='';
  const due=stDue().length, act=S.players.filter(p=>stOf(p.id).n>0).length, given=S.players.reduce((a,p)=>a+stOf(p.id).red,0);
  const list=S.players.filter(p=>ui.lf==='all'||inTeam(p,ui.lf)).sort((a,b)=>(stOf(b.id).n-stOf(a.id).n)||(TK.indexOf(a.team)-TK.indexOf(b.team))||a.name.localeCompare(b.name));
  return `<div class="ph"><button class="chip" onclick="go('club')" style="margin-bottom:10px;display:table">← Club</button><small>${L.on?'Stamp cards':'Stamp cards · switched off'}</small><h1>Loyalty</h1></div>
  <div class="lsum"><div><b>${act}</b><small>Active cards</small></div><div><b style="${due?'color:var(--amber)':''}">${due}</b><small>Rewards due</small></div><div><b>${given}</b><small>Rewards given</small></div></div>
  <div class="toolrow"><button class="btn gh" onclick="loyaltySheet()">⚙️ Settings${L.on?'':' · turn on'}</button><button class="btn gh" onclick="go('training')">✅ Take the register</button></div>
  ${loyDueHTML()}
  <h2 class="sec">All cards</h2>
  <div style="padding:0 14px"><input id="lSearch" placeholder="🔍 Find a child" value="${esc(ui.lq)}" oninput="ui.lq=this.value;filterLoy(this.value)" style="width:100%;background:var(--card);border:1px solid var(--line);border-radius:14px;padding:13px 14px;color:var(--w);font-size:16px"></div>
  <div class="hscroll" style="padding-top:10px"><button class="chip ${ui.lf==='all'?'on':''}" onclick="ui.lf='all';paint(true)">All</button>${TK.map(t=>`<button class="chip ${ui.lf===t?'on':''}" onclick="ui.lf='${t}';paint(true)">${esc(TEAMS[t].short)}</button>`).join('')}</div>
  <div class="list" id="lList" style="margin-top:10px">${list.map(p=>{ const c=stOf(p.id), pct=Math.min(100,Math.round(c.n/L.need*100)), d=c.n>=L.need;
    return `<button class="row" data-q="${esc((p.name+' '+(p.last||'')).toLowerCase())}" onclick="stampSheet('${p.id}')"><span class="ic" style="font-family:var(--disp);font-weight:900;font-size:18px">${p.num||'–'}</span><div class="grow"><b>${esc(p.name)}${p.last?' '+esc(p.last):''}</b><p>${esc(TEAMS[p.team]?.short||'')}</p><div class="lbar ${d?'due':''}"><i style="width:${pct}%"></i></div></div><span class="stb ${d?'due':c.n?'':'zero'}">${d?'🎁 due':'🎟️ '+c.n+'/'+L.need}</span></button>`; }).join('')||'<div class="empty">No players</div>'}</div>
  <p class="hint" style="text-align:center;margin:12px 18px">Tap a child to add or take off stamps, see their history and give a reward.</p><div style="height:16px"></div>`; };
V.coach_parents=()=>{ ui.pf2??='all'; ui.pq??='';
  const pa=S.users.filter(u=>u.role==='parent').map(u=>({u,ks:S.players.filter(p=>pars(p).includes(u.id))})).filter(x=>ui.pf2==='all'||x.ks.some(k=>k.team===ui.pf2)).sort((a,b)=>a.u.name.localeCompare(b.u.name));
  return `<div class="ph"><button class="chip" onclick="go('club')" style="margin-bottom:10px;display:table">← Club</button><small>${S.users.filter(u=>u.role==='parent').length} joined</small><h1>Parents &amp; guardians</h1></div>
  <div style="padding:0 14px"><input id="paSearch" placeholder="🔍 Find a parent or child" value="${esc(ui.pq)}" oninput="ui.pq=this.value;filterPar(this.value)" style="width:100%;background:var(--card);border:1px solid var(--line);border-radius:14px;padding:13px 14px;color:var(--w);font-size:16px"></div>
  <div class="hscroll" style="padding-top:10px"><button class="chip ${ui.pf2==='all'?'on':''}" onclick="ui.pf2='all';paint(true)">All</button>${TK.map(t=>`<button class="chip ${ui.pf2===t?'on':''}" onclick="ui.pf2='${t}';paint(true)">${esc(TEAMS[t].short)}</button>`).join('')}</div>
  <div class="list" id="paList" style="margin-top:10px">${pa.map(({u,ks})=>`<button class="row" data-q="${esc((u.name+' '+ks.map(k=>k.name+' '+(k.last||'')).join(' ')).toLowerCase())}" onclick="familySheet('${u.id}')">${avHTML(u.name,u.photo,'width:44px;height:44px;font-size:16px;background:linear-gradient(145deg,#5aa8ff,#2453a8);color:#fff')}<div class="grow"><b>${esc(u.name)}</b><p>${esc(ks.map(k=>k.name+' · '+(TEAMS[k.team]?.short||'')).join(', ')||'No children linked')}</p></div></button>`).join('')||'<div class="empty">No parents or guardians here yet. Share the club code: <b style="color:var(--g)">'+esc(JOIN||'')+'</b></div>'}</div>
  <div class="empty" id="paNone" style="display:none">No match</div><div style="height:16px"></div>`; };
function filterPar(q){ q=q.trim().toLowerCase(); let n=0; $$('#paList .row').forEach(r=>{ const sh=!q||r.dataset.q.includes(q); r.style.display=sh?'':'none'; if(sh) n++; }); const e=$('#paNone'); if(e) e.style.display=(q&&!n)?'':'none'; }
function filterPlayers(q){ q=q.trim().toLowerCase(); $$('#pList .row').forEach(r=>r.style.display=!q||r.dataset.q.includes(q)?'':'none'); }
{ const _sq=V.coach_squad; V.coach_squad=()=>_sq().replace('<div class="ph">','<div class="ph"><button class="chip" onclick="go(\'players\')" style="margin-bottom:10px;display:table">← Players</button>'); }

/* ---------- install first: phones get the app on the home screen ---------- */
const UA=navigator.userAgent, IOS=/iphone|ipad|ipod/i.test(UA)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1), ANDROID=/android/i.test(UA);
const INAPP=/FBAN|FBAV|Instagram|Line\/|Snapchat|TikTok|; wv\)|WhatsApp/i.test(UA);
const isStandalone=()=>matchMedia('(display-mode: standalone)').matches||matchMedia('(display-mode: fullscreen)').matches||navigator.standalone===true;
function needsInstall(){ if(isStandalone()) return false; if(/[?&]reset=/.test(location.search)) return false; if(!(IOS||ANDROID)) return false; try{ if(sessionStorage.getItem('agfc_web')) return false; }catch(e){} return true; }
const shareIco='<svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="vertical-align:-5px"><path d="M12 3v12"/><path d="m7 8 5-5 5 5"/><path d="M5 12v7a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2v-7"/></svg>';
const plusIco='<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="2" style="vertical-align:-4px"><rect x="3" y="3" width="18" height="18" rx="4"/><path d="M12 8v8M8 12h8"/></svg>';
function showInstall(done){
  let el=$('#inst'); if(!el){ el=document.createElement('div'); el.id='inst'; el.className='inst'; $('#app').appendChild(el); }
  const step=(n,t)=>`<div class="ist"><i>${n}</i><span>${t}</span></div>`;
  let body;
  if(done) body=`<h2>You're all set 🎉</h2><p>Open <b>AG FC</b> from your home screen to log in.</p>`;
  else if(INAPP) body=`<h2>Open in your browser first</h2><p>This page opened inside another app. To install AG FC:</p>${IOS?step(1,`Tap <b>•••</b> or the share button`)+step(2,'Choose <b>Open in Safari</b>')+step(3,'Then follow the steps to add it to your home screen'):step(1,'Tap <b>⋮</b> at the top right')+step(2,'Choose <b>Open in Chrome</b>')+step(3,'Then tap <b>Install app</b>')}`;
  else if(IOS) body=`<h2>Add it to your home screen</h2><p>It takes 10 seconds and works just like an app.</p>${step(1,`Tap the <b>Share</b> button ${shareIco} at the bottom of the screen`)}${step(2,`Scroll down and tap <b>Add to Home Screen</b> ${plusIco}`)}${step(3,'Tap <b>Add</b>, then open <b>AG FC</b> from your home screen')}<div class="iarrow">↓</div>`;
  else body=`<h2>Install the app</h2><p>It takes 5 seconds and works just like an app.</p>${typeof deferred!=='undefined'&&deferred?`<button class="btn full big" onclick="installNow()">📲 Install AG FC</button>`:step(1,'Tap <b>⋮</b> at the top right of Chrome')+step(2,'Tap <b>Install app</b> or <b>Add to Home screen</b>')+step(3,'Open <b>AG FC</b> from your home screen')}`;
  el.innerHTML=`<div class="iin"><img src="${BADGE}" alt="AG Coaching FC"><div class="ieb">The official club app</div>${body}<button class="iweb" onclick="skipInstall()">Use it in the browser instead</button><a href="https://northpointcreative.co.uk" target="_blank" rel="noopener" style="display:block;text-align:center;margin-top:18px;font-size:11px;color:var(--mute);text-decoration:none">App designed &amp; created by <b style="color:var(--ink)">Dan · North Point Creative</b> · <span style="color:var(--g)">northpointcreative.co.uk</span></a></div>`;
  el.classList.add('on'); if(!done&&!showInstall.seen){ showInstall.seen=1; hit('install_screen'); }
}
async function installNow(){ if(!deferred) return showInstall(); deferred.prompt(); const r=await deferred.userChoice; deferred=null; if(r.outcome==='accepted'){ hit('install'); showInstall(true); } else showInstall(); }
function skipInstall(){ try{ sessionStorage.setItem('agfc_web','1'); }catch(e){} $('#inst')?.classList.remove('on'); route(); }
window.addEventListener('beforeinstallprompt',()=>setTimeout(()=>{ if($('#inst')?.classList.contains('on')&&!INAPP&&ANDROID) showInstall(); },50));
window.addEventListener('appinstalled',()=>{ if($('#inst')?.classList.contains('on')) showInstall(true); });

/* visitor stats beacon (no cookies) */
function hit(e){ try{ const m=isStandalone()?'standalone':'browser'; (new Image()).src='?a=hit&p=app&e='+(e||'view')+'&m='+m+'&r='+encodeURIComponent(document.referrer||'')+'&_='+Date.now(); }catch(err){} }
hit();
let hidAt=0; document.addEventListener('visibilitychange',()=>{ if(document.hidden) hidAt=Date.now(); else if(hidAt&&Date.now()-hidAt>5*60000){ hidAt=0; hit(); } });
window.addEventListener('appinstalled',()=>hit('install'));
/* Preserve unrelated registrations; no confirmed legacy script/scope is known. */

/* ---------- lock-screen notifications ---------- */
const pushOK=()=>'serviceWorker' in navigator&&'PushManager' in window&&'Notification' in window&&location.protocol==='https:';
const pushOn=()=>pushOK()&&Notification.permission==='granted';
function u8(b){ const p='='.repeat((4-b.length%4)%4), s=atob((b+p).replace(/-/g,'+').replace(/_/g,'/')); return Uint8Array.from(s,c=>c.charCodeAt(0)); }
async function pushSubscribe(){
  const reg=await navigator.serviceWorker.ready; let sub=await reg.pushManager.getSubscription();
  if(!sub){ const {key}=await api('vapid'); sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:u8(key)}); }
  await api('subscribe',sub.toJSON()); return sub;
}
async function enablePush(){
  if(!pushOK()) return toast(IOS&&!isStandalone()?'Add AG FC to your home screen first, then turn notifications on':'Notifications aren\'t supported on this browser');
  try{ const p=await Notification.requestPermission(); if(p!=='granted') return toast('Notifications are off. You can turn them on in your phone settings.');
    await pushSubscribe(); try{localStorage.setItem('agfc_push','1');}catch(e){} toast('Notifications on 🔔'); buzz([30,40,30]); paint(true); }
  catch(e){ toast('Couldn\'t turn on notifications: '+e.message); }
}
function pushCard(){
  if(!pushOK()||Notification.permission!=='default') return '';
  try{ if(sessionStorage.getItem('agfc_pushx')) return ''; }catch(e){}
  const coach=me.role==='coach';
  return `<div class="card" style="margin-top:10px;display:flex;gap:12px;align-items:center;border-color:var(--line2)"><span style="font-size:28px">🔔</span><div style="flex:1"><b style="font-family:var(--disp);font-size:19px;text-transform:uppercase">Turn on notifications</b><p class="hint" style="margin:2px 0 0">${coach?'New sign-ups, parent messages and bookings straight to your lock screen.':'Match updates, goals, cancellations and messages straight to your lock screen.'}</p></div><div style="display:grid;gap:6px"><button class="btn sm" onclick="enablePush()">Turn on</button><button class="chip" onclick="try{sessionStorage.setItem('agfc_pushx','1')}catch(e){};paint(true)">Later</button></div></div>`;
}
['coach_home','parent_home'].forEach(k=>{ const f=V[k]; V[k]=()=>{ const h=f(), m='aria-label="Your account">', i=h.indexOf(m); if(i<0) return h; const j=h.indexOf('</div>',i)+6; return h.slice(0,j)+pushCard()+h.slice(j); }; });
{ const _acc=accountSheet; accountSheet=function(){ _acc(); const b=$('#shb'); if(!b||!pushOK()) return;
  b.insertAdjacentHTML('afterbegin',`<div class="card" style="margin:0 0 14px;display:flex;align-items:center;gap:12px"><span style="font-size:24px">🔔</span><div style="flex:1"><b>Notifications</b><p class="hint" style="margin:0">${pushOn()?'On for this phone':Notification.permission==='denied'?'Blocked. Turn them on in your phone settings.':'Off'}</p></div>${pushOn()?'':Notification.permission==='denied'?'':'<button class="btn sm" onclick="enablePush().then(accountSheet)">Turn on</button>'}</div>`); }; }
{ const _lo=logout; logout=async function(){ try{ if(pushOK()){ const reg=await navigator.serviceWorker.getRegistration(location.pathname); const s=await reg?.pushManager.getSubscription(); if(s){ await api('unsubscribe',{endpoint:s.endpoint}).catch(()=>{}); } } }catch(e){} return _lo(); }; }
/* keep this phone's subscription linked to whoever is logged in */
setInterval(()=>{ if(me&&me.status==='approved'&&pushOn()&&!window._pushSynced){ window._pushSynced=1; pushSubscribe().catch(()=>{ window._pushSynced=0; }); } },3000);

/* ---------- quick result: score, who played, scorers & assists in one go ---------- */
function addResult(fid){
  const past=S.fixtures.filter(f=>f.status!=='live').sort((a,b)=>b.at-a.at);
  const f=fid?F(fid):past.find(x=>x.status!=='ft'&&x.at<Date.now()+864e5)||null;
  const team=f?.team||TK.find(t=>t!=='dev')||TK[0];
  ui.ar={fid:f?.id||'',opp:f?.opp||'',date:ymd(new Date(f?.at||Date.now())),ko:f?hm(new Date(f.at)):'10:00',team,home:f?f.home!==false:true,us:f?.status==='ft'?f.us:0,them:f?.status==='ft'?f.them:0,
    played:f?.status==='ft'?[...(f.squad||[])]:teamPlayers(team).filter(p=>!f||f.avail?.[p.id]!==false).map(p=>p.id),
    goals:f?.status==='ft'?(f.events||[]).filter(e=>e.type==='goal').map(e=>({who:e.who||'',ast:e.ast||''})):[],potm:f?.potm||''};
  arSheet(true);
}
function arSet(fn){ const sc=$('#sheet').scrollTop; fn(ui.ar); arSheet(); $('#sheet').scrollTop=sc; }
function arSheet(first){ const r=ui.ar, ps=teamPlayers(r.team), pl=ps.filter(p=>r.played.includes(p.id));
  while(r.goals.length<r.us) r.goals.push({who:'',ast:''}); r.goals.length=r.us;
  const opts=(sel,none)=>`<option value="">${none}</option>`+pl.map(p=>`<option value="${p.id}" ${sel===p.id?'selected':''}>${esc(p.name)}${p.num?' #'+p.num:''}</option>`).join('');
  const past=S.fixtures.filter(f=>f.status!=='live').sort((a,b)=>b.at-a.at).slice(0,12);
  const step=(lbl,k)=>`<div class="score-stepper"><button class="ib" style="width:44px;height:44px;font-size:22px" onclick="arSet(r=>r.${k}=Math.max(0,r.${k}-1))">−</button><b style="font-family:var(--disp);font-size:44px;min-width:44px;text-align:center">${r[k]}</b><button class="ib" style="width:44px;height:44px;font-size:22px" onclick="arSet(r=>r.${k}++)">＋</button></div>`;
  (first?openSheet:(h=>{$('#shb').innerHTML=h;}))(`<div class="shb"><h3>Add a result</h3><p class="hint">Score, who played, and who scored. Everyone's matches, goals and assists update in one go.</p>
   <label class="field"><span>Match</span><select onchange="const v=this.value;v?addResult(v):(ui.ar.fid='',arSet(()=>{}))"><option value="">New match (not in the app yet)</option>${past.map(f=>`<option value="${f.id}" ${f.id===r.fid?'selected':''}>${f.status==='ft'?'✏️ ':''}${esc(TEAMS[f.team]?.short||'')} v ${esc(f.opp)} · ${fmtD(new Date(f.at))}</option>`).join('')}</select></label>
   ${r.fid?'':`<div class="g2"><label class="field"><span>Opposition</span><input value="${esc(r.opp)}" oninput="ui.ar.opp=this.value" placeholder="e.g. Formby Juniors"></label><label class="field"><span>Squad</span><select onchange="arSet(r=>{r.team=this.value;r.played=teamPlayers(r.team).map(p=>p.id);r.goals=[];r.potm=''})">${TK.filter(t=>t!=='dev').map(t=>`<option value="${t}" ${t===r.team?'selected':''}>${esc(TEAMS[t].name)}</option>`).join('')}</select></label></div>
