   ${r.us?`<div class="lab" style="margin-top:14px">Our goals</div>${r.goals.map((g,i)=>`<div class="g2" style="align-items:end"><label class="field"><span>Goal ${i+1} · scorer</span><select onchange="ui.ar.goals[${i}].who=this.value">${opts(g.who,'Own goal / not sure')}</select></label><label class="field"><span>Assist</span><select onchange="ui.ar.goals[${i}].ast=this.value">${opts(g.ast,'No assist')}</select></label></div>`).join('')}`:''}
   <label class="field" style="margin-top:6px"><span>Player of the match (optional)</span><select onchange="ui.ar.potm=this.value">${opts(r.potm,'None')}</select></label>
