  f.status='ft'; f.us=r.us; f.them=r.them; f.squad=[...r.played]; f.potm=r.potm||null; f.step=4; f.live=null; f.plan=f.plan||null; f.mins=f.mins||{};
  f.events=[...r.goals.map(g=>({t:0,type:'goal',who:g.who||null,ast:g.ast||null})),...Array.from({length:r.them},()=>({t:0,type:'opp'}))];
  if(!wasFt){ const sc=r.goals.filter(g=>g.who).map(g=>P(g.who)?.name).filter(Boolean), pm=r.potm?P(r.potm)?.name:'';
    tell(f.team,`🏁 FT: AG ${f.us}–${f.them} ${f.opp}.${sc.length?` ⚽ ${[...new Set(sc)].map(n=>n+(sc.filter(x=>x===n).length>1?' ×'+sc.filter(x=>x===n).length:'')).join(', ')}.`:''}${pm?` ⭐ Player of the Match: ${pm}!`:''} Stats updated in the app.`);
    r.goals.forEach(g=>{ const p=P(g.who); if(p) note(pars(p),'⚽',`${p.name} scored vs ${f.opp}! AG ${f.us}–${f.them}`); }); }
  log('🏁',`Result ${wasFt?'updated':'added'}: AG ${TEAMS[f.team].short} ${f.us}–${f.them} ${f.opp}`); save(); closeSheet(); toast(wasFt?'Result updated ✓':'Result saved · stats updated ✓'); if(!wasFt&&f.us>f.them) confetti(); ui.fx=f.id; ui.ftView=1; paint(true); }
{ const _ft=ftView; ftView=f=>{ let h=_ft(f); if(!Object.values(f.mins||{}).some(Boolean)) h=h.replace(/<h2 class="sec">Minutes played<\/h2>\s*<div[^>]*>\s*<\/div>/,''); return h+`<div class="toolrow"><button class="btn gh" onclick="addResult('${f.id}')">✏️ Edit result, scorers &amp; who played</button></div><div class="toolrow"><button class="btn gh" onclick="editFixture('${f.id}')">📅 Change date, venue or delete</button></div>`; }; }

