/* if anything ever goes wrong, say so and tell Dan's stats page */
let errShown=0; function reportErr(msg,quiet){ try{ (new Image()).src='?a=err&m='+encodeURIComponent(String(msg).slice(0,300))+'&v='+encodeURIComponent(view||'')+'&_='+Date.now(); }catch(e){} if(!quiet&&Date.now()-errShown>4000){ errShown=Date.now(); toast('Something went wrong. Close and reopen the app.'); } }
window.addEventListener('error',e=>{ const m=String(e.message||'error');
  /* "Script error." with no line = an error inside something that isn't the app (a Safari add-on, ad blocker, password manager, translate). Not ours: never show parents a warning for it. */
  if(/^Script error\.?$/i.test(m)&&!e.lineno) return;
  const src=e.filename&&!e.filename.includes(location.host)?' ['+String(e.filename).slice(0,60)+']':'';
  reportErr(m+' @'+(e.lineno||'')+src+(e.error&&e.error.stack?' | '+String(e.error.stack).split('\n').slice(0,2).join(' ').slice(0,160):'')); });
window.addEventListener('unhandledrejection',e=>{ const m=String(e.reason?.message||e.reason||''); if(!/auth|reach the club server/i.test(m)) reportErr('promise: '+m); });

