  const t=ui.st, key=ui.ssort, rows=arc?arc.players.filter(p=>p.team===t&&(me.role==='coach'||true)).map(p=>({p:{...p,num:(P(p.id)||{}).num,pos:(P(p.id)||{}).pos},s:{apps:p.apps,goals:p.goals,ast:p.ast,potm:p.potm}})):teamPlayers(t,true).map(p=>({p,s:stats(p,t)}));
