  ${seas.length?`<div class="hscroll" style="padding-top:10px"><button class="chip ${!arc?'on':''}" onclick="ui.sea=null;paint(true)">This season</button>${seas.slice().reverse().map(s=>`<button class="chip ${arc&&arc.id===s.id?'on':''}" onclick="ui.sea='${s.id}';paint(true)">${esc(s.name)}</button>`).join('')}</div>`:''}
  ${teams.length>1?`<div class="hscroll" style="padding-top:10px">${teams.map(x=>`<button class="chip ${x===t?'on':''}" onclick="ui.st='${x}';paint(true)">${esc(TEAMS[x].short)}</button>`).join('')}</div>`:''}
  <div style="display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr) minmax(0,1fr);gap:8px;padding:12px 14px 0">${[['Team goals',tg],['Assists',ta],['Top '+(key==='potm'?'MOTM':lbl[key].toLowerCase()),top?esc(top.p.name):'—']].map(([l,v])=>`<div style="background:var(--card);border:1px solid var(--line);border-radius:14px;padding:12px"><small style="color:var(--mute);font-size:11px">${l}</small><div style="font-family:var(--disp);font-weight:800;font-size:22px;margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${v}</div></div>`).join('')}</div>
  <div class="hscroll" style="padding-top:12px">${Object.entries(lbl).map(([k,l])=>`<button class="chip ${key===k?'on':''}" onclick="ui.ssort='${k}';paint(true)">Sort by ${k==='potm'?'MOTM':l.toLowerCase()}</button>`).join('')}</div>
  <div class="list stats-scroll"><div class="row" style="gap:6px;padding:6px 12px;font-size:9px;color:var(--mute);letter-spacing:.02em"><span style="flex:0 0 22px"></span><div style="flex:1 1 auto;min-width:0">PLAYER</div>${col('apps','PLAYED')}${col('goals','GOALS')}${col('ast','ASSISTS')}${col('potm','MOTM')}</div>
  ${rows.map((r,i)=>{ const own=mine.includes(r.p.id); return `<button class="row" onclick="statCard('${r.p.id}')" style="gap:6px;padding:12px;${own?'border-color:var(--g);background:rgba(57,255,120,.08)':''}"><span style="flex:0 0 22px;font-weight:800;color:${i<3&&val(r)>0?'var(--g)':'var(--mute)'}">${i+1}</span><div style="flex:1 1 auto;min-width:0"><span style="display:block;font-weight:800;font-size:15px;line-height:1.2;white-space:normal;overflow-wrap:anywhere">${esc(r.p.name)}${own?' ⭐':''}</span><small style="color:var(--mute);font-size:11px">#${r.p.num||'–'} · ${esc(r.p.pos||'')}</small></div>${col('apps',r.s.apps)}${col('goals',r.s.goals)}${col('ast',r.s.ast)}${col('potm',r.s.potm)}</button>`; }).join('')}</div>
  <p class="hint" style="padding:0 18px;margin:12px 0 24px">${arc?`Saved stats from the ${esc(arc.name)} season.`:'Updates automatically as Coach Alfie adds results. Tap a player to see their card.'}</p>`;
}
