/* ---------- matchday data guard: repairs any fixture before it is drawn ---------- */
function fixFx(f){
  if(!f||typeof f!=='object') return f;
  if(typeof f.opp!=='string') f.opp=String(f.opp||'Opposition');
  if(!f.avail||typeof f.avail!=='object'||Array.isArray(f.avail)) f.avail={};
  if(!Array.isArray(f.events)) f.events=[];
  if(f.locks&&!Array.isArray(f.locks)) f.locks=[];
  f.len=+f.len||40; f.int=+f.int||5; f.us=+f.us||0; f.them=+f.them||0; if(!+f.at) f.at=Date.now();
  if(!TEAMS[f.team]) return f;
  if(f.lineup&&(typeof f.lineup!=='object'||Array.isArray(f.lineup))){ const a=f.lineup; f.lineup={}; if(Array.isArray(a)) a.forEach((id,i)=>{ if(id) f.lineup[i]=id; }); }
  if(f.lineup) Object.keys(f.lineup).forEach(k=>{ if(!P(f.lineup[k])) delete f.lineup[k]; });
  if(f.plan&&(!Array.isArray(f.plan.blocks)||!f.plan.blocks.length||!+f.plan.B)) f.plan=null;
  if(f.status==='ft') return f;
  const fmt=TEAMS[f.team].fmt, av=teamPlayers(f.team,true).filter(p=>f.avail[p.id]).length;
  let st=+f.step||1; if(st<1||st>4) st=1; if(f.status!=='live'&&st===4) st=3;
  if(f.status!=='live'&&st>=2&&av<fmt) st=1;
  if(st>=2&&(!f.lineup||Object.keys(f.lineup).length<fmt)){ try{ autoPick(f,ui.mode||'balanced'); }catch(e){ st=1; } if(!f.lineup||!Object.keys(f.lineup).length) st=f.status==='live'?4:1; }
  if((st>=3||f.status==='live')&&!f.plan&&f.lineup&&Object.keys(f.lineup).length){ try{ buildPlan(f); }catch(e){ f.plan=null; if(f.status!=='live') st=Math.min(st,2); } }
  if(f.status==='live'){ st=4; if(!f.live||typeof f.live!=='object') f.live={secs:0,on:{...(f.lineup||{})},blk:0,due:false,mins:{}}; f.live.on=f.live.on||{...(f.lineup||{})}; f.live.mins=f.live.mins||{}; f.live.secs=+f.live.secs||0; f.live.blk=+f.live.blk||0; }
  f.step=st; return f;
}
function tidyData(){ if(!S||!Array.isArray(S.fixtures)) return; const n=S.fixtures.length; S.fixtures=S.fixtures.filter(f=>f&&typeof f==='object'&&TEAMS[f.team]); S.fixtures.forEach(fixFx); if(S.fixtures.length!==n&&me&&me.role==='coach') save(); }
{ const _cm=V.coach_match; V.coach_match=()=>{
  try{ return _cm(); }catch(e){ reportErr('match: '+(e&&e.message),1); const f=F(ui.fx); if(f&&f.status!=='live'&&f.status!=='ft'){ f.step=1; f.plan=null; } try{ return _cm(); }catch(e2){ throw e2; } } }; }
function recover(e){ reportErr('paint '+(me&&me.role)+'_'+view+': '+(e&&e.message),1); if(view==='match'){ const f=F(ui.fx); if(f&&f.status!=='live'&&f.status!=='ft'){ f.step=1; f.plan=null; f.lineup=null; } ui.fx=null; }
  const fn=V[me.role+'_'+view]||V[me.role+'_home']; return fn(); }
