function rgFit(x,txt,max,size,font){ let s=size; do{ x.font=font.replace('$',s); if(x.measureText(txt).width<=max) break; s-=2; }while(s>14); return s; }
function rgWrap(x,txt,max){ const w=txt.split(' '), out=[]; let l=''; w.forEach(t=>{ const tryL=l?l+' '+t:t; if(x.measureText(tryL).width>max&&l){ out.push(l); l=t; } else l=tryL; }); if(l) out.push(l); return out; }
async function rgDraw(){ const r=ui.rg, f=F(r.fid); if(!f) return; const W=1080, H=r.fmt==='story'?1920:1350, t=TEAMS[f.team];
  const c=document.createElement('canvas'); c.width=W; c.height=H; const x=c.getContext('2d');
  try{ await Promise.all(['italic 900 120px "Barlow Condensed"','900 200px "Barlow Condensed"','800 40px "Barlow Condensed"','600 34px Barlow','800 28px Barlow'].map(s=>document.fonts.load(s))); }catch(e){}
  const img=await new Promise(res=>{ const i=new Image(); i.onload=()=>res(i); i.onerror=()=>res(null); i.src=BADGE; });
  if(r.photo){ x.fillStyle='#020a05'; x.fillRect(0,0,W,H); const p=r.photo, RH=H*(r.fmt==='story'?.64:.72), s=Math.max(W/p.width,RH/p.height), dw=p.width*s, dh=p.height*s; x.drawImage(p,(W-dw)/2,(RH-dh)/2,dw,dh);
    let g=x.createLinearGradient(0,0,0,H); g.addColorStop(0,'rgba(2,10,5,.8)'); g.addColorStop(.16,'rgba(2,10,5,.1)'); g.addColorStop(.36,'rgba(2,10,5,0)'); g.addColorStop(RH/H*.82,'rgba(2,10,5,.85)'); g.addColorStop(RH/H,'rgba(2,10,5,1)'); g.addColorStop(1,'rgba(1,4,2,1)'); x.fillStyle=g; x.fillRect(0,0,W,H);
    x.save(); x.globalAlpha=.05; x.fillStyle='#3ff36a'; for(let i=-H;i<W+H;i+=110){x.beginPath();x.moveTo(i,H*.55);x.lineTo(i+55,H*.55);x.lineTo(i+55-H*.25,H);x.lineTo(i-H*.25,H);x.fill();} x.restore();
  } else { const g=x.createLinearGradient(0,0,0,H); g.addColorStop(0,'#134a25'); g.addColorStop(.55,'#06120a'); g.addColorStop(1,'#010302'); x.fillStyle=g; x.fillRect(0,0,W,H);
    x.save(); x.globalAlpha=.07; x.fillStyle='#3ff36a'; for(let i=-H;i<W+H;i+=110){x.beginPath();x.moveTo(i,0);x.lineTo(i+55,0);x.lineTo(i+55-H*.47,H);x.lineTo(i-H*.47,H);x.fill();} x.restore();
    for(const cx of [W*.08,W*.92]){ const rg=x.createRadialGradient(cx,0,0,cx,0,620); rg.addColorStop(0,'rgba(196,255,77,.32)'); rg.addColorStop(1,'rgba(196,255,77,0)'); x.fillStyle=rg; x.fillRect(0,0,W,H); }
    if(img){ const bw=r.fmt==='story'?420:270, by=r.fmt==='story'?330:185; x.save(); x.shadowColor='rgba(63,243,106,.55)'; x.shadowBlur=90; x.drawImage(img,W/2-bw/2,by,bw,bw*img.height/img.width); x.restore(); } }
  const top=r.fmt==='story'?120:64;
