/* ---------- import Alfie's stats spreadsheet (.xlsx / .csv) ---------- */
async function unzipText(buf, want){ const v=new DataView(buf), u8=new Uint8Array(buf); let e=u8.length-22; while(e>=0&&v.getUint32(e,true)!==0x06054b50) e--; if(e<0) throw new Error('not a zip');
  const n=v.getUint16(e+10,true); let p=v.getUint32(e+16,true); const out={};
  for(let i=0;i<n;i++){ const method=v.getUint16(p+10,true), csize=v.getUint32(p+20,true), fl=v.getUint16(p+28,true), xl=v.getUint16(p+30,true), cl=v.getUint16(p+32,true), off=v.getUint32(p+42,true);
    const name=new TextDecoder().decode(u8.subarray(p+46,p+46+fl)); p+=46+fl+xl+cl;
    if(!want(name)) continue; const lfl=v.getUint16(off+26,true), lxl=v.getUint16(off+28,true), data=u8.subarray(off+30+lfl+lxl,off+30+lfl+lxl+csize);
    let bytes; if(method===0) bytes=data; else if(method===8){ if(!window.DecompressionStream) throw new Error('old phone'); bytes=new Uint8Array(await new Response(new Blob([data]).stream().pipeThrough(new DecompressionStream('deflate-raw'))).arrayBuffer()); } else continue;
    out[name]=new TextDecoder().decode(bytes); }
  return out; }
async function readXlsx(buf){ const f=await unzipText(buf,n=>/^xl\/(workbook\.xml|_rels\/workbook\.xml\.rels|sharedStrings\.xml|worksheets\/[^/]+\.xml)$/.test(n)); const dp=new DOMParser(), X=s=>dp.parseFromString(s,'application/xml');
  const ss=f['xl/sharedStrings.xml']?[...X(f['xl/sharedStrings.xml']).getElementsByTagName('si')].map(si=>[...si.getElementsByTagName('t')].map(t=>t.textContent).join('')):[];
  const rel={}; if(f['xl/_rels/workbook.xml.rels']) [...X(f['xl/_rels/workbook.xml.rels']).getElementsByTagName('Relationship')].forEach(r=>rel[r.getAttribute('Id')]=r.getAttribute('Target'));
  const sheets=f['xl/workbook.xml']?[...X(f['xl/workbook.xml']).getElementsByTagName('sheet')].map(s=>{ let t=rel[s.getAttribute('r:id')]||rel[s.getAttributeNS('http://schemas.openxmlformats.org/officeDocument/2006/relationships','id')]||''; t=t.replace(/^\/?xl\//,'').replace(/^\//,''); return {name:s.getAttribute('name'),path:'xl/'+t}; }):[];
  if(!sheets.length) Object.keys(f).filter(k=>k.startsWith('xl/worksheets/')).forEach((k,i)=>sheets.push({name:'Sheet '+(i+1),path:k}));
  const col=r=>{ const m=/^[A-Z]+/.exec(r)[0]; let n=0; for(const ch of m) n=n*26+ch.charCodeAt(0)-64; return n-1; };
  return sheets.filter(s=>f[s.path]).map(s=>{ const rows=[]; [...X(f[s.path]).getElementsByTagName('row')].forEach(r=>{ const ri=(+r.getAttribute('r')||rows.length+1)-1, row=[];
      [...r.getElementsByTagName('c')].forEach((c,ci)=>{ const t=c.getAttribute('t'), vEl=c.getElementsByTagName('v')[0]; let val='';
        if(t==='s') val=ss[+(vEl?.textContent)]??''; else if(t==='inlineStr') val=[...c.getElementsByTagName('t')].map(x=>x.textContent).join(''); else val=vEl?vEl.textContent:'';
        row[c.getAttribute('r')?col(c.getAttribute('r')):ci]=val; }); rows[ri]=row; });
    return {name:s.name,rows:[...rows].map(r=>r||[])}; }); }
function readCsv(txt){ const rows=[]; let row=[], cell='', q=false; const d=(txt.split('\n')[0].split(';').length>txt.split('\n')[0].split(',').length)?';':',';
  for(let i=0;i<txt.length;i++){ const ch=txt[i]; if(q){ if(ch==='"'){ if(txt[i+1]==='"'){ cell+='"'; i++; } else q=false; } else cell+=ch; }
    else if(ch==='"') q=true; else if(ch===d){ row.push(cell); cell=''; } else if(ch==='\n'||ch==='\r'){ if(ch==='\r'&&txt[i+1]==='\n') i++; row.push(cell); rows.push(row); row=[]; cell=''; } else cell+=ch; }
  if(cell||row.length){ row.push(cell); rows.push(row); } return [{name:'CSV',rows}]; }
const impNorm=s=>String(s??'').toUpperCase().replace(/[^A-Z0-9%/ ]/g,' ').replace(/\s+/g,' ').trim();
function impFindTables(sheets){ const out=[];
  sheets.forEach(sh=>{ const R=sh.rows; for(let i=0;i<Math.min(R.length,60);i++){ const h=(R[i]||[]).map(impNorm); const nameC=h.findIndex(c=>/^(NAME|FIRST NAME|FORENAME|PLAYER|PLAYER NAME|PLAYERS)$/.test(c)); if(nameC<0) continue;
      const pick=(re,bad)=>h.findIndex(c=>re.test(c)&&!(bad&&bad.test(c)));
      const cols={name:nameC,last:pick(/^(SURNAME|LAST NAME|FAMILY NAME)$/),apps:pick(/^(APPEARANCES|APPS|GAMES PLAYED|MATCHES PLAYED|MATCHES|PLAYED|GAMES)$/),goals:pick(/^(PLAYER GOALS|GOALS|GOALS SCORED)$/),ast:pick(/^(ASSISTS|ASSIST|PLAYER ASSISTS)$/),potm:pick(/^(MOTM|POTM|PLAYER OF THE MATCH|MAN OF THE MATCH|PLAYER OF MATCH)$/)};
      if(cols.apps<0) cols.apps=pick(/APPEAR/,/%|PER/); if(cols.goals<0) cols.goals=pick(/GOAL/,/PER|%|CONCEDED|OVERALL|TOTAL|FOR|OWN|DIFF|INVOLV|ASSIST/); if(cols.ast<0) cols.ast=pick(/ASSIST/,/PER|%|TOTAL|GOAL/);
      if(cols.apps<0&&cols.goals<0&&cols.ast<0) continue;
      const rows=[]; for(let j=i+1;j<R.length;j++){ const r=R[j]||[]; const nm=String(r[nameC]??'').trim(); if(!nm){ if(rows.length) break; else continue; } if(/^(NAME|TOTAL|SQUAD|AVERAGE)/i.test(nm)) break; rows.push(r); }
      if(rows.length) out.push({sheet:sh.name,head:R[i],cols,rows}); } });
  const full=out.filter(t=>t.cols.apps>=0&&t.cols.goals>=0&&t.cols.ast>=0); const use=full.length?full:out;
  return use.sort((a,b)=>((b.cols.apps>=0)+(b.cols.goals>=0)+(b.cols.ast>=0))-((a.cols.apps>=0)+(a.cols.goals>=0)+(a.cols.ast>=0))); }
function impStart(){ ui.imp={step:'file'}; openSheet(`<div class="shb"><h3>Import stats spreadsheet</h3>
  <p class="hint">Upload your stats spreadsheet and the app pulls out each player's <b>matches played, goals and assists</b> and puts them on their player cards and Squad stats.</p>
  <label class="btn full" style="text-align:center;cursor:pointer;margin-top:10px">📄 Choose spreadsheet<input type="file" accept=".xlsx,.csv,text/csv,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" style="display:none" onchange="impFile(this)"></label>
  <div class="card" style="margin-top:14px;padding:12px 14px"><p class="hint" style="margin:0"><b>Excel or Numbers</b>: save it as <b>.xlsx</b>.<br><b>Google Sheets app</b>: ⋮ → Share &amp; export → Save as → <b>Excel (.xlsx)</b> or CSV.<br>Your sheet needs a <b>NAME</b> column and columns for <b>APPEARANCES</b>, <b>PLAYER GOALS</b> and <b>ASSISTS</b>. Your current layout works as it is.</p></div>
  <button class="btn full gh" style="margin-top:12px" onclick="closeSheet()">Cancel</button></div>`); }
async function impFile(inp){ const file=inp.files&&inp.files[0]; if(!file) return; toast('Reading spreadsheet…');
  try{ const buf=await file.arrayBuffer(); let sheets;
    if(/\.csv$/i.test(file.name)||file.type==='text/csv') sheets=readCsv(new TextDecoder().decode(buf));
    else if(/\.xls$/i.test(file.name)) return toast('That is an old .xls file. Save it as .xlsx and try again');
    else if(/\.(pdf|numbers)$/i.test(file.name)) return toast('Save it as .xlsx or CSV first, then try again');
    else sheets=await readXlsx(buf);
    const tabs=impFindTables(sheets); if(!tabs.length) return toast("Couldn't find a NAME column with goals, assists or appearances");
    ui.imp={tabs,ti:0,file:file.name}; impPrep(); }
  catch(e){ reportErr('import: '+e.message,1); toast(e.message==='old phone'?'Your phone is too old to read .xlsx. Save it as CSV instead':"Couldn't read that file. Save it as .xlsx or CSV and try again"); } }
function impNum(v){ const n=parseFloat(String(v??'').replace(/[^0-9.\-]/g,'')); return isFinite(n)?Math.max(0,Math.round(n)):0; }
function impPrep(){ const I=ui.imp, T=I.tabs[I.ti], c=T.cols;
  I.rows=T.rows.map(r=>{ let first=String(r[c.name]??'').trim(), last=c.last>=0?String(r[c.last]??'').trim():''; if(!last&&first.includes(' ')){ const s=first.split(/\s+/); first=s.shift(); last=s.join(' '); }
    return {first,last,apps:c.apps>=0?impNum(r[c.apps]):null,goals:c.goals>=0?impNum(r[c.goals]):null,ast:c.ast>=0?impNum(r[c.ast]):null,potm:c.potm>=0?impNum(r[c.potm]):null}; });
  const eq=(a,b)=>impNorm(a)===impNorm(b);
  const score=t=>I.rows.filter(r=>teamPlayers(t,true).some(p=>eq(p.name,r.first))).length;
  if(!I.team) I.team=[...TK].sort((a,b)=>score(b)-score(a))[0];
  impMatch(); impSheet(); }
function impMatch(){ const I=ui.imp, ps=teamPlayers(I.team,true), used=new Set(), eq=(a,b)=>impNorm(a)===impNorm(b);
  I.rows.forEach(r=>{ r.to=''; });
  I.rows.forEach(r=>{ const p=ps.find(p=>!used.has(p.id)&&eq(p.name,r.first)&&r.last&&eq(p.last||'',r.last)); if(p){ r.to=p.id; used.add(p.id); } });
  I.rows.forEach(r=>{ if(r.to) return; const c=ps.filter(p=>!used.has(p.id)&&eq(p.name,r.first)); if(c.length===1){ r.to=c[0].id; used.add(c[0].id); } });
  I.rows.forEach(r=>{ if(!r.to) r.to='new'; }); }
function impSheet(){ const I=ui.imp, T=I.tabs[I.ti], c=T.cols, ps=teamPlayers(I.team,true);
  const H=i=>i>=0?esc(String(T.head[i]??'')):'<i>not found</i>';
  const opts=r=>`<option value="new" ${r.to==='new'?'selected':''}>➕ Add as new player</option><option value="skip" ${r.to==='skip'?'selected':''}>Skip this row</option>${ps.map(p=>`<option value="${p.id}" ${r.to===p.id?'selected':''}>${esc(p.name)}${p.last?' '+esc(p.last):''}</option>`).join('')}`;
  const nMatch=I.rows.filter(r=>r.to&&r.to!=='new'&&r.to!=='skip').length, nNew=I.rows.filter(r=>r.to==='new').length;
  openSheet(`<div class="shb"><h3>Check before importing</h3><p class="hint" style="margin-bottom:8px">From <b>${esc(I.file)}</b>${I.tabs.length>1?'':` · ${esc(T.sheet)}`}</p>
   ${I.tabs.length>1?`<label class="field"><span>Which table?</span><select onchange="ui.imp.ti=+this.value;ui.imp.team=null;impPrep()">${I.tabs.map((t,i)=>`<option value="${i}" ${i===I.ti?'selected':''}>${esc(t.sheet)} · ${t.rows.length} players</option>`).join('')}</select></label>`:''}
   <label class="field"><span>Squad</span><select onchange="ui.imp.team=this.value;impMatch();impSheet()">${TK.map(t=>`<option value="${t}" ${t===I.team?'selected':''}>${esc(TEAMS[t].name)}</option>`).join('')}</select></label>
   <p class="hint" style="margin:6px 0 10px">Using columns: <b>${H(c.apps)}</b> for matches · <b>${H(c.goals)}</b> for goals · <b>${H(c.ast)}</b> for assists${c.potm>=0?` · <b>${H(c.potm)}</b> for MOTM`:''}</p>
   <div style="display:grid;gap:8px">${I.rows.map((r,i)=>`<div style="background:var(--card);border:1px solid ${r.to==='new'?'var(--amber)':r.to==='skip'?'var(--line)':'var(--line)'};border-radius:14px;padding:10px 12px;${r.to==='skip'?'opacity:.5':''}">
     <div style="display:flex;justify-content:space-between;gap:8px;align-items:baseline"><b style="font-size:15px">${esc(r.first)} ${esc(r.last)}</b><span style="font-size:12px;color:var(--mute);white-space:nowrap">${r.apps??'–'} played · ${r.goals??'–'} goals · ${r.ast??'–'} assists${r.potm!=null?` · ${r.potm} MOTM`:''}</span></div>
     <select style="margin-top:8px;width:100%;background:var(--bg);color:var(--ink);border:1px solid var(--line);border-radius:10px;padding:8px" onchange="ui.imp.rows[${i}].to=this.value;impSheet()">${opts(r)}</select></div>`).join('')}</div>
   <p class="hint" style="margin-top:12px">These numbers become each player's <b>season totals</b>. Results you add in the app from now on add on top, and you can import again any time to bring it back in line with your sheet.</p>
   <button class="btn full" style="margin-top:8px" onclick="impSave()">✅ Import ${nMatch+nNew} player${nMatch+nNew===1?'':'s'}${nNew?` (${nNew} new)`:''}</button>
   <button class="btn full gh" style="margin-top:8px" onclick="closeSheet()">Cancel</button></div>`); }
function impSave(){ const I=ui.imp, team=I.team; let up=0, add=0;
  I.rows.forEach(r=>{ if(!r.to||r.to==='skip') return; let p=r.to==='new'?null:P(r.to);
    if(!p){ p={id:uid('p_'),playerRef:newPlayerRef(),name:r.first,last:r.last,num:0,pos:'MID',lvl:3,team,tr:false,parent:null,parents:[],info:{med:'',emer:'',photo:true},base:{apps:0,goals:0,ast:0}}; S.players.push(p); add++; } else up++;
    if(r.last&&!p.last) p.last=r.last;
    const now=stats({...p,base:{},squadBase:{}},team), b={...((p.squadBase||{})[team]||(team===p.team?p.base:{} )||{})};
    if(r.apps!=null) b.apps=Math.max(0,r.apps-now.apps); if(r.goals!=null) b.goals=Math.max(0,r.goals-now.goals); if(r.ast!=null) b.ast=Math.max(0,r.ast-now.ast); if(r.potm!=null) b.potm=Math.max(0,r.potm-now.potm);
    p.squadBase=p.squadBase||{}; p.squadBase[team]={apps:+b.apps||0,goals:+b.goals||0,ast:+b.ast||0,potm:+b.potm||0}; if(team===p.team) p.base={...p.squadBase[team]}; });
  log('📥',`Stats imported for ${TEAMS[team].name}: ${up} updated${add?`, ${add} added`:''}`); save(); closeSheet(); confetti&&confetti();
  toast(`Stats imported ✓ ${up} updated${add?` · ${add} new`:''}`); ui.st=team; ui.ssort='goals'; go('stats'); }

