  return `<div style="margin-top:8px;display:grid;gap:4px;font-size:13px;color:var(--mute)">${f.meet?`<span>🕘 Meet <b style="color:var(--ink)">${esc(f.meet)}</b> · Kick-off <b style="color:var(--ink)">${hm(new Date(f.at))}</b></span>`:''}
   ${v&&v.name&&v.name!=='TBC'?`<a href="${fxMap(v)}" target="_blank" rel="noopener" style="color:var(--mute);text-decoration:none">📍 <b style="color:var(--ink)">${esc(v.name)}</b>${v.address?', '+esc(v.address):''}${v.postcode?', '+esc(v.postcode):''} <span style="color:var(--g)">· Map</span></a>${v.notes?`<span>ℹ️ ${esc(v.notes)}</span>`:''}`:v&&v.name==='TBC'?'<span>📍 Venue to be confirmed</span>':''}
   ${edit?`<a onclick="editFixture('${f.id}')" style="color:var(--g);font-weight:700;cursor:pointer">✏️ ${v&&f.meet?'Edit or delete fixture':'Add venue &amp; meet time · edit or delete'}</a>`:''}</div>`; }
function fxMinus(t,mins){ const [h,m]=String(t||'10:00').split(':').map(Number); const d=(h*60+m-mins+1440)%1440; return String(d/60|0).padStart(2,'0')+':'+String(d%60).padStart(2,'0'); }
function fxForm(f){ const isNew=!f; f=f||{team:TK.filter(t=>t!=='dev')[0],home:true,at:addDays(dayStart(new Date()),((7-new Date().getDay())%7||7)+7).getTime()+10*3600000,opp:''};
  const ko=isNew?'10:00':hm(new Date(f.at)), vs=S.venues||[], cur=f.venue?.name||'', known=vs.find(v=>v.name===cur);
  const vsel=!cur?'':cur==='TBC'?'TBC':known?known.id:'new';
  openSheet(`<div class="shb"><h3>${isNew?'New fixture':'Edit fixture'}</h3>${isNew?'<p class="hint">Parents see it straight away and reply with availability.</p>':''}
   <label class="field"><span>Opposition</span><input id="fO" placeholder="e.g. Formby Juniors" value="${esc(f.opp)}"></label>
   <div class="g2"><label class="field"><span>Squad</span><select id="fT">${TK.filter(t=>t!=='dev').map(t=>`<option value="${t}" ${t===f.team?'selected':''}>${TEAMS[t].name}</option>`).join('')}</select></label><label class="field"><span>Home or away</span><select id="fH"><option value="1" ${f.home?'selected':''}>Home</option><option value="0" ${f.home?'':'selected'}>Away</option></select></label></div>
   <label class="field"><span>Venue</span><select id="fV" onchange="$('#fVn').style.display=this.value==='new'?'':'none'"><option value="" ${vsel===''?'selected':''}>Choose the venue…</option>${vs.map(v=>`<option value="${v.id}" ${vsel===v.id?'selected':''}>${esc(v.name)}</option>`).join('')}<option value="new" ${vsel==='new'?'selected':''}>➕ Another venue…</option><option value="TBC" ${vsel==='TBC'?'selected':''}>To be confirmed</option></select></label>
   <div id="fVn" style="display:${vsel==='new'?'':'none'}"><label class="field"><span>Venue name</span><input id="fVa" placeholder="e.g. Formby Sports Centre" value="${vsel==='new'?esc(cur):''}"></label><div class="g2"><label class="field"><span>Address</span><input id="fVb" placeholder="Street, town" value="${vsel==='new'?esc(f.venue.address||''):''}"></label><label class="field"><span>Postcode</span><input id="fVc" placeholder="L37 …" value="${vsel==='new'?esc(f.venue.postcode||''):''}"></label></div>
     <label style="display:flex;gap:8px;align-items:center;font-size:13px;color:var(--mute);margin:-2px 0 10px"><input type="checkbox" id="fVs" checked> Save to my venues for next time</label></div>
   <div class="g2"><label class="field"><span>Date</span><input id="fD" type="date" value="${ymd(new Date(f.at))}"></label><label class="field"><span>Kick-off</span><input id="fK" type="time" value="${ko}" oninput="if(!ui.meetEd) $('#fM').value=fxMinus(this.value,30)"></label></div>
   <label class="field"><span>Meet time</span><input id="fM" type="time" value="${esc(f.meet||fxMinus(ko,30))}" oninput="ui.meetEd=1"></label>
   <button class="btn full big" onclick="saveFixture(${isNew?'':`'${f.id}'`})">${isNew?'Add fixture':'Save changes'}</button>${isNew?'':`<button class="btn full gh" style="margin-top:8px" onclick="closeSheet()">Cancel</button><div id="fxDel" style="margin-top:14px;border-top:1px solid var(--line);padding-top:14px"><button class="btn full gh" style="color:#ff6b6b" onclick="askDelFx('${f.id}')">🗑️ Delete this fixture</button></div>`}</div>`); ui.meetEd=!isNew&&!!f.meet; }
function askDelFx(fid){ const f=F(fid); $('#fxDel').innerHTML=`<p class="hint" style="text-align:center;margin:0 0 8px">Delete <b>vs ${esc(f.opp)}</b> on ${fmtD(new Date(f.at))}?</p>
  <label style="display:flex;gap:8px;align-items:center;justify-content:center;font-size:13px;color:var(--mute);margin-bottom:10px"><input type="checkbox" id="fxTell" ${f.status==='up'&&Object.keys(f.avail||{}).length?'checked':''}> Tell parents the match is off</label>
  <div style="display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:8px"><button class="btn gh" onclick="closeSheet()">Keep it</button><button class="btn" style="background:#ff4d4d;color:#fff" onclick="delFx('${fid}')">Yes, delete</button></div>`; }
function delFx(fid){ const f=F(fid); if(!f) return; if($('#fxTell')?.checked) tell(f.team,`❌ Match off: ${fmtD(new Date(f.at))} vs ${f.opp} is no longer happening.`);
  S.fixtures=S.fixtures.filter(x=>x.id!==fid); log('🗑️',`Fixture deleted: ${TEAMS[f.team]?.short||''} vs ${f.opp}`); if(ui.fx===fid) ui.fx=null; save(); closeSheet(); toast('Fixture deleted ✓'); paint(); }
function addFixture(){ fxForm(null); }
function editFixture(fid){ const f=F(fid); if(f) fxForm(f); }
function saveFixture(fid){ const opp=$('#fO').value.trim(); if(!opp) return toast('Add the opposition'); const vv=$('#fV').value; if(!vv) return toast('Choose the venue (or To be confirmed)');
  let venue; if(vv==='TBC') venue={name:'TBC'}; else if(vv==='new'){ const n=$('#fVa').value.trim(); if(!n) return toast('Add the venue name'); venue={name:n,address:$('#fVb').value.trim(),postcode:$('#fVc').value.trim().toUpperCase()};
    if($('#fVs').checked&&!(S.venues||[]).some(v=>v.name.toLowerCase()===n.toLowerCase())){ S.venues=S.venues||[]; S.venues.push({id:uid('v_'),...venue,notes:''}); } }
  else { const v=(S.venues||[]).find(x=>x.id===vv); venue={name:v.name,address:v.address||'',postcode:v.postcode||'',notes:v.notes||''}; }
  const at=new Date($('#fD').value+'T'+$('#fK').value).getTime(); if(!at) return toast('Check the date and kick-off'); const meet=$('#fM').value||'', home=$('#fH').value==='1';
  const where=venue.name==='TBC'?'venue TBC':venue.name+(venue.postcode?' ('+venue.postcode+')':'');
  if(fid){ const f=F(fid); const was=JSON.stringify([f.opp,f.at,f.meet,f.venue?.name,f.home,f.team]); const nt=$('#fT').value; if(nt&&nt!==f.team&&f.status!=='live'){ f.team=nt; f.avail={}; f.lineup=null; f.plan=null; f.step=1; } Object.assign(f,{opp,at,meet,home,venue}); const now=JSON.stringify([f.opp,f.at,f.meet,f.venue?.name,f.home,f.team]);
    if(was!==now) tell(f.team,`📍 Fixture details: ${fmtD(new Date(at))}, ${home?'home':'away'} vs ${opp}. Meet ${meet||'TBC'}, KO ${hm(new Date(at))} at ${where}.`);
    log('✏️',`Fixture updated: ${TEAMS[f.team].short} vs ${opp}`); save(); closeSheet(); toast(was!==now?'Fixture updated · parents told ✓':'Saved ✓'); paint(); return; }
  const cols=['#c0392b','#2980b9','#8e44ad','#d35400','#16a085'];
  const f={id:uid('f'),team:$('#fT').value,opp,col:cols[Math.random()*5|0],home,at,meet,venue,status:'up',len:40,int:5,us:0,them:0,events:[],avail:{}};
  S.fixtures.push(f); tell(f.team,`🗓️ New fixture: ${fmtD(new Date(at))}, ${home?'home':'away'} vs ${opp}. Meet ${meet||'TBC'}, KO ${hm(new Date(at))} at ${where}. Please reply with availability!`);
  log('🗓️',`Fixture added: ${TEAMS[f.team].short} vs ${opp}`); ui.fx=f.id; save(); closeSheet(); toast('Fixture added · parents asked ✓'); paint(); }

/* ===== snag sweep 22 Nov: edit/delete everything ===== */
const confirmRow=(id,q,yes,fn)=>{ $('#'+id).innerHTML=`<p class="hint" style="text-align:center;margin:0 0 8px">${q}</p><div style="display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:8px"><button class="btn gh" onclick="closeSheet()">Keep it</button><button class="btn" style="background:#ff4d4d;color:#fff" onclick="${fn}">${yes}</button></div>`; };
const delBtn=(id,label,onclick)=>`<div id="${id}" style="margin-top:14px;border-top:1px solid var(--line);padding-top:14px"><button class="btn full gh" style="color:#ff6b6b" onclick="${onclick}">🗑️ ${label}</button></div>`;

/* events */
{ const _es=eventSheet; eventSheet=id=>{ _es(id); if(me.role!=='coach') return; $('#shb').insertAdjacentHTML('beforeend',`<div class="toolrow" style="padding:10px 0 0"><button class="btn gh" onclick="eventForm('${id}')">✏️ Edit event</button></div>${delBtn('evDel','Delete this event',`askDelEvent('${id}')`)}`); }; }
function eventForm(id){ const e=id?S.events.find(x=>x.id===id):null, at=e?new Date(e.at):addDays(new Date(),14);
  openSheet(`<div class="shb"><h3>${e?'Edit event':'New club event'}</h3>${e?'':'<p class="hint">Goes in every parent\'s calendar with an RSVP button. Add a ticket price and they pay in the app.</p>'}
   <label class="field"><span>Event</span><input id="evT" placeholder="e.g. Christmas Party" value="${esc(e?.title||'')}"></label>
   <div class="g2"><label class="field"><span>Date</span><input id="evD" type="date" value="${ymd(at)}"></label><label class="field"><span>Time</span><input id="evH" type="time" value="${e?hm(at):'18:00'}"></label></div>
   <div class="g2"><label class="field"><span>Where</span><input id="evP" placeholder="Venue" list="evPl" value="${esc(e?.place||'')}"><datalist id="evPl">${(S.venues||[]).map(v=>`<option value="${esc(v.name)}">`).join('')}</datalist></label><label class="field"><span>Ticket £ (0 = free)</span><input id="evM" type="number" step="0.01" value="${e?.price||0}"></label></div>
   <label class="field"><span>Details for parents</span><textarea id="evX" rows="3" placeholder="e.g. Arrive by 11:55 to get signed in">${esc(e?.desc||'')}</textarea></label>
   <button class="btn full big" onclick="saveEventX(${e?`'${e.id}'`:''})">${e?'Save changes':'Add &amp; tell parents'}</button>${e?'<button class="btn full gh" style="margin-top:8px" onclick="closeSheet()">Cancel</button>':''}</div>`); }
function newEvent(){ return eventForm(null); }
function saveEventX(id){ const t=$('#evT').value.trim(); if(!t) return toast('Name the event'); const at=new Date($('#evD').value+'T'+$('#evH').value).getTime(); if(!at) return toast('Check the date and time');
  const d={title:t,at,place:$('#evP').value.trim()||'TBC',price:Math.max(0,+$('#evM').value||0),desc:$('#evX').value.trim()};
  if(id){ const e=S.events.find(x=>x.id===id); const was=e.at+'|'+e.place; Object.assign(e,d); if(was!==e.at+'|'+e.place) tell(TK,`🎉 ${t} update: now ${fmtL(at)} at ${hm(new Date(at))}, ${d.place}.`); log('✏️',`Event updated: ${t}`); save(); closeSheet(); toast('Event updated ✓'); paint(true); return; }
  const e={id:uid('e'),icon:'🎉',rsvp:{},...d}; S.events.push(e); tell(TK,`🎉 New event: ${t}, ${fmtL(at)} at ${hm(new Date(at))}, ${d.place}. RSVP in the app${e.price?` (tickets ${money(e.price)})`:''}!`); log('🎉',`Event added: ${t}`); save(); closeSheet(); toast('Event added · every parent told ✓'); paint(true); }
function askDelEvent(id){ confirmRow('evDel','Delete this event? It comes off every parent\'s calendar.','Yes, delete',`delEvent('${id}')`); }
function delEvent(id){ const e=S.events.find(x=>x.id===id); S.events=S.events.filter(x=>x.id!==id); if(e&&e.at>Date.now()) tell(TK,`❌ ${e.title} on ${fmtL(e.at)} has been cancelled.`); log('🗑️',`Event deleted: ${e?.title}`); save(); closeSheet(); toast('Event deleted ✓'); paint(true); }

/* camps */
{ const _ca=campAdmin; campAdmin=id=>{ _ca(id); const c=S.camps.find(x=>x.id===id), n=S.campBk.filter(b=>b.camp===id).length;
  $('#shb').insertAdjacentHTML('beforeend',`<div class="toolrow" style="padding:10px 0 0"><button class="btn gh" onclick="campForm('${id}')">✏️ Edit camp</button><button class="btn gh" onclick="campBookings('${id}')">🧾 Bookings (${n})</button></div>${delBtn('cpDel','Delete this camp',`askDelCamp('${id}')`)}`); }; }
function campForm(id){ const c=id?S.camps.find(x=>x.id===id):null; ui.cdays=c?c.days.map(d=>ymd(new Date(d))):[ymd(addDays(new Date(),30))];
  const dayInputs=()=>ui.cdays.map((d,i)=>`<div style="display:flex;gap:6px;margin-bottom:6px"><input type="date" value="${d}" onchange="ui.cdays[${i}]=this.value" style="flex:1;background:var(--bg);color:var(--ink);border:1px solid var(--line);border-radius:12px;padding:10px">${ui.cdays.length>1?`<button class="chip" onclick="ui.cdays.splice(${i},1);$('#cpDays').innerHTML=window.__cdi()">✕</button>`:''}</div>`).join('')+`<button class="chip" onclick="ui.cdays.push(ymd(addDays(new Date(ui.cdays.at(-1)+'T12:00'),1)));$('#cpDays').innerHTML=window.__cdi()">＋ Add a day</button>`;
  window.__cdi=dayInputs;
  openSheet(`<div class="shb"><h3>${c?'Edit camp':'New camp'}</h3>${c?'':'<p class="hint">Parents pick days, pay in the app and join the camp group chat automatically.</p>'}
   <label class="field"><span>Name</span><input id="cpN" placeholder="e.g. Easter Holiday Camp" value="${esc(c?.name||'')}"></label>
   <div class="lab">Camp days</div><div id="cpDays">${dayInputs()}</div>
   <div class="g2" style="margin-top:10px"><label class="field"><span>Starts</span><input id="cpS" type="time" value="${c?.start||'09:30'}"></label><label class="field"><span>Finishes</span><input id="cpE" type="time" value="${c?.end||'15:00'}"></label></div>
   <div class="g2"><label class="field"><span>Venue</span><input id="cpV" list="cpVl" value="${esc(c?.place||'')}" placeholder="Venue"><datalist id="cpVl">${(S.venues||[]).map(v=>`<option value="${esc(v.name)}">`).join('')}</datalist></label><label class="field"><span>Ages</span><input id="cpA" value="${esc(c?.ages||'Ages 5–11')}"></label></div>
   <div class="g2"><label class="field"><span>Price for 1 day £</span><input id="cpP" type="number" step="0.01" value="${c?.tiers?.[0]??c?.price??20}"></label><label class="field"><span>Places per day</span><input id="cpC" type="number" value="${c?.cap||16}"></label></div>
   <label class="field"><span>Prices for 1, 2, 3… days (optional)</span><input id="cpT" placeholder="e.g. 35, 60, 85, 100" value="${c?.tiers?c.tiers.join(', '):''}"></label>
   <label class="field"><span>Info for parents</span><textarea id="cpX" rows="3" placeholder="What to bring, drop-off, etc.">${esc(c?.info||'')}</textarea></label>
   <button class="btn full big" onclick="saveCampX(${c?`'${c.id}'`:''})">${c?'Save changes':'Create &amp; open bookings'}</button>${c?'<button class="btn full gh" style="margin-top:8px" onclick="closeSheet()">Cancel</button>':''}</div>`); }
function newCamp(){ return campForm(null); }
function saveCampX(id){ const n=$('#cpN').value.trim(); if(!n) return toast('Name the camp'); const days=[...new Set(ui.cdays.filter(Boolean))].sort().map(d=>+new Date(d+'T00:00')); if(!days.length) return toast('Add at least one day');
  const p1=Math.max(0,+$('#cpP').value||0); let tiers=$('#cpT').value.split(/[,\s]+/).map(Number).filter(v=>v>0); if(!tiers.length) tiers=days.map((_,i)=>Math.round(p1*(i+1)*100)/100); while(tiers.length<days.length) tiers.push(tiers.at(-1)); tiers=tiers.slice(0,days.length);
  const d={name:n,days,start:$('#cpS').value||'09:30',end:$('#cpE').value||'15:00',place:$('#cpV').value.trim()||'Venue TBC',ages:$('#cpA').value.trim(),price:tiers[0],week:tiers.at(-1),tiers,cap:Math.max(1,+$('#cpC').value||16),info:$('#cpX').value.trim()};
  if(id){ const c=S.camps.find(x=>x.id===id); const oldDays=c.days.map(Number); Object.assign(c,d); c.taken=days.map(()=>0);
    S.campBk.filter(b=>b.camp===id).forEach(b=>{ b.days=b.days.map(i=>days.indexOf(oldDays[i])).filter(i=>i>=0); });
    const g=S.groups.find(x=>x.id==='g_'+id); if(g) g.name=n; log('✏️',`Camp updated: ${n}`); save(); closeSheet(); toast('Camp updated ✓'); paint(true); return; }
  const c={id:uid('c_'),icon:'🏕️',taken:days.map(()=>0),...d}; S.camps.push(c);
  S.groups.push({id:'g_'+c.id,name:n,icon:'🏕️',camp:c.id,read:{},msgs:[{by:'coach',uid:me.id,name:'Coach '+me.first,t:`Welcome to ${n}! Info and reminders will go here.`,ts:Date.now()}]});
  tell(TK,`🏕️ ${n} is now booking: ${fmtD(new Date(days[0]))}${days.length>1?` (${days.length} days)`:''}, ${c.start}–${c.end} at ${c.place}, from ${money(tiers[0])}. Book in the app!`); log('🏕️',`Camp created: ${n}`); save(); closeSheet(); toast('Camp live · every parent told ✓'); paint(true); }
function campBookings(id){ const c=S.camps.find(x=>x.id===id), bk=S.campBk.filter(b=>b.camp===id);
  openSheet(`<div class="shb"><h3>${c.icon} Bookings</h3><p class="hint">${esc(c.name)} · tap Cancel to remove a booking. The parent is told.</p><div class="list" style="margin:0">${bk.map(b=>`<div class="row"><div class="grow"><b>${esc(b.child||P(b.pid)?.name||'Child')}</b><p>${b.days.map(i=>c.days[i]?fmtD(new Date(c.days[i])):'').filter(Boolean).join(', ')||'No days'}</p></div><button class="chip" style="color:#ff6b6b" onclick="cancelCampBk('${b.id||''}','${id}','${b.pid}')">Cancel</button></div>`).join('')||'<div class="row"><div class="grow"><p>No bookings yet</p></div></div>'}</div>
   <button class="btn full gh" style="margin-top:12px" onclick="campAdmin('${id}')">← Back</button></div>`); }
function cancelCampBk(bid,cid,pid){ const c=S.camps.find(x=>x.id===cid), b=S.campBk.find(x=>x.camp===cid&&(bid?x.id===bid:x.pid===pid)); if(!b) return;
  S.campBk=S.campBk.filter(x=>x!==b); if(b.uid) note(b.uid,'🏕️',`${b.child||P(b.pid)?.name}'s place on ${c.name} has been cancelled by Coach Alfie. Any questions, message Alfie.`); log('🗑️',`Camp booking cancelled: ${b.child||P(b.pid)?.name}`); save(); toast('Booking cancelled · parent told ✓'); campBookings(cid); }
function askDelCamp(id){ const n=S.campBk.filter(b=>b.camp===id).length; confirmRow('cpDel',n?`Delete this camp? ${n} booking${n>1?'s':''} will be cancelled and parents told.`:'Delete this camp?','Yes, delete',`delCamp('${id}')`); }
function delCamp(id){ const c=S.camps.find(x=>x.id===id); S.campBk.filter(b=>b.camp===id).forEach(b=>b.uid&&note(b.uid,'🏕️',`${c.name} has been cancelled. Any questions, message Coach Alfie.`));
  S.campBk=S.campBk.filter(b=>b.camp!==id); S.camps=S.camps.filter(x=>x.id!==id); S.groups=S.groups.filter(g=>g.id!=='g_'+id); log('🗑️',`Camp deleted: ${c?.name}`); save(); closeSheet(); toast('Camp deleted ✓'); paint(true); }

/* groups */
function editGroup(gid){ const g=S.groups.find(x=>x.id===gid); if(!g) return; const fixed=g.camp||g.coaches||g.id==='g_all';
  openSheet(`<div class="shb"><h3>Edit group</h3><label class="field"><span>Group name</span><input id="egN" value="${esc(g.name)}"></label>
   <div class="lab">Icon</div><div class="chips" id="egI">${['⚽','🎯','🏆','🧤','🌟','🔥','🏃','📣','🏕️','🎄'].map(e=>`<button class="chip ${e===g.icon?'on':''}" onclick="$$('#egI .chip').forEach(c=>c.classList.remove('on'));this.classList.add('on')">${e}</button>`).join('')}</div>
   ${fixed?'':`<div class="lab">Who's in it?</div><div class="chips" id="egT"><button class="chip ${g.all?'on':''}" data-t="*" onclick="this.classList.toggle('on')">Whole club</button>${TK.map(t=>`<button class="chip ${(g.teams||[]).includes(t)?'on':''}" data-t="${t}" onclick="this.classList.toggle('on')">${TEAMS[t].name}</button>`).join('')}</div>`}
   ${g.coaches?'':`<div style="display:flex;align-items:center;gap:12px;margin:16px 0 0"><span style="flex:1;font-size:14px;font-weight:700">📣 Announcements only (just coaches post)</span><button class="tog ${g.ro?'on':''}" id="egR" onclick="this.classList.toggle('on')"></button></div>`}
   <button class="btn full big" style="margin-top:18px" onclick="saveGroupX('${gid}')">Save changes</button><button class="btn full gh" style="margin-top:8px" onclick="closeSheet()">Cancel</button>
   ${g.id==='g_all'||g.coaches?'':delBtn('grDel','Delete this group',`askDelGroup('${gid}')`)}</div>`); }
function saveGroupX(gid){ const g=S.groups.find(x=>x.id===gid), n=$('#egN').value.trim(); if(!n) return toast('Name the group'); g.name=n; g.icon=$('#egI .chip.on')?.textContent||g.icon;
  if($('#egT')){ const t=$$('#egT .chip.on').map(c=>c.dataset.t); if(!t.length) return toast('Pick at least one squad'); if(t.includes('*')){ g.all=true; delete g.teams; } else { delete g.all; g.teams=t; } }
  if($('#egR')){ if($('#egR').classList.contains('on')) g.ro=true; else delete g.ro; }
  log('✏️',`Group updated: ${n}`); save(); closeSheet(); toast('Group updated ✓'); paint(true); }
function askDelGroup(gid){ confirmRow('grDel','Delete this group and all its messages?','Yes, delete',`delGroup('${gid}')`); }
function delGroup(gid){ const g=S.groups.find(x=>x.id===gid); S.groups=S.groups.filter(x=>x.id!==gid); log('🗑️',`Group deleted: ${g?.name}`); save(); closeSheet(); toast('Group deleted ✓'); go('groups'); }

/* 1-1 booked slot */
function slotSheet(id){ const s=S.slots.find(x=>x.id===id); if(!s||!s.booked) return;
  openSheet(`<div class="shb"><h3>1-1 · ${esc(s.booked.name)}</h3><p class="hint">${fmtL(new Date(s.at))} at ${hm(new Date(s.at))} · ${s.len||45} mins · ${money(s.price)}</p>
   <button class="btn full gh" onclick="closeSheet()">Close</button>${delBtn('slDel','Cancel this booking',`confirmRow('slDel','Cancel ${esc(s.booked.name).replace(/'/g,'')}\\'s 1-1? The parent is told and the slot opens up again.','Yes, cancel it',\`cancelSlot('${id}')\`)`)}</div>`); }
function cancelSlot(id){ const s=S.slots.find(x=>x.id===id); if(!s?.booked) return; const b=s.booked; if(b.uid) note(b.uid,'🎯',`${b.name}'s 1-1 on ${fmtD(new Date(s.at))} at ${hm(new Date(s.at))} has been cancelled by Coach Alfie. Message Alfie to rearrange.`);
  s.booked=null; log('🗑️',`1-1 cancelled: ${b.name}`); save(); closeSheet(); toast('1-1 cancelled · parent told ✓'); paint(true); }

/* sent messages */
function sentMsgs(){ const ms=S.messages.slice().sort((a,b)=>b.ts-a.ts).slice(0,40);
  openSheet(`<div class="shb"><h3>Sent messages</h3><p class="hint">Messages you've sent to parents' inboxes. Delete one and it disappears from their app.</p><div class="list" style="margin:0">${ms.map(m=>`<div class="row" style="align-items:flex-start"><div class="grow">${m.text?`<p style="color:var(--ink);font-size:14px;white-space:normal">${esc(m.text)}</p>`:''}${m.img?`<img class="mimg" src="?a=img&f=${m.img}" loading="lazy" alt="Photo" onclick="viewImg('${m.img}')">`:''}<p style="font-size:11px;margin-top:4px">${ago(m.ts)} · ${m.teams.length>=TK.length?'Whole club':m.teams.map(t=>TEAMS[t]?.short||t).join(', ')}</p>${(()=>{const r=updSeen(m);return r.n?`<button class="chip" style="margin-top:8px" onclick="updInfo('${m.id}')">👀 Seen by ${r.seen.length} of ${r.n} <i class="tk ${r.seen.length===r.n?'rd':''}">✓✓</i></button>`:''})()}</div><button class="chip" style="color:#ff6b6b" onclick="delMsg('${m.id}')">Delete</button></div>`).join('')||'<div class="row"><div class="grow"><p>Nothing sent yet</p></div></div>'}</div>
   <button class="btn full gh" style="margin-top:12px" onclick="closeSheet()">Done</button></div>`); }
function updSeen(m){ const ps=S.users.filter(u=>u.role==='parent'), out=[];
  ps.forEach(u=>{ const ks=S.players.filter(p=>m.teams.includes(p.team)&&pars(p).includes(u.id)); if(ks.length) out.push([u.id,`${u.name} (${[...new Set(ks.map(k=>k.name))].join(' & ')})`]); });
  return {seen:out.filter(([u])=>(m.read||[]).includes(u)).map(x=>x[1]),not:out.filter(([u])=>!(m.read||[]).includes(u)).map(x=>x[1]),n:out.length}; }
function updInfo(id){ const m=S.messages.find(x=>x.id===id), r=updSeen(m), li=(a,ic)=>a.map(n=>`<div class="act"><i>${ic}</i><span>${esc(n)}</span></div>`).join('');
  openSheet(`<div class="shb"><h3>Who's seen it</h3><div class="mprev">${m.img?'📷 ':''}${esc((m.text||'Photo').slice(0,160))}</div>
   <h2 class="sec" style="margin:6px 0 6px;padding:0">Seen by ${r.seen.length} of ${r.n}</h2><div class="card" style="padding:4px 14px">${li(r.seen,'👀')||'<p class="hint" style="margin:10px 0">Nobody yet</p>'}</div>
   ${r.not.length?`<h2 class="sec" style="margin:14px 0 6px;padding:0">Not opened yet</h2><div class="card" style="padding:4px 14px">${li(r.not,'⏳')}</div>`:''}
   <button class="btn full gh" style="margin-top:14px" onclick="sentMsgs()">← Back</button></div>`); }
function delMsg(id){ S.messages=S.messages.filter(m=>m.id!==id); save(); toast('Message deleted ✓'); sentMsgs(); }

/* venues */
function venuesSheet(){ const vs=S.venues||[];
  openSheet(`<div class="shb"><h3>Venues</h3><p class="hint">Used for fixtures, sessions, camps and events. Parents see them in Club info with a Maps link.</p><div class="list" style="margin:0">${vs.map(v=>`<button class="row" onclick="venueForm('${v.id}')"><span class="ic">📍</span><div class="grow"><b>${esc(v.name)}</b><p>${esc([v.address,v.postcode].filter(Boolean).join(', '))}${v.notes?' · '+esc(v.notes):''}</p></div><span style="color:var(--g);font-weight:700">Edit</span></button>`).join('')||'<div class="row"><div class="grow"><p>No venues yet</p></div></div>'}</div>
   <button class="btn full" style="margin-top:12px" onclick="venueForm()">＋ Add a venue</button><button class="btn full gh" style="margin-top:8px" onclick="closeSheet()">Done</button></div>`); }
function venueForm(id){ const v=id?(S.venues||[]).find(x=>x.id===id):null;
  openSheet(`<div class="shb"><h3>${v?'Edit venue':'New venue'}</h3><label class="field"><span>Name</span><input id="vnN" value="${esc(v?.name||'')}" placeholder="e.g. Formby Sports Centre"></label>
   <label class="field"><span>Address</span><input id="vnA" value="${esc(v?.address||'')}" placeholder="Street, town"></label><div class="g2"><label class="field"><span>Postcode</span><input id="vnP" value="${esc(v?.postcode||'')}"></label><label class="field"><span>Notes</span><input id="vnX" value="${esc(v?.notes||'')}" placeholder="e.g. Barrier code"></label></div>
   <button class="btn full big" onclick="saveVenue(${v?`'${v.id}'`:''})">${v?'Save changes':'Add venue'}</button><button class="btn full gh" style="margin-top:8px" onclick="venuesSheet()">← Back</button>${v?delBtn('vnDel','Delete this venue',`confirmRow('vnDel','Delete ${esc(v.name).replace(/'/g,'')}? Fixtures already using it keep their details.','Yes, delete',\`delVenue('${v.id}')\`)`):''}</div>`); }
function saveVenue(id){ const n=$('#vnN').value.trim(); if(!n) return toast('Name the venue'); const d={name:n,address:$('#vnA').value.trim(),postcode:$('#vnP').value.trim().toUpperCase(),notes:$('#vnX').value.trim()}; S.venues=S.venues||[];
  if(id) Object.assign(S.venues.find(x=>x.id===id),d); else S.venues.push({id:uid('v_'),...d}); save(); toast(id?'Venue updated ✓':'Venue added ✓'); venuesSheet(); }
function delVenue(id){ S.venues=(S.venues||[]).filter(v=>v.id!==id); save(); toast('Venue deleted ✓'); venuesSheet(); }

