function incogSheet(){ if(!me){ document.getElementById('incogB')?.remove(); return; } const asP=me.role==='parent', cur=asP?(kids()[0]?.id||''):(me.viewas||'');
  const opts=TK.filter(t=>TEAMS[t]).map(t=>{ const ps=S.players.filter(p=>p.team===t).sort((x,y)=>x.name.localeCompare(y.name)); return ps.length?`<optgroup label="${esc(TEAMS[t].name||TEAMS[t].short)}">${ps.map(p=>`<option value="${p.id}" ${p.id===cur?'selected':''}>${esc(p.name)}</option>`).join('')}</optgroup>`:''; }).join('');
  openSheet(`<div class="shb"><h3>🕶️ Incognito view</h3><p class="hint">View only. Nothing you tap is saved, and nobody can see you're logged in.</p>
   <button class="btn full ${asP?'gh':''}" onclick="incogGo('coach')">🧑‍🏫 View as coach (Alfie's view)</button>
   <div style="margin-top:18px"><label class="hint" style="display:block;margin-bottom:6px">View as the parent of…</label><select id="icP" style="width:100%;padding:14px;border-radius:14px;background:var(--card);color:var(--ink);border:1px solid var(--line);font-size:16px">${opts}</select></div>
   <button class="btn full ${asP?'':'gh'}" style="margin-top:10px" onclick="incogGo('parent')">👪 View as parent</button>
   <p class="hint" style="margin-top:12px">Parent view shows exactly what that child's parent sees: their squad, fixtures, messages, groups and stats. Their private chats and payments stay private.</p></div>`); }
