/* ---------- delete my account ---------- */
function deleteMe(){ openSheet(`<div class="shb"><h3>Delete my account</h3><p class="hint">This removes your log-in, your contact details and your private messages with the coaches. Your child stays on the club's squad list unless you ask Alfie to remove them too. This can't be undone.</p>
  <label class="field"><span>Type your password to confirm</span><input id="dmP" type="password" autocomplete="current-password"></label>
  <button class="btn full big" style="background:#ff4d4d;color:#fff" onclick="doDeleteMe()">Delete my account</button><button class="btn full gh" style="margin-top:8px" onclick="closeSheet()">Keep my account</button></div>`); }
async function doDeleteMe(){ const pw=$('#dmP').value; if(!pw) return toast('Type your password'); try{ await api('deleteme',{password:pw}); closeSheet(); toast('Your account has been deleted'); setTimeout(()=>{ me=null; S=null; try{ onLoggedOut(); }catch(e){ location.reload(); } },900); }catch(e){ toast(e.message); } }

/* ---------- end of season ---------- */
function seasonName(){ const d=new Date(), y=d.getFullYear(), m=d.getMonth(); const a=m>=6?y:y-1; return `${a}/${String(a+1).slice(2)}`; }
function seasonSheet(){ const past=(S.seasons||[]);
  openSheet(`<div class="shb"><h3>🏁 End of season</h3><p class="hint">Saves every player's stats for this season (matches, goals, assists, MOTM, minutes), then starts the new season from zero. Finished results move into the archive. Upcoming fixtures, players, parents, chats and bookings all stay.</p>
   <label class="field"><span>Season name</span><input id="snN" value="${seasonName()}"></label>
   <div class="lab">Rename squads for the new season (optional)</div>${TK.map(t=>`<div class="g2"><label class="field"><span>Squad name</span><input id="snT_${t}" value="${esc(TEAMS[t].name)}"></label><label class="field"><span>Short name</span><input id="snS_${t}" value="${esc(TEAMS[t].short||TEAMS[t].name)}"></label></div>`).join('')}
   <label style="display:flex;gap:10px;align-items:center;font-size:14px;margin:4px 0 14px"><input type="checkbox" id="snTell" checked style="width:20px;height:20px;accent-color:#3ff36a"> Send parents an end-of-season message</label>
   <div id="snGo"><button class="btn full big" onclick="confirmRow('snGo','Save the ${esc(seasonName())} season and start the new one? Stats reset to zero (they\\'re kept in the archive).','Yes, end the season','endSeason()')">Save season &amp; start the new one</button></div>
   ${past.length?`<div class="lab" style="margin-top:16px">Saved seasons</div><div class="list" style="margin:0">${past.slice().reverse().map(s=>`<div class="row"><span class="ic">📚</span><div class="grow"><b>${esc(s.name)}</b><p>Saved ${fmtD(new Date(s.ts))} · ${s.players.length} players · ${s.fixtures.length} results</p></div></div>`).join('')}</div>`:''}
   <button class="btn full gh" style="margin-top:10px" onclick="closeSheet()">Cancel</button></div>`); }
function endSeason(){ const name=($('#snN').value||seasonName()).trim(), doTell=$('#snTell').checked;
  const players=S.players.map(p=>{ const s=stats(p); return {id:p.id,name:p.name,last:p.last||'',team:p.team,teamName:TEAMS[p.team]?.name||p.team,apps:s.apps,goals:s.goals,ast:s.ast,potm:s.potm,mins:s.mins||0}; });
  const fin=S.fixtures.filter(f=>f.status==='ft');
  const fixtures=fin.map(f=>({id:f.id,team:f.team,teamName:TEAMS[f.team]?.name||f.team,opp:f.opp,at:f.at,home:f.home,us:f.us,them:f.them,potm:f.potm||null,scorers:(f.events||[]).filter(e=>e.type==='goal').map(e=>e.who)}));
  S.seasons=S.seasons||[]; S.seasons.push({id:uid('sn'),name,ts:Date.now(),teams:Object.fromEntries(TK.map(t=>[t,TEAMS[t].name])),players,fixtures});
  S.fixtures=S.fixtures.filter(f=>f.status!=='ft'); S.seasonFrom=ymd(new Date()); S.players.forEach(p=>{ p.base={apps:0,goals:0,ast:0,potm:0}; });
  TK.forEach(t=>{ const nn=$('#snT_'+t)?.value.trim(), ns=$('#snS_'+t)?.value.trim(), old=TEAMS[t].name; if(nn&&nn!==old){ S.teams[t].name=nn; TEAMS[t].name=nn; const g=S.groups.find(x=>x.id==='g_'+t); if(g&&g.name===old) g.name=nn; } if(ns){ S.teams[t].short=ns; TEAMS[t].short=ns; } });
  if(doTell) tell(TK,`🏁 That's a wrap on the ${name} season! Thank you all for your support. Every player's stats have been saved, and the new season starts fresh. 💚🖤`);
  log('🏁',`${name} season saved and new season started`); save(); closeSheet(); confetti&&confetti(); toast(`${name} season saved ✓ New season started`); paint(); }


/* ---------- swipe down to close any pop-up card ---------- */
(()=>{ const sh=document.getElementById('sheet'); if(!sh) return; let y0=null,x0=0,t0=0,dy=0,drag=false;

  const g=sh.querySelector('.grab'); if(g){ const z=document.createElement('div'); z.className='grabz'; g.replaceWith(z); z.appendChild(g); }
  const x=document.createElement('button'); x.className='shx'; x.setAttribute('aria-label','Close'); x.textContent='✕'; x.onclick=()=>closeSheet(); (sh.querySelector('.grabz')||sh).appendChild(x);
  const inField=el=>el&&el.closest&&el.closest('input,textarea,select,[contenteditable],canvas,.nosw');
  sh.addEventListener('touchstart',e=>{ if(e.touches.length!==1||inField(e.target)||!e.target.closest('.grabz')||e.target.closest('button')) { y0=null; return; } y0=e.touches[0].clientY; x0=e.touches[0].clientX; t0=Date.now(); dy=0; drag=false; },{passive:true});
  sh.addEventListener('touchmove',e=>{ if(y0===null) return; const d=e.touches[0].clientY-y0, dx=Math.abs(e.touches[0].clientX-x0);
    if(!drag){ const fromGrab=!!e.target.closest('.grabz'); if(d>8&&d>dx&&(sh.scrollTop<=0||fromGrab)){ drag=true; y0=e.touches[0].clientY; sh.style.transition='none'; } else if(Math.abs(d)>8||dx>8){ y0=null; return; } else return; }
    dy=Math.max(0,e.touches[0].clientY-y0); sh.style.transform=`translateY(${dy}px)`; const sc=document.getElementById('scrim'); if(sc) sc.style.opacity=String(Math.max(.15,1-dy/(sh.offsetHeight||600))); e.preventDefault(); },{passive:false});
  const end=()=>{ if(y0===null&&!drag) return; const was=drag, v=dy/Math.max(1,Date.now()-t0); y0=null; drag=false; if(!was) return;
    sh.style.transition=''; const sc=document.getElementById('scrim'); if(sc) sc.style.opacity='';
    if(dy>Math.min(140,(sh.offsetHeight||600)*.25)||v>.6){ sh.style.transform=''; closeSheet(); } else sh.style.transform=''; dy=0; };
  sh.addEventListener('touchend',end);sh.addEventListener('touchcancel',()=>{y0=null;drag=false;dy=0;resetSheetDrag();});
})();

/* ---------- install ---------- */
let deferred=null; const standalone=matchMedia('(display-mode: standalone)').matches||navigator.standalone, isIOS=/iphone|ipad|ipod/i.test(navigator.userAgent);
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferred=e;}); window.addEventListener('appinstalled',()=>{hidePill();toast('Installed 🎉');});
if('serviceWorker' in navigator&&location.protocol==='https:'&&!/claude/.test(location.host)){
  let pwaReg=null, userAcceptedUpdate=false, updateReloaded=false, updateWork=0;
  const note=document.getElementById('pwaNote');
  // Observe existing async work without changing arguments, results or API rules.
  const watchUpdateWork=fn=>async function(...args){updateWork++;try{return await fn.apply(this,args);}finally{updateWork--;}};
  api=watchUpdateWork(api);uploadPhoto=watchUpdateWork(uploadPhoto);uploadAudio=watchUpdateWork(uploadAudio);
  pickPhoto=watchUpdateWork(pickPhoto);pickProfilePhoto=watchUpdateWork(pickProfilePhoto);
  const updateBlocked=()=>{
    if(!navigator.onLine||outbox.length||inflight||updateWork||busy())return true;
    if((typeof L!=='undefined'&&L.timer)||(S&&S.fixtures&&S.fixtures.some(f=>f.status==='live')))return true;
    if(typeof voiceSession!=='undefined'&&voiceSession)return true;
    if(typeof voiceStream!=='undefined'&&voiceStream)return true;
    if(typeof voiceRec!=='undefined'&&voiceRec&&voiceRec.state!=='inactive')return true;
    if(ui.voicePending||ui.voice||ui.ph||ui.mph||ui.profilePhotoBusy||String(ui.draft||'').trim())return true;
    if(typeof chatDrafts!=='undefined'&&Object.keys(chatDrafts).some(k=>String(chatDrafts[k]||'').trim()))return true;
    return Array.from(document.querySelectorAll('.chat-composer input,.chat-composer textarea,#cIn,#cIn2,#gIn,#phC,#mText')).some(el=>String(el.value||'').trim());
  };
  const showPwaNote=(text,button)=>{if(!note)return;note.innerHTML=`<span>${text}</span>${button||''}`;note.classList.add('on');};
  const offer=()=>{
    if(!navigator.onLine){showPwaNote('You’re offline. Live club information and changes need a connection.');return;}
    if(!pwaReg||!pwaReg.waiting||!navigator.serviceWorker.controller){if(note)note.classList.remove('on');return;}
    showPwaNote('An app update is ready. Updating may require signing in again.', '<button type="button" id="pwaUpdate">Update</button>');
    const button=document.getElementById('pwaUpdate');if(!button)return;
    button.addEventListener('click',()=>{
      // Defer rather than force a flush/reload of memory-only changes or drafts.
      if(updateBlocked()){toast('Finish or cancel drafts, forms, media and live matches; wait for saving and reconnect before updating.');return;}
      const waiting=pwaReg.waiting;if(!waiting)return;
      userAcceptedUpdate=true;button.disabled=true;
      waiting.postMessage({type:'SKIP_WAITING'});
    });
  };
  addEventListener('online',offer);addEventListener('offline',offer);offer();
  navigator.serviceWorker.register('/index.php?a=sw',{scope:'/',updateViaCache:'none'}).then(reg=>{
    pwaReg=reg;offer();reg.addEventListener('updatefound',()=>{const w=reg.installing;if(w)w.addEventListener('statechange',()=>{if(w.state==='installed')offer();});});
    setInterval(()=>reg.update().catch(()=>{}),6*60*60*1000);
  }).catch(()=>{});
  navigator.serviceWorker.addEventListener('controllerchange',()=>{
    if(updateReloaded)return;
    if(userAcceptedUpdate&&!updateBlocked()){updateReloaded=true;location.reload();return;}
    userAcceptedUpdate=false;
    // Another client may activate the worker. Never reload this client's drafts.
    showPwaNote('The app was updated. Finish saving and your drafts before reopening it.');
  });
}
function showPill(){ let x; try{x=localStorage.getItem('agfc_pillx');}catch(e){} if(standalone||x||!me) return; $('#ipill').classList.add('on'); setTimeout(()=>$('#ipill').classList.remove('on'),9000); }
function hidePill(){ $('#ipill').classList.remove('on'); try{localStorage.setItem('agfc_pillx','1');}catch(e){} }
function openInstall(){ $('#ipill').classList.remove('on'); openSheet(`<div class="shb"><div class="ihd"><img src="${ICON}" alt=""><div><h3>AG Coaching FC</h3><p>Official club app · Southport</p></div></div><div class="perks"><div><span>⚡</span>Installs in 2 seconds</div><div><span>🔔</span>Training &amp; match updates</div><div><span>📶</span>Cached app shell may open offline; live data needs a connection</div></div><div id="ib"><button class="btn full big" onclick="doInstall()">📲 Install app</button></div></div>`); }
async function doInstall(){ if(deferred){ deferred.prompt(); const r=await deferred.userChoice; deferred=null; if(r.outcome==='accepted'){closeSheet();confetti();} return; }
  const mock=`<div class="home"><div class="hg">${['Phone','Photos','Maps','Camera','Weather','Clock','Music','Mail','Notes','Files','Settings'].map(a=>`<div class="ha"><i></i>${a}</div>`).join('')}<div class="ha new"><img src="${ICON}" alt="">AG FC</div></div></div>`;
  if(isIOS&&!standalone){ $('#ib').innerHTML=`<div class="kv"><div><i>1</i>Tap <b style="margin:0 4px">Share</b> in Safari</div><div><i>2</i>Choose <b style="margin:0 4px">Add to Home Screen</b></div><div><i>3</i>Tap <b style="margin:0 4px">Add</b> 🎉</div></div>${mock}`; return; }
  $('#ib').innerHTML=mock+`<p class="hint" style="text-align:center;margin-top:12px"><b style="color:#fff">Add AG FC to your home screen</b><br>Open your browser menu and choose <b>Add to Home screen</b> or <b>Install app</b>. If that option is missing, try Chrome.</p><button class="btn full" onclick="closeSheet()">Done</button>`; }

/* ---------- intro ---------- */
(function(){ const c=$('#introFx'), x=c.getContext('2d'); const r=c.getBoundingClientRect(); const w=c.width=r.width*2, h=c.height=r.height*2; const t0=performance.now();
  const pts=Array.from({length:100},()=>({x:Math.random(),y:Math.random(),z:Math.random(),v:.0006+Math.random()*.0018}));
  (function loop(t){ const k=(t-t0)/1000; x.clearRect(0,0,w,h); const gr=x.createRadialGradient(w/2,h*.42,0,w/2,h*.42,w*.9); gr.addColorStop(0,`rgba(63,243,106,${Math.min(.22,k*.12)})`); gr.addColorStop(1,'rgba(0,0,0,0)'); x.fillStyle=gr; x.fillRect(0,0,w,h);
    pts.forEach(p=>{ p.y-=p.v; if(p.y<-.02){p.y=1.02;p.x=Math.random();} x.fillStyle=`rgba(196,255,77,${.15+p.z*.55})`; x.beginPath(); x.arc(p.x*w,p.y*h,1+p.z*3.2,0,7); x.fill(); });
    if(!$('#intro').classList.contains('gone')) requestAnimationFrame(loop); })(t0); })();
