const REACTS=['❤️','😂','👍','😮','😢','🙏','👏','⚽'];
const prevTxt=m=>m.del?'Message deleted':m.img?'📷 '+(m.t||'Photo'):m.audio?'🎤 Voice note':(m.t||'');
function parseRef(ref){ const [k,id,i]=ref.split('|'); return [k,id,+i]; }
function msgAt(root,ref){ const [k,id,i]=parseRef(ref); const c=(k==='g'?root?.groups:root?.threads)?.find(x=>x.id===id); return c?.msgs?.[i]; }
function setIn(o,sub,op,v){ let c=o; for(let j=0;j<sub.length-1;j++){ if(!isObj(c[sub[j]])) c[sub[j]]={}; c=c[sub[j]]; } const k=sub.at(-1); if(op==='del') delete c[k]; else c[k]=clone(v); }
function msgOps(ref,ops){ const [k,id,i]=parseRef(ref), root=[k==='g'?'groups':'threads','#'+id,'msgs',i];
  [S,base].forEach(r=>{ const m=msgAt(r,ref); if(m) ops.forEach(o=>setIn(m,o.sub,o.op,o.value)); });
  outbox.push(...ops.map(o=>o.op==='set'?{op:'set',path:[...root,...o.sub],value:o.value}:{op:'del',path:[...root,...o.sub]})); flush(); }
function isMine(ref,m){ const [k]=parseRef(ref); if(k==='t') return me.role==='coach'?m.by==='c':m.by==='p'; return m.uid?m.uid===me.id:(me.role==='coach'&&m.by==='coach'); }
function bubHTML(m,mine,ref,head,tick){ const d=new Date(m.ts);
  if(m.del) return `<div class="bub ${mine?'me':'them'} gone">${head}🚫 ${mine?'You deleted this message':'This message was deleted'}<small>${hm(d)}</small></div>`;
  const re=Object.values(m.re||{}), cnt={}; re.forEach(r=>{ if(r?.e) cnt[r.e]=(cnt[r.e]||0)+1; });
  return `<div class="bub ${mine?'me':'them'}${m.img?' pic':''}${m.audio?' voice':''}${re.length?' hasrx':''}" data-m="${ref}">${head}${m.img?`<img class="mimg" src="?a=img&f=${m.img}" loading="lazy" alt="Photo" onclick="viewImg('${m.img}')">`:''}${m.audio?`<audio class="voice-player" controls preload="none" playsinline aria-label="Voice note, up to 20 seconds" src="?a=audio&f=${encodeURIComponent(m.audio)}"></audio>`:''}${m.t?`<span class="mt">${esc(m.t)}</span>`:''}${m.link?payBtn(m.link):''}<small>${m.ed?'edited · ':''}${hm(d)}${tick?`<i class="tk ${tick==='read'?'rd':''}" aria-label="${tick==='read'?'Read':'Sent'}">✓✓</i>`:''}</small>${re.length?`<button class="rx" onclick="event.stopPropagation();whoReacted('${ref}')">${Object.entries(cnt).map(([e,n])=>e+(n>1?' '+n:'')).join(' ')}</button>`:''}</div>`; }
/* long press (or right-click) opens the reaction menu */
(function(){ let t=null, sx=0, sy=0, el=null, fired=false, firedAt=0, swallow=0;
  const stop=()=>{ clearTimeout(t); t=null; el?.classList.remove('lp'); el=null; };
  document.addEventListener('pointerdown',e=>{ const b=e.target.closest('.bub[data-m]'); if(!b||e.target.closest('.rx,a,audio,button:not(.mimg)')) return; fired=false; sx=e.clientX; sy=e.clientY; el=b; b.classList.add('lp');
    t=setTimeout(()=>{ fired=true; firedAt=Date.now(); const r=b.dataset.m; stop(); buzz(12); openMsgMenu(r); },430); },{passive:true});
  document.addEventListener('pointermove',e=>{ if(t&&Math.hypot(e.clientX-sx,e.clientY-sy)>10) stop(); },{passive:true});
  ['pointerup','pointercancel','scroll'].forEach(ev=>document.addEventListener(ev,stop,{passive:true,capture:true}));
  document.addEventListener('pointerup',()=>{ if(fired){ fired=false; swallow=Date.now()+400; } },true);
  document.addEventListener('click',e=>{ if(Date.now()<swallow){ e.preventDefault(); e.stopPropagation(); swallow=0; } },true); // the tap that ends a long press mustn't close the menu
  document.addEventListener('contextmenu',e=>{ const b=e.target.closest('.bub[data-m]'); if(!b) return; e.preventDefault(); if(!fired){ stop(); openMsgMenu(b.dataset.m); } fired=false; }); })();
/* read receipts */
function seenBy(g,i){ const m=g.msgs[i], au=m?.uid||(m?.by==='coach'&&me.role==='coach'?me.id:''), rd=g.read||{};
  const others=(g.mem||[]).filter(([u])=>u!==au), seen=others.filter(([u])=>(rd[u]||0)>i);
  return {seen:seen.map(x=>x[1]),not:others.filter(([u])=>(rd[u]||0)<=i).map(x=>x[1]),n:others.length,all:others.length>0&&seen.length===others.length}; }
function msgInfo(ref){ const [k,id,i]=parseRef(ref), g=S.groups.find(x=>x.id===id); if(!g) return; const r=seenBy(g,i), m=g.msgs[i];
  const li=(a,ic)=>a.map(n=>`<div class="act"><i>${ic}</i><span>${esc(n)}</span></div>`).join('');
  openSheet(`<div class="shb"><h3>Message info</h3><div class="mprev">${m.img?'📷 ':''}${esc((m.t||'Photo').slice(0,160))}</div>
   <h2 class="sec" style="margin:6px 0 6px;padding:0">Seen by ${r.seen.length} of ${r.n}</h2><div class="card" style="padding:4px 14px">${li(r.seen,'👀')||'<p class="hint" style="margin:10px 0">Nobody yet</p>'}</div>
   ${r.not.length?`<h2 class="sec" style="margin:14px 0 6px;padding:0">Not seen yet</h2><div class="card" style="padding:4px 14px">${li(r.not,'⏳')}</div>`:''}
   <button class="btn full gh" style="margin-top:14px" onclick="afterMsg('${ref}')">Done</button></div>`); }
function afterMsg(ref){ const [k,id]=parseRef(ref); if(k==='t'&&me.role==='coach') openThread(id); else { closeSheet(); paint(true); } }
function openMsgMenu(ref){ const m=msgAt(S,ref); if(!m||m.del||!me) return; if(me.hidden) return toast('View only');
  const [k]=parseRef(ref), mine=isMine(ref,m), mod=me.role==='coach'&&k==='g', cur=m.re?.[me.id]?.e;
  openSheet(`<div class="shb"><div class="rxbar">${REACTS.map(e=>`<button class="${cur===e?'on':''}" onclick="react('${ref}','${e}')" aria-label="React ${e}">${e}</button>`).join('')}</div>
   <div class="mprev">${m.img?'📷 ':''}${esc((m.t||'Photo').slice(0,160))}</div><div class="list" style="margin:0" id="mmL">
   ${mine&&k==='g'?(()=>{const g=S.groups.find(x=>x.id===parseRef(ref)[1]), r=seenBy(g,parseRef(ref)[2]); return `<button class="row" onclick="msgInfo('${ref}')"><span class="ic">👀</span><div class="grow"><b>Seen by ${r.seen.length} of ${r.n}</b><p>See who's read it</p></div></button>`;})():''}
   ${m.t?`<button class="row" onclick="copyMsg('${ref}')"><span class="ic">📋</span><div class="grow"><b>Copy text</b></div></button>`:''}
   ${mine&&m.t?`<button class="row" onclick="editMsg('${ref}')"><span class="ic">✏️</span><div class="grow"><b>Edit</b><p>Shows as edited</p></div></button>`:''}
   ${mine||mod?`<button class="row" onclick="askDelChat('${ref}')"><span class="ic">🗑️</span><div class="grow"><b style="color:#ff6b6b">Delete${mine?'':' for everyone'}</b><p>${mine?'Removed for everyone in the chat':`Remove ${esc((m.name||'this parent').split(' ')[0])}'s message from the group`}</p></div></button>`:''}
   ${Object.keys(m.re||{}).length?`<button class="row" onclick="whoReacted('${ref}')"><span class="ic">👀</span><div class="grow"><b>See reactions</b></div></button>`:''}</div>
   <button class="btn full gh" style="margin-top:12px" onclick="afterMsg('${ref}')">Cancel</button></div>`); }
function react(ref,e){ const m=msgAt(S,ref); if(!m) return; buzz(10);
  if(m.re?.[me.id]?.e===e) msgOps(ref,[{op:'del',sub:['re',me.id]}]); else msgOps(ref,[{op:'set',sub:['re',me.id],value:{e,n:me.first}}]);
  afterMsg(ref); }
function whoReacted(ref){ const m=msgAt(S,ref); if(!m?.re) return; const by={}; Object.entries(m.re).forEach(([u,r])=>{ if(!r?.e) return; (by[r.e]??=[]).push(u===me.id?'You':(r.n||'Someone')); });
  toast(Object.entries(by).map(([e,ns])=>`${e} ${ns.join(', ')}`).join('  ·  ')); }
function copyMsg(ref){ const m=msgAt(S,ref); try{ navigator.clipboard.writeText(m.t); toast('Copied ✓'); }catch(e){ toast('Couldn’t copy'); } afterMsg(ref); }
function editMsg(ref){ const m=msgAt(S,ref); openSheet(`<div class="shb"><h3>Edit message</h3><label class="field"><span>Message</span><textarea id="emT" rows="4">${esc(m.t)}</textarea></label>
   <button class="btn full big" onclick="saveEdit('${ref}')">Save</button><button class="btn full gh" style="margin-top:8px" onclick="afterMsg('${ref}')">Cancel</button></div>`); setTimeout(()=>$('#emT')?.focus(),80); }
function saveEdit(ref){ const t=$('#emT').value.trim(), m=msgAt(S,ref); if(!t) return toast('Write something, or delete the message instead'); if(t!==m.t) msgOps(ref,[{op:'set',sub:['t'],value:t},{op:'set',sub:['ed'],value:Date.now()}]); toast('Edited ✓'); afterMsg(ref); }
function askDelChat(ref){ confirmRow('mmL','Delete this message for everyone?','Yes, delete',`delChat('${ref}')`); }
function delChat(ref){ const m=msgAt(S,ref); const ops=[{op:'set',sub:['t'],value:''},{op:'set',sub:['del'],value:Date.now()}]; if(m.img) ops.push({op:'del',sub:['img']}); if(m.audio) ops.push({op:'del',sub:['audio']}); if(m.re) ops.push({op:'del',sub:['re']});
  msgOps(ref,ops); if(me.role==='coach'&&!isMine(ref,m)) log('🗑️',`Deleted a message from ${m.name||'a parent'}`); toast('Message deleted ✓'); afterMsg(ref); }


/* Cross-platform voice notes: Safari iOS commonly records MP4; Android commonly WebM/Opus. */
const voiceBtn=ctx=>me?.hidden?'':`<button class="att voice-btn" type="button" aria-label="Record a voice note" title="Record voice note" onclick="startVoice('${ctx}')">🎙</button>`;
let voiceStream=null, voiceRec=null, voiceChunks=[], voiceTimer=null, voiceLimit=null, voiceStarted=0, voiceSession=null, voiceRequest=0;
function captureMediaContext(ctx){
  if(!me||!S)return null;const [kind,id]=ctx.split('|');
  if(!['g','tp','tc'].includes(kind))return null;
  const thread=kind==='tp'?myThread():null;
  return {kind,id:kind==='tp'?thread?.id:id,sender:{id:me.id,role:me.role,first:me.first,kidName:kids()[0]?.name||''}};
}
function mediaAccountCurrent(target){return !!target&&!!S&&me?.id===target.sender.id&&me?.role===target.sender.role;}
function postCapturedMedia(target,text,img,audio,dur,quiet){
  // Cancelling the preview must not discard an already-uploaded message. Never
  // post it as a different signed-in account, or resolve its target from ui.th.
  if(!mediaAccountCurrent(target))return;
  const media={sender:target.sender,threadId:target.id,quiet};
  if(target.kind==='g')postGroup(target.id,text,img,audio,dur,media);
  else if(target.kind==='tp')postDM(text,img,audio,dur,media);
  else if(target.kind==='tc')postReply(target.id,text,img,audio,dur,media);
}
function voiceMime(){const ios=/iPad|iPhone|iPod/.test(navigator.userAgent)||(/Macintosh/.test(navigator.userAgent)&&navigator.maxTouchPoints>1);
  const a=ios?['audio/mp4','audio/aac','audio/webm;codecs=opus','audio/webm','audio/ogg;codecs=opus']:['audio/webm;codecs=opus','audio/webm','audio/mp4','audio/ogg;codecs=opus','audio/ogg'];
  return a.find(x=>window.MediaRecorder?.isTypeSupported?.(x))||'';
}
function voiceSessionLive(q){return !!q&&voiceSession===q&&!q.disposed&&q.request===voiceRequest&&q.generation===sheetGeneration&&mediaAccountCurrent(q.target)&&q.root?.isConnected&&$('#sheet')?.classList.contains('on');}
function stopVoiceTracks(q=voiceSession){
  if(q?.stream){q.stream.getTracks().forEach(t=>t.stop());q.stream=null;}
  if(!q||voiceSession===q)voiceStream=null;
}
function clearVoiceTimers(q){
  if(!q)return;clearInterval(q.timer);clearTimeout(q.limit);q.timer=null;q.limit=null;
  if(voiceSession===q){voiceTimer=null;voiceLimit=null;}
}
function disposeVoiceSession(q){
  if(!q||q.disposed)return;q.disposed=true;clearVoiceTimers(q);
  const rec=q.rec;q.rec=null;if(rec){rec.onstop=null;rec.ondataavailable=null;rec.onerror=null;if(rec.state!=='inactive')try{rec.stop();}catch(e){}}
  stopVoiceTracks(q);q.chunks=[];
  const audio=q.root?.querySelector('audio');if(audio){try{audio.pause();audio.removeAttribute('src');audio.load();}catch(e){}}
  if(q.preview?.url){URL.revokeObjectURL(q.preview.url);q.preview.url='';}
  if(ui.voice===q.preview)ui.voice=null;
  if(voiceSession===q){voiceSession=null;voiceRequest++;voiceRec=null;voiceChunks=[];voiceStarted=0;}
}
async function startVoice(ctx){
  if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)return toast('Voice recording is not supported by this browser. Update Safari or Chrome and try again.');
  if(!window.isSecureContext)return toast('Voice recording requires a secure HTTPS connection.');
  if(voiceSessionLive(voiceSession))return;
  const target=captureMediaContext(ctx);if(!target)return;
  openSheet(`<div class="shb" id="voicePendingSheet"><h3>🎙 Microphone permission</h3><p class="hint">Allow microphone access to record a voice note, up to 20 seconds. You can cancel while permission is pending.</p><button class="btn full gh" onclick="cancelVoice()">Cancel</button></div>`);
  const q={request:++voiceRequest,generation:sheetGeneration,target,ctx,root:$('#voicePendingSheet'),stream:null,rec:null,chunks:[],timer:null,limit:null,started:0,preview:null,disposed:false,stopping:false};voiceSession=q;
  setSheetDisposer(()=>disposeVoiceSession(q));
  try{
    const stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true}});
    if(!voiceSessionLive(q)){stream.getTracks().forEach(t=>t.stop());return;}
    q.stream=stream;voiceStream=stream;const mime=voiceMime();const rec=new MediaRecorder(stream,mime?{mimeType:mime}:undefined);q.rec=rec;voiceRec=rec;voiceChunks=q.chunks;
    rec.ondataavailable=e=>{if(!q.disposed&&e.data?.size)q.chunks.push(e.data);};
    rec.onerror=()=>{if(!voiceSessionLive(q))return;closeSheet();toast('Recording stopped unexpectedly. Please try again.');};
    rec.onstop=()=>{
      clearVoiceTimers(q);stopVoiceTracks(q);q.rec=null;if(voiceSession===q)voiceRec=null;
      if(!voiceSessionLive(q)){q.chunks=[];return;}
      const dur=Math.min(20,Math.max(1,Math.round((Date.now()-q.started)/1000))),type=rec.mimeType||mime||q.chunks[0]?.type||'audio/webm',blob=new Blob(q.chunks,{type});q.chunks=[];voiceChunks=[];
      if(!blob.size){closeSheet();toast('No audio was recorded.');return;}
      q.preview={blob,dur,ctx:q.ctx,target:q.target,url:URL.createObjectURL(blob),session:q,sending:false};ui.voice=q.preview;voicePreview();
    };
    q.started=Date.now();voiceStarted=q.started;rec.start(250);voiceRecordingSheet(ctx);
    q.limit=setTimeout(()=>{if(voiceSessionLive(q))stopVoice(true);},20000);voiceLimit=q.limit;
  }catch(e){
    if(!voiceSessionLive(q))return;
    closeSheet();toast(e?.name==='NotAllowedError'?'Allow microphone access in your browser settings, then try again.':'Could not access the microphone. Check permissions and try again.');
  }
}
function voiceRecordingSheet(ctx){
  const q=voiceSession;if(!voiceSessionLive(q))return;
  openSheet(`<div class="shb" id="voiceRecSheet"><h3>🎙 Recording voice note</h3><p class="hint" id="voiceClock" role="timer">00:00 / 00:20</p><div class="voice-live" aria-hidden="true">● Recording</div><button class="btn full big" onclick="stopVoice(false)">Stop recording</button><button class="btn full gh" style="margin-top:8px" onclick="cancelVoice()">Cancel</button></div>`,{preserveMedia:true});q.root=$('#voiceRecSheet');
  const clock=$('#voiceClock');q.timer=setInterval(()=>{if(voiceSessionLive(q)&&clock?.isConnected)clock.textContent=`00:${String(Math.min(20,Math.floor((Date.now()-q.started)/1000))).padStart(2,'0')} / 00:20`;},200);voiceTimer=q.timer;
}
function stopVoice(auto){
  const q=voiceSession;if(!voiceSessionLive(q)||q.stopping||!q.rec||q.rec.state==='inactive')return;
  q.stopping=true;clearVoiceTimers(q);
  try{q.rec.stop();if(auto)toast('20-second limit reached');}catch(e){closeSheet();toast('Recording stopped unexpectedly. Please try again.');}
}
function cancelVoice(){disposeVoiceSession(voiceSession);closeSheet();}
function voicePreview(){
  const v=ui.voice,q=v?.session;if(!v||!voiceSessionLive(q))return;
  const cancel=v.target.kind==='tc'?'tc':'other';
  openSheet(`<div class="shb" id="voicePreviewSheet"><h3>Voice note preview</h3><p class="hint">${v.dur} second${v.dur===1?'':'s'} · max 20 seconds</p><audio controls playsinline src="${v.url}" style="width:100%"></audio><button class="btn full big" id="voiceSendBtn" onclick="sendVoice()">Send voice note ↑</button><button class="btn full gh" style="margin-top:8px" onclick="cancelVoicePreview('${cancel}')">Cancel</button></div>`,{preserveMedia:true});q.root=$('#voicePreviewSheet');
}
function cancelVoicePreview(ctx){
