async function uploadAudio(blob){const type=(blob.type||'audio/webm').split(';')[0];const r=await fetch('?a=upAudio',{method:'POST',headers:{'Content-Type':type,'X-AGFC':'1'},body:blob,credentials:'same-origin'});let j=null;try{j=await r.json();}catch(e){}if(!r.ok||!j?.ok)throw new Error(j?.error||'Voice note didn’t send. Check your connection and try again.');return j.f;}
async function sendVoice(){
  const v=ui.voice,q=v?.session;if(!v||v.sending||!voiceSessionLive(q))return;
  v.sending=true;const target=v.target,b=$('#voiceSendBtn');if(b){b.disabled=true;b.textContent='Sending…';}
  const visible=()=>voiceSessionLive(q)&&ui.voice===v&&b?.isConnected;
  try{
    const f=await uploadAudio(v.blob),show=visible();
    if(show)closeSheet();
    postCapturedMedia(target,'',null,f,v.dur,!show);
  }catch(e){v.sending=false;if(visible()){b.disabled=false;b.textContent='Try again ↑';toast(e.message);}}
