/* photos */
const attBtn=ctx=>me?.hidden?'':`<label class="att" aria-label="Send a photo">📷<input type="file" accept="image/*" hidden onchange="pickPhoto(this,'${ctx}')"></label>`;
function viewImg(f){ let lb=$('#lb'); if(!lb){ lb=document.createElement('div'); lb.id='lb'; lb.onclick=e=>{ if(e.target.tagName!=='IMG') lb.classList.remove('on'); }; document.body.appendChild(lb); }
  lb.innerHTML=`<img src="?a=img&f=${f}" alt="Photo"><button aria-label="Close">✕</button><p>Press and hold the photo to save it</p>`; lb.classList.add('on'); }
async function shrink(file){ const url=URL.createObjectURL(file);
  try{ const im=await new Promise((ok,no)=>{ const i=new Image(); i.onload=()=>ok(i); i.onerror=no; i.src=url; });
    const M=1600, sc=Math.min(1,M/Math.max(im.naturalWidth,im.naturalHeight)), c=document.createElement('canvas'); c.width=Math.max(1,Math.round(im.naturalWidth*sc)); c.height=Math.max(1,Math.round(im.naturalHeight*sc));
    const x=c.getContext('2d'); x.fillStyle='#fff'; x.fillRect(0,0,c.width,c.height); x.drawImage(im,0,0,c.width,c.height);
    const blob=await new Promise(r=>c.toBlob(r,'image/jpeg',.82)); if(!blob) throw 0; return {blob,prev:c.toDataURL('image/jpeg',.5)}; }
  catch(e){ throw new Error('Couldn’t open that photo. Try another one.'); } finally{ URL.revokeObjectURL(url); } }
async function uploadPhoto(blob){ const r=await fetch('?a=up',{method:'POST',headers:{'Content-Type':'image/jpeg','X-AGFC':'1'},body:blob,credentials:'same-origin'}); let j=null; try{ j=await r.json(); }catch(e){}
  if(!r.ok||!j?.ok) throw new Error(j?.error||'Photo didn’t send. Check your signal and try again.'); return j.f; }
function consentNote(players){ if(me?.role!=='coach') return ''; const no=[...new Set(players.filter(p=>p.info?.photo===false).map(p=>p.name+(p.last?' '+p.last[0]:'')))];
  return no.length?`<div class="consent">📸 <b>No photo consent:</b> ${esc(no.join(', '))}. Make sure ${no.length>1?'they\'re':'they\'re'} not in this photo.</div>`:''; }
function ctxPlayers(ctx){ const [k,id]=ctx.split('|'); if(k!=='g') return []; const g=S.groups.find(x=>x.id===id); if(!g||g.coaches) return [];
  if(g.all) return S.players; if(g.teams) return S.players.filter(p=>g.teams.includes(p.team)); if(g.camp){ const ids=new Set(S.campBk.filter(b=>b.camp===g.camp).map(b=>b.pid)); return S.players.filter(p=>ids.has(p.id)); } return []; }
async function pickProfilePhoto(inp,kind,pid=''){
  const f=inp.files?.[0]; inp.value=''; if(!f) return;
  if(ui.profilePhotoBusy) return toast('Please wait for the photo to finish saving');
  const accountId=me?.id, editor=kind==='player'?ui.ep:null, editorGeneration=sheetGeneration, editorAvatar=kind==='player'?$('#epAv'):null;
  // Capture the target before awaiting image conversion/upload: changing child
  // tabs during an upload must never apply the photo to a different player.
  if(kind==='child'&&!pid) pid=selectedPhotoPlayer()?.id||'';
  if(kind==='me'&&me?.role==='parent'&&!pid) pid=selectedPhotoPlayer()?.id||'';
  ui.profilePhotoBusy=true; toast('Getting photo ready…');
  try{
    const ph=await shrinkSquare(f);
    const file=await uploadPhoto(ph.blob);
    if(!me||me.id!==accountId||!S) throw new Error('Please log in again');
    if(kind==='player'){ if(!editor||ui.ep!==editor||sheetGeneration!==editorGeneration||!editorAvatar?.isConnected)return; editor.photo=file; editorAvatar.innerHTML=`<span class="av hasph"><img src="${ph.prev}" alt=""></span>`; toast('Photo ready – save the player to keep it'); }
    else if(kind==='child'||kind==='me'){ if(me.role==='parent') await saveParentPhoto(file,pid); else await saveCoachPhoto(file); }
  }catch(e){ toast(e.message); }
  finally{ ui.profilePhotoBusy=false; if(kind!=='player') refreshProfilePhotoUI(); }
}
async function shrinkSquare(file){
  const url=URL.createObjectURL(file);
  try{
    const im=await new Promise((ok,no)=>{ const i=new Image(); i.onload=()=>ok(i); i.onerror=no; i.src=url; });
    const side=Math.min(im.naturalWidth,im.naturalHeight);
    const sx=(im.naturalWidth-side)/2, sy=(im.naturalHeight-side)/2;
    const M=512; const c=document.createElement('canvas'); c.width=M; c.height=M;
    const x=c.getContext('2d'); x.fillStyle='#0a1a10'; x.fillRect(0,0,M,M);
    x.drawImage(im,sx,sy,side,side,0,0,M,M);
    const blob=await new Promise(r=>c.toBlob(r,'image/jpeg',.88)); if(!blob) throw 0;
    return {blob,prev:c.toDataURL('image/jpeg',.6)};
  }catch(e){ throw new Error('Couldn’t open that photo. Try another one.'); }
  finally{ URL.revokeObjectURL(url); }
}

