/* ---------- reliable chat scroll helper ---------- */
function scrollChatToEnd(force){
  const sheet=$('#sheet'), sc=$('#screen');
  const chat=(sheet&&sheet.classList.contains('on')&&sheet.querySelector('.chat'))?sheet.querySelector('.chat'):sc?.querySelector('.chat');
  if(!chat) return;
  const near=chat.scrollHeight-chat.scrollTop-chat.clientHeight<200;
  if(!force&&!near) return;
  requestAnimationFrame(()=>{ chat.scrollTop=chat.scrollHeight; });
}


/* ---------- chat polish: open at the newest message, live updates while typing, keyboard stays up ---------- */
{ let lastKey='', lastN=0, lastSig='';
  const _p=paint;
  const typingIn=()=>{ const a=document.activeElement; return a&&/^(gIn|cIn|cIn2)$/.test(a.id)?a:null; };
