    if(!c){ lastKey=''; lastSig=''; return; }
    const key=k+c.id, n=c.msgs.length;
    const sheet=$('#sheet'), chat=(sheet?.classList.contains('on')&&sheet.querySelector('.chat'))?sheet.querySelector('.chat'):sc?.querySelector('.chat');
    const near=!!chat&&chat.scrollHeight-chat.scrollTop-chat.clientHeight<200;
