    if(key!==lastKey||(n>lastN&&(near||mine))){
      scrollChatToEnd(key!==lastKey||(n>lastN&&mine));
    }
    lastKey=key; lastN=n;
  };
  paint=function(soft){
    const a=typingIn(), [c,k]=cur(), sheet=$('#sheet');
    const box=(sheet?.classList.contains('on')&&sheet.querySelector('.chat'))?sheet.querySelector('.chat'):$('.screen .chat');
    if(soft===true&&a&&box&&c&&lastKey===k+c.id){
      // Routine live ticks must not rebuild the conversation while a person is typing.
      const sig=JSON.stringify([k,c.id,(c.msgs||[]).slice(-160),k==='g'?(c.read||{}):{cu:c.cu||0,pu:c.pu||0}]);
      if(sig!==lastSig){
        const near=box.scrollHeight-box.scrollTop-box.clientHeight<200, top=box.scrollTop;
        box.innerHTML=k==='g'?groupChatHTML(c,me.id,null,true):chatHTML(c,me.role==='parent'?'p':'c',0,true);
