        if(updated){if(near)updated.scrollTop=updated.scrollHeight;else updated.scrollTop=top;}
        lastSig=sig;
        try{ tabs(); }catch(e){}
      }
      afterChat();refreshViewport();
      return;
    }
    _p(soft);
    lastSig='';
    afterChat();
  };
  const _b=busy;
  busy=()=>typingIn()&&!$('#sheet')?.classList.contains('on')?false:_b(); // keep live ticks arriving while typing
  document.addEventListener('pointerdown',e=>{ if(e.target.closest?.('.chat-composer .send')) e.preventDefault(); });
}
