/* ---------- viewport and keyboard: one owner for every mobile surface ---------- */
(function(){
  const root=document.documentElement, vv=window.visualViewport, vk=navigator.virtualKeyboard;
  const nativeHeight=!!(window.CSS&&CSS.supports&&CSS.supports('height','100dvh'));
  const mobile=()=>matchMedia('(max-width:860px), (hover:none) and (pointer:coarse)').matches;
  const textField=el=>!!el&&!el.disabled&&!el.readOnly&&!el.closest('.sheet:not(.on),.login.gone')&&(el.isContentEditable||el.tagName==='TEXTAREA'||(el.tagName==='INPUT'&&!/^(button|submit|reset|checkbox|radio|range|color|file|hidden|image|date|time|month|week|datetime-local)$/.test(el.type)));
  let raf=0, revealTimer=0, baseHeight=0, lastWidth=window.innerWidth, rotatedHeight=0, carriedKeyboard=false;
  const normalHeights={};
  function clear(){
    root.classList.remove('keyboard-open','typing','viewport-adjusted');
    root.style.removeProperty('--keyboard-height');root.style.removeProperty('--keyboard-top');
  }
  function ensureVisible(field){
    if(!textField(field)||!root.classList.contains('keyboard-open'))return;
    // A chat composer is a non-shrinking flex child, not a scrolling form field.
    if(field.closest('.chat-composer'))return;
    const container=field.closest('.sheet,.login,.screen,.inst');if(!container)return;
    const r=field.getBoundingClientRect(), c=container.getBoundingClientRect();
    if(r.bottom>c.bottom-16)container.scrollTop+=r.bottom-(c.bottom-16);
    else if(r.top<c.top+12)container.scrollTop-=c.top+12-r.top;
  }
  function update(){
    raf=0;
    // Preserve the last layout rectangle during pinch zoom; let the browser pan it.
    if(vv&&Math.abs((vv.scale||1)-1)>.05)return;
    if(!mobile()){clear();return;}
    const field=document.activeElement, focused=textField(field);
    const width=Math.round(window.innerWidth), natural=window.innerHeight||root.clientHeight;
    let top=vv?Math.max(0,vv.offsetTop||0):0, height=vv?vv.height:natural;
    if(!height||!isFinite(height))return;
    const wasOpen=root.classList.contains('keyboard-open');
    if(Math.abs(width-lastWidth)>2){
      lastWidth=width;baseHeight=normalHeights[width]||0;
      carriedKeyboard=wasOpen&&focused;rotatedHeight=height;
    }
    // Never subtract a floating keyboard or subtract a docked keyboard twice.
    let docked=false;const rect=vk&&vk.overlaysContent===true&&vk.boundingRect;
    if(rect&&rect.height>0&&rect.width>=width*.7&&rect.y>top&&rect.y<top+height&&rect.y+rect.height>=top+height-2){
      height=Math.min(height,rect.y-top);docked=true;
    }
    if(!baseHeight&&!focused){baseHeight=natural;normalHeights[width]=natural;}
    const open=focused&&(docked||baseHeight-height>100||natural-(top+height)>100||(carriedKeyboard&&height<rotatedHeight+100));
    if(!open)carriedKeyboard=false;
    if(!focused&&!wasOpen&&!docked){baseHeight=Math.max(height,natural);normalHeights[width]=baseHeight;}
    if(focused&&!open&&height>=baseHeight-40){baseHeight=Math.max(baseHeight,natural,height);normalHeights[width]=baseHeight;}
    // Geometry follows the visible rectangle even during keyboard dismissal.
    // Keyboard inference controls navigation presentation, not whether forms fit.
    const adjusted=focused||docked||Math.abs(natural-height)>2||top>0;
    root.classList.toggle('viewport-adjusted',adjusted);
    root.classList.toggle('keyboard-open',!!open);
    root.classList.toggle('typing',focused&&!!field.closest('.chat-composer'));
    root.style.setProperty('--keyboard-height',Math.max(1,Math.round(height))+'px');
    root.style.setProperty('--keyboard-top',Math.round(top)+'px');
    if(!nativeHeight)root.style.setProperty('--legacy-height',Math.max(1,Math.round(height))+'px');
    clearTimeout(revealTimer);
    requestAnimationFrame(()=>{
      ensureVisible(document.activeElement);
      requestAnimationFrame(()=>ensureVisible(document.activeElement));
    });
    revealTimer=setTimeout(()=>ensureVisible(document.activeElement),60);
  }
  function schedule(){if(!raf)raf=requestAnimationFrame(update);}
  function settle(){schedule();[100,250,450].forEach(t=>setTimeout(schedule,t));}
  window.AppViewport={refresh:settle};
  if(!nativeHeight)root.classList.add('legacy-viewport');
  document.addEventListener('focusin',settle,true);document.addEventListener('focusout',settle,true);
  if(vv){vv.addEventListener('resize',schedule);vv.addEventListener('scroll',schedule);}
  if(vk&&vk.addEventListener)vk.addEventListener('geometrychange',schedule);
  window.addEventListener('resize',schedule);window.addEventListener('orientationchange',settle);
  window.addEventListener('pageshow',settle);
  document.addEventListener('visibilitychange',()=>{if(!document.hidden)settle();});
  settle();
})();

function filterCoachThreads(q){
  const needle=(q||'').trim().toLowerCase(); let shown=0;
  $$('.chat-directory .thread').forEach(row=>{ const hit=!needle||row.textContent.toLowerCase().includes(needle); row.style.display=hit?'':'none'; if(hit) shown++; });
  const empty=$('.chat-directory-empty'); if(empty) empty.style.display=shown?'none':'block';
}
