if ($gzOk) {
  $z = gzencode($html, 9);
  if (is_string($z) && strlen($z) > 0) {
    // Unique same-directory temp + rename: readers never see a partial release.
    // Keep current/prior build files; do not glob-delete another request's cache.
    $tmp = @tempnam($DIR, '.app-gzip-');
    if ($tmp !== false) {
      if (dirname($tmp) === $DIR && @file_put_contents($tmp, $z, LOCK_EX) === strlen($z)) {
        @chmod($tmp, 0640);
        @rename($tmp, $gzf);
      }
      // Only this request's temporary file is eligible for cleanup.
      if (is_file($tmp)) @unlink($tmp);
    }
    header('Content-Encoding: gzip'); $html = $z;
  }
}
